insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (372, 46, 1, 14, 'سورة الأحقاف ١ – ١٤', 'الأحقاف: ما كنت بدعاً من الرسل', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 372) = $j$[{"lbl": "الآيات ١ – ٩", "q": "حمٓ ﴿١﴾ تَنزِيلُ ٱلۡكِتَٰبِ مِنَ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ ﴿٢﴾ مَا خَلَقۡنَا ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَآ إِلَّا بِٱلۡحَقِّ وَأَجَلٖ مُّسَمّٗىۚ وَٱلَّذِينَ كَفَرُواْ عَمَّآ أُنذِرُواْ مُعۡرِضُونَ ﴿٣﴾ قُلۡ أَرَءَيۡتُم مَّا تَدۡعُونَ مِن دُونِ ٱللَّهِ أَرُونِي مَاذَا خَلَقُواْ مِنَ ٱلۡأَرۡضِ أَمۡ لَهُمۡ شِرۡكٞ فِي ٱلسَّمَٰوَٰتِۖ ٱئۡتُونِي بِكِتَٰبٖ مِّن قَبۡلِ هَٰذَآ أَوۡ أَثَٰرَةٖ مِّنۡ عِلۡمٍ إِن كُنتُمۡ صَٰدِقِينَ ﴿٤﴾ وَمَنۡ أَضَلُّ مِمَّن يَدۡعُواْ مِن دُونِ ٱللَّهِ مَن لَّا يَسۡتَجِيبُ لَهُۥٓ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ وَهُمۡ عَن دُعَآئِهِمۡ غَٰفِلُونَ ﴿٥﴾ وَإِذَا حُشِرَ ٱلنَّاسُ كَانُواْ لَهُمۡ أَعۡدَآءٗ وَكَانُواْ بِعِبَادَتِهِمۡ كَٰفِرِينَ ﴿٦﴾ وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتٖ قَالَ ٱلَّذِينَ كَفَرُواْ لِلۡحَقِّ لَمَّا جَآءَهُمۡ هَٰذَا سِحۡرٞ مُّبِينٌ ﴿٧﴾ أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ إِنِ ٱفۡتَرَيۡتُهُۥ فَلَا تَمۡلِكُونَ لِي مِنَ ٱللَّهِ شَيۡـًٔاۖ هُوَ أَعۡلَمُ بِمَا تُفِيضُونَ فِيهِۚ كَفَىٰ بِهِۦ شَهِيدَۢا بَيۡنِي وَبَيۡنَكُمۡۖ وَهُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ ﴿٨﴾ قُلۡ مَا كُنتُ بِدۡعٗا مِّنَ ٱلرُّسُلِ وَمَآ أَدۡرِي مَا يُفۡعَلُ بِي وَلَا بِكُمۡۖ إِنۡ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَيَّ وَمَآ أَنَا۠ إِلَّا نَذِيرٞ مُّبِينٞ ﴿٩﴾", "w": [["حم", "أحد الحروف المقطعة، يُكتب «حم» ويُقرأ «حا ميم»."], ["تنزيل الكتاب", "تنزيل القرآن."], ["من الله العزيز الحكيم", "من لدن الله العزيز في ملكه، الحكيم في صنعه."], ["إلا بالحق وأجل مسمى", "ما خلقنا السماوات والأرض إلا خلقاً متلبّساً بالحق، وبأجل مسمى لفنائهما."], ["عما أُنذروا معرضون", "عما خُوّفوا به من العذاب معرضون غير ملتفتين إليه."], ["ما تدعون من دون الله", "من الأصنام والأوثان."], ["أروني ماذا خلقوا من الأرض", "أشيروا إلى شيء خلقوه من الأرض."], ["أم لهم شرك في السماوات", "أم لهم شركة فيها؟"], ["ائتوني بكتاب من قبل هذا", "منزَّل من قبل القرآن."], ["أو أثارة من علم", "بقية من علم يؤثر عن الأولين بصحة دعواكم في عبادة الأصنام."], ["من لا يستجيب له إلى يوم القيامة", "لا أحد أضل ممن يدعو من لا يستجيب له في شيء يطلبه منه أبداً."], ["وهم عن دعائهم غافلون", "الأصنام عن دعاء المشركين إياهم غافلون لا يعرفون عنه شيئاً."], ["كانوا لهم أعداءً", "يوم القيامة كانت الأصنام أعداء لعابديها."], ["وكانوا بعبادتهم كافرين", "جاحدة غير معترفة."], ["هذا سحر مبين", "قالوا في القرآن: سحر ظاهر، لما رأوا من تأثيره على النفوس."], ["أم يقولون افتراه", "بل أيقولون اختلقه من نفسه؟"], ["فلا تملكون لي من الله شيئاً", "إن افتريته فأنتم لا تملكون لي من الله شيئاً إن أراد أن يعذبني."], ["هو أعلم بما تُفيضون فيه", "أعلم بما تخوضون فيه من القدح والطعن في القرآن."], ["ما كنت بدعاً من الرسل", "لم أكن أول رسول فأكون بدعاً، بل سبقني رسل كثيرون."], ["وما أدري ما يُفعل بي ولا بكم", "في هذه الحياة: هل أُخرج من بلدي أو أُقتل، وهل تُرجمون بالحجارة أو يُخسف بكم."], ["إن أتبع إلا ما يوحى إليّ", "ما أتبع إلا ما يوحيه إليّ ربي فأقول وأفعل ما يأمرني به."]], "m": "حم: الله أعلم بمراده به. تنزيل القرآن من لدن الله العزيز في ملكه الحكيم في صنعه وتدبيره. ما خلقنا السماوات والأرض وما بينهما إلا بالحق لحِكم عالية لا عبثاً، وبأجل مسمى هو وقت إفنائهما، والذين كفروا عما خُوّفوا به من العذاب معرضون لظلمة نفوسهم وقسوة قلوبهم. قل: أخبروني عما تدعون من دون الله من الأصنام، أروني ماذا خلقوا من الأرض أم لهم أدنى شرك في السماوات؟ ائتوني بكتاب من قبل القرآن أو بقية من علم تشهد بصحة عبادة آلهة لم تخلق شيئاً إن كنتم صادقين. ولا أضل ممن يقف أمام جماد لا يسمع ولا يبصر يدعوه ويسأله حاجته، وهم عن دعائهم غافلون لعدم الحياة فيهم، ويوم القيامة يُنطقهم الله فيتبرّؤون ممن عبدوهم، ويكونون لهم أعداء، وبعبادتهم من دعاء وذبح ونذر جاحدين. وإذا قرأ عليهم رسول الله ﷺ آيات القرآن البيّنات قالوا: هذا سحر مبين، بل قالوا: افتراه. قل: إن افتريته على الله وأراد الانتقام مني فهل أنتم تستطيعون دفع العذاب عني؟ فكيف أعرّض نفسي للعذاب بالافتراء عليه؟ هو أعلم بما تخوضون فيه من الطعن فيّ وفي القرآن، كفى به شهيداً بيني وبينكم، وهو الغفور لمن تاب الرحيم بمن آمن، فتوبوا إليه. وقل لهم: ما أنا بأول رسول فأكون بدعاً يُستغرب مني، بل سبقتني رسل كثيرة، وما أدري ما يُفعل بي مستقبلاً: أأُخرج أم أُقتل أم أُنصر، ولا بكم: أتُعذّبون أم تُهدون، ما أتبع إلا ما يوحى إليّ اعتقاداً وقولاً وعملاً، فلا أُحدث ولا أبتدع شيئاً، وما أنا إلا نذير مبين لا أملك لنفسي ولا لغيري خيراً ولا ضراً.", "h": ["إثبات النبوة المحمدية بتقرير أن القرآن تنزيل الله على رسوله المنزل عليه وهو محمد ﷺ.", "انتفاء العبث عن الله تعالى في خلقه السماوات والأرض وما بينهما، وفي كل أفعاله وأقواله.", "تقرير حقيقة علمية، وهي: من لا يخلق لا يُعبد.", "بيان أنه لا أضل في الحياة من أحد يدعو من لا يستجيب له أبداً، كمن يدعون الأصنام والقبور والأشجار بعنوان التوسل والاستشفاع والتبرك."], "k": "«إن أتبع إلا ما يوحى إليّ»… هذا منهج نبيّ؛ فهل أتّبع الوحي أم ما استحسنته؟"}, {"lbl": "الآيات ١٠ – ١٤", "q": "قُلۡ أَرَءَيۡتُمۡ إِن كَانَ مِنۡ عِندِ ٱللَّهِ وَكَفَرۡتُم بِهِۦ وَشَهِدَ شَاهِدٞ مِّنۢ بَنِيٓ إِسۡرَـٰٓءِيلَ عَلَىٰ مِثۡلِهِۦ فَـَٔامَنَ وَٱسۡتَكۡبَرۡتُمۡۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ ﴿١٠﴾ وَقَالَ ٱلَّذِينَ كَفَرُواْ لِلَّذِينَ ءَامَنُواْ لَوۡ كَانَ خَيۡرٗا مَّا سَبَقُونَآ إِلَيۡهِۚ وَإِذۡ لَمۡ يَهۡتَدُواْ بِهِۦ فَسَيَقُولُونَ هَٰذَآ إِفۡكٞ قَدِيمٞ ﴿١١﴾ وَمِن قَبۡلِهِۦ كِتَٰبُ مُوسَىٰٓ إِمَامٗا وَرَحۡمَةٗۚ وَهَٰذَا كِتَٰبٞ مُّصَدِّقٞ لِّسَانًا عَرَبِيّٗا لِّيُنذِرَ ٱلَّذِينَ ظَلَمُواْ وَبُشۡرَىٰ لِلۡمُحۡسِنِينَ ﴿١٢﴾ إِنَّ ٱلَّذِينَ قَالُواْ رَبُّنَا ٱللَّهُ ثُمَّ ٱسۡتَقَٰمُواْ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ﴿١٣﴾ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِ خَٰلِدِينَ فِيهَا جَزَآءَۢ بِمَا كَانُواْ يَعۡمَلُونَ ﴿١٤﴾", "w": [["قل أرأيتم", "أخبروني ماذا تكون حالكم."], ["إن كان من عند الله", "إن كان القرآن من عند الله."], ["وكفرتم به", "وكذّبتم بالقرآن."], ["وشهد شاهد من بني إسرائيل", "عبد الله بن سلام."], ["على مثله فآمن", "على أنه من عند الله فآمن."], ["واستكبرتم", "واستكبرتم أنتم فلم تؤمنوا، ألستم ظالمين؟"], ["لو كان خيراً ما سبقونا إليه", "لو كان ما جاء به محمد من القرآن والدين خيراً ما سبقنا إليه المؤمنون."], ["وإذ لم يهتدوا به", "بالقرآن العظيم."], ["فسيقولون هذا إفك قديم", "هو من كذب الأولين."], ["وهذا كتاب مصدّق", "القرآن مصدّق للكتب التي سبقته."], ["لساناً عربياً لينذر الذين ظلموا", "بلسان عربي لينذر به الظالمين المشركين."], ["وبشرى للمحسنين", "بشرى لأهل الإحسان في عقائدهم وأقوالهم وأعمالهم."], ["ثم استقاموا", "فلم يرتدّوا، واستمروا على فعل الواجبات وترك المحرمات."], ["فلا خوف عليهم ولا هم يحزنون", "في الدنيا وفي البرزخ وفي عرصات القيامة."], ["جزاءً بما كانوا يعملون", "بأعمالهم الصالحة وتركهم الأعمال الفاسدة."]], "m": "ما زال السياق في طلب هداية قريش الذين قالوا في القرآن سحر وفي صاحبه مفترٍ: قل يا محمد: أخبروني ماذا تكون حالكم إن كان القرآن من عند الله وكفرتم به، وشهد شاهد من بني إسرائيل، عبد الله بن سلام، على مثله، أي على التوراة أنها من عند الله كالقرآن، والكتابان يصدّق بعضهما بعضاً في أصول الدين كالتوحيد والبعث ومكارم الأخلاق، فآمن هذا الشاهد واستكبرتم أنتم، ألم تكونوا شر الناس وأظلمهم؟ إن الله لا يهدي القوم الظالمين. وقال الذين كفروا للذين آمنوا: لو كان الإسلام خيراً ما سبقنا إليه الفقراء والمساكين؛ اعتذاراً عن عدم قبوله بحجة أنه لا فائدة مادية فيه. وإذ لم يهتدوا بالقرآن لعنادهم فسيقولون: هذا كذب قديم أفكه غير محمد فهو يقول به، وما أقبح هذا القول وقائله. ومن قبل القرآن كتاب موسى التوراة أنزلناه إماماً يُؤتمّ به ورحمة، وهذا القرآن كتاب مصدّق لما قبله بلسان عربي لينذر به رسولنا الذين ظلموا أنفسهم بالشرك والمعاصي، وبشرى للمحسنين بالنجاة من النار ودخول الجنة. ثم عقّب بذكر المحسنين على نهج الترهيب والترغيب: إن الذين قالوا ربنا الله فآمنوا وجاهروا بإيمانهم، ثم استقاموا على منهج لا إله إلا الله فعبدوا الله بما شرع حتى ماتوا، لا خوف عليهم ولا هم يحزنون في الدنيا والبرزخ والآخرة، أولئك أصحاب الجنة خالدين فيها جزاءً بما كانوا يعملون.", "h": ["اعتبار الشهادة، وأنها أداة يُتوصّل بها إلى إحقاق الحق وإبطال الباطل، فلذا يُشترط عدالة صاحبها، والعدالة هي اجتناب الكبائر واتقاء الصغائر غالباً.", "تقرير قاعدة: من جهل شيئاً عاداه، إذ المشركون لما لم يهتدوا بالقرآن قالوا: هذا إفك قديم.", "بيان تآخي وتلاقي الكتابين التوراة والقرآن، فشهادة أحدهما للآخر أثبتت صحته.", "وجوب تعلّم العربية لمن أراد أن يحمل رسالة الدعوة المحمدية فينذر ويبشّر.", "فضل الاستقامة، حتى قيل إنها خير من ألف كرامة، والاستقامة هي التمسك بالإيمان والعبادة كما جاء بذلك القرآن وبيّنت السنة."], "k": "«لو كان خيراً ما سبقونا إليه»… هل أقيس الخير بما يعود عليّ من دنيا؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 372;
insert into public.tdb_cards(topic, i, body) select 372, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٩", "q": "حمٓ ﴿١﴾ تَنزِيلُ ٱلۡكِتَٰبِ مِنَ ٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَكِيمِ ﴿٢﴾ مَا خَلَقۡنَا ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَآ إِلَّا بِٱلۡحَقِّ وَأَجَلٖ مُّسَمّٗىۚ وَٱلَّذِينَ كَفَرُواْ عَمَّآ أُنذِرُواْ مُعۡرِضُونَ ﴿٣﴾ قُلۡ أَرَءَيۡتُم مَّا تَدۡعُونَ مِن دُونِ ٱللَّهِ أَرُونِي مَاذَا خَلَقُواْ مِنَ ٱلۡأَرۡضِ أَمۡ لَهُمۡ شِرۡكٞ فِي ٱلسَّمَٰوَٰتِۖ ٱئۡتُونِي بِكِتَٰبٖ مِّن قَبۡلِ هَٰذَآ أَوۡ أَثَٰرَةٖ مِّنۡ عِلۡمٍ إِن كُنتُمۡ صَٰدِقِينَ ﴿٤﴾ وَمَنۡ أَضَلُّ مِمَّن يَدۡعُواْ مِن دُونِ ٱللَّهِ مَن لَّا يَسۡتَجِيبُ لَهُۥٓ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ وَهُمۡ عَن دُعَآئِهِمۡ غَٰفِلُونَ ﴿٥﴾ وَإِذَا حُشِرَ ٱلنَّاسُ كَانُواْ لَهُمۡ أَعۡدَآءٗ وَكَانُواْ بِعِبَادَتِهِمۡ كَٰفِرِينَ ﴿٦﴾ وَإِذَا تُتۡلَىٰ عَلَيۡهِمۡ ءَايَٰتُنَا بَيِّنَٰتٖ قَالَ ٱلَّذِينَ كَفَرُواْ لِلۡحَقِّ لَمَّا جَآءَهُمۡ هَٰذَا سِحۡرٞ مُّبِينٌ ﴿٧﴾ أَمۡ يَقُولُونَ ٱفۡتَرَىٰهُۖ قُلۡ إِنِ ٱفۡتَرَيۡتُهُۥ فَلَا تَمۡلِكُونَ لِي مِنَ ٱللَّهِ شَيۡـًٔاۖ هُوَ أَعۡلَمُ بِمَا تُفِيضُونَ فِيهِۚ كَفَىٰ بِهِۦ شَهِيدَۢا بَيۡنِي وَبَيۡنَكُمۡۖ وَهُوَ ٱلۡغَفُورُ ٱلرَّحِيمُ ﴿٨﴾ قُلۡ مَا كُنتُ بِدۡعٗا مِّنَ ٱلرُّسُلِ وَمَآ أَدۡرِي مَا يُفۡعَلُ بِي وَلَا بِكُمۡۖ إِنۡ أَتَّبِعُ إِلَّا مَا يُوحَىٰٓ إِلَيَّ وَمَآ أَنَا۠ إِلَّا نَذِيرٞ مُّبِينٞ ﴿٩﴾", "w": [["حم", "أحد الحروف المقطعة، يُكتب «حم» ويُقرأ «حا ميم»."], ["تنزيل الكتاب", "تنزيل القرآن."], ["من الله العزيز الحكيم", "من لدن الله العزيز في ملكه، الحكيم في صنعه."], ["إلا بالحق وأجل مسمى", "ما خلقنا السماوات والأرض إلا خلقاً متلبّساً بالحق، وبأجل مسمى لفنائهما."], ["عما أُنذروا معرضون", "عما خُوّفوا به من العذاب معرضون غير ملتفتين إليه."], ["ما تدعون من دون الله", "من الأصنام والأوثان."], ["أروني ماذا خلقوا من الأرض", "أشيروا إلى شيء خلقوه من الأرض."], ["أم لهم شرك في السماوات", "أم لهم شركة فيها؟"], ["ائتوني بكتاب من قبل هذا", "منزَّل من قبل القرآن."], ["أو أثارة من علم", "بقية من علم يؤثر عن الأولين بصحة دعواكم في عبادة الأصنام."], ["من لا يستجيب له إلى يوم القيامة", "لا أحد أضل ممن يدعو من لا يستجيب له في شيء يطلبه منه أبداً."], ["وهم عن دعائهم غافلون", "الأصنام عن دعاء المشركين إياهم غافلون لا يعرفون عنه شيئاً."], ["كانوا لهم أعداءً", "يوم القيامة كانت الأصنام أعداء لعابديها."], ["وكانوا بعبادتهم كافرين", "جاحدة غير معترفة."], ["هذا سحر مبين", "قالوا في القرآن: سحر ظاهر، لما رأوا من تأثيره على النفوس."], ["أم يقولون افتراه", "بل أيقولون اختلقه من نفسه؟"], ["فلا تملكون لي من الله شيئاً", "إن افتريته فأنتم لا تملكون لي من الله شيئاً إن أراد أن يعذبني."], ["هو أعلم بما تُفيضون فيه", "أعلم بما تخوضون فيه من القدح والطعن في القرآن."], ["ما كنت بدعاً من الرسل", "لم أكن أول رسول فأكون بدعاً، بل سبقني رسل كثيرون."], ["وما أدري ما يُفعل بي ولا بكم", "في هذه الحياة: هل أُخرج من بلدي أو أُقتل، وهل تُرجمون بالحجارة أو يُخسف بكم."], ["إن أتبع إلا ما يوحى إليّ", "ما أتبع إلا ما يوحيه إليّ ربي فأقول وأفعل ما يأمرني به."]], "m": "حم: الله أعلم بمراده به. تنزيل القرآن من لدن الله العزيز في ملكه الحكيم في صنعه وتدبيره. ما خلقنا السماوات والأرض وما بينهما إلا بالحق لحِكم عالية لا عبثاً، وبأجل مسمى هو وقت إفنائهما، والذين كفروا عما خُوّفوا به من العذاب معرضون لظلمة نفوسهم وقسوة قلوبهم. قل: أخبروني عما تدعون من دون الله من الأصنام، أروني ماذا خلقوا من الأرض أم لهم أدنى شرك في السماوات؟ ائتوني بكتاب من قبل القرآن أو بقية من علم تشهد بصحة عبادة آلهة لم تخلق شيئاً إن كنتم صادقين. ولا أضل ممن يقف أمام جماد لا يسمع ولا يبصر يدعوه ويسأله حاجته، وهم عن دعائهم غافلون لعدم الحياة فيهم، ويوم القيامة يُنطقهم الله فيتبرّؤون ممن عبدوهم، ويكونون لهم أعداء، وبعبادتهم من دعاء وذبح ونذر جاحدين. وإذا قرأ عليهم رسول الله ﷺ آيات القرآن البيّنات قالوا: هذا سحر مبين، بل قالوا: افتراه. قل: إن افتريته على الله وأراد الانتقام مني فهل أنتم تستطيعون دفع العذاب عني؟ فكيف أعرّض نفسي للعذاب بالافتراء عليه؟ هو أعلم بما تخوضون فيه من الطعن فيّ وفي القرآن، كفى به شهيداً بيني وبينكم، وهو الغفور لمن تاب الرحيم بمن آمن، فتوبوا إليه. وقل لهم: ما أنا بأول رسول فأكون بدعاً يُستغرب مني، بل سبقتني رسل كثيرة، وما أدري ما يُفعل بي مستقبلاً: أأُخرج أم أُقتل أم أُنصر، ولا بكم: أتُعذّبون أم تُهدون، ما أتبع إلا ما يوحى إليّ اعتقاداً وقولاً وعملاً، فلا أُحدث ولا أبتدع شيئاً، وما أنا إلا نذير مبين لا أملك لنفسي ولا لغيري خيراً ولا ضراً.", "h": ["إثبات النبوة المحمدية بتقرير أن القرآن تنزيل الله على رسوله المنزل عليه وهو محمد ﷺ.", "انتفاء العبث عن الله تعالى في خلقه السماوات والأرض وما بينهما، وفي كل أفعاله وأقواله.", "تقرير حقيقة علمية، وهي: من لا يخلق لا يُعبد.", "بيان أنه لا أضل في الحياة من أحد يدعو من لا يستجيب له أبداً، كمن يدعون الأصنام والقبور والأشجار بعنوان التوسل والاستشفاع والتبرك."], "k": "«إن أتبع إلا ما يوحى إليّ»… هذا منهج نبيّ؛ فهل أتّبع الوحي أم ما استحسنته؟"}, {"lbl": "الآيات ١٠ – ١٤", "q": "قُلۡ أَرَءَيۡتُمۡ إِن كَانَ مِنۡ عِندِ ٱللَّهِ وَكَفَرۡتُم بِهِۦ وَشَهِدَ شَاهِدٞ مِّنۢ بَنِيٓ إِسۡرَـٰٓءِيلَ عَلَىٰ مِثۡلِهِۦ فَـَٔامَنَ وَٱسۡتَكۡبَرۡتُمۡۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّـٰلِمِينَ ﴿١٠﴾ وَقَالَ ٱلَّذِينَ كَفَرُواْ لِلَّذِينَ ءَامَنُواْ لَوۡ كَانَ خَيۡرٗا مَّا سَبَقُونَآ إِلَيۡهِۚ وَإِذۡ لَمۡ يَهۡتَدُواْ بِهِۦ فَسَيَقُولُونَ هَٰذَآ إِفۡكٞ قَدِيمٞ ﴿١١﴾ وَمِن قَبۡلِهِۦ كِتَٰبُ مُوسَىٰٓ إِمَامٗا وَرَحۡمَةٗۚ وَهَٰذَا كِتَٰبٞ مُّصَدِّقٞ لِّسَانًا عَرَبِيّٗا لِّيُنذِرَ ٱلَّذِينَ ظَلَمُواْ وَبُشۡرَىٰ لِلۡمُحۡسِنِينَ ﴿١٢﴾ إِنَّ ٱلَّذِينَ قَالُواْ رَبُّنَا ٱللَّهُ ثُمَّ ٱسۡتَقَٰمُواْ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ﴿١٣﴾ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِ خَٰلِدِينَ فِيهَا جَزَآءَۢ بِمَا كَانُواْ يَعۡمَلُونَ ﴿١٤﴾", "w": [["قل أرأيتم", "أخبروني ماذا تكون حالكم."], ["إن كان من عند الله", "إن كان القرآن من عند الله."], ["وكفرتم به", "وكذّبتم بالقرآن."], ["وشهد شاهد من بني إسرائيل", "عبد الله بن سلام."], ["على مثله فآمن", "على أنه من عند الله فآمن."], ["واستكبرتم", "واستكبرتم أنتم فلم تؤمنوا، ألستم ظالمين؟"], ["لو كان خيراً ما سبقونا إليه", "لو كان ما جاء به محمد من القرآن والدين خيراً ما سبقنا إليه المؤمنون."], ["وإذ لم يهتدوا به", "بالقرآن العظيم."], ["فسيقولون هذا إفك قديم", "هو من كذب الأولين."], ["وهذا كتاب مصدّق", "القرآن مصدّق للكتب التي سبقته."], ["لساناً عربياً لينذر الذين ظلموا", "بلسان عربي لينذر به الظالمين المشركين."], ["وبشرى للمحسنين", "بشرى لأهل الإحسان في عقائدهم وأقوالهم وأعمالهم."], ["ثم استقاموا", "فلم يرتدّوا، واستمروا على فعل الواجبات وترك المحرمات."], ["فلا خوف عليهم ولا هم يحزنون", "في الدنيا وفي البرزخ وفي عرصات القيامة."], ["جزاءً بما كانوا يعملون", "بأعمالهم الصالحة وتركهم الأعمال الفاسدة."]], "m": "ما زال السياق في طلب هداية قريش الذين قالوا في القرآن سحر وفي صاحبه مفترٍ: قل يا محمد: أخبروني ماذا تكون حالكم إن كان القرآن من عند الله وكفرتم به، وشهد شاهد من بني إسرائيل، عبد الله بن سلام، على مثله، أي على التوراة أنها من عند الله كالقرآن، والكتابان يصدّق بعضهما بعضاً في أصول الدين كالتوحيد والبعث ومكارم الأخلاق، فآمن هذا الشاهد واستكبرتم أنتم، ألم تكونوا شر الناس وأظلمهم؟ إن الله لا يهدي القوم الظالمين. وقال الذين كفروا للذين آمنوا: لو كان الإسلام خيراً ما سبقنا إليه الفقراء والمساكين؛ اعتذاراً عن عدم قبوله بحجة أنه لا فائدة مادية فيه. وإذ لم يهتدوا بالقرآن لعنادهم فسيقولون: هذا كذب قديم أفكه غير محمد فهو يقول به، وما أقبح هذا القول وقائله. ومن قبل القرآن كتاب موسى التوراة أنزلناه إماماً يُؤتمّ به ورحمة، وهذا القرآن كتاب مصدّق لما قبله بلسان عربي لينذر به رسولنا الذين ظلموا أنفسهم بالشرك والمعاصي، وبشرى للمحسنين بالنجاة من النار ودخول الجنة. ثم عقّب بذكر المحسنين على نهج الترهيب والترغيب: إن الذين قالوا ربنا الله فآمنوا وجاهروا بإيمانهم، ثم استقاموا على منهج لا إله إلا الله فعبدوا الله بما شرع حتى ماتوا، لا خوف عليهم ولا هم يحزنون في الدنيا والبرزخ والآخرة، أولئك أصحاب الجنة خالدين فيها جزاءً بما كانوا يعملون.", "h": ["اعتبار الشهادة، وأنها أداة يُتوصّل بها إلى إحقاق الحق وإبطال الباطل، فلذا يُشترط عدالة صاحبها، والعدالة هي اجتناب الكبائر واتقاء الصغائر غالباً.", "تقرير قاعدة: من جهل شيئاً عاداه، إذ المشركون لما لم يهتدوا بالقرآن قالوا: هذا إفك قديم.", "بيان تآخي وتلاقي الكتابين التوراة والقرآن، فشهادة أحدهما للآخر أثبتت صحته.", "وجوب تعلّم العربية لمن أراد أن يحمل رسالة الدعوة المحمدية فينذر ويبشّر.", "فضل الاستقامة، حتى قيل إنها خير من ألف كرامة، والاستقامة هي التمسك بالإيمان والعبادة كما جاء بذلك القرآن وبيّنت السنة."], "k": "«لو كان خيراً ما سبقونا إليه»… هل أقيس الخير بما يعود عليّ من دنيا؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (373, 46, 15, 20, 'سورة الأحقاف ١٥ – ٢٠', 'الأحقاف: ووصّينا الإنسان بوالديه إحساناً', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 373) = $j$[{"lbl": "الآيتان ١٥ – ١٦", "q": "وَوَصَّيۡنَا ٱلۡإِنسَٰنَ بِوَٰلِدَيۡهِ إِحۡسَٰنًاۖ حَمَلَتۡهُ أُمُّهُۥ كُرۡهٗا وَوَضَعَتۡهُ كُرۡهٗاۖ وَحَمۡلُهُۥ وَفِصَٰلُهُۥ ثَلَٰثُونَ شَهۡرًاۚ حَتَّىٰٓ إِذَا بَلَغَ أَشُدَّهُۥ وَبَلَغَ أَرۡبَعِينَ سَنَةٗ قَالَ رَبِّ أَوۡزِعۡنِيٓ أَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِيٓ أَنۡعَمۡتَ عَلَيَّ وَعَلَىٰ وَٰلِدَيَّ وَأَنۡ أَعۡمَلَ صَٰلِحٗا تَرۡضَىٰهُ وَأَصۡلِحۡ لِي فِي ذُرِّيَّتِيٓۖ إِنِّي تُبۡتُ إِلَيۡكَ وَإِنِّي مِنَ ٱلۡمُسۡلِمِينَ ﴿١٥﴾ أُوْلَـٰٓئِكَ ٱلَّذِينَ نَتَقَبَّلُ عَنۡهُمۡ أَحۡسَنَ مَا عَمِلُواْ وَنَتَجَاوَزُ عَن سَيِّـَٔاتِهِمۡ فِيٓ أَصۡحَٰبِ ٱلۡجَنَّةِۖ وَعۡدَ ٱلصِّدۡقِ ٱلَّذِي كَانُواْ يُوعَدُونَ ﴿١٦﴾", "w": [["ووصّينا الإنسان بوالديه", "أمرناه أمراً مؤكداً بالإيصاء."], ["إحساناً", "أن يُحسن بهما إحساناً، وهو المعاملة بالحسنى."], ["حملته أمه كُرهاً ووضعته كُرهاً", "حملته في بطنها على مشقة، وولدته كذلك على مشقة."], ["وحمله وفصاله ثلاثون شهراً", "مدة حمله في بطنها وفطامه من الرضاع ثلاثون شهراً."], ["حتى إذا بلغ أشدّه", "اكتمال قوته البدنية والعقلية، وهي من الثلاث والثلاثين فما فوق."], ["رب أوزعني أن أشكر نعمتك", "ألهمني ووفّقني أن أشكر نعمتك بصرفها فيما تحب."], ["وأن أعمل صالحاً ترضاه", "عملاً صالحاً تتقبّله مني."], ["ونتجاوز عن سيئاتهم", "فلا نؤاخذهم بها بل نغفرها."], ["في أصحاب الجنة", "في جملة أصحاب الجنة وعدادهم."], ["وعد الصدق الذي كانوا يوعدون", "في مثل قوله: وعد الله المؤمنين والمؤمنات جنات تجري من تحتها الأنهار."]], "m": "الفرد كالجماعة: أوصى تعالى الإنسان بالإحسان إلى والديه وبرّهما في جميع كتبه وعلى ألسنة رسله، فمنهم من يُحسن ومنهم من يُسيء، وكذلك الأمة يُرسل إليها الرسول فمنهم من يؤمن ومنهم من يكذّب. ووصّينا جنس الإنسان بوالديه إحساناً: بكفّ الأذى عنهما، وإيصال الخير إليهما، وطاعتهما في المعروف، وبرّهما بعد موتهما. حملته أمه بمشقة تسعة أشهر ووضعته بمشقة لا يعرفها إلا من قاسى آلامها، وحمله وفصاله ثلاثون شهراً بعضها للحمل وبعضها للإرضاع. حتى إذا بلغ اكتمال قواه البدنية والعقلية وبلغ أربعين سنة قال الإنسان البارّ بوالديه، كأبي بكر الصديق رضي الله عنه إذ بلغ الأربعين بعد البعثة المحمدية بسنتين: رب ألهمني أن أشكر نعمتك التي أنعمت عليّ وعلى والديّ، وهي نعمة الإيمان والتوحيد، إذ آمن هو وأبواه أبو قحافة وأم الخير سلمى، ولم يحصل هذا لأحد من الصحابة، وأن أعمل صالحاً ترضاه، وقد استجاب له ربه فأعتق تسعة أعبد مؤمنين من استرقاق الكافرين منهم بلال رضي الله عنه، وأصلح لي في ذريتي، وقد استجاب الله له فآمن أولاده أجمعون ذكوراً وإناثاً، إني تبت إليك وإني من المسلمين؛ توسّل إلى ربه بالتوبة من الشرك وبالإسلام. أولئك الذين نتقبّل عنهم أحسن ما عملوا ونتجاوز عن سيئاتهم بعد توبتهم في جملة أصحاب الجنة، وعد الصدق الذي كانوا يوعدون في الكتاب.", "h": ["وجوب البر بالوالدين بطاعتهما في المعروف والإحسان إليهما بعد كفّ الأذى عنهما.", "الإشارة إلى أن مدة الحمل قد تكون ستة أشهر فأكثر، وأن الرضاع قد يكون حولين فأقل.", "جواز التوسل بالتوبة إلى الله والانقياد له بالطاعة.", "فضيلة آل أبي بكر الصديق على غيرهم من سائر الصحابة ما عدا آل بيت رسول الله ﷺ.", "بشارة الصديق وأسرته بالجنة، إذ آمنوا كلهم وأسلموا أجمعين وماتوا على ذلك."], "k": "«رب أوزعني أن أشكر نعمتك التي أنعمت عليّ وعلى والديّ»… هل أدعو لوالديّ بالشكر كما أدعو لنفسي؟"}, {"lbl": "الآيات ١٧ – ٢٠", "q": "وَٱلَّذِي قَالَ لِوَٰلِدَيۡهِ أُفّٖ لَّكُمَآ أَتَعِدَانِنِيٓ أَنۡ أُخۡرَجَ وَقَدۡ خَلَتِ ٱلۡقُرُونُ مِن قَبۡلِي وَهُمَا يَسۡتَغِيثَانِ ٱللَّهَ وَيۡلَكَ ءَامِنۡ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞ فَيَقُولُ مَا هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلۡأَوَّلِينَ ﴿١٧﴾ أُوْلَـٰٓئِكَ ٱلَّذِينَ حَقَّ عَلَيۡهِمُ ٱلۡقَوۡلُ فِيٓ أُمَمٖ قَدۡ خَلَتۡ مِن قَبۡلِهِم مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِۖ إِنَّهُمۡ كَانُواْ خَٰسِرِينَ ﴿١٨﴾ وَلِكُلّٖ دَرَجَٰتٞ مِّمَّا عَمِلُواْۖ وَلِيُوَفِّيَهُمۡ أَعۡمَٰلَهُمۡ وَهُمۡ لَا يُظۡلَمُونَ ﴿١٩﴾ وَيَوۡمَ يُعۡرَضُ ٱلَّذِينَ كَفَرُواْ عَلَى ٱلنَّارِ أَذۡهَبۡتُمۡ طَيِّبَٰتِكُمۡ فِي حَيَاتِكُمُ ٱلدُّنۡيَا وَٱسۡتَمۡتَعۡتُم بِهَا فَٱلۡيَوۡمَ تُجۡزَوۡنَ عَذَابَ ٱلۡهُونِ بِمَا كُنتُمۡ تَسۡتَكۡبِرُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَبِمَا كُنتُمۡ تَفۡسُقُونَ ﴿٢٠﴾", "w": [["والذي قال لوالديه", "اسم موصول استُعمل في الجنس فدلّ على متعدد، بدليل الخبر عنه: أولئك الذين حقّ عليهم القول."], ["أفٍّ لكما", "نتناً وقبحاً لكما."], ["أتعدانني أن أُخرج", "من القبر حياً بعد موتي."], ["وقد خلت القرون من قبلي", "مضت الأمم قبلي ولم يخرج منها أحد من قبره."], ["وهما يستغيثان الله", "يطلبان الغوث برجوع ولدهما إلى الإيمان بعد الإلحاد والكفر."], ["ويلك آمن", "يقولان له: إن لم ترجع هلكت، آمن."], ["إن وعد الله حق", "وعد العباد بالرجوع إليه ومحاسبتهم ومجازاتهم."], ["ما هذا إلا أساطير الأولين", "ما القول ببعث الناس أحياء بعد الموت إلا أكاذيب الأولين."], ["أولئك الذين حقّ عليهم القول", "وجب عليهم القول بالعذاب يوم القيامة."], ["في أمم قد خلت من قبلهم", "في جملة أمم قد مضت من قبلهم من الجن والإنس."], ["ولكلٍّ درجات مما عملوا", "للمؤمنين الأبرار درجات في الجنة، وللكفار الفجار دركات في النار."], ["أذهبتم طيباتكم في حياتكم الدنيا", "يقال لهم: أذهبتم طيباتكم باشتغالكم بملذّاتكم."], ["فاليوم تُجزون عذاب الهون", "جزاؤكم عذاب الهوان."], ["بما كنتم تستكبرون في الأرض بغير الحق", "إذ لا حق لكم في الكبر، والكبرياء لله ولم يأذن لكم فيه."], ["وبما كنتم تفسقون", "تخرجون عن طاعة الله ورسوله."]], "m": "لما ذكر الرجل المؤمن وأعماله الصالحة ذكر هنا الرجل الكافر وأعماله الباطلة، ترغيباً وترهيباً: يخبر تعالى عن أخبث إنسان، الملحد العاقّ لوالديه المنكر للبعث، إذ قال لأمه وأبيه: أفٍّ لكما، أتعدانني أن أُخرج من قبري حياً بعد موتي وقد مضت أمم وشعوب قبلي ولم يخرج منها أحد؟ إن هذا لتخلّف عقلي وتأخّر حضاري. ووالداه يستغيثان الله طلباً لهداية ولدهما الملحد، ويقولان له: ويلك، هلكت، آمن بالبعث والجزاء، وصلّ وصم، واترك الزنا والخمر، إن وعد الله حق، فيردّ عليهما: ما هذا إلا أكاذيب الأولين التي كانوا يقصّونها في مجالسهم. أولئك الذين وجب عليهم العذاب في جملة أمم سبقتهم في الإلحاد من الجن والإنس، إنهم كانوا خاسرين، وأي خسران أعظم من عبد يخسر نفسه وأهله ويعيش في جهنم خالداً؟ ولكلٍّ من المؤمنين البارّين والكافرين العاقّين درجات مما عملوا: درجات المؤمنين في الجنة تذهب في علوّ متزايد، ودرجات الكافرين في النار تذهب في سفل متزايد، وليوفّيهم أعمالهم وهم لا يُظلمون. واذكر لهم يوم يُعرض الذين كفروا على النار ويقال لهم توبيخاً: أذهبتم طيباتكم في حياتكم الدنيا بإقبالكم على الشهوات ناسين الدار الآخرة، فلم تُبقوا للآخرة شيئاً، فاليوم تُجزون عذاب الهوان بما كنتم تستكبرون في الأرض بغير الحق لضعفكم وعجزكم، إنما الكبرياء لله الملك الحق، وبما كنتم تفسقون عن طاعة ربكم ورسوله.", "h": ["حرمة عقوق الوالدين، وأنها من الكبائر.", "بيان حنان الوالدين وحبهما لولدهما، وبذل كل ما يقدران عليه من أجل إسعاده وهدايته.", "التحذير من الانغماس في الملاذّ والشهوات والاستمتاع.", "التحذير من الكبر والفسق، وأن الكبر من أعمال القلوب والفسق من أعمال الجوارح.", "بيان مدى فهم السلف الصالح لهذه الآية: «أذهبتم طيباتكم في حياتكم الدنيا واستمتعتم بها»."], "k": "«أذهبتم طيباتكم في حياتكم الدنيا»… كم من طيباتي أستبقيه للآخرة؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 373;
insert into public.tdb_cards(topic, i, body) select 373, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ١٥ – ١٦", "q": "وَوَصَّيۡنَا ٱلۡإِنسَٰنَ بِوَٰلِدَيۡهِ إِحۡسَٰنًاۖ حَمَلَتۡهُ أُمُّهُۥ كُرۡهٗا وَوَضَعَتۡهُ كُرۡهٗاۖ وَحَمۡلُهُۥ وَفِصَٰلُهُۥ ثَلَٰثُونَ شَهۡرًاۚ حَتَّىٰٓ إِذَا بَلَغَ أَشُدَّهُۥ وَبَلَغَ أَرۡبَعِينَ سَنَةٗ قَالَ رَبِّ أَوۡزِعۡنِيٓ أَنۡ أَشۡكُرَ نِعۡمَتَكَ ٱلَّتِيٓ أَنۡعَمۡتَ عَلَيَّ وَعَلَىٰ وَٰلِدَيَّ وَأَنۡ أَعۡمَلَ صَٰلِحٗا تَرۡضَىٰهُ وَأَصۡلِحۡ لِي فِي ذُرِّيَّتِيٓۖ إِنِّي تُبۡتُ إِلَيۡكَ وَإِنِّي مِنَ ٱلۡمُسۡلِمِينَ ﴿١٥﴾ أُوْلَـٰٓئِكَ ٱلَّذِينَ نَتَقَبَّلُ عَنۡهُمۡ أَحۡسَنَ مَا عَمِلُواْ وَنَتَجَاوَزُ عَن سَيِّـَٔاتِهِمۡ فِيٓ أَصۡحَٰبِ ٱلۡجَنَّةِۖ وَعۡدَ ٱلصِّدۡقِ ٱلَّذِي كَانُواْ يُوعَدُونَ ﴿١٦﴾", "w": [["ووصّينا الإنسان بوالديه", "أمرناه أمراً مؤكداً بالإيصاء."], ["إحساناً", "أن يُحسن بهما إحساناً، وهو المعاملة بالحسنى."], ["حملته أمه كُرهاً ووضعته كُرهاً", "حملته في بطنها على مشقة، وولدته كذلك على مشقة."], ["وحمله وفصاله ثلاثون شهراً", "مدة حمله في بطنها وفطامه من الرضاع ثلاثون شهراً."], ["حتى إذا بلغ أشدّه", "اكتمال قوته البدنية والعقلية، وهي من الثلاث والثلاثين فما فوق."], ["رب أوزعني أن أشكر نعمتك", "ألهمني ووفّقني أن أشكر نعمتك بصرفها فيما تحب."], ["وأن أعمل صالحاً ترضاه", "عملاً صالحاً تتقبّله مني."], ["ونتجاوز عن سيئاتهم", "فلا نؤاخذهم بها بل نغفرها."], ["في أصحاب الجنة", "في جملة أصحاب الجنة وعدادهم."], ["وعد الصدق الذي كانوا يوعدون", "في مثل قوله: وعد الله المؤمنين والمؤمنات جنات تجري من تحتها الأنهار."]], "m": "الفرد كالجماعة: أوصى تعالى الإنسان بالإحسان إلى والديه وبرّهما في جميع كتبه وعلى ألسنة رسله، فمنهم من يُحسن ومنهم من يُسيء، وكذلك الأمة يُرسل إليها الرسول فمنهم من يؤمن ومنهم من يكذّب. ووصّينا جنس الإنسان بوالديه إحساناً: بكفّ الأذى عنهما، وإيصال الخير إليهما، وطاعتهما في المعروف، وبرّهما بعد موتهما. حملته أمه بمشقة تسعة أشهر ووضعته بمشقة لا يعرفها إلا من قاسى آلامها، وحمله وفصاله ثلاثون شهراً بعضها للحمل وبعضها للإرضاع. حتى إذا بلغ اكتمال قواه البدنية والعقلية وبلغ أربعين سنة قال الإنسان البارّ بوالديه، كأبي بكر الصديق رضي الله عنه إذ بلغ الأربعين بعد البعثة المحمدية بسنتين: رب ألهمني أن أشكر نعمتك التي أنعمت عليّ وعلى والديّ، وهي نعمة الإيمان والتوحيد، إذ آمن هو وأبواه أبو قحافة وأم الخير سلمى، ولم يحصل هذا لأحد من الصحابة، وأن أعمل صالحاً ترضاه، وقد استجاب له ربه فأعتق تسعة أعبد مؤمنين من استرقاق الكافرين منهم بلال رضي الله عنه، وأصلح لي في ذريتي، وقد استجاب الله له فآمن أولاده أجمعون ذكوراً وإناثاً، إني تبت إليك وإني من المسلمين؛ توسّل إلى ربه بالتوبة من الشرك وبالإسلام. أولئك الذين نتقبّل عنهم أحسن ما عملوا ونتجاوز عن سيئاتهم بعد توبتهم في جملة أصحاب الجنة، وعد الصدق الذي كانوا يوعدون في الكتاب.", "h": ["وجوب البر بالوالدين بطاعتهما في المعروف والإحسان إليهما بعد كفّ الأذى عنهما.", "الإشارة إلى أن مدة الحمل قد تكون ستة أشهر فأكثر، وأن الرضاع قد يكون حولين فأقل.", "جواز التوسل بالتوبة إلى الله والانقياد له بالطاعة.", "فضيلة آل أبي بكر الصديق على غيرهم من سائر الصحابة ما عدا آل بيت رسول الله ﷺ.", "بشارة الصديق وأسرته بالجنة، إذ آمنوا كلهم وأسلموا أجمعين وماتوا على ذلك."], "k": "«رب أوزعني أن أشكر نعمتك التي أنعمت عليّ وعلى والديّ»… هل أدعو لوالديّ بالشكر كما أدعو لنفسي؟"}, {"lbl": "الآيات ١٧ – ٢٠", "q": "وَٱلَّذِي قَالَ لِوَٰلِدَيۡهِ أُفّٖ لَّكُمَآ أَتَعِدَانِنِيٓ أَنۡ أُخۡرَجَ وَقَدۡ خَلَتِ ٱلۡقُرُونُ مِن قَبۡلِي وَهُمَا يَسۡتَغِيثَانِ ٱللَّهَ وَيۡلَكَ ءَامِنۡ إِنَّ وَعۡدَ ٱللَّهِ حَقّٞ فَيَقُولُ مَا هَٰذَآ إِلَّآ أَسَٰطِيرُ ٱلۡأَوَّلِينَ ﴿١٧﴾ أُوْلَـٰٓئِكَ ٱلَّذِينَ حَقَّ عَلَيۡهِمُ ٱلۡقَوۡلُ فِيٓ أُمَمٖ قَدۡ خَلَتۡ مِن قَبۡلِهِم مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِۖ إِنَّهُمۡ كَانُواْ خَٰسِرِينَ ﴿١٨﴾ وَلِكُلّٖ دَرَجَٰتٞ مِّمَّا عَمِلُواْۖ وَلِيُوَفِّيَهُمۡ أَعۡمَٰلَهُمۡ وَهُمۡ لَا يُظۡلَمُونَ ﴿١٩﴾ وَيَوۡمَ يُعۡرَضُ ٱلَّذِينَ كَفَرُواْ عَلَى ٱلنَّارِ أَذۡهَبۡتُمۡ طَيِّبَٰتِكُمۡ فِي حَيَاتِكُمُ ٱلدُّنۡيَا وَٱسۡتَمۡتَعۡتُم بِهَا فَٱلۡيَوۡمَ تُجۡزَوۡنَ عَذَابَ ٱلۡهُونِ بِمَا كُنتُمۡ تَسۡتَكۡبِرُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَبِمَا كُنتُمۡ تَفۡسُقُونَ ﴿٢٠﴾", "w": [["والذي قال لوالديه", "اسم موصول استُعمل في الجنس فدلّ على متعدد، بدليل الخبر عنه: أولئك الذين حقّ عليهم القول."], ["أفٍّ لكما", "نتناً وقبحاً لكما."], ["أتعدانني أن أُخرج", "من القبر حياً بعد موتي."], ["وقد خلت القرون من قبلي", "مضت الأمم قبلي ولم يخرج منها أحد من قبره."], ["وهما يستغيثان الله", "يطلبان الغوث برجوع ولدهما إلى الإيمان بعد الإلحاد والكفر."], ["ويلك آمن", "يقولان له: إن لم ترجع هلكت، آمن."], ["إن وعد الله حق", "وعد العباد بالرجوع إليه ومحاسبتهم ومجازاتهم."], ["ما هذا إلا أساطير الأولين", "ما القول ببعث الناس أحياء بعد الموت إلا أكاذيب الأولين."], ["أولئك الذين حقّ عليهم القول", "وجب عليهم القول بالعذاب يوم القيامة."], ["في أمم قد خلت من قبلهم", "في جملة أمم قد مضت من قبلهم من الجن والإنس."], ["ولكلٍّ درجات مما عملوا", "للمؤمنين الأبرار درجات في الجنة، وللكفار الفجار دركات في النار."], ["أذهبتم طيباتكم في حياتكم الدنيا", "يقال لهم: أذهبتم طيباتكم باشتغالكم بملذّاتكم."], ["فاليوم تُجزون عذاب الهون", "جزاؤكم عذاب الهوان."], ["بما كنتم تستكبرون في الأرض بغير الحق", "إذ لا حق لكم في الكبر، والكبرياء لله ولم يأذن لكم فيه."], ["وبما كنتم تفسقون", "تخرجون عن طاعة الله ورسوله."]], "m": "لما ذكر الرجل المؤمن وأعماله الصالحة ذكر هنا الرجل الكافر وأعماله الباطلة، ترغيباً وترهيباً: يخبر تعالى عن أخبث إنسان، الملحد العاقّ لوالديه المنكر للبعث، إذ قال لأمه وأبيه: أفٍّ لكما، أتعدانني أن أُخرج من قبري حياً بعد موتي وقد مضت أمم وشعوب قبلي ولم يخرج منها أحد؟ إن هذا لتخلّف عقلي وتأخّر حضاري. ووالداه يستغيثان الله طلباً لهداية ولدهما الملحد، ويقولان له: ويلك، هلكت، آمن بالبعث والجزاء، وصلّ وصم، واترك الزنا والخمر، إن وعد الله حق، فيردّ عليهما: ما هذا إلا أكاذيب الأولين التي كانوا يقصّونها في مجالسهم. أولئك الذين وجب عليهم العذاب في جملة أمم سبقتهم في الإلحاد من الجن والإنس، إنهم كانوا خاسرين، وأي خسران أعظم من عبد يخسر نفسه وأهله ويعيش في جهنم خالداً؟ ولكلٍّ من المؤمنين البارّين والكافرين العاقّين درجات مما عملوا: درجات المؤمنين في الجنة تذهب في علوّ متزايد، ودرجات الكافرين في النار تذهب في سفل متزايد، وليوفّيهم أعمالهم وهم لا يُظلمون. واذكر لهم يوم يُعرض الذين كفروا على النار ويقال لهم توبيخاً: أذهبتم طيباتكم في حياتكم الدنيا بإقبالكم على الشهوات ناسين الدار الآخرة، فلم تُبقوا للآخرة شيئاً، فاليوم تُجزون عذاب الهوان بما كنتم تستكبرون في الأرض بغير الحق لضعفكم وعجزكم، إنما الكبرياء لله الملك الحق، وبما كنتم تفسقون عن طاعة ربكم ورسوله.", "h": ["حرمة عقوق الوالدين، وأنها من الكبائر.", "بيان حنان الوالدين وحبهما لولدهما، وبذل كل ما يقدران عليه من أجل إسعاده وهدايته.", "التحذير من الانغماس في الملاذّ والشهوات والاستمتاع.", "التحذير من الكبر والفسق، وأن الكبر من أعمال القلوب والفسق من أعمال الجوارح.", "بيان مدى فهم السلف الصالح لهذه الآية: «أذهبتم طيباتكم في حياتكم الدنيا واستمتعتم بها»."], "k": "«أذهبتم طيباتكم في حياتكم الدنيا»… كم من طيباتي أستبقيه للآخرة؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (374, 46, 21, 28, 'سورة الأحقاف ٢١ – ٢٨', 'الأحقاف: واذكر أخا عاد إذ أنذر قومه بالأحقاف', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 374) = $j$[{"lbl": "الآيات ٢١ – ٢٥", "q": "۞وَٱذۡكُرۡ أَخَا عَادٍ إِذۡ أَنذَرَ قَوۡمَهُۥ بِٱلۡأَحۡقَافِ وَقَدۡ خَلَتِ ٱلنُّذُرُ مِنۢ بَيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِهِۦٓ أَلَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ عَظِيمٖ ﴿٢١﴾ قَالُوٓاْ أَجِئۡتَنَا لِتَأۡفِكَنَا عَنۡ ءَالِهَتِنَا فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ ﴿٢٢﴾ قَالَ إِنَّمَا ٱلۡعِلۡمُ عِندَ ٱللَّهِ وَأُبَلِّغُكُم مَّآ أُرۡسِلۡتُ بِهِۦ وَلَٰكِنِّيٓ أَرَىٰكُمۡ قَوۡمٗا تَجۡهَلُونَ ﴿٢٣﴾ فَلَمَّا رَأَوۡهُ عَارِضٗا مُّسۡتَقۡبِلَ أَوۡدِيَتِهِمۡ قَالُواْ هَٰذَا عَارِضٞ مُّمۡطِرُنَاۚ بَلۡ هُوَ مَا ٱسۡتَعۡجَلۡتُم بِهِۦۖ رِيحٞ فِيهَا عَذَابٌ أَلِيمٞ ﴿٢٤﴾ تُدَمِّرُ كُلَّ شَيۡءِۭ بِأَمۡرِ رَبِّهَا فَأَصۡبَحُواْ لَا يُرَىٰٓ إِلَّا مَسَٰكِنُهُمۡۚ كَذَٰلِكَ نَجۡزِي ٱلۡقَوۡمَ ٱلۡمُجۡرِمِينَ ﴿٢٥﴾", "w": [["واذكر أخا عاد", "نبي الله هوداً ﵇."], ["إذ أنذر قومه بالأحقاف", "خوّف قومه عذاب الله بوادي الأحقاف."], ["وقد خلت النذر", "مضت الرسل."], ["من بين يديه ومن خلفه", "من قبله ومن بعده إلى أممهم."], ["ألا تعبدوا إلا الله", "أنذروهم بألا يعبدوا إلا الله."], ["إني أخاف عليكم عذاب يوم عظيم", "إن عبدتم غير الله، عذاب يوم هائل."], ["لتأفكنا عن آلهتنا", "لتصرفنا عن عبادتها."], ["فأتنا بما تعدنا", "من العذاب على عبادتها."], ["إنما العلم عند الله", "علم مجيء العذاب ليس لي، وإنما هو لله وحده."], ["وأبلّغكم ما أُرسلت به", "إنما أنا رسول أبلّغكم ما أرسلني به ربي."], ["ولكني أراكم قوماً تجهلون", "تجهلون حظوظ أنفسكم وما ينبغي لها من الإسعاد، وإلا كيف تستعجلون العذاب؟"], ["فلما رأوه عارضاً", "رأوا العذاب سحاباً يعرض في الأفق."], ["مستقبل أوديتهم", "متجهاً نحو أوديتهم التي فيها مزارعهم."], ["هذا عارض ممطرنا", "قالوا مشيرين إلى السحاب: هذا عارض ممطرنا."], ["بل هو ما استعجلتم به", "ليس هو بالعارض الممطر، بل العذاب الذي استعجلتموه."], ["ريح تدمّر كل شيء", "ريح عاتية تهلك كل شيء تمرّ به."], ["بأمر ربها", "بإذن ربها تعالى."], ["فأصبحوا لا يُرى إلا مساكنهم", "أهلكتهم عن آخرهم فلم يبق إلا مساكنهم."], ["كذلك نجزي القوم المجرمين", "كذلك الجزاء بالهلاك الشامل نجزي المجرمين من سائر الأمم."]], "m": "ما زال السياق في طلب هداية قوم النبي ﷺ: واذكر لقومك للعبرة أخا عاد هوداً ﵇، والأخوّة هنا أخوّة نسب لا دين، إذ خوّف قومه عذاب الله إن لم يتوبوا ويوحّدوه، والأحقاف وادي القوم الذي به مزارعهم ومنازلهم، ما بين حضرموت ومهرة وعُمان جنوب الجزيرة العربية. وقد مضت الرسل قبله وبعده إلى أممهم، فلم يكن هود أول نذير، وكل رسول أنذر أمته ألا تعبدوا إلا الله، وهو معنى لا إله إلا الله التي دعا إليها محمد ﷺ، إني أخاف عليكم عذاب يوم عظيم. فقالوا: أجئتنا لتصرفنا عن عبادة آلهتنا؟ فأتنا بما تعدنا من العذاب إن كنت من الصادقين. فقال: إنما علم مجيء العذاب وتحديد وقته لله منزله، ومهمتي أن أنذركم وأبلّغكم ما أُرسلت به، ولكني أراكم قوماً تجهلون ما يضركم وما ينفعكم، إذ المفروض أن تطلبوا الرحمة لا العذاب. فلما رأوا العذاب سحاباً متجهاً نحو أوديتهم قالوا: هذا سحاب ممطر أراضينا المصابة بالجفاف الشديد، قال تعالى: بل هو العذاب الذي طالبتم به لجهلكم وخفّة أحلامكم، ريح فيها عذاب موجع تدمّر كل شيء تمرّ به بإذن ربها، وقد أتت عليهم عن آخرهم ولم ينجُ إلا هود والذين آمنوا معه برحمة من الله، فأصبحوا لا يرى الرائي إلا مساكنهم خالية، كذلك نجزي المجرمين المفسدين أنفسهم بالشرك والمعاصي.", "h": ["بيان سنة الله في الأمم في إرسال الرسل إليهم.", "بيان مهمة الرسل، وهي النذارة والبلاغ.", "بيان سفه وجهل الأمم التي تطالب بالعذاب وتستعجل به.", "بيان أن عاداً أُهلكت بالريح الدَّبور، وأن نبينا محمداً ﷺ نُصر بريح الصَّبا كما في الحديث.", "بيان سنة الله تعالى في إهلاك المجرمين."], "k": "«قالوا هذا عارض ممطرنا بل هو ما استعجلتم به»… كم شيئاً ظننته خيراً فكان بلاءً، أو العكس؟ فهل أثق في علم الله؟"}, {"lbl": "الآيات ٢٦ – ٢٨", "q": "وَلَقَدۡ مَكَّنَّـٰهُمۡ فِيمَآ إِن مَّكَّنَّـٰكُمۡ فِيهِ وَجَعَلۡنَا لَهُمۡ سَمۡعٗا وَأَبۡصَٰرٗا وَأَفۡـِٔدَةٗ فَمَآ أَغۡنَىٰ عَنۡهُمۡ سَمۡعُهُمۡ وَلَآ أَبۡصَٰرُهُمۡ وَلَآ أَفۡـِٔدَتُهُم مِّن شَيۡءٍ إِذۡ كَانُواْ يَجۡحَدُونَ بِـَٔايَٰتِ ٱللَّهِ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ﴿٢٦﴾ وَلَقَدۡ أَهۡلَكۡنَا مَا حَوۡلَكُم مِّنَ ٱلۡقُرَىٰ وَصَرَّفۡنَا ٱلۡأٓيَٰتِ لَعَلَّهُمۡ يَرۡجِعُونَ ﴿٢٧﴾ فَلَوۡلَا نَصَرَهُمُ ٱلَّذِينَ ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ قُرۡبَانًا ءَالِهَةَۢۖ بَلۡ ضَلُّواْ عَنۡهُمۡۚ وَذَٰلِكَ إِفۡكُهُمۡ وَمَا كَانُواْ يَفۡتَرُونَ ﴿٢٨﴾", "w": [["ولقد مكّنّاهم فيما إن مكّنّاكم فيه", "مكّنّا قوم عاد من القوة ما لم نمكّنكم أنتم منه."], ["وجعلنا لهم سمعاً وأبصاراً وأفئدة", "أسماعاً وأبصاراً وقلوباً."], ["فما أغنى عنهم سمعهم ولا أبصارهم ولا أفئدتهم من شيء", "لم يغنِ عنهم شيئاً من الإغناء."], ["إذ كانوا يجحدون بآيات الله", "لعلّة هي أنهم كانوا يجحدون بحججه البيّنة."], ["وحاق بهم ما كانوا به يستهزئون", "نزل بهم العذاب الذي كانوا يستهزئون به."], ["ولقد أهلكنا ما حولكم من القرى", "من أهل القرى كعاد وثمود وقوم لوط وأصحاب مدين."], ["وصرّفنا الآيات لعلهم يرجعون", "كرّرنا الحجج وضربنا الأمثال ونوّعنا الأساليب لعلهم يرجعون إلى الحق."], ["فلولا نصرهم الذين اتخذوا من دون الله قرباناً آلهة", "فهلّا نصرهم بدفع العذاب الذين اتخذوهم آلهة يتقرّبون بهم إلى الله في زعمهم."], ["بل ضلّوا عنهم", "غابوا عنهم عند نزول العذاب."], ["وذلك إفكهم وما كانوا يفترون", "خذلان آلهتهم لهم وغيابها عنهم هو حقيقة كذبهم وافترائهم."]], "m": "ما زال السياق في طلب هداية قريش، فلما قصّ عليهم قصة عاد وما فيها من عظات قال: ولقد مكّنّا قوم عاد في الأرض فأعطيناهم من مظاهر القوة المادية ما لم نعطكم يا معشر كفار قريش، وجعلنا لهم أسماعاً وأبصاراً وقلوباً، فما أغنى عنهم ذلك شيئاً، إذ كانوا يجحدون بحجج الله الدالة على وجوب توحيده، ونزل بهم العذاب الذي كانوا إذا خُوّفوا به استهزؤوا وسخروا. ولقد أهلكنا ما حولكم من القرى كعاد وثمود وقوم لوط وأصحاب مدين، وكرّرنا الحجج وضربنا الأمثال ونوّعنا العظات لعلهم يرجعون إلى التوحيد والاستقامة، فأبوا إلا الإصرار على الشرك فأهلكناهم. فهلّا نصرهم الذين اتخذوهم من دون الله آلهة يتقرّبون بها إلى الله في زعمهم؟ ما نصروهم، بل غابوا عنهم فلم يعثروا عليهم بالكلية، وذلك الذي تم لهم من الخذلان والعذاب هو نتيجة كذبهم وافترائهم الذي كانوا يعيشون عليه.", "h": ["بيان أن الإعراض عن دين الله والإصرار على الفسق عن أمر الله والاستمرار على الخروج على طاعته إذا استوجب صاحبه العذاب ونزل به لم يغن عنه ذكاؤه ولا دهاؤه ولا علمه وحضارته ولا علوّه وتطاوله.", "بيان أن الآيات والحجج وضرب الأمثال وسوق العبر والعظات لا تنفع في هداية العبد إذا لم يُرد الله هدايته، «إن الله لا يهدي من يُضل»، ويحيق به العذاب ويهلكه جزاء تكذيبه وكفره وإعراضه وفسقه.", "بيان غياب الشركاء من الأنداد التي كانت تُعبد عن عابديها فضلاً عن نصرتها لهم، وذلك الخذلان هو جزاء كذبهم وافترائهم في الحياة الدنيا."], "k": "«فما أغنى عنهم سمعهم ولا أبصارهم ولا أفئدتهم»… حواسّي نعمة؛ فهل أستعملها في الاهتداء أم في الغفلة؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 374;
insert into public.tdb_cards(topic, i, body) select 374, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢١ – ٢٥", "q": "۞وَٱذۡكُرۡ أَخَا عَادٍ إِذۡ أَنذَرَ قَوۡمَهُۥ بِٱلۡأَحۡقَافِ وَقَدۡ خَلَتِ ٱلنُّذُرُ مِنۢ بَيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِهِۦٓ أَلَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ عَظِيمٖ ﴿٢١﴾ قَالُوٓاْ أَجِئۡتَنَا لِتَأۡفِكَنَا عَنۡ ءَالِهَتِنَا فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ ﴿٢٢﴾ قَالَ إِنَّمَا ٱلۡعِلۡمُ عِندَ ٱللَّهِ وَأُبَلِّغُكُم مَّآ أُرۡسِلۡتُ بِهِۦ وَلَٰكِنِّيٓ أَرَىٰكُمۡ قَوۡمٗا تَجۡهَلُونَ ﴿٢٣﴾ فَلَمَّا رَأَوۡهُ عَارِضٗا مُّسۡتَقۡبِلَ أَوۡدِيَتِهِمۡ قَالُواْ هَٰذَا عَارِضٞ مُّمۡطِرُنَاۚ بَلۡ هُوَ مَا ٱسۡتَعۡجَلۡتُم بِهِۦۖ رِيحٞ فِيهَا عَذَابٌ أَلِيمٞ ﴿٢٤﴾ تُدَمِّرُ كُلَّ شَيۡءِۭ بِأَمۡرِ رَبِّهَا فَأَصۡبَحُواْ لَا يُرَىٰٓ إِلَّا مَسَٰكِنُهُمۡۚ كَذَٰلِكَ نَجۡزِي ٱلۡقَوۡمَ ٱلۡمُجۡرِمِينَ ﴿٢٥﴾", "w": [["واذكر أخا عاد", "نبي الله هوداً ﵇."], ["إذ أنذر قومه بالأحقاف", "خوّف قومه عذاب الله بوادي الأحقاف."], ["وقد خلت النذر", "مضت الرسل."], ["من بين يديه ومن خلفه", "من قبله ومن بعده إلى أممهم."], ["ألا تعبدوا إلا الله", "أنذروهم بألا يعبدوا إلا الله."], ["إني أخاف عليكم عذاب يوم عظيم", "إن عبدتم غير الله، عذاب يوم هائل."], ["لتأفكنا عن آلهتنا", "لتصرفنا عن عبادتها."], ["فأتنا بما تعدنا", "من العذاب على عبادتها."], ["إنما العلم عند الله", "علم مجيء العذاب ليس لي، وإنما هو لله وحده."], ["وأبلّغكم ما أُرسلت به", "إنما أنا رسول أبلّغكم ما أرسلني به ربي."], ["ولكني أراكم قوماً تجهلون", "تجهلون حظوظ أنفسكم وما ينبغي لها من الإسعاد، وإلا كيف تستعجلون العذاب؟"], ["فلما رأوه عارضاً", "رأوا العذاب سحاباً يعرض في الأفق."], ["مستقبل أوديتهم", "متجهاً نحو أوديتهم التي فيها مزارعهم."], ["هذا عارض ممطرنا", "قالوا مشيرين إلى السحاب: هذا عارض ممطرنا."], ["بل هو ما استعجلتم به", "ليس هو بالعارض الممطر، بل العذاب الذي استعجلتموه."], ["ريح تدمّر كل شيء", "ريح عاتية تهلك كل شيء تمرّ به."], ["بأمر ربها", "بإذن ربها تعالى."], ["فأصبحوا لا يُرى إلا مساكنهم", "أهلكتهم عن آخرهم فلم يبق إلا مساكنهم."], ["كذلك نجزي القوم المجرمين", "كذلك الجزاء بالهلاك الشامل نجزي المجرمين من سائر الأمم."]], "m": "ما زال السياق في طلب هداية قوم النبي ﷺ: واذكر لقومك للعبرة أخا عاد هوداً ﵇، والأخوّة هنا أخوّة نسب لا دين، إذ خوّف قومه عذاب الله إن لم يتوبوا ويوحّدوه، والأحقاف وادي القوم الذي به مزارعهم ومنازلهم، ما بين حضرموت ومهرة وعُمان جنوب الجزيرة العربية. وقد مضت الرسل قبله وبعده إلى أممهم، فلم يكن هود أول نذير، وكل رسول أنذر أمته ألا تعبدوا إلا الله، وهو معنى لا إله إلا الله التي دعا إليها محمد ﷺ، إني أخاف عليكم عذاب يوم عظيم. فقالوا: أجئتنا لتصرفنا عن عبادة آلهتنا؟ فأتنا بما تعدنا من العذاب إن كنت من الصادقين. فقال: إنما علم مجيء العذاب وتحديد وقته لله منزله، ومهمتي أن أنذركم وأبلّغكم ما أُرسلت به، ولكني أراكم قوماً تجهلون ما يضركم وما ينفعكم، إذ المفروض أن تطلبوا الرحمة لا العذاب. فلما رأوا العذاب سحاباً متجهاً نحو أوديتهم قالوا: هذا سحاب ممطر أراضينا المصابة بالجفاف الشديد، قال تعالى: بل هو العذاب الذي طالبتم به لجهلكم وخفّة أحلامكم، ريح فيها عذاب موجع تدمّر كل شيء تمرّ به بإذن ربها، وقد أتت عليهم عن آخرهم ولم ينجُ إلا هود والذين آمنوا معه برحمة من الله، فأصبحوا لا يرى الرائي إلا مساكنهم خالية، كذلك نجزي المجرمين المفسدين أنفسهم بالشرك والمعاصي.", "h": ["بيان سنة الله في الأمم في إرسال الرسل إليهم.", "بيان مهمة الرسل، وهي النذارة والبلاغ.", "بيان سفه وجهل الأمم التي تطالب بالعذاب وتستعجل به.", "بيان أن عاداً أُهلكت بالريح الدَّبور، وأن نبينا محمداً ﷺ نُصر بريح الصَّبا كما في الحديث.", "بيان سنة الله تعالى في إهلاك المجرمين."], "k": "«قالوا هذا عارض ممطرنا بل هو ما استعجلتم به»… كم شيئاً ظننته خيراً فكان بلاءً، أو العكس؟ فهل أثق في علم الله؟"}, {"lbl": "الآيات ٢٦ – ٢٨", "q": "وَلَقَدۡ مَكَّنَّـٰهُمۡ فِيمَآ إِن مَّكَّنَّـٰكُمۡ فِيهِ وَجَعَلۡنَا لَهُمۡ سَمۡعٗا وَأَبۡصَٰرٗا وَأَفۡـِٔدَةٗ فَمَآ أَغۡنَىٰ عَنۡهُمۡ سَمۡعُهُمۡ وَلَآ أَبۡصَٰرُهُمۡ وَلَآ أَفۡـِٔدَتُهُم مِّن شَيۡءٍ إِذۡ كَانُواْ يَجۡحَدُونَ بِـَٔايَٰتِ ٱللَّهِ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ ﴿٢٦﴾ وَلَقَدۡ أَهۡلَكۡنَا مَا حَوۡلَكُم مِّنَ ٱلۡقُرَىٰ وَصَرَّفۡنَا ٱلۡأٓيَٰتِ لَعَلَّهُمۡ يَرۡجِعُونَ ﴿٢٧﴾ فَلَوۡلَا نَصَرَهُمُ ٱلَّذِينَ ٱتَّخَذُواْ مِن دُونِ ٱللَّهِ قُرۡبَانًا ءَالِهَةَۢۖ بَلۡ ضَلُّواْ عَنۡهُمۡۚ وَذَٰلِكَ إِفۡكُهُمۡ وَمَا كَانُواْ يَفۡتَرُونَ ﴿٢٨﴾", "w": [["ولقد مكّنّاهم فيما إن مكّنّاكم فيه", "مكّنّا قوم عاد من القوة ما لم نمكّنكم أنتم منه."], ["وجعلنا لهم سمعاً وأبصاراً وأفئدة", "أسماعاً وأبصاراً وقلوباً."], ["فما أغنى عنهم سمعهم ولا أبصارهم ولا أفئدتهم من شيء", "لم يغنِ عنهم شيئاً من الإغناء."], ["إذ كانوا يجحدون بآيات الله", "لعلّة هي أنهم كانوا يجحدون بحججه البيّنة."], ["وحاق بهم ما كانوا به يستهزئون", "نزل بهم العذاب الذي كانوا يستهزئون به."], ["ولقد أهلكنا ما حولكم من القرى", "من أهل القرى كعاد وثمود وقوم لوط وأصحاب مدين."], ["وصرّفنا الآيات لعلهم يرجعون", "كرّرنا الحجج وضربنا الأمثال ونوّعنا الأساليب لعلهم يرجعون إلى الحق."], ["فلولا نصرهم الذين اتخذوا من دون الله قرباناً آلهة", "فهلّا نصرهم بدفع العذاب الذين اتخذوهم آلهة يتقرّبون بهم إلى الله في زعمهم."], ["بل ضلّوا عنهم", "غابوا عنهم عند نزول العذاب."], ["وذلك إفكهم وما كانوا يفترون", "خذلان آلهتهم لهم وغيابها عنهم هو حقيقة كذبهم وافترائهم."]], "m": "ما زال السياق في طلب هداية قريش، فلما قصّ عليهم قصة عاد وما فيها من عظات قال: ولقد مكّنّا قوم عاد في الأرض فأعطيناهم من مظاهر القوة المادية ما لم نعطكم يا معشر كفار قريش، وجعلنا لهم أسماعاً وأبصاراً وقلوباً، فما أغنى عنهم ذلك شيئاً، إذ كانوا يجحدون بحجج الله الدالة على وجوب توحيده، ونزل بهم العذاب الذي كانوا إذا خُوّفوا به استهزؤوا وسخروا. ولقد أهلكنا ما حولكم من القرى كعاد وثمود وقوم لوط وأصحاب مدين، وكرّرنا الحجج وضربنا الأمثال ونوّعنا العظات لعلهم يرجعون إلى التوحيد والاستقامة، فأبوا إلا الإصرار على الشرك فأهلكناهم. فهلّا نصرهم الذين اتخذوهم من دون الله آلهة يتقرّبون بها إلى الله في زعمهم؟ ما نصروهم، بل غابوا عنهم فلم يعثروا عليهم بالكلية، وذلك الذي تم لهم من الخذلان والعذاب هو نتيجة كذبهم وافترائهم الذي كانوا يعيشون عليه.", "h": ["بيان أن الإعراض عن دين الله والإصرار على الفسق عن أمر الله والاستمرار على الخروج على طاعته إذا استوجب صاحبه العذاب ونزل به لم يغن عنه ذكاؤه ولا دهاؤه ولا علمه وحضارته ولا علوّه وتطاوله.", "بيان أن الآيات والحجج وضرب الأمثال وسوق العبر والعظات لا تنفع في هداية العبد إذا لم يُرد الله هدايته، «إن الله لا يهدي من يُضل»، ويحيق به العذاب ويهلكه جزاء تكذيبه وكفره وإعراضه وفسقه.", "بيان غياب الشركاء من الأنداد التي كانت تُعبد عن عابديها فضلاً عن نصرتها لهم، وذلك الخذلان هو جزاء كذبهم وافترائهم في الحياة الدنيا."], "k": "«فما أغنى عنهم سمعهم ولا أبصارهم ولا أفئدتهم»… حواسّي نعمة؛ فهل أستعملها في الاهتداء أم في الغفلة؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (375, 46, 29, 35, 'سورة الأحقاف ٢٩ – ٣٥', 'الأحقاف: فاصبر كما صبر أولو العزم من الرسل', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 375) = $j$[{"lbl": "الآيات ٢٩ – ٣٢", "q": "وَإِذۡ صَرَفۡنَآ إِلَيۡكَ نَفَرٗا مِّنَ ٱلۡجِنِّ يَسۡتَمِعُونَ ٱلۡقُرۡءَانَ فَلَمَّا حَضَرُوهُ قَالُوٓاْ أَنصِتُواْۖ فَلَمَّا قُضِيَ وَلَّوۡاْ إِلَىٰ قَوۡمِهِم مُّنذِرِينَ ﴿٢٩﴾ قَالُواْ يَٰقَوۡمَنَآ إِنَّا سَمِعۡنَا كِتَٰبًا أُنزِلَ مِنۢ بَعۡدِ مُوسَىٰ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ يَهۡدِيٓ إِلَى ٱلۡحَقِّ وَإِلَىٰ طَرِيقٖ مُّسۡتَقِيمٖ ﴿٣٠﴾ يَٰقَوۡمَنَآ أَجِيبُواْ دَاعِيَ ٱللَّهِ وَءَامِنُواْ بِهِۦ يَغۡفِرۡ لَكُم مِّن ذُنُوبِكُمۡ وَيُجِرۡكُم مِّنۡ عَذَابٍ أَلِيمٖ ﴿٣١﴾ وَمَن لَّا يُجِبۡ دَاعِيَ ٱللَّهِ فَلَيۡسَ بِمُعۡجِزٖ فِي ٱلۡأَرۡضِ وَلَيۡسَ لَهُۥ مِن دُونِهِۦٓ أَوۡلِيَآءُۚ أُوْلَـٰٓئِكَ فِي ضَلَٰلٖ مُّبِينٍ ﴿٣٢﴾", "w": [["وإذ صرفنا إليك نفراً من الجن", "واذكر إذ أملنا إليك نفراً من الجن، جن نصيبين أو نينوى."], ["فلما حضروه قالوا أنصتوا", "حضروا سماع القرآن فقال بعضهم لبعض: أصغوا لاستماعه."], ["فلما قُضي ولّوا إلى قومهم منذرين", "فلما فرغ من قراءته رجعوا إلى قومهم مخوّفين."], ["مصدّقاً لما بين يديه", "من الكتب السابقة كالتوراة والإنجيل والزبور."], ["يهدي إلى الحق وإلى طريق مستقيم", "إلى الحق من العقائد والشرائع، وإلى الإسلام."], ["ويُجركم من عذاب أليم", "ويحفظكم من عذاب يوم القيامة."], ["فليس بمعجز في الأرض", "ليس بمعجز الله هرباً منه فيفوته."], ["أولئك في ضلال مبين", "الذين لم يجيبوا داعي الله محمداً ﷺ في ضلال عن طريق الإسعاد والكمال ظاهر بيّن."]], "m": "بعد أن ذكّر قوم النبي ﷺ بعاد وما أصابها، ذكّرهم هنا بما هو تقريع لهم إذ أراهم أن الجن خير منهم لسرعة استجابتهم للدعوة وقيامهم بتبليغها: واذكر لقومك إذ أملنا إليك نفراً من الجن، ما بين السبعة إلى التسعة من جن نصيبين، من أشرافهم وسادتهم، وأنت تقرأ في صلاة الصبح ببطن نخلة بين مكة والطائف، فلما حضروا قال بعضهم لبعض: أنصتوا ولا تشوّشوا، فلما فرغ رجعوا إلى قومهم منذرين من عذاب الله إن استمروا على الشرك، قالوا: يا قومنا إنا سمعنا كتاباً أُنزل من بعد موسى، هو القرآن، مصدّقاً لما بين يديه من الكتب الإلهية، يهدي إلى الحق في كل ما اختلف فيه الناس من العقائد والديانات والأحكام، وإلى طريق مستقيم هو الإسلام دين الأنبياء عامة. يا قومنا أجيبوا داعي الله محمداً ﷺ إلى توحيد الله وطاعته، وآمنوا به وبعموم رسالته، يغفر لكم من ذنوبكم التي بينكم وبين الله، أما الذنوب التي بينكم وبين بعضكم فلا تُغفر إلا من قِبل المظلوم باستسماحه أو ردّ الحق إليه، ويحفظكم من عذاب النار. ومن لا يجب داعي الله فليس بمعجز الله في الأرض، بل الله مدركه لا محالة، وليس له من دون الله أولياء ولا أنصار، أولئك في ضلال بيّن واضح لا يستره شيء.", "h": ["إثبات عالم الجن وتقريره في هذا السياق، ولذا كان إنكار الجن كإنكار الملائكة كفراً.", "وجوب التأدب عند تلاوة القرآن بالإصغاء التام.", "وجوب البلاغ عن رسول الله ﷺ، وفي الحديث: «بلّغوا عني ولو آية».", "الإعراض عن دين الله يوجب الخذلان والحرمان."], "k": "«فلما حضروه قالوا أنصتوا»… سمعوه مرة فرجعوا دعاة؛ فما الذي أفعله أنا بعد سماعه؟"}, {"lbl": "الآيات ٣٣ – ٣٥", "q": "أَوَلَمۡ يَرَوۡاْ أَنَّ ٱللَّهَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَلَمۡ يَعۡيَ بِخَلۡقِهِنَّ بِقَٰدِرٍ عَلَىٰٓ أَن يُحۡـِۧيَ ٱلۡمَوۡتَىٰۚ بَلَىٰٓۚ إِنَّهُۥ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿٣٣﴾ وَيَوۡمَ يُعۡرَضُ ٱلَّذِينَ كَفَرُواْ عَلَى ٱلنَّارِ أَلَيۡسَ هَٰذَا بِٱلۡحَقِّۖ قَالُواْ بَلَىٰ وَرَبِّنَاۚ قَالَ فَذُوقُواْ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ ﴿٣٤﴾ فَٱصۡبِرۡ كَمَا صَبَرَ أُوْلُواْ ٱلۡعَزۡمِ مِنَ ٱلرُّسُلِ وَلَا تَسۡتَعۡجِل لَّهُمۡۚ كَأَنَّهُمۡ يَوۡمَ يَرَوۡنَ مَا يُوعَدُونَ لَمۡ يَلۡبَثُوٓاْ إِلَّا سَاعَةٗ مِّن نَّهَارِۭۚ بَلَٰغٞۚ فَهَلۡ يُهۡلَكُ إِلَّا ٱلۡقَوۡمُ ٱلۡفَٰسِقُونَ ﴿٣٥﴾", "w": [["ولم يعيَ بخلقهن", "لم يتعب ولم ينصب لخلق السماوات والأرض."], ["بقادر على أن يحيي الموتى", "إنه قادر على إحياء الموتى وإخراجهم أحياء من قبورهم."], ["ويوم يُعرض الذين كفروا على النار", "ليُعذّبوا فيها."], ["أليس هذا بالحق", "يقال لهم تقريعاً: أليس هذا العذاب بحق؟"], ["قالوا بلى وربنا", "إنه لحق وربنا، حلفوا بالله تأكيداً لخبرهم."], ["فاصبر", "يا رسولنا على أذى قومك."], ["أولو العزم", "أصحاب الحزم والصبر والعزم، وهم نوح وإبراهيم وموسى وعيسى ومحمد صلى الله عليهم أجمعين وسلم."], ["ولا تستعجل لهم", "لا تستعجل نزول العذاب لأجلهم."], ["كأنهم يوم يرون ما يوعدون", "في الآخرة."], ["لم يلبثوا إلا ساعة من نهار", "لم يقيموا في الدنيا إلا ساعة من نهار لطول ما يرون من العذاب."], ["بلاغ", "هذا القرآن تبليغ للناس."], ["فهل يُهلك إلا القوم الفاسقون", "ما يهلك إلا القوم التاركون لأمر الله المعرضون عنه الخارجون عن طاعته."]], "m": "ما زال السياق في طلب هداية قريش المكذبة بالتوحيد والبعث والنبوة: أوَلم يروا أن الله الذي خلق السماوات والأرض إنشاءً وإبداعاً من غير مثال سابق، ولم يتعب بخلقهن، بقادر على أن يحيي الموتى لحشرهم ومحاسبتهم ومجازاتهم؟ بلى إنه على كل شيء قدير. ويوم تعرضهم الزبانية على النار يقولون لهم تقريعاً: أليس هذا التعذيب بحق؟ فيقولون مقسمين: بلى وربنا، فيقال لهم: فذوقوا العذاب بما كنتم تكفرون بتوحيد الله ولقائه. ثم أمر تعالى رسوله أن يتدرّع بالصبر ويتمثّل صبر أولي العزم ليكون أقوى منهم صبراً كما هو أعلى منهم درجة: فاصبر على ما تلاقي من تكذيب وأذى كما ثبت أولو العزم من قبلك، والظاهر أنهم المذكورون في سورة الأحزاب: وإذ أخذنا من النبيين ميثاقهم ومنك ومن نوح وإبراهيم وموسى وعيسى ابن مريم، وجائز أن يكون عددهم أكثر. ولا تستعجل لهم العذاب فإنه قريب جداً، حتى إنهم يوم يرونه كأنهم لم يلبثوا في الدنيا على طولها إلا ساعة من نهار. هذا القرآن وما حواه بلاغ للناس، فهل يهلك إلا القوم الفاسقون عن أوامر الله الخارجون عن طاعته وطاعة رسوله؟", "h": ["تقرير عقيدة البعث والجزاء.", "الكفر هو الموجب للنار، والكفر هو تكذيب بوجود الله تعالى وهو الإلحاد، أو تكذيب بلقائه تعالى، أو بآياته، أو رسله، أو شرائعه بعضاً أو كلاً.", "وجوب الصبر على الطاعات فعلاً، وعن المعاصي تركاً، وعلى البلاء بعدم التضجّر والسخط.", "إطلاق الفسق على الكفر باعتباره خروجاً عن طاعة الله فيما يأمر به من العقائد والعبادات وينهى عنه من الشرك والمعاصي."], "k": "«كأنهم يوم يرون ما يوعدون لم يلبثوا إلا ساعة من نهار»… عمري كله ساعة؛ فبماذا أملؤها؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 375;
insert into public.tdb_cards(topic, i, body) select 375, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٩ – ٣٢", "q": "وَإِذۡ صَرَفۡنَآ إِلَيۡكَ نَفَرٗا مِّنَ ٱلۡجِنِّ يَسۡتَمِعُونَ ٱلۡقُرۡءَانَ فَلَمَّا حَضَرُوهُ قَالُوٓاْ أَنصِتُواْۖ فَلَمَّا قُضِيَ وَلَّوۡاْ إِلَىٰ قَوۡمِهِم مُّنذِرِينَ ﴿٢٩﴾ قَالُواْ يَٰقَوۡمَنَآ إِنَّا سَمِعۡنَا كِتَٰبًا أُنزِلَ مِنۢ بَعۡدِ مُوسَىٰ مُصَدِّقٗا لِّمَا بَيۡنَ يَدَيۡهِ يَهۡدِيٓ إِلَى ٱلۡحَقِّ وَإِلَىٰ طَرِيقٖ مُّسۡتَقِيمٖ ﴿٣٠﴾ يَٰقَوۡمَنَآ أَجِيبُواْ دَاعِيَ ٱللَّهِ وَءَامِنُواْ بِهِۦ يَغۡفِرۡ لَكُم مِّن ذُنُوبِكُمۡ وَيُجِرۡكُم مِّنۡ عَذَابٍ أَلِيمٖ ﴿٣١﴾ وَمَن لَّا يُجِبۡ دَاعِيَ ٱللَّهِ فَلَيۡسَ بِمُعۡجِزٖ فِي ٱلۡأَرۡضِ وَلَيۡسَ لَهُۥ مِن دُونِهِۦٓ أَوۡلِيَآءُۚ أُوْلَـٰٓئِكَ فِي ضَلَٰلٖ مُّبِينٍ ﴿٣٢﴾", "w": [["وإذ صرفنا إليك نفراً من الجن", "واذكر إذ أملنا إليك نفراً من الجن، جن نصيبين أو نينوى."], ["فلما حضروه قالوا أنصتوا", "حضروا سماع القرآن فقال بعضهم لبعض: أصغوا لاستماعه."], ["فلما قُضي ولّوا إلى قومهم منذرين", "فلما فرغ من قراءته رجعوا إلى قومهم مخوّفين."], ["مصدّقاً لما بين يديه", "من الكتب السابقة كالتوراة والإنجيل والزبور."], ["يهدي إلى الحق وإلى طريق مستقيم", "إلى الحق من العقائد والشرائع، وإلى الإسلام."], ["ويُجركم من عذاب أليم", "ويحفظكم من عذاب يوم القيامة."], ["فليس بمعجز في الأرض", "ليس بمعجز الله هرباً منه فيفوته."], ["أولئك في ضلال مبين", "الذين لم يجيبوا داعي الله محمداً ﷺ في ضلال عن طريق الإسعاد والكمال ظاهر بيّن."]], "m": "بعد أن ذكّر قوم النبي ﷺ بعاد وما أصابها، ذكّرهم هنا بما هو تقريع لهم إذ أراهم أن الجن خير منهم لسرعة استجابتهم للدعوة وقيامهم بتبليغها: واذكر لقومك إذ أملنا إليك نفراً من الجن، ما بين السبعة إلى التسعة من جن نصيبين، من أشرافهم وسادتهم، وأنت تقرأ في صلاة الصبح ببطن نخلة بين مكة والطائف، فلما حضروا قال بعضهم لبعض: أنصتوا ولا تشوّشوا، فلما فرغ رجعوا إلى قومهم منذرين من عذاب الله إن استمروا على الشرك، قالوا: يا قومنا إنا سمعنا كتاباً أُنزل من بعد موسى، هو القرآن، مصدّقاً لما بين يديه من الكتب الإلهية، يهدي إلى الحق في كل ما اختلف فيه الناس من العقائد والديانات والأحكام، وإلى طريق مستقيم هو الإسلام دين الأنبياء عامة. يا قومنا أجيبوا داعي الله محمداً ﷺ إلى توحيد الله وطاعته، وآمنوا به وبعموم رسالته، يغفر لكم من ذنوبكم التي بينكم وبين الله، أما الذنوب التي بينكم وبين بعضكم فلا تُغفر إلا من قِبل المظلوم باستسماحه أو ردّ الحق إليه، ويحفظكم من عذاب النار. ومن لا يجب داعي الله فليس بمعجز الله في الأرض، بل الله مدركه لا محالة، وليس له من دون الله أولياء ولا أنصار، أولئك في ضلال بيّن واضح لا يستره شيء.", "h": ["إثبات عالم الجن وتقريره في هذا السياق، ولذا كان إنكار الجن كإنكار الملائكة كفراً.", "وجوب التأدب عند تلاوة القرآن بالإصغاء التام.", "وجوب البلاغ عن رسول الله ﷺ، وفي الحديث: «بلّغوا عني ولو آية».", "الإعراض عن دين الله يوجب الخذلان والحرمان."], "k": "«فلما حضروه قالوا أنصتوا»… سمعوه مرة فرجعوا دعاة؛ فما الذي أفعله أنا بعد سماعه؟"}, {"lbl": "الآيات ٣٣ – ٣٥", "q": "أَوَلَمۡ يَرَوۡاْ أَنَّ ٱللَّهَ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَلَمۡ يَعۡيَ بِخَلۡقِهِنَّ بِقَٰدِرٍ عَلَىٰٓ أَن يُحۡـِۧيَ ٱلۡمَوۡتَىٰۚ بَلَىٰٓۚ إِنَّهُۥ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ ﴿٣٣﴾ وَيَوۡمَ يُعۡرَضُ ٱلَّذِينَ كَفَرُواْ عَلَى ٱلنَّارِ أَلَيۡسَ هَٰذَا بِٱلۡحَقِّۖ قَالُواْ بَلَىٰ وَرَبِّنَاۚ قَالَ فَذُوقُواْ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ ﴿٣٤﴾ فَٱصۡبِرۡ كَمَا صَبَرَ أُوْلُواْ ٱلۡعَزۡمِ مِنَ ٱلرُّسُلِ وَلَا تَسۡتَعۡجِل لَّهُمۡۚ كَأَنَّهُمۡ يَوۡمَ يَرَوۡنَ مَا يُوعَدُونَ لَمۡ يَلۡبَثُوٓاْ إِلَّا سَاعَةٗ مِّن نَّهَارِۭۚ بَلَٰغٞۚ فَهَلۡ يُهۡلَكُ إِلَّا ٱلۡقَوۡمُ ٱلۡفَٰسِقُونَ ﴿٣٥﴾", "w": [["ولم يعيَ بخلقهن", "لم يتعب ولم ينصب لخلق السماوات والأرض."], ["بقادر على أن يحيي الموتى", "إنه قادر على إحياء الموتى وإخراجهم أحياء من قبورهم."], ["ويوم يُعرض الذين كفروا على النار", "ليُعذّبوا فيها."], ["أليس هذا بالحق", "يقال لهم تقريعاً: أليس هذا العذاب بحق؟"], ["قالوا بلى وربنا", "إنه لحق وربنا، حلفوا بالله تأكيداً لخبرهم."], ["فاصبر", "يا رسولنا على أذى قومك."], ["أولو العزم", "أصحاب الحزم والصبر والعزم، وهم نوح وإبراهيم وموسى وعيسى ومحمد صلى الله عليهم أجمعين وسلم."], ["ولا تستعجل لهم", "لا تستعجل نزول العذاب لأجلهم."], ["كأنهم يوم يرون ما يوعدون", "في الآخرة."], ["لم يلبثوا إلا ساعة من نهار", "لم يقيموا في الدنيا إلا ساعة من نهار لطول ما يرون من العذاب."], ["بلاغ", "هذا القرآن تبليغ للناس."], ["فهل يُهلك إلا القوم الفاسقون", "ما يهلك إلا القوم التاركون لأمر الله المعرضون عنه الخارجون عن طاعته."]], "m": "ما زال السياق في طلب هداية قريش المكذبة بالتوحيد والبعث والنبوة: أوَلم يروا أن الله الذي خلق السماوات والأرض إنشاءً وإبداعاً من غير مثال سابق، ولم يتعب بخلقهن، بقادر على أن يحيي الموتى لحشرهم ومحاسبتهم ومجازاتهم؟ بلى إنه على كل شيء قدير. ويوم تعرضهم الزبانية على النار يقولون لهم تقريعاً: أليس هذا التعذيب بحق؟ فيقولون مقسمين: بلى وربنا، فيقال لهم: فذوقوا العذاب بما كنتم تكفرون بتوحيد الله ولقائه. ثم أمر تعالى رسوله أن يتدرّع بالصبر ويتمثّل صبر أولي العزم ليكون أقوى منهم صبراً كما هو أعلى منهم درجة: فاصبر على ما تلاقي من تكذيب وأذى كما ثبت أولو العزم من قبلك، والظاهر أنهم المذكورون في سورة الأحزاب: وإذ أخذنا من النبيين ميثاقهم ومنك ومن نوح وإبراهيم وموسى وعيسى ابن مريم، وجائز أن يكون عددهم أكثر. ولا تستعجل لهم العذاب فإنه قريب جداً، حتى إنهم يوم يرونه كأنهم لم يلبثوا في الدنيا على طولها إلا ساعة من نهار. هذا القرآن وما حواه بلاغ للناس، فهل يهلك إلا القوم الفاسقون عن أوامر الله الخارجون عن طاعته وطاعة رسوله؟", "h": ["تقرير عقيدة البعث والجزاء.", "الكفر هو الموجب للنار، والكفر هو تكذيب بوجود الله تعالى وهو الإلحاد، أو تكذيب بلقائه تعالى، أو بآياته، أو رسله، أو شرائعه بعضاً أو كلاً.", "وجوب الصبر على الطاعات فعلاً، وعن المعاصي تركاً، وعلى البلاء بعدم التضجّر والسخط.", "إطلاق الفسق على الكفر باعتباره خروجاً عن طاعة الله فيما يأمر به من العقائد والعبادات وينهى عنه من الشرك والمعاصي."], "k": "«كأنهم يوم يرون ما يوعدون لم يلبثوا إلا ساعة من نهار»… عمري كله ساعة؛ فبماذا أملؤها؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (376, 47, 1, 9, 'سورة محمد ١ – ٩', 'محمد: إن تنصروا الله ينصركم ويثبّت أقدامكم', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 376) = $j$[{"lbl": "الآيات ١ – ٣", "q": "ٱلَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ أَضَلَّ أَعۡمَٰلَهُمۡ ﴿١﴾ وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ وَءَامَنُواْ بِمَا نُزِّلَ عَلَىٰ مُحَمَّدٖ وَهُوَ ٱلۡحَقُّ مِن رَّبِّهِمۡ كَفَّرَ عَنۡهُمۡ سَيِّـَٔاتِهِمۡ وَأَصۡلَحَ بَالَهُمۡ ﴿٢﴾ ذَٰلِكَ بِأَنَّ ٱلَّذِينَ كَفَرُواْ ٱتَّبَعُواْ ٱلۡبَٰطِلَ وَأَنَّ ٱلَّذِينَ ءَامَنُواْ ٱتَّبَعُواْ ٱلۡحَقَّ مِن رَّبِّهِمۡۚ كَذَٰلِكَ يَضۡرِبُ ٱللَّهُ لِلنَّاسِ أَمۡثَٰلَهُمۡ ﴿٣﴾", "w": [["الذين كفروا وصدّوا عن سبيل الله", "كفروا بتوحيد الله ولقائه وآياته ورسوله، وصدّوا غيرهم عن الدخول في الإسلام."], ["أضلّ أعمالهم", "أحبط أعمالهم الخيرية كإطعام الطعام وصلة الأرحام فلا يُرى لها أثر يوم القيامة."], ["والذين آمنوا وعملوا الصالحات", "آمنوا بالله وآياته ورسوله ولقائه، وأدّوا الفرائض واجتنبوا المحرمات."], ["وآمنوا بما نُزّل على محمد", "بالقرآن الكريم."], ["كفّر عنهم سيئاتهم", "محا عنهم ذنوبهم وغفرها لهم."], ["وأصلح بالهم", "شأنهم وحالهم، فهم لا يعصون الله تعالى."], ["ذلك", "إضلال أعمال الكافرين وتكفير سيئات المؤمنين."], ["بأن الذين كفروا اتبعوا الباطل", "اتبعوا الشيطان في كل ما يمليه عليهم ويزيّنه لهم من الكفر."], ["اتبعوا الحق من ربهم", "التوحيد والعمل الصالح."], ["كذلك يضرب الله للناس أمثالهم", "كما بيّن حال الكافرين وحال المؤمنين يبيّن للناس أمثالهم ليعتبروا."]], "m": "الذين كفروا بالله ورسوله وصدّوا غيرهم عن الإسلام أحبط الله أعمالهم فلم يحصل لهم بها ثواب في الآخرة، ولازمه أنهم هالكون في النار؛ وكأن هذه الجملة جواب لسؤال نشأ عن خاتمة الأحقاف: فهل يهلك إلا القوم الفاسقون؟ فقيل: من هم؟ فكان الجواب: الذين كفروا وصدّوا عن سبيل الله، وهو وجه ارتباط حسن بين السورتين. والذين آمنوا بالله ورسوله ولقائه وعملوا الصالحات، من إقام الصلاة وإيتاء الزكاة وصيام رمضان وحج البيت وصلة الأرحام والأمر بالمعروف والنهي عن المنكر ولو بالاستعداد للقيام بذلك إذ بعضها لم يُشرع بعد، وآمنوا بما نُزّل على محمد ﷺ، القرآن والسنة الصحيحة لأنها وحي يتلقّاه الرسول، وفي الحديث: «ألا وإني أوتيت القرآن ومثله معه»، وهو الحق من ربهم لأنه ناسخ للكتب قبله ولا يُنسخ، كفّر عنهم سيئاتهم وأصلح شأنهم وحالهم. ذلك الجزاء للفريقين بسبب أن الذين كفروا اتبعوا الشيطان وما يزيّنه من الشرك والفساد، وأن الذين آمنوا اتبعوا الحق من ربهم، القرآن وما دعا إليه من العقائد الصحيحة والعبادات المزكّية للنفس. ومثل هذا التبيين يبيّن الله للناس أحوالهم بالخسران والنجاح ليعتبروا فيسلكوا سبيل النجاح ويتجنّبوا سبيل الخسران.", "h": ["بيان طريقي الفلاح والخسران: فطريق الفلاح الإيمان والعمل الصالح، وطريق الخسران الشرك.", "بيان أن أعمال البر مع الكفر والشرك لا تنفع صاحبها يوم القيامة ولا تشفع له، وقد يُثاب عليها في الدنيا فيُبارك له في ماله وولده.", "بيان الحكمة في ضرب الأمثال، وهي هداية الناس إلى ما يُفلحون به فينجون من النار ويدخلون الجنة."], "k": "«وأصلح بالهم»… راحة البال ثمرة الإيمان والعمل؛ فمن أين يأتيني القلق؟"}, {"lbl": "الآيات ٤ – ٩", "q": "فَإِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُواْ فَضَرۡبَ ٱلرِّقَابِ حَتَّىٰٓ إِذَآ أَثۡخَنتُمُوهُمۡ فَشُدُّواْ ٱلۡوَثَاقَ فَإِمَّا مَنَّۢا بَعۡدُ وَإِمَّا فِدَآءً حَتَّىٰ تَضَعَ ٱلۡحَرۡبُ أَوۡزَارَهَاۚ ذَٰلِكَۖ وَلَوۡ يَشَآءُ ٱللَّهُ لَٱنتَصَرَ مِنۡهُمۡ وَلَٰكِن لِّيَبۡلُوَاْ بَعۡضَكُم بِبَعۡضٖۗ وَٱلَّذِينَ قُتِلُواْ فِي سَبِيلِ ٱللَّهِ فَلَن يُضِلَّ أَعۡمَٰلَهُمۡ ﴿٤﴾ سَيَهۡدِيهِمۡ وَيُصۡلِحُ بَالَهُمۡ ﴿٥﴾ وَيُدۡخِلُهُمُ ٱلۡجَنَّةَ عَرَّفَهَا لَهُمۡ ﴿٦﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تَنصُرُواْ ٱللَّهَ يَنصُرۡكُمۡ وَيُثَبِّتۡ أَقۡدَامَكُمۡ ﴿٧﴾ وَٱلَّذِينَ كَفَرُواْ فَتَعۡسٗا لَّهُمۡ وَأَضَلَّ أَعۡمَٰلَهُمۡ ﴿٨﴾ ذَٰلِكَ بِأَنَّهُمۡ كَرِهُواْ مَآ أَنزَلَ ٱللَّهُ فَأَحۡبَطَ أَعۡمَٰلَهُمۡ ﴿٩﴾", "w": [["فإذا لقيتم الذين كفروا", "في ساحة المعركة."], ["فضرب الرقاب", "فاضربوا رقابهم ضرباً شديداً."], ["حتى إذا أثخنتموهم", "أكثرتم فيهم القتل ولم يبق لهم أمل في الانتصار."], ["فشدّوا الوثاق", "فأسروهم بدل قتلهم، وأحكموا ما يوثق به الأسير حتى لا يتفلّتوا ويهربوا."], ["فإما منّاً بعد وإما فداءً", "بعد أسرهم فإما أن تفكّوهم مجاناً، وإما تفادونهم بمال أو أسير مسلم، وهذا بعد نهاية المعركة."], ["حتى تضع الحرب أوزارها", "واصلوا القتال والأسر إلى أن تضع الحرب آلاتها، وذلك عند إسلام الكفار أو دخولهم في عهدكم."], ["ولو يشاء الله لانتصر منهم", "بغير قتال منكم، كأن يخسف بهم الأرض أو يصيبهم بوباء."], ["ولكن ليبلوَ بعضكم ببعض", "شرع لكم القتال ليختبركم من يقاتل منكم ومن لا يقاتل."], ["والذين قُتلوا في سبيل الله", "قتلهم العدو، وقُرئ: قاتلوا في سبيل الله."], ["فلن يُضلّ أعمالهم", "لا يحبطها ولا يبطلها."], ["سيهديهم ويصلح بالهم", "سيوفّقهم إلى ما فيه خيرهم وسعادتهم ويصلح شأنهم."], ["عرّفها لهم", "بيّنها لهم فعرفوها بما وصفها لهم في كتابه وعلى لسان رسوله."], ["إن تنصروا الله", "في دينه ورسوله وعباده المؤمنين."], ["ينصركم ويثبّت أقدامكم", "على عدوكم، ويثبّت أقدامكم في المعارك."], ["فتعساً لهم", "هلاكاً وخيبة لهم."], ["ذلك بأنهم كرهوا ما أنزل الله", "من القرآن المشتمل على أنواع الهدايات والإصلاحات."], ["فأحبط أعمالهم", "أبطلها فلا ينتفعون بها لا في الدنيا ولا في الآخرة."]], "m": "إذا كان الذين كفروا وصدّوا عن سبيل الله قد أضلّ الله أعمالهم فليُقاتَلوا لإنهاء مفسدتيهم: كفرهم وصدّهم غيرهم عن الإسلام: فإذا لقيتم الذين كفروا في المعركة فاضربوا رقابهم، وواصلوا قتالهم حتى إذا أكثرتم فيهم القتل فأحكموا ربط الأسرى حتى لا يتمكّنوا من قتلكم ولا الهرب، وبعد ذلك ما يراه إمامكم من المصلحة: فإما منّاً عليهم مجاناً، وإما فداءً بمال أو برجال، وستظل تلك حالكم حتى تضع الحرب أثقالها من عُدد وعتاد، وذلك لوصولكم إلى الغاية من الحرب، وهي أن يُسلم الكافر أو يدخل في ذمة المسلمين، كما في البقرة: وقاتلوهم حتى لا تكون فتنة ويكون الدين لله. ذلك الأمر، ولو يشاء الله لانتصر منهم بدون قتال منكم بخسف أو وباء أو صواعق، ولكن ليختبركم بهم فيعلم المجاهدين منكم والصابرين، ويبلوهم بكم فيعاقب من شاء منهم بأيديكم ويتوب على من يشاء، إذ وقوعهم تحت سلطانكم يساعدهم على التوبة فيُسلموا فيفلحوا. والذين قُتلوا في سبيل الله، وهي عامة في شهداء أحد وغيرهم، فلن يضل أعمالهم، سيهديهم ويوفّقهم ويصلح شأنهم، ويدخلهم الجنة بيّنها لهم في كتابه، ويهديهم إلى منازلهم فيها، كما قال ﷺ: «فوالذي نفس محمد بيده لأحدهم أهدى بمنزله في الجنة من منزله الذي كان في الدنيا». يا من آمنتم بالله رباً وبالإسلام ديناً وبمحمد رسولاً، إن تنصروا الله بنصر دينه ونبيه وأوليائه بقتال أعدائه ينصركم ويثبّت أقدامكم في كل معترك، وهذا وعد أنجزه لعباده في تاريخ الجهاد. والذين كفروا فتعساً لهم، هلكوا وخابوا، وأضل أعمالهم فلم يروا لها أدنى فائدة، بسبب أنهم كرهوا ما أنزل الله من آيات التوحيد والشرائع والأحكام فأحبط أعمالهم.", "h": ["وجوب الجهاد على أمة الإسلام ومواصلته كما بيّن تعالى في هذه الآيات.", "إمام المسلمين مخيّر في الأسرى بين المنّ والفداء، والقتل أيضاً لأدلة من السنة.", "بشرى المجاهدين في سبيل الله بإكرام الله لهم وإنعامه عليهم في الدنيا والآخرة.", "يظفر بالنصر الحقيقي من نصر الله تعالى في دينه وأوليائه.", "إنذار الكافرين بالتعاسة والشقاء في الدنيا والآخرة."], "k": "«إن تنصروا الله ينصركم»… كيف أنصر دين الله في موقعي الصغير اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 376;
insert into public.tdb_cards(topic, i, body) select 376, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٣", "q": "ٱلَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ أَضَلَّ أَعۡمَٰلَهُمۡ ﴿١﴾ وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ وَءَامَنُواْ بِمَا نُزِّلَ عَلَىٰ مُحَمَّدٖ وَهُوَ ٱلۡحَقُّ مِن رَّبِّهِمۡ كَفَّرَ عَنۡهُمۡ سَيِّـَٔاتِهِمۡ وَأَصۡلَحَ بَالَهُمۡ ﴿٢﴾ ذَٰلِكَ بِأَنَّ ٱلَّذِينَ كَفَرُواْ ٱتَّبَعُواْ ٱلۡبَٰطِلَ وَأَنَّ ٱلَّذِينَ ءَامَنُواْ ٱتَّبَعُواْ ٱلۡحَقَّ مِن رَّبِّهِمۡۚ كَذَٰلِكَ يَضۡرِبُ ٱللَّهُ لِلنَّاسِ أَمۡثَٰلَهُمۡ ﴿٣﴾", "w": [["الذين كفروا وصدّوا عن سبيل الله", "كفروا بتوحيد الله ولقائه وآياته ورسوله، وصدّوا غيرهم عن الدخول في الإسلام."], ["أضلّ أعمالهم", "أحبط أعمالهم الخيرية كإطعام الطعام وصلة الأرحام فلا يُرى لها أثر يوم القيامة."], ["والذين آمنوا وعملوا الصالحات", "آمنوا بالله وآياته ورسوله ولقائه، وأدّوا الفرائض واجتنبوا المحرمات."], ["وآمنوا بما نُزّل على محمد", "بالقرآن الكريم."], ["كفّر عنهم سيئاتهم", "محا عنهم ذنوبهم وغفرها لهم."], ["وأصلح بالهم", "شأنهم وحالهم، فهم لا يعصون الله تعالى."], ["ذلك", "إضلال أعمال الكافرين وتكفير سيئات المؤمنين."], ["بأن الذين كفروا اتبعوا الباطل", "اتبعوا الشيطان في كل ما يمليه عليهم ويزيّنه لهم من الكفر."], ["اتبعوا الحق من ربهم", "التوحيد والعمل الصالح."], ["كذلك يضرب الله للناس أمثالهم", "كما بيّن حال الكافرين وحال المؤمنين يبيّن للناس أمثالهم ليعتبروا."]], "m": "الذين كفروا بالله ورسوله وصدّوا غيرهم عن الإسلام أحبط الله أعمالهم فلم يحصل لهم بها ثواب في الآخرة، ولازمه أنهم هالكون في النار؛ وكأن هذه الجملة جواب لسؤال نشأ عن خاتمة الأحقاف: فهل يهلك إلا القوم الفاسقون؟ فقيل: من هم؟ فكان الجواب: الذين كفروا وصدّوا عن سبيل الله، وهو وجه ارتباط حسن بين السورتين. والذين آمنوا بالله ورسوله ولقائه وعملوا الصالحات، من إقام الصلاة وإيتاء الزكاة وصيام رمضان وحج البيت وصلة الأرحام والأمر بالمعروف والنهي عن المنكر ولو بالاستعداد للقيام بذلك إذ بعضها لم يُشرع بعد، وآمنوا بما نُزّل على محمد ﷺ، القرآن والسنة الصحيحة لأنها وحي يتلقّاه الرسول، وفي الحديث: «ألا وإني أوتيت القرآن ومثله معه»، وهو الحق من ربهم لأنه ناسخ للكتب قبله ولا يُنسخ، كفّر عنهم سيئاتهم وأصلح شأنهم وحالهم. ذلك الجزاء للفريقين بسبب أن الذين كفروا اتبعوا الشيطان وما يزيّنه من الشرك والفساد، وأن الذين آمنوا اتبعوا الحق من ربهم، القرآن وما دعا إليه من العقائد الصحيحة والعبادات المزكّية للنفس. ومثل هذا التبيين يبيّن الله للناس أحوالهم بالخسران والنجاح ليعتبروا فيسلكوا سبيل النجاح ويتجنّبوا سبيل الخسران.", "h": ["بيان طريقي الفلاح والخسران: فطريق الفلاح الإيمان والعمل الصالح، وطريق الخسران الشرك.", "بيان أن أعمال البر مع الكفر والشرك لا تنفع صاحبها يوم القيامة ولا تشفع له، وقد يُثاب عليها في الدنيا فيُبارك له في ماله وولده.", "بيان الحكمة في ضرب الأمثال، وهي هداية الناس إلى ما يُفلحون به فينجون من النار ويدخلون الجنة."], "k": "«وأصلح بالهم»… راحة البال ثمرة الإيمان والعمل؛ فمن أين يأتيني القلق؟"}, {"lbl": "الآيات ٤ – ٩", "q": "فَإِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُواْ فَضَرۡبَ ٱلرِّقَابِ حَتَّىٰٓ إِذَآ أَثۡخَنتُمُوهُمۡ فَشُدُّواْ ٱلۡوَثَاقَ فَإِمَّا مَنَّۢا بَعۡدُ وَإِمَّا فِدَآءً حَتَّىٰ تَضَعَ ٱلۡحَرۡبُ أَوۡزَارَهَاۚ ذَٰلِكَۖ وَلَوۡ يَشَآءُ ٱللَّهُ لَٱنتَصَرَ مِنۡهُمۡ وَلَٰكِن لِّيَبۡلُوَاْ بَعۡضَكُم بِبَعۡضٖۗ وَٱلَّذِينَ قُتِلُواْ فِي سَبِيلِ ٱللَّهِ فَلَن يُضِلَّ أَعۡمَٰلَهُمۡ ﴿٤﴾ سَيَهۡدِيهِمۡ وَيُصۡلِحُ بَالَهُمۡ ﴿٥﴾ وَيُدۡخِلُهُمُ ٱلۡجَنَّةَ عَرَّفَهَا لَهُمۡ ﴿٦﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن تَنصُرُواْ ٱللَّهَ يَنصُرۡكُمۡ وَيُثَبِّتۡ أَقۡدَامَكُمۡ ﴿٧﴾ وَٱلَّذِينَ كَفَرُواْ فَتَعۡسٗا لَّهُمۡ وَأَضَلَّ أَعۡمَٰلَهُمۡ ﴿٨﴾ ذَٰلِكَ بِأَنَّهُمۡ كَرِهُواْ مَآ أَنزَلَ ٱللَّهُ فَأَحۡبَطَ أَعۡمَٰلَهُمۡ ﴿٩﴾", "w": [["فإذا لقيتم الذين كفروا", "في ساحة المعركة."], ["فضرب الرقاب", "فاضربوا رقابهم ضرباً شديداً."], ["حتى إذا أثخنتموهم", "أكثرتم فيهم القتل ولم يبق لهم أمل في الانتصار."], ["فشدّوا الوثاق", "فأسروهم بدل قتلهم، وأحكموا ما يوثق به الأسير حتى لا يتفلّتوا ويهربوا."], ["فإما منّاً بعد وإما فداءً", "بعد أسرهم فإما أن تفكّوهم مجاناً، وإما تفادونهم بمال أو أسير مسلم، وهذا بعد نهاية المعركة."], ["حتى تضع الحرب أوزارها", "واصلوا القتال والأسر إلى أن تضع الحرب آلاتها، وذلك عند إسلام الكفار أو دخولهم في عهدكم."], ["ولو يشاء الله لانتصر منهم", "بغير قتال منكم، كأن يخسف بهم الأرض أو يصيبهم بوباء."], ["ولكن ليبلوَ بعضكم ببعض", "شرع لكم القتال ليختبركم من يقاتل منكم ومن لا يقاتل."], ["والذين قُتلوا في سبيل الله", "قتلهم العدو، وقُرئ: قاتلوا في سبيل الله."], ["فلن يُضلّ أعمالهم", "لا يحبطها ولا يبطلها."], ["سيهديهم ويصلح بالهم", "سيوفّقهم إلى ما فيه خيرهم وسعادتهم ويصلح شأنهم."], ["عرّفها لهم", "بيّنها لهم فعرفوها بما وصفها لهم في كتابه وعلى لسان رسوله."], ["إن تنصروا الله", "في دينه ورسوله وعباده المؤمنين."], ["ينصركم ويثبّت أقدامكم", "على عدوكم، ويثبّت أقدامكم في المعارك."], ["فتعساً لهم", "هلاكاً وخيبة لهم."], ["ذلك بأنهم كرهوا ما أنزل الله", "من القرآن المشتمل على أنواع الهدايات والإصلاحات."], ["فأحبط أعمالهم", "أبطلها فلا ينتفعون بها لا في الدنيا ولا في الآخرة."]], "m": "إذا كان الذين كفروا وصدّوا عن سبيل الله قد أضلّ الله أعمالهم فليُقاتَلوا لإنهاء مفسدتيهم: كفرهم وصدّهم غيرهم عن الإسلام: فإذا لقيتم الذين كفروا في المعركة فاضربوا رقابهم، وواصلوا قتالهم حتى إذا أكثرتم فيهم القتل فأحكموا ربط الأسرى حتى لا يتمكّنوا من قتلكم ولا الهرب، وبعد ذلك ما يراه إمامكم من المصلحة: فإما منّاً عليهم مجاناً، وإما فداءً بمال أو برجال، وستظل تلك حالكم حتى تضع الحرب أثقالها من عُدد وعتاد، وذلك لوصولكم إلى الغاية من الحرب، وهي أن يُسلم الكافر أو يدخل في ذمة المسلمين، كما في البقرة: وقاتلوهم حتى لا تكون فتنة ويكون الدين لله. ذلك الأمر، ولو يشاء الله لانتصر منهم بدون قتال منكم بخسف أو وباء أو صواعق، ولكن ليختبركم بهم فيعلم المجاهدين منكم والصابرين، ويبلوهم بكم فيعاقب من شاء منهم بأيديكم ويتوب على من يشاء، إذ وقوعهم تحت سلطانكم يساعدهم على التوبة فيُسلموا فيفلحوا. والذين قُتلوا في سبيل الله، وهي عامة في شهداء أحد وغيرهم، فلن يضل أعمالهم، سيهديهم ويوفّقهم ويصلح شأنهم، ويدخلهم الجنة بيّنها لهم في كتابه، ويهديهم إلى منازلهم فيها، كما قال ﷺ: «فوالذي نفس محمد بيده لأحدهم أهدى بمنزله في الجنة من منزله الذي كان في الدنيا». يا من آمنتم بالله رباً وبالإسلام ديناً وبمحمد رسولاً، إن تنصروا الله بنصر دينه ونبيه وأوليائه بقتال أعدائه ينصركم ويثبّت أقدامكم في كل معترك، وهذا وعد أنجزه لعباده في تاريخ الجهاد. والذين كفروا فتعساً لهم، هلكوا وخابوا، وأضل أعمالهم فلم يروا لها أدنى فائدة، بسبب أنهم كرهوا ما أنزل الله من آيات التوحيد والشرائع والأحكام فأحبط أعمالهم.", "h": ["وجوب الجهاد على أمة الإسلام ومواصلته كما بيّن تعالى في هذه الآيات.", "إمام المسلمين مخيّر في الأسرى بين المنّ والفداء، والقتل أيضاً لأدلة من السنة.", "بشرى المجاهدين في سبيل الله بإكرام الله لهم وإنعامه عليهم في الدنيا والآخرة.", "يظفر بالنصر الحقيقي من نصر الله تعالى في دينه وأوليائه.", "إنذار الكافرين بالتعاسة والشقاء في الدنيا والآخرة."], "k": "«إن تنصروا الله ينصركم»… كيف أنصر دين الله في موقعي الصغير اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (377, 47, 10, 19, 'سورة محمد ١٠ – ١٩', 'محمد: فاعلم أنه لا إله إلا الله واستغفر لذنبك', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 377) = $j$[{"lbl": "الآيات ١٠ – ١٤", "q": "۞أَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡۖ دَمَّرَ ٱللَّهُ عَلَيۡهِمۡۖ وَلِلۡكَٰفِرِينَ أَمۡثَٰلُهَا ﴿١٠﴾ ذَٰلِكَ بِأَنَّ ٱللَّهَ مَوۡلَى ٱلَّذِينَ ءَامَنُواْ وَأَنَّ ٱلۡكَٰفِرِينَ لَا مَوۡلَىٰ لَهُمۡ ﴿١١﴾ إِنَّ ٱللَّهَ يُدۡخِلُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ وَٱلَّذِينَ كَفَرُواْ يَتَمَتَّعُونَ وَيَأۡكُلُونَ كَمَا تَأۡكُلُ ٱلۡأَنۡعَٰمُ وَٱلنَّارُ مَثۡوٗى لَّهُمۡ ﴿١٢﴾ وَكَأَيِّن مِّن قَرۡيَةٍ هِيَ أَشَدُّ قُوَّةٗ مِّن قَرۡيَتِكَ ٱلَّتِيٓ أَخۡرَجَتۡكَ أَهۡلَكۡنَٰهُمۡ فَلَا نَاصِرَ لَهُمۡ ﴿١٣﴾ أَفَمَن كَانَ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّهِۦ كَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ وَٱتَّبَعُوٓاْ أَهۡوَآءَهُم ﴿١٤﴾", "w": [["أفلم يسيروا في الأرض", "أغفل هؤلاء المشركون فلم يسيروا في البلاد؟"], ["فينظروا كيف كان عاقبة الذين من قبلهم", "كيف كانت نهاية الذين من قبلهم كعاد وثمود."], ["دمّر الله عليهم وللكافرين أمثالها", "دمّر عليهم مساكنهم فأهلكهم وأولادهم وأموالهم، وللكافرين أمثال تلك العاقبة السيئة."], ["وأن الكافرين لا مولى لهم", "لا ناصر لهم."], ["يتمتّعون ويأكلون كما تأكل الأنعام", "يتمتّعون بمتع الدنيا ويأكلون بنهم وازدراد كأكل الأنعام."], ["والنار مثوى لهم", "مأواهم."], ["وكأيّن من قرية هي أشد قوة", "وكثير من أهل قرية هي أشد قوة."], ["من قريتك التي أخرجتك", "مكة، إذ أخرج أهلها النبي ﷺ."], ["أفمن كان على بيّنة من ربه", "على حجة وبرهان من أمر دينه فهو يعبد الله على علم."], ["كمن زُيّن له سوء عمله", "كمن زيّن الشيطان له سوء عمله."], ["واتبعوا أهواءهم", "في عبادة الأصنام، والجواب: ليسوا سواء."]], "m": "يوبّخ تعالى المشركين المصرّين على الشرك: أغفلوا فلم يسيروا في الأرض فينظروا كيف كان عاقبة الذين من قبلهم كعاد وثمود وقوم لوط، إذ دمّر الله عليهم بلادهم فأهلكهم وأولادهم وأموالهم فيعتبروا؟ وللكافرين أمثال تلك العاقبة؛ وعيد لكفار مكة إن لم يتوبوا. ذلك النصر للمؤمنين والقهر للكافرين بأن الله وليّ الذين آمنوا وناصرهم، وأن الكافرين لا مولى لهم لأن الله خاذلهم، ومن يخذله الله فلا ناصر له. إن الله يدخل الذين آمنوا وعملوا الصالحات جنات تجري من تحت قصورها وأشجارها الأنهار، والذين كفروا يتمتّعون في الدنيا بملاذّها ويأكلون كما تأكل الأنعام، إذ ليس لهم همّ إلا بطونهم وفروجهم، فلا يلتفتون إلى الآخرة، والنار مثوى لهم؛ وهذا الترغيب والترهيب سمة بارزة في أسلوب القرآن. وكثير من القرى أهلها أشد قوة من أهل مكة التي أخرجك أهلها أهلكناهم فلا ناصر لهم؛ نزلت ساعة خروج الرسول ﷺ مهاجراً إذ التفت إلى مكة وقال: «أنتِ أحب البلاد إلى الله وأحب بلاد الله إليّ، ولو أن المشركين لم يخرجوني لم أخرج منك»، فكانت تسلية له. أفمن كان على علم وبرهان من صحة معتقده وعبادته لله راجياً ثوابه خائفاً عقابه، كمن زيّن له الشيطان قبيح عمله من الشرك فهو يعبد الأصنام واتبعوا أهواءهم فلم يتبعوا وحياً ولا عقلاً؟ لا يتماثلان، إذ بينهما كما بين الحياة والموت والجنة والنار.", "h": ["تقرير قاعدة: العاقل من اعتبر بغيره.", "تقرير ولاية الله لأهل الإيمان والتقوى.", "بيان الفرق بين الماديين وأهل الإيمان والاستقامة على منهج الإسلام.", "تسلية الرسول ﷺ تخفيفاً من آلامه التي يعانيها من إعراض المشركين وصدودهم."], "k": "«ويأكلون كما تأكل الأنعام»… هل في حياتي هدف أبعد من بطني وراحتي؟"}, {"lbl": "الآية ١٥", "q": "مَّثَلُ ٱلۡجَنَّةِ ٱلَّتِي وُعِدَ ٱلۡمُتَّقُونَۖ فِيهَآ أَنۡهَٰرٞ مِّن مَّآءٍ غَيۡرِ ءَاسِنٖ وَأَنۡهَٰرٞ مِّن لَّبَنٖ لَّمۡ يَتَغَيَّرۡ طَعۡمُهُۥ وَأَنۡهَٰرٞ مِّنۡ خَمۡرٖ لَّذَّةٖ لِّلشَّـٰرِبِينَ وَأَنۡهَٰرٞ مِّنۡ عَسَلٖ مُّصَفّٗىۖ وَلَهُمۡ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَمَغۡفِرَةٞ مِّن رَّبِّهِمۡۖ كَمَنۡ هُوَ خَٰلِدٞ فِي ٱلنَّارِ وَسُقُواْ مَآءً حَمِيمٗا فَقَطَّعَ أَمۡعَآءَهُمۡ ﴿١٥﴾", "w": [["مثل الجنة التي وُعد المتقون", "صفة الجنة دار السلام التي وعد الله بها عباده المتقين."], ["من ماء غير آسن", "غير متغيّر الريح والطعم لطول مكثه."], ["وأنهار من عسل مصفّى", "مصفّى من الشمع وفضلات النحل."], ["وسُقوا ماءً حميماً", "حاراً شديد الحرارة."], ["فقطّع أمعاءهم", "مصارينهم فخرجت من أدبارهم."]], "m": "هذه الآية تضمّنت شرحاً وافياً لأنهار الجنة وشراب أهل النار، ومقارنة بين حال أهل الإيمان والتقوى وما وُعدوا به من المغفرة ودخول الجنة، وحال أهل النار الخالدين فيها: صفة الجنة التي وعد الله بها عباده المتقين، أولياءه الذين عبدوه ووحّدوه وأطاعوه فاتقوا الشرك والمعاصي: فيها أنهار من ماء غير متغيّر الطعم ولا الريح، وأنهار من لبن لم يتغيّر طعمه بحموضة، وأنهار من خمر لذة لمن يشربها، غير كدرة ولا مسكرة ولا ريح غير طيبة لها، وأنهار من عسل مصفّى من الشمع وفضلات النحل، ولهم فيها من سائر أنواع الثمار والفواكه، ومع ذلك مغفرة من ربهم لسائر ذنوبهم. فهل يستوي من هذه حالهم بحال من هو خالد في النار لا يخرج منها، وسُقوا ماءً حاراً شديد الحرارة فلما شربوه قطّع أمعاءهم فخرجت من أدبارهم؟ والعياذ بالله من النار وحال أهل النار.", "h": ["التقوى هي السبب المورث للجنة، هكذا جعلها الله عز وجل، والتقوى هي بعد الإيمان فعل المأمورات وترك المنهيات من سائر أنواع الشرك والمعاصي.", "بيان بعض نعيم الجنة من الشراب والفواكه.", "بيان بعض عذاب النار، وهو الخلود فيها وشرب الحميم.", "تقرير البعث والجزاء، وأن لا مماثلة بين أهل السعادة وأهل الشقاء."], "k": "«مثل الجنة التي وُعد المتقون»… الوصف بين يديّ؛ فهل يحرّك شوقي إليها عملي اليوم؟"}, {"lbl": "الآيات ١٦ – ١٩", "q": "وَمِنۡهُم مَّن يَسۡتَمِعُ إِلَيۡكَ حَتَّىٰٓ إِذَا خَرَجُواْ مِنۡ عِندِكَ قَالُواْ لِلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ مَاذَا قَالَ ءَانِفًاۚ أُوْلَـٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَٱتَّبَعُوٓاْ أَهۡوَآءَهُمۡ ﴿١٦﴾ وَٱلَّذِينَ ٱهۡتَدَوۡاْ زَادَهُمۡ هُدٗى وَءَاتَىٰهُمۡ تَقۡوَىٰهُمۡ ﴿١٧﴾ فَهَلۡ يَنظُرُونَ إِلَّا ٱلسَّاعَةَ أَن تَأۡتِيَهُم بَغۡتَةٗۖ فَقَدۡ جَآءَ أَشۡرَاطُهَاۚ فَأَنَّىٰ لَهُمۡ إِذَا جَآءَتۡهُمۡ ذِكۡرَىٰهُمۡ ﴿١٨﴾ فَٱعۡلَمۡ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱللَّهُ وَٱسۡتَغۡفِرۡ لِذَنۢبِكَ وَلِلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِۗ وَٱللَّهُ يَعۡلَمُ مُتَقَلَّبَكُمۡ وَمَثۡوَىٰكُمۡ ﴿١٩﴾", "w": [["ومنهم من يستمع إليك", "ومن الكفار المنافقين من يستمع إليك في خطبة الجمعة."], ["ماذا قال آنفاً", "الساعة؟ استهزاءً وسخرية، يعنون أنه شيء لا يُرجع إليه ولا يُعتدّ به."], ["طبع الله على قلوبهم", "بالكفر، فلذا هم لا يعون."], ["واتبعوا أهواءهم", "في الكفر والنفاق."], ["والذين اهتدوا", "المؤمنون."], ["زادهم هدى", "زادهم الله هدى."], ["وآتاهم تقواهم", "ألهمهم ما يتقون به عذاب الله تعالى."], ["فهل ينظرون إلا الساعة", "ما ينتظر أهل مكة إلا الساعة."], ["أن تأتيهم بغتة", "فجأة."], ["فقد جاء أشراطها", "علاماتها، كبعثة النبي ﷺ وانشقاق القمر والدخان."], ["فأنّى لهم إذا جاءتهم ذكراهم", "أنّى لهم التذكّر الذي ينفعهم إذا جاءتهم، إذ قد أُغلق باب التوبة."], ["فاعلم أنه لا إله إلا الله", "بناءً على ما تقدم فاعلم يا نبينا أنه لا يستحق العبادة إلا الله، فاعبده وتوكل عليه."], ["واستغفر لذنبك", "قل: أستغفر الله، أو: اللهم اغفر لي."], ["وللمؤمنين والمؤمنات", "واستغفر للمؤمنين والمؤمنات."], ["والله يعلم متقلّبكم", "متصرّفكم في النهار في أمور دنياكم."], ["ومثواكم", "مكان إقامتكم ونومكم بالليل."]], "m": "هذه الآية والتي بعدها مدنيّتان نزلتا في شأن المنافقين: ومن المنافقين من يستمع إلى حديثك يوم الجمعة وأنت تخطب على المنبر، حتى إذا خرجوا من المسجد قالوا للذين أوتوا العلم من أصحابك كعبد الله بن مسعود: ماذا قال آنفاً؟ وقولهم هذا ظاهر عليه الخبث، إذ لو كانوا مؤمنين لقالوا: ماذا قال رسول الله؟ وهم يعنون أن ما قاله ليس بشيء مفيد. أولئك الذين طبع الله على قلوبهم بالكفر والنفاق لكثرة تلوّثهم بأوضارهما حتى ران على قلوبهم، واتبعوا أهواءهم؛ فهما علّتان: الطبع المانع من طلب الهداية، واتباع الهوى وهو يُعمي ويُصمّ. والذين اهتدوا إلى الإيمان الصحيح والعمل الصالح زادهم الله هدى حسب سنته في نماء الأشياء، وألهمهم ما يتقون به مساخطه، وأعظمها الشرك والمعاصي. فهل ينتظر زعماء الكفر في مكة إلا الساعة أن تأتيهم فجأة؟ فقد جاءت أشراطها: بعثة محمد ﷺ، والدخان، وانشقاق القمر، فأنّى لهم التذكّر النافع إذا جاءت؟ إذ بظهور علاماتها الكبرى لا تُقبل التوبة ممن لم يكن مؤمناً. فالآية تستبطئ إيمان كفار مكة مع ظهور أدلة العقل والنقل. فاعلم يا محمد أنه لا معبود تنبغي له العبادة إلا الله الذي هو خالق كل شيء ومالكه، واستغفر لذنبك وللمؤمنين والمؤمنات؛ والخطاب وإن وُجّه للرسول فالمراد به غيره، فكأنما قال: يا عباد الله والرسول على رأسكم، اعلموا أنه لا إله إلا الله واستغفروا لذنوبكم، والله يعلم تصرّفكم في النهار في مصالح معاشكم ومعادكم، ويعلم مثواكم في فرشكم نائمين، فاخشوه واتقوه حتى تفوزوا برضاه.", "h": ["من الجائز أن تكون السورة مكية وبها آية أو أكثر مدنية.", "التحذير من اتباع الهوى فإنه يُعمي ويُصمّ، والعياذ بالله.", "بيان أن لقيام الساعة أشراطاً، أي علامات تظهر قبلها فتدل على قربها.", "وجوب العلم بأنه لا إله إلا الله، وذلك يتم على الطريقة التالية: الاعتراف بأن الإنسان مخلوق كسائر المخلوقات حوله، وكل مخلوق لا بد له من خالق، فمن خالق الإنسان والكون؟ والجواب قطعاً: الله، فما دام الله هو الخالق فمن عداه مخلوق مفتقر إليه، ومن يُؤلّه ويُعبد إذاً، الخالق أم المخلوق؟ والجواب: الخالق، إذاً تعيّن أنه لا معبود إلا الله، وهو معنى لا إله إلا الله، ولما كانت العبادة لا تُعرف إلا بالوحي وجب الإيمان برسول الله، فكان لا بد من زيادة: محمد رسول الله."], "k": "«فاعلم أنه لا إله إلا الله واستغفر لذنبك»… علمٌ ثم استغفار؛ فهل أجدّد الاثنين كل يوم؟"}]$j$::jsonb then 0 else 1 end;
