insert into public.tdb_cards(topic, i, body) select 377, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٠ – ١٤", "q": "۞أَفَلَمۡ يَسِيرُواْ فِي ٱلۡأَرۡضِ فَيَنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلَّذِينَ مِن قَبۡلِهِمۡۖ دَمَّرَ ٱللَّهُ عَلَيۡهِمۡۖ وَلِلۡكَٰفِرِينَ أَمۡثَٰلُهَا ﴿١٠﴾ ذَٰلِكَ بِأَنَّ ٱللَّهَ مَوۡلَى ٱلَّذِينَ ءَامَنُواْ وَأَنَّ ٱلۡكَٰفِرِينَ لَا مَوۡلَىٰ لَهُمۡ ﴿١١﴾ إِنَّ ٱللَّهَ يُدۡخِلُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ وَٱلَّذِينَ كَفَرُواْ يَتَمَتَّعُونَ وَيَأۡكُلُونَ كَمَا تَأۡكُلُ ٱلۡأَنۡعَٰمُ وَٱلنَّارُ مَثۡوٗى لَّهُمۡ ﴿١٢﴾ وَكَأَيِّن مِّن قَرۡيَةٍ هِيَ أَشَدُّ قُوَّةٗ مِّن قَرۡيَتِكَ ٱلَّتِيٓ أَخۡرَجَتۡكَ أَهۡلَكۡنَٰهُمۡ فَلَا نَاصِرَ لَهُمۡ ﴿١٣﴾ أَفَمَن كَانَ عَلَىٰ بَيِّنَةٖ مِّن رَّبِّهِۦ كَمَن زُيِّنَ لَهُۥ سُوٓءُ عَمَلِهِۦ وَٱتَّبَعُوٓاْ أَهۡوَآءَهُم ﴿١٤﴾", "w": [["أفلم يسيروا في الأرض", "أغفل هؤلاء المشركون فلم يسيروا في البلاد؟"], ["فينظروا كيف كان عاقبة الذين من قبلهم", "كيف كانت نهاية الذين من قبلهم كعاد وثمود."], ["دمّر الله عليهم وللكافرين أمثالها", "دمّر عليهم مساكنهم فأهلكهم وأولادهم وأموالهم، وللكافرين أمثال تلك العاقبة السيئة."], ["وأن الكافرين لا مولى لهم", "لا ناصر لهم."], ["يتمتّعون ويأكلون كما تأكل الأنعام", "يتمتّعون بمتع الدنيا ويأكلون بنهم وازدراد كأكل الأنعام."], ["والنار مثوى لهم", "مأواهم."], ["وكأيّن من قرية هي أشد قوة", "وكثير من أهل قرية هي أشد قوة."], ["من قريتك التي أخرجتك", "مكة، إذ أخرج أهلها النبي ﷺ."], ["أفمن كان على بيّنة من ربه", "على حجة وبرهان من أمر دينه فهو يعبد الله على علم."], ["كمن زُيّن له سوء عمله", "كمن زيّن الشيطان له سوء عمله."], ["واتبعوا أهواءهم", "في عبادة الأصنام، والجواب: ليسوا سواء."]], "m": "يوبّخ تعالى المشركين المصرّين على الشرك: أغفلوا فلم يسيروا في الأرض فينظروا كيف كان عاقبة الذين من قبلهم كعاد وثمود وقوم لوط، إذ دمّر الله عليهم بلادهم فأهلكهم وأولادهم وأموالهم فيعتبروا؟ وللكافرين أمثال تلك العاقبة؛ وعيد لكفار مكة إن لم يتوبوا. ذلك النصر للمؤمنين والقهر للكافرين بأن الله وليّ الذين آمنوا وناصرهم، وأن الكافرين لا مولى لهم لأن الله خاذلهم، ومن يخذله الله فلا ناصر له. إن الله يدخل الذين آمنوا وعملوا الصالحات جنات تجري من تحت قصورها وأشجارها الأنهار، والذين كفروا يتمتّعون في الدنيا بملاذّها ويأكلون كما تأكل الأنعام، إذ ليس لهم همّ إلا بطونهم وفروجهم، فلا يلتفتون إلى الآخرة، والنار مثوى لهم؛ وهذا الترغيب والترهيب سمة بارزة في أسلوب القرآن. وكثير من القرى أهلها أشد قوة من أهل مكة التي أخرجك أهلها أهلكناهم فلا ناصر لهم؛ نزلت ساعة خروج الرسول ﷺ مهاجراً إذ التفت إلى مكة وقال: «أنتِ أحب البلاد إلى الله وأحب بلاد الله إليّ، ولو أن المشركين لم يخرجوني لم أخرج منك»، فكانت تسلية له. أفمن كان على علم وبرهان من صحة معتقده وعبادته لله راجياً ثوابه خائفاً عقابه، كمن زيّن له الشيطان قبيح عمله من الشرك فهو يعبد الأصنام واتبعوا أهواءهم فلم يتبعوا وحياً ولا عقلاً؟ لا يتماثلان، إذ بينهما كما بين الحياة والموت والجنة والنار.", "h": ["تقرير قاعدة: العاقل من اعتبر بغيره.", "تقرير ولاية الله لأهل الإيمان والتقوى.", "بيان الفرق بين الماديين وأهل الإيمان والاستقامة على منهج الإسلام.", "تسلية الرسول ﷺ تخفيفاً من آلامه التي يعانيها من إعراض المشركين وصدودهم."], "k": "«ويأكلون كما تأكل الأنعام»… هل في حياتي هدف أبعد من بطني وراحتي؟"}, {"lbl": "الآية ١٥", "q": "مَّثَلُ ٱلۡجَنَّةِ ٱلَّتِي وُعِدَ ٱلۡمُتَّقُونَۖ فِيهَآ أَنۡهَٰرٞ مِّن مَّآءٍ غَيۡرِ ءَاسِنٖ وَأَنۡهَٰرٞ مِّن لَّبَنٖ لَّمۡ يَتَغَيَّرۡ طَعۡمُهُۥ وَأَنۡهَٰرٞ مِّنۡ خَمۡرٖ لَّذَّةٖ لِّلشَّـٰرِبِينَ وَأَنۡهَٰرٞ مِّنۡ عَسَلٖ مُّصَفّٗىۖ وَلَهُمۡ فِيهَا مِن كُلِّ ٱلثَّمَرَٰتِ وَمَغۡفِرَةٞ مِّن رَّبِّهِمۡۖ كَمَنۡ هُوَ خَٰلِدٞ فِي ٱلنَّارِ وَسُقُواْ مَآءً حَمِيمٗا فَقَطَّعَ أَمۡعَآءَهُمۡ ﴿١٥﴾", "w": [["مثل الجنة التي وُعد المتقون", "صفة الجنة دار السلام التي وعد الله بها عباده المتقين."], ["من ماء غير آسن", "غير متغيّر الريح والطعم لطول مكثه."], ["وأنهار من عسل مصفّى", "مصفّى من الشمع وفضلات النحل."], ["وسُقوا ماءً حميماً", "حاراً شديد الحرارة."], ["فقطّع أمعاءهم", "مصارينهم فخرجت من أدبارهم."]], "m": "هذه الآية تضمّنت شرحاً وافياً لأنهار الجنة وشراب أهل النار، ومقارنة بين حال أهل الإيمان والتقوى وما وُعدوا به من المغفرة ودخول الجنة، وحال أهل النار الخالدين فيها: صفة الجنة التي وعد الله بها عباده المتقين، أولياءه الذين عبدوه ووحّدوه وأطاعوه فاتقوا الشرك والمعاصي: فيها أنهار من ماء غير متغيّر الطعم ولا الريح، وأنهار من لبن لم يتغيّر طعمه بحموضة، وأنهار من خمر لذة لمن يشربها، غير كدرة ولا مسكرة ولا ريح غير طيبة لها، وأنهار من عسل مصفّى من الشمع وفضلات النحل، ولهم فيها من سائر أنواع الثمار والفواكه، ومع ذلك مغفرة من ربهم لسائر ذنوبهم. فهل يستوي من هذه حالهم بحال من هو خالد في النار لا يخرج منها، وسُقوا ماءً حاراً شديد الحرارة فلما شربوه قطّع أمعاءهم فخرجت من أدبارهم؟ والعياذ بالله من النار وحال أهل النار.", "h": ["التقوى هي السبب المورث للجنة، هكذا جعلها الله عز وجل، والتقوى هي بعد الإيمان فعل المأمورات وترك المنهيات من سائر أنواع الشرك والمعاصي.", "بيان بعض نعيم الجنة من الشراب والفواكه.", "بيان بعض عذاب النار، وهو الخلود فيها وشرب الحميم.", "تقرير البعث والجزاء، وأن لا مماثلة بين أهل السعادة وأهل الشقاء."], "k": "«مثل الجنة التي وُعد المتقون»… الوصف بين يديّ؛ فهل يحرّك شوقي إليها عملي اليوم؟"}, {"lbl": "الآيات ١٦ – ١٩", "q": "وَمِنۡهُم مَّن يَسۡتَمِعُ إِلَيۡكَ حَتَّىٰٓ إِذَا خَرَجُواْ مِنۡ عِندِكَ قَالُواْ لِلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ مَاذَا قَالَ ءَانِفًاۚ أُوْلَـٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَٱتَّبَعُوٓاْ أَهۡوَآءَهُمۡ ﴿١٦﴾ وَٱلَّذِينَ ٱهۡتَدَوۡاْ زَادَهُمۡ هُدٗى وَءَاتَىٰهُمۡ تَقۡوَىٰهُمۡ ﴿١٧﴾ فَهَلۡ يَنظُرُونَ إِلَّا ٱلسَّاعَةَ أَن تَأۡتِيَهُم بَغۡتَةٗۖ فَقَدۡ جَآءَ أَشۡرَاطُهَاۚ فَأَنَّىٰ لَهُمۡ إِذَا جَآءَتۡهُمۡ ذِكۡرَىٰهُمۡ ﴿١٨﴾ فَٱعۡلَمۡ أَنَّهُۥ لَآ إِلَٰهَ إِلَّا ٱللَّهُ وَٱسۡتَغۡفِرۡ لِذَنۢبِكَ وَلِلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِۗ وَٱللَّهُ يَعۡلَمُ مُتَقَلَّبَكُمۡ وَمَثۡوَىٰكُمۡ ﴿١٩﴾", "w": [["ومنهم من يستمع إليك", "ومن الكفار المنافقين من يستمع إليك في خطبة الجمعة."], ["ماذا قال آنفاً", "الساعة؟ استهزاءً وسخرية، يعنون أنه شيء لا يُرجع إليه ولا يُعتدّ به."], ["طبع الله على قلوبهم", "بالكفر، فلذا هم لا يعون."], ["واتبعوا أهواءهم", "في الكفر والنفاق."], ["والذين اهتدوا", "المؤمنون."], ["زادهم هدى", "زادهم الله هدى."], ["وآتاهم تقواهم", "ألهمهم ما يتقون به عذاب الله تعالى."], ["فهل ينظرون إلا الساعة", "ما ينتظر أهل مكة إلا الساعة."], ["أن تأتيهم بغتة", "فجأة."], ["فقد جاء أشراطها", "علاماتها، كبعثة النبي ﷺ وانشقاق القمر والدخان."], ["فأنّى لهم إذا جاءتهم ذكراهم", "أنّى لهم التذكّر الذي ينفعهم إذا جاءتهم، إذ قد أُغلق باب التوبة."], ["فاعلم أنه لا إله إلا الله", "بناءً على ما تقدم فاعلم يا نبينا أنه لا يستحق العبادة إلا الله، فاعبده وتوكل عليه."], ["واستغفر لذنبك", "قل: أستغفر الله، أو: اللهم اغفر لي."], ["وللمؤمنين والمؤمنات", "واستغفر للمؤمنين والمؤمنات."], ["والله يعلم متقلّبكم", "متصرّفكم في النهار في أمور دنياكم."], ["ومثواكم", "مكان إقامتكم ونومكم بالليل."]], "m": "هذه الآية والتي بعدها مدنيّتان نزلتا في شأن المنافقين: ومن المنافقين من يستمع إلى حديثك يوم الجمعة وأنت تخطب على المنبر، حتى إذا خرجوا من المسجد قالوا للذين أوتوا العلم من أصحابك كعبد الله بن مسعود: ماذا قال آنفاً؟ وقولهم هذا ظاهر عليه الخبث، إذ لو كانوا مؤمنين لقالوا: ماذا قال رسول الله؟ وهم يعنون أن ما قاله ليس بشيء مفيد. أولئك الذين طبع الله على قلوبهم بالكفر والنفاق لكثرة تلوّثهم بأوضارهما حتى ران على قلوبهم، واتبعوا أهواءهم؛ فهما علّتان: الطبع المانع من طلب الهداية، واتباع الهوى وهو يُعمي ويُصمّ. والذين اهتدوا إلى الإيمان الصحيح والعمل الصالح زادهم الله هدى حسب سنته في نماء الأشياء، وألهمهم ما يتقون به مساخطه، وأعظمها الشرك والمعاصي. فهل ينتظر زعماء الكفر في مكة إلا الساعة أن تأتيهم فجأة؟ فقد جاءت أشراطها: بعثة محمد ﷺ، والدخان، وانشقاق القمر، فأنّى لهم التذكّر النافع إذا جاءت؟ إذ بظهور علاماتها الكبرى لا تُقبل التوبة ممن لم يكن مؤمناً. فالآية تستبطئ إيمان كفار مكة مع ظهور أدلة العقل والنقل. فاعلم يا محمد أنه لا معبود تنبغي له العبادة إلا الله الذي هو خالق كل شيء ومالكه، واستغفر لذنبك وللمؤمنين والمؤمنات؛ والخطاب وإن وُجّه للرسول فالمراد به غيره، فكأنما قال: يا عباد الله والرسول على رأسكم، اعلموا أنه لا إله إلا الله واستغفروا لذنوبكم، والله يعلم تصرّفكم في النهار في مصالح معاشكم ومعادكم، ويعلم مثواكم في فرشكم نائمين، فاخشوه واتقوه حتى تفوزوا برضاه.", "h": ["من الجائز أن تكون السورة مكية وبها آية أو أكثر مدنية.", "التحذير من اتباع الهوى فإنه يُعمي ويُصمّ، والعياذ بالله.", "بيان أن لقيام الساعة أشراطاً، أي علامات تظهر قبلها فتدل على قربها.", "وجوب العلم بأنه لا إله إلا الله، وذلك يتم على الطريقة التالية: الاعتراف بأن الإنسان مخلوق كسائر المخلوقات حوله، وكل مخلوق لا بد له من خالق، فمن خالق الإنسان والكون؟ والجواب قطعاً: الله، فما دام الله هو الخالق فمن عداه مخلوق مفتقر إليه، ومن يُؤلّه ويُعبد إذاً، الخالق أم المخلوق؟ والجواب: الخالق، إذاً تعيّن أنه لا معبود إلا الله، وهو معنى لا إله إلا الله، ولما كانت العبادة لا تُعرف إلا بالوحي وجب الإيمان برسول الله، فكان لا بد من زيادة: محمد رسول الله."], "k": "«فاعلم أنه لا إله إلا الله واستغفر لذنبك»… علمٌ ثم استغفار؛ فهل أجدّد الاثنين كل يوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (378, 47, 20, 38, 'سورة محمد ٢٠ – ٣٨', 'محمد: أفلا يتدبرون القرآن أم على قلوب أقفالها', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 378) = $j$[{"lbl": "الآيات ٢٠ – ٢٣", "q": "وَيَقُولُ ٱلَّذِينَ ءَامَنُواْ لَوۡلَا نُزِّلَتۡ سُورَةٞۖ فَإِذَآ أُنزِلَتۡ سُورَةٞ مُّحۡكَمَةٞ وَذُكِرَ فِيهَا ٱلۡقِتَالُ رَأَيۡتَ ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ يَنظُرُونَ إِلَيۡكَ نَظَرَ ٱلۡمَغۡشِيِّ عَلَيۡهِ مِنَ ٱلۡمَوۡتِۖ فَأَوۡلَىٰ لَهُمۡ ﴿٢٠﴾ طَاعَةٞ وَقَوۡلٞ مَّعۡرُوفٞۚ فَإِذَا عَزَمَ ٱلۡأَمۡرُ فَلَوۡ صَدَقُواْ ٱللَّهَ لَكَانَ خَيۡرٗا لَّهُمۡ ﴿٢١﴾ فَهَلۡ عَسَيۡتُمۡ إِن تَوَلَّيۡتُمۡ أَن تُفۡسِدُواْ فِي ٱلۡأَرۡضِ وَتُقَطِّعُوٓاْ أَرۡحَامَكُمۡ ﴿٢٢﴾ أُوْلَـٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُ فَأَصَمَّهُمۡ وَأَعۡمَىٰٓ أَبۡصَٰرَهُمۡ ﴿٢٣﴾", "w": [["لولا نُزّلت سورة", "هلّا نزلت سورة، يقول هذا المؤمنون طلباً للجهاد."], ["سورة محكمة", "لم يُنسخ منها شيء من أوامرها ونواهيها."], ["وذُكر فيها القتال", "طُلب القتال بالدعوة إليه والترغيب فيه."], ["في قلوبهم مرض", "شك، وهم المنافقون."], ["نظر المغشيّ عليه من الموت", "ينظرون إلى الرسول خوفاً من القتال وكراهية له مثل نظر المغشيّ عليه من سكرات الموت."], ["فأولى لهم طاعة وقول معروف", "فأجدر بهم طاعة لرسول الله وقول معروف حسن له."], ["فإذا عزم الأمر", "فُرض القتال وجدّ أمر الخروج إليه."], ["فلو صدقوا الله", "وفوا لله بما تعهّدوا به من أنهم يقاتلون."], ["لكان خيراً لهم", "في دنياهم وآخرتهم."], ["فهل عسيتم إن تولّيتم", "أعرضتم عن الإيمان الصوري الذي أنتم عليه وأعلنتم الكفر."], ["أن تفسدوا في الأرض وتقطّعوا أرحامكم", "تفسدوا بالشرك والمعاصي ولا تصلوا أرحامكم."], ["فأصمّهم وأعمى أبصارهم", "فلذا هم لا يسمعون الحق ولا يبصرون الخير والمعروف."]], "m": "من هنا إلى آخر السورة ظاهره أنه مدني، إذ القتال لم يُفرض والنفاق لم يظهر إلا بعد الهجرة: ويقول أصحاب رسول الله ﷺ متمنّين الجهاد: هلّا أنزل الله سورة تأمر بالجهاد، فإذا أُنزلت سورة محكمة ليس فيها نسخ وذُكر فيها الأمر بالقتال والترغيب فيه رأيت الذين في قلوبهم مرض الشك والنفاق ينظرون إليك نظر المغمى عليه من سكرات الموت. فأولى لهم: صالح لأن يكون دعاءً عليهم بالهلاك لجبنهم ونفاقهم، وصالح أن يكون بمعنى الأجدر بمثلهم طاعة لله ورسوله وقول معروف حسن. فإذا جدّ الأمر للجهاد فلو صدقوا الله ما عاهدوا عليه من القتال مع رسوله لكان خيراً لهم في الدنيا والآخرة. ثم قال لهم توبيخاً: فهل عسيتم إن رجعتم عن الإيمان الصوري إلى الكفر الظاهر أن تفسدوا في الأرض بالشرك والمعاصي وتقطّعوا أرحامكم بإعلان الحرب على أقربائكم المؤمنين؟ وإن كان التولّي بمعنى الحكم فالأمر كذلك. أولئك البعداء في الخسّة الذين لعنهم الله فأبعدهم من رحمته، فأصمّهم عن سماع الحق وأعمى أبصارهم عن رؤية الهدى.", "h": ["جواز تمنّي الخير، والأولى أن يسأل الله تعالى ولا يتمنّى بلفظ: ليت كذا.", "القرآن محكم ومنسوخ من الآيات، وكله كلام الله يُتلى ويُتقرّب به إلى الله تعالى، ويُعمل بالمحكم دون المنسوخ، وهو قليل جداً.", "ذمّ الجبن والخور والهزيمة الروحية.", "شر الخلق من إذا تولّى أفسد في الأرض بالشرك والمعاصي."], "k": "«فلو صدقوا الله لكان خيراً لهم»… كم وعدتُ الله وعوداً في الرخاء؛ فهل أصدق حين يجدّ الأمر؟"}, {"lbl": "الآيات ٢٤ – ٢٨", "q": "أَفَلَا يَتَدَبَّرُونَ ٱلۡقُرۡءَانَ أَمۡ عَلَىٰ قُلُوبٍ أَقۡفَالُهَآ ﴿٢٤﴾ إِنَّ ٱلَّذِينَ ٱرۡتَدُّواْ عَلَىٰٓ أَدۡبَٰرِهِم مِّنۢ بَعۡدِ مَا تَبَيَّنَ لَهُمُ ٱلۡهُدَى ٱلشَّيۡطَٰنُ سَوَّلَ لَهُمۡ وَأَمۡلَىٰ لَهُمۡ ﴿٢٥﴾ ذَٰلِكَ بِأَنَّهُمۡ قَالُواْ لِلَّذِينَ كَرِهُواْ مَا نَزَّلَ ٱللَّهُ سَنُطِيعُكُمۡ فِي بَعۡضِ ٱلۡأَمۡرِۖ وَٱللَّهُ يَعۡلَمُ إِسۡرَارَهُمۡ ﴿٢٦﴾ فَكَيۡفَ إِذَا تَوَفَّتۡهُمُ ٱلۡمَلَـٰٓئِكَةُ يَضۡرِبُونَ وُجُوهَهُمۡ وَأَدۡبَٰرَهُمۡ ﴿٢٧﴾ ذَٰلِكَ بِأَنَّهُمُ ٱتَّبَعُواْ مَآ أَسۡخَطَ ٱللَّهَ وَكَرِهُواْ رِضۡوَٰنَهُۥ فَأَحۡبَطَ أَعۡمَٰلَهُمۡ ﴿٢٨﴾", "w": [["أفلا يتدبرون القرآن", "يتفكّرون فيه فيعرفون الحق من الباطل."], ["أم على قلوب أقفالها", "بل على قلوب لهم أقفالها فهم لا يفهمون إن تدبّروا."], ["إن الذين ارتدّوا على أدبارهم", "رجعوا كافرين بنفاقهم."], ["من بعد ما تبيّن لهم الهدى", "من بعد ما تبيّن لهم صدق الرسول وصحة دينه بالحجج."], ["الشيطان سوّل لهم وأملى لهم", "زيّن لهم نفاقهم، وواعدهم بطول العمر ومنّاهم."], ["ذلك بأنهم قالوا للذين كرهوا ما نزّل الله", "ذلك الإضلال بسبب قولهم للمشركين الكارهين لما أنزل الله."], ["سنطيعكم في بعض الأمر", "بأن نتعاون معكم على عداوة الرسول وتثبيط المؤمنين عن الجهاد، وكان ذلك سراً فأظهره الله لرسوله."], ["يضربون وجوههم وأدبارهم", "بمقامع من حديد يضربون وجوههم وظهورهم."], ["ذلك بأنهم اتبعوا ما أسخط الله", "التوفّي على هذه الحال بسبب اتباعهم ما أسخط الله من الشرك والمعاصي."], ["وكرهوا رضوانه", "ما يرضيه من التوحيد والعمل الصالح."], ["فأحبط أعمالهم", "أبطلها فلم يحصلوا منها على ثواب حسن."]], "m": "ما زال السياق في تأديب المنافقين بعيبهم وتهديدهم لعلهم يرجعون: أغفلوا فلم يتدبّروا القرآن فيعرفوا الحق من الباطل والهدى من الضلال، والقرآن نزل لبيان ذلك؟ بل على قلوب لهم أقفالها، أقفل الله عليها فلا يعقلون ما في كتابه من المواعظ والحجج حتى يكون الله هو الذي يفتحها، والله يُقفل ويفتح حسب سنن له في ذلك. إن الذين رجعوا إلى الكفر بقلوبهم دون ألسنتهم، وهم المنافقون، من بعد ما تبيّن لهم صدق الرسول وصحة دينه، الشيطان زيّن لهم ذلك الارتداد ومنّاهم بطول العمر والعيش الواسع. ذلك الإضلال بسبب أنهم قالوا سراً للمشركين الكارهين لما أنزل الله من القرآن والشرائع: سنطيعكم في بعض الأمر، كعدم قتالكم وتثبيط الناس عن القتال، والله يعلم إسرارهم، وقد أطلع عليهم رسوله والمؤمنين. فكيف حالهم إذا توفّتهم ملائكة الموت والعذاب يضربون وجوههم وظهورهم بمقامع من حديد؟ ذلك بسبب أنهم اتبعوا ما أسخط الله من الكفر به وبرسوله، وكرهوا ما يرضيه وهو الجهاد في سبيله، فأحبط الله أعمالهم لأن عمل الكافر باطل.", "h": ["وجوب تدبّر القرآن الكريم عند تلاوته أو سماعه، وهو تفهّم معانيه في حدود قدرة المسلم.", "الارتداد عن الإسلام، كالرجوع عن الطاعة إلى المعصية، سببهما تزيين الشيطان للعبد ذلك وإملاؤه له بالتمنّي والوعد الكاذب.", "من الردة التعاون مع الكافرين على المؤمنين بأي شكل من أشكال التعاون ضد الإسلام.", "تقرير عقيدة عذاب القبر، وأنه حق ثابت، أعاذنا الله منه."], "k": "«أفلا يتدبرون القرآن أم على قلوب أقفالها»… هل أقرأ اليوم بقلب مفتوح؟"}, {"lbl": "الآيات ٢٩ – ٣٢", "q": "أَمۡ حَسِبَ ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٌ أَن لَّن يُخۡرِجَ ٱللَّهُ أَضۡغَٰنَهُمۡ ﴿٢٩﴾ وَلَوۡ نَشَآءُ لَأَرَيۡنَٰكَهُمۡ فَلَعَرَفۡتَهُم بِسِيمَٰهُمۡۚ وَلَتَعۡرِفَنَّهُمۡ فِي لَحۡنِ ٱلۡقَوۡلِۚ وَٱللَّهُ يَعۡلَمُ أَعۡمَٰلَكُمۡ ﴿٣٠﴾ وَلَنَبۡلُوَنَّكُمۡ حَتَّىٰ نَعۡلَمَ ٱلۡمُجَٰهِدِينَ مِنكُمۡ وَٱلصَّـٰبِرِينَ وَنَبۡلُوَاْ أَخۡبَارَكُمۡ ﴿٣١﴾ إِنَّ ٱلَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ وَشَآقُّواْ ٱلرَّسُولَ مِنۢ بَعۡدِ مَا تَبَيَّنَ لَهُمُ ٱلۡهُدَىٰ لَن يَضُرُّواْ ٱللَّهَ شَيۡـٔٗا وَسَيُحۡبِطُ أَعۡمَٰلَهُمۡ ﴿٣٢﴾", "w": [["في قلوبهم مرض", "مرض النفاق."], ["أن لن يُخرج الله أضغانهم", "أن لن يُظهر أحقادهم على النبي ﷺ والمؤمنين."], ["ولو نشاء لأريناكهم", "لعرّفناك بهم فلعرفتهم."], ["بسيماهم", "بعلاماتهم."], ["ولتعرفنّهم في لحن القول", "في معنى كلامهم إذا تكلموا عندك، بأن يُعرّضوا فيه بتقبيح أمر المسلمين."], ["والله يعلم أعمالكم", "أيها المؤمنون، وسيجزيكم بها خيراً."], ["ولنبلونّكم", "لنختبرنّكم بالجهاد وغيره من التكاليف."], ["حتى نعلم", "علم ظهور لكم ولغيركم، إذ الله يعلم ذلك قبل ظهوره."], ["المجاهدين منكم والصابرين", "الذين جاهدوا وصبروا من غيرهم."], ["ونبلوَ أخباركم", "نُظهر أخباركم للناس من طاعة وعصيان."], ["وشاقّوا الرسول", "خالفوه وعادوه وحاربوه."], ["من بعد ما تبيّن لهم الهدى", "عرفوا أن الرسول حق والإسلام حق، كاليهود وغيرهم."], ["لن يضرّوا الله شيئاً", "لأنه متعالٍ أن يناله خلقه بضرر."], ["وسيُحبط أعمالهم", "يبطلها فلا تثمر لهم ما يرجونه منها في الدنيا والآخرة."]], "m": "ما زال السياق في كشف عوار المنافقين: أحسب الذين في قلوبهم مرض النفاق الناجم عن الشك في الإسلام أن لن يُظهر الله أحقادهم لرسوله والمؤمنين؟ حسبانهم باطل. ولو نشاء لأريناكهم فلعرفتهم بعلامات النفاق فيهم، ولتعرفنّهم في معاني كلامهم إذا تكلموا بين يديك، فإنه لا يخلو من التعريض بالمؤمنين وانتقاصهم، كما قيل: من أضمر سريرة ألبسه الله رداءها. والله يعلم أعمالكم أيها المؤمنون وسيجزيكم بها فاصبروا، ولنختبرنّكم بالجهاد والإنفاق والتكاليف حتى نُظهر لكم المجاهد من القاعد والصابر من الضاجر، ونُظهر الصدق من خلافه فيما تتحدثون به عن أنفسكم؛ ولذا كان الفضيل بن عياض إذا قرأ هذه الآية بكى وقال: اللهم لا تبتلنا فإنك إذا بلوتنا فضحتنا وهتكت أستارنا. إن الذين كفروا وصدّوا الناس عن الإسلام وخالفوا الرسول وعادوه من بعد ما ظهر لهم الحق بالحجج لن يضرّوا الله شيئاً لتنزّهه عن صفات المحدَثين، وسيبطل أعمالهم فلا ينالون بها ما يؤمّلون في الدنيا بذهاب كيدهم إذ ينصر الله رسوله، وفي الآخرة لأن أعمال الكافر حابطة.", "h": ["بيان حقيقة، وهي: من أسرّ سريرة ألبسه الله رداءها فكشفه للناس.", "ومن أحب شيئاً ظهر على وجهه وفلتات لسانه.", "تقرير قاعدة، وهي أنه لا بد من الابتلاء لمن دخل في الإسلام ليكون الإيمان على حقيقته، لا إيماناً صورياً أدنى فتنة تصيب صاحبه يرتدّ بها عن الإسلام.", "أعمال المشرك والكافر باطلة لا ثواب خير عليها، لأن الشرك محبط للأعمال الصالحة."], "k": "«ونبلوَ أخباركم»… ما أقوله عن نفسي سيُختبر؛ فهل يصدّقه عملي؟"}, {"lbl": "الآيات ٣٣ – ٣٨", "q": "۞يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَ وَلَا تُبۡطِلُوٓاْ أَعۡمَٰلَكُمۡ ﴿٣٣﴾ إِنَّ ٱلَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ ثُمَّ مَاتُواْ وَهُمۡ كُفَّارٞ فَلَن يَغۡفِرَ ٱللَّهُ لَهُمۡ ﴿٣٤﴾ فَلَا تَهِنُواْ وَتَدۡعُوٓاْ إِلَى ٱلسَّلۡمِ وَأَنتُمُ ٱلۡأَعۡلَوۡنَ وَٱللَّهُ مَعَكُمۡ وَلَن يَتِرَكُمۡ أَعۡمَٰلَكُمۡ ﴿٣٥﴾ إِنَّمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَا لَعِبٞ وَلَهۡوٞۚ وَإِن تُؤۡمِنُواْ وَتَتَّقُواْ يُؤۡتِكُمۡ أُجُورَكُمۡ وَلَا يَسۡـَٔلۡكُمۡ أَمۡوَٰلَكُمۡ ﴿٣٦﴾ إِن يَسۡـَٔلۡكُمُوهَا فَيُحۡفِكُمۡ تَبۡخَلُواْ وَيُخۡرِجۡ أَضۡغَٰنَكُمۡ ﴿٣٧﴾ هَـٰٓأَنتُمۡ هَـٰٓؤُلَآءِ تُدۡعَوۡنَ لِتُنفِقُواْ فِي سَبِيلِ ٱللَّهِ فَمِنكُم مَّن يَبۡخَلُۖ وَمَن يَبۡخَلۡ فَإِنَّمَا يَبۡخَلُ عَن نَّفۡسِهِۦۚ وَٱللَّهُ ٱلۡغَنِيُّ وَأَنتُمُ ٱلۡفُقَرَآءُۚ وَإِن تَتَوَلَّوۡاْ يَسۡتَبۡدِلۡ قَوۡمًا غَيۡرَكُمۡ ثُمَّ لَا يَكُونُوٓاْ أَمۡثَٰلَكُم ﴿٣٨﴾", "w": [["ولا تُبطلوا أعمالكم", "بالرياء والشرك والمعاصي."], ["فلن يغفر الله لهم", "لأنهم ماتوا على الكفر، والكفر محبط للعمل."], ["فلا تهنوا وتدعوا إلى السلم", "لا تضعفوا وتدعوا إلى الصلح مع الكفار."], ["وأنتم الأعلون", "الغالبون القاهرون."], ["ولن يَتِرَكم أعمالكم", "لن ينقصكم أجر أعمالكم وثوابها."], ["إنما الحياة الدنيا لعب ولهو", "الاشتغال بالدنيا والتفرّغ لها ما هو إلا لهو ولعب لعدم عائده."], ["ولا يسألكم أموالكم", "لا يكلّفكم بإنفاق أموالكم كلها، بل بالزكاة فقط."], ["فيُحفِكم تبخلوا", "بالمبالغة في طلب المال منكم تبخلوا."], ["ويُخرج أضغانكم", "أحقادكم وبغضكم لدين الإسلام."], ["فإنما يبخل عن نفسه", "عائد ذلك على نفسه، فهو الذي يُحرم الثواب."], ["وإن تتولّوا يستبدل قوماً غيركم", "عن طاعة الله ورسوله يأتِ بآخرين غيركم."], ["ثم لا يكونوا أمثالكم", "بل يكونوا أطوع منكم لله ورسوله."]], "m": "لما ذكر الكفار ومشاقّتهم لرسوله نادى المؤمنين: يا أيها الذين آمنوا بالله رباً وبالإسلام ديناً وبمحمد رسولاً، أطيعوا الله وأطيعوا الرسول فيما يأمرانكم به وينهيانكم عنه، ولا تبطلوا أعمالكم بالشرك والرياء والمعاصي فتُحرموا ثوابها. إن الذين كفروا وصدّوا عن الإسلام ثم ماتوا كفاراً قبل أن يتوبوا لن يغفر الله لهم. فلا تضعفوا عن قتال أعدائكم وتدعوهم إلى الصلح والمهادنة وأنتم أقوياء قادرون غالبون، والله معكم، ولن ينقصكم أجر أعمالكم بل يجزيكم ويزيدكم من فضله. إنما الحياة الدنيا إن أقبل عليها العبد ناسياً الآخرة لعب ولهو، لا يظفر منها بطائل، كلعب الصبيان يلهون بجد ثم يعودون إلى والديهم يطلبون الطعام. وإن تؤمنوا الإيمان الصحيح وتتقوا الشرك والمعاصي يؤتكم أجوركم، ولا يسألكم أموالكم كلها، إن يسألكموها فيُلحّ عليكم تبخلوا، إذ هذا معروف من طباع البشر، وقد يترك أحدهم الإسلام لذلك، ويُخرج أحقادكم وكراهيتكم للدين. ها أنتم هؤلاء تُدعون لتنفقوا بعض أموالكم في الزكاة والجهاد، فمنكم من يبخل، ومن يبخل فإنما يحرم نفسه أجر النفقة، والله الغني عنكم وأنتم الفقراء إليه، لا يحضّكم على النفقة لحاجته إليها ولكن لحاجتكم أنتم، إذ بها تزكو نفوسكم وتقوم أموركم وتنتصرون على عدوكم. وإن ترجعوا عن الإسلام يستبدل قوماً غيركم أطوع لله منكم، وحاشاهم أن يتولّوا وما تولّوا، وإنما هذا من باب حثّهم على معالي الأمور، نظراً لمكانتهم من هذه الأمة، فهم أشرفها وأكملها وأطوعها لله وأحبها له ولرسوله.", "h": ["وجوب طاعة الله وطاعة رسوله.", "وجوب إتمام العمل الصالح من صلاة وغيرها بالشروع فيه.", "بطلان العمل الصالح بالرياء، أو بإفساده عند أدائه، أو بالردة عن الإسلام.", "حرمة الركون إلى مصالحة الأعداء مع القدرة على قتالهم والتمكن من دفع شرهم.", "التنفير من الإقبال على الدنيا والإعراض عن الآخرة.", "حرمة البخل مع الجِدة والسعة."], "k": "«ولا تُبطلوا أعمالكم»… العمل يُبنى ويُهدم؛ فما الذي قد يهدم عملي اليوم بعد أن بنيته؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 378;
insert into public.tdb_cards(topic, i, body) select 378, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٠ – ٢٣", "q": "وَيَقُولُ ٱلَّذِينَ ءَامَنُواْ لَوۡلَا نُزِّلَتۡ سُورَةٞۖ فَإِذَآ أُنزِلَتۡ سُورَةٞ مُّحۡكَمَةٞ وَذُكِرَ فِيهَا ٱلۡقِتَالُ رَأَيۡتَ ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ يَنظُرُونَ إِلَيۡكَ نَظَرَ ٱلۡمَغۡشِيِّ عَلَيۡهِ مِنَ ٱلۡمَوۡتِۖ فَأَوۡلَىٰ لَهُمۡ ﴿٢٠﴾ طَاعَةٞ وَقَوۡلٞ مَّعۡرُوفٞۚ فَإِذَا عَزَمَ ٱلۡأَمۡرُ فَلَوۡ صَدَقُواْ ٱللَّهَ لَكَانَ خَيۡرٗا لَّهُمۡ ﴿٢١﴾ فَهَلۡ عَسَيۡتُمۡ إِن تَوَلَّيۡتُمۡ أَن تُفۡسِدُواْ فِي ٱلۡأَرۡضِ وَتُقَطِّعُوٓاْ أَرۡحَامَكُمۡ ﴿٢٢﴾ أُوْلَـٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُ فَأَصَمَّهُمۡ وَأَعۡمَىٰٓ أَبۡصَٰرَهُمۡ ﴿٢٣﴾", "w": [["لولا نُزّلت سورة", "هلّا نزلت سورة، يقول هذا المؤمنون طلباً للجهاد."], ["سورة محكمة", "لم يُنسخ منها شيء من أوامرها ونواهيها."], ["وذُكر فيها القتال", "طُلب القتال بالدعوة إليه والترغيب فيه."], ["في قلوبهم مرض", "شك، وهم المنافقون."], ["نظر المغشيّ عليه من الموت", "ينظرون إلى الرسول خوفاً من القتال وكراهية له مثل نظر المغشيّ عليه من سكرات الموت."], ["فأولى لهم طاعة وقول معروف", "فأجدر بهم طاعة لرسول الله وقول معروف حسن له."], ["فإذا عزم الأمر", "فُرض القتال وجدّ أمر الخروج إليه."], ["فلو صدقوا الله", "وفوا لله بما تعهّدوا به من أنهم يقاتلون."], ["لكان خيراً لهم", "في دنياهم وآخرتهم."], ["فهل عسيتم إن تولّيتم", "أعرضتم عن الإيمان الصوري الذي أنتم عليه وأعلنتم الكفر."], ["أن تفسدوا في الأرض وتقطّعوا أرحامكم", "تفسدوا بالشرك والمعاصي ولا تصلوا أرحامكم."], ["فأصمّهم وأعمى أبصارهم", "فلذا هم لا يسمعون الحق ولا يبصرون الخير والمعروف."]], "m": "من هنا إلى آخر السورة ظاهره أنه مدني، إذ القتال لم يُفرض والنفاق لم يظهر إلا بعد الهجرة: ويقول أصحاب رسول الله ﷺ متمنّين الجهاد: هلّا أنزل الله سورة تأمر بالجهاد، فإذا أُنزلت سورة محكمة ليس فيها نسخ وذُكر فيها الأمر بالقتال والترغيب فيه رأيت الذين في قلوبهم مرض الشك والنفاق ينظرون إليك نظر المغمى عليه من سكرات الموت. فأولى لهم: صالح لأن يكون دعاءً عليهم بالهلاك لجبنهم ونفاقهم، وصالح أن يكون بمعنى الأجدر بمثلهم طاعة لله ورسوله وقول معروف حسن. فإذا جدّ الأمر للجهاد فلو صدقوا الله ما عاهدوا عليه من القتال مع رسوله لكان خيراً لهم في الدنيا والآخرة. ثم قال لهم توبيخاً: فهل عسيتم إن رجعتم عن الإيمان الصوري إلى الكفر الظاهر أن تفسدوا في الأرض بالشرك والمعاصي وتقطّعوا أرحامكم بإعلان الحرب على أقربائكم المؤمنين؟ وإن كان التولّي بمعنى الحكم فالأمر كذلك. أولئك البعداء في الخسّة الذين لعنهم الله فأبعدهم من رحمته، فأصمّهم عن سماع الحق وأعمى أبصارهم عن رؤية الهدى.", "h": ["جواز تمنّي الخير، والأولى أن يسأل الله تعالى ولا يتمنّى بلفظ: ليت كذا.", "القرآن محكم ومنسوخ من الآيات، وكله كلام الله يُتلى ويُتقرّب به إلى الله تعالى، ويُعمل بالمحكم دون المنسوخ، وهو قليل جداً.", "ذمّ الجبن والخور والهزيمة الروحية.", "شر الخلق من إذا تولّى أفسد في الأرض بالشرك والمعاصي."], "k": "«فلو صدقوا الله لكان خيراً لهم»… كم وعدتُ الله وعوداً في الرخاء؛ فهل أصدق حين يجدّ الأمر؟"}, {"lbl": "الآيات ٢٤ – ٢٨", "q": "أَفَلَا يَتَدَبَّرُونَ ٱلۡقُرۡءَانَ أَمۡ عَلَىٰ قُلُوبٍ أَقۡفَالُهَآ ﴿٢٤﴾ إِنَّ ٱلَّذِينَ ٱرۡتَدُّواْ عَلَىٰٓ أَدۡبَٰرِهِم مِّنۢ بَعۡدِ مَا تَبَيَّنَ لَهُمُ ٱلۡهُدَى ٱلشَّيۡطَٰنُ سَوَّلَ لَهُمۡ وَأَمۡلَىٰ لَهُمۡ ﴿٢٥﴾ ذَٰلِكَ بِأَنَّهُمۡ قَالُواْ لِلَّذِينَ كَرِهُواْ مَا نَزَّلَ ٱللَّهُ سَنُطِيعُكُمۡ فِي بَعۡضِ ٱلۡأَمۡرِۖ وَٱللَّهُ يَعۡلَمُ إِسۡرَارَهُمۡ ﴿٢٦﴾ فَكَيۡفَ إِذَا تَوَفَّتۡهُمُ ٱلۡمَلَـٰٓئِكَةُ يَضۡرِبُونَ وُجُوهَهُمۡ وَأَدۡبَٰرَهُمۡ ﴿٢٧﴾ ذَٰلِكَ بِأَنَّهُمُ ٱتَّبَعُواْ مَآ أَسۡخَطَ ٱللَّهَ وَكَرِهُواْ رِضۡوَٰنَهُۥ فَأَحۡبَطَ أَعۡمَٰلَهُمۡ ﴿٢٨﴾", "w": [["أفلا يتدبرون القرآن", "يتفكّرون فيه فيعرفون الحق من الباطل."], ["أم على قلوب أقفالها", "بل على قلوب لهم أقفالها فهم لا يفهمون إن تدبّروا."], ["إن الذين ارتدّوا على أدبارهم", "رجعوا كافرين بنفاقهم."], ["من بعد ما تبيّن لهم الهدى", "من بعد ما تبيّن لهم صدق الرسول وصحة دينه بالحجج."], ["الشيطان سوّل لهم وأملى لهم", "زيّن لهم نفاقهم، وواعدهم بطول العمر ومنّاهم."], ["ذلك بأنهم قالوا للذين كرهوا ما نزّل الله", "ذلك الإضلال بسبب قولهم للمشركين الكارهين لما أنزل الله."], ["سنطيعكم في بعض الأمر", "بأن نتعاون معكم على عداوة الرسول وتثبيط المؤمنين عن الجهاد، وكان ذلك سراً فأظهره الله لرسوله."], ["يضربون وجوههم وأدبارهم", "بمقامع من حديد يضربون وجوههم وظهورهم."], ["ذلك بأنهم اتبعوا ما أسخط الله", "التوفّي على هذه الحال بسبب اتباعهم ما أسخط الله من الشرك والمعاصي."], ["وكرهوا رضوانه", "ما يرضيه من التوحيد والعمل الصالح."], ["فأحبط أعمالهم", "أبطلها فلم يحصلوا منها على ثواب حسن."]], "m": "ما زال السياق في تأديب المنافقين بعيبهم وتهديدهم لعلهم يرجعون: أغفلوا فلم يتدبّروا القرآن فيعرفوا الحق من الباطل والهدى من الضلال، والقرآن نزل لبيان ذلك؟ بل على قلوب لهم أقفالها، أقفل الله عليها فلا يعقلون ما في كتابه من المواعظ والحجج حتى يكون الله هو الذي يفتحها، والله يُقفل ويفتح حسب سنن له في ذلك. إن الذين رجعوا إلى الكفر بقلوبهم دون ألسنتهم، وهم المنافقون، من بعد ما تبيّن لهم صدق الرسول وصحة دينه، الشيطان زيّن لهم ذلك الارتداد ومنّاهم بطول العمر والعيش الواسع. ذلك الإضلال بسبب أنهم قالوا سراً للمشركين الكارهين لما أنزل الله من القرآن والشرائع: سنطيعكم في بعض الأمر، كعدم قتالكم وتثبيط الناس عن القتال، والله يعلم إسرارهم، وقد أطلع عليهم رسوله والمؤمنين. فكيف حالهم إذا توفّتهم ملائكة الموت والعذاب يضربون وجوههم وظهورهم بمقامع من حديد؟ ذلك بسبب أنهم اتبعوا ما أسخط الله من الكفر به وبرسوله، وكرهوا ما يرضيه وهو الجهاد في سبيله، فأحبط الله أعمالهم لأن عمل الكافر باطل.", "h": ["وجوب تدبّر القرآن الكريم عند تلاوته أو سماعه، وهو تفهّم معانيه في حدود قدرة المسلم.", "الارتداد عن الإسلام، كالرجوع عن الطاعة إلى المعصية، سببهما تزيين الشيطان للعبد ذلك وإملاؤه له بالتمنّي والوعد الكاذب.", "من الردة التعاون مع الكافرين على المؤمنين بأي شكل من أشكال التعاون ضد الإسلام.", "تقرير عقيدة عذاب القبر، وأنه حق ثابت، أعاذنا الله منه."], "k": "«أفلا يتدبرون القرآن أم على قلوب أقفالها»… هل أقرأ اليوم بقلب مفتوح؟"}, {"lbl": "الآيات ٢٩ – ٣٢", "q": "أَمۡ حَسِبَ ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٌ أَن لَّن يُخۡرِجَ ٱللَّهُ أَضۡغَٰنَهُمۡ ﴿٢٩﴾ وَلَوۡ نَشَآءُ لَأَرَيۡنَٰكَهُمۡ فَلَعَرَفۡتَهُم بِسِيمَٰهُمۡۚ وَلَتَعۡرِفَنَّهُمۡ فِي لَحۡنِ ٱلۡقَوۡلِۚ وَٱللَّهُ يَعۡلَمُ أَعۡمَٰلَكُمۡ ﴿٣٠﴾ وَلَنَبۡلُوَنَّكُمۡ حَتَّىٰ نَعۡلَمَ ٱلۡمُجَٰهِدِينَ مِنكُمۡ وَٱلصَّـٰبِرِينَ وَنَبۡلُوَاْ أَخۡبَارَكُمۡ ﴿٣١﴾ إِنَّ ٱلَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ وَشَآقُّواْ ٱلرَّسُولَ مِنۢ بَعۡدِ مَا تَبَيَّنَ لَهُمُ ٱلۡهُدَىٰ لَن يَضُرُّواْ ٱللَّهَ شَيۡـٔٗا وَسَيُحۡبِطُ أَعۡمَٰلَهُمۡ ﴿٣٢﴾", "w": [["في قلوبهم مرض", "مرض النفاق."], ["أن لن يُخرج الله أضغانهم", "أن لن يُظهر أحقادهم على النبي ﷺ والمؤمنين."], ["ولو نشاء لأريناكهم", "لعرّفناك بهم فلعرفتهم."], ["بسيماهم", "بعلاماتهم."], ["ولتعرفنّهم في لحن القول", "في معنى كلامهم إذا تكلموا عندك، بأن يُعرّضوا فيه بتقبيح أمر المسلمين."], ["والله يعلم أعمالكم", "أيها المؤمنون، وسيجزيكم بها خيراً."], ["ولنبلونّكم", "لنختبرنّكم بالجهاد وغيره من التكاليف."], ["حتى نعلم", "علم ظهور لكم ولغيركم، إذ الله يعلم ذلك قبل ظهوره."], ["المجاهدين منكم والصابرين", "الذين جاهدوا وصبروا من غيرهم."], ["ونبلوَ أخباركم", "نُظهر أخباركم للناس من طاعة وعصيان."], ["وشاقّوا الرسول", "خالفوه وعادوه وحاربوه."], ["من بعد ما تبيّن لهم الهدى", "عرفوا أن الرسول حق والإسلام حق، كاليهود وغيرهم."], ["لن يضرّوا الله شيئاً", "لأنه متعالٍ أن يناله خلقه بضرر."], ["وسيُحبط أعمالهم", "يبطلها فلا تثمر لهم ما يرجونه منها في الدنيا والآخرة."]], "m": "ما زال السياق في كشف عوار المنافقين: أحسب الذين في قلوبهم مرض النفاق الناجم عن الشك في الإسلام أن لن يُظهر الله أحقادهم لرسوله والمؤمنين؟ حسبانهم باطل. ولو نشاء لأريناكهم فلعرفتهم بعلامات النفاق فيهم، ولتعرفنّهم في معاني كلامهم إذا تكلموا بين يديك، فإنه لا يخلو من التعريض بالمؤمنين وانتقاصهم، كما قيل: من أضمر سريرة ألبسه الله رداءها. والله يعلم أعمالكم أيها المؤمنون وسيجزيكم بها فاصبروا، ولنختبرنّكم بالجهاد والإنفاق والتكاليف حتى نُظهر لكم المجاهد من القاعد والصابر من الضاجر، ونُظهر الصدق من خلافه فيما تتحدثون به عن أنفسكم؛ ولذا كان الفضيل بن عياض إذا قرأ هذه الآية بكى وقال: اللهم لا تبتلنا فإنك إذا بلوتنا فضحتنا وهتكت أستارنا. إن الذين كفروا وصدّوا الناس عن الإسلام وخالفوا الرسول وعادوه من بعد ما ظهر لهم الحق بالحجج لن يضرّوا الله شيئاً لتنزّهه عن صفات المحدَثين، وسيبطل أعمالهم فلا ينالون بها ما يؤمّلون في الدنيا بذهاب كيدهم إذ ينصر الله رسوله، وفي الآخرة لأن أعمال الكافر حابطة.", "h": ["بيان حقيقة، وهي: من أسرّ سريرة ألبسه الله رداءها فكشفه للناس.", "ومن أحب شيئاً ظهر على وجهه وفلتات لسانه.", "تقرير قاعدة، وهي أنه لا بد من الابتلاء لمن دخل في الإسلام ليكون الإيمان على حقيقته، لا إيماناً صورياً أدنى فتنة تصيب صاحبه يرتدّ بها عن الإسلام.", "أعمال المشرك والكافر باطلة لا ثواب خير عليها، لأن الشرك محبط للأعمال الصالحة."], "k": "«ونبلوَ أخباركم»… ما أقوله عن نفسي سيُختبر؛ فهل يصدّقه عملي؟"}, {"lbl": "الآيات ٣٣ – ٣٨", "q": "۞يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَ وَلَا تُبۡطِلُوٓاْ أَعۡمَٰلَكُمۡ ﴿٣٣﴾ إِنَّ ٱلَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ ثُمَّ مَاتُواْ وَهُمۡ كُفَّارٞ فَلَن يَغۡفِرَ ٱللَّهُ لَهُمۡ ﴿٣٤﴾ فَلَا تَهِنُواْ وَتَدۡعُوٓاْ إِلَى ٱلسَّلۡمِ وَأَنتُمُ ٱلۡأَعۡلَوۡنَ وَٱللَّهُ مَعَكُمۡ وَلَن يَتِرَكُمۡ أَعۡمَٰلَكُمۡ ﴿٣٥﴾ إِنَّمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَا لَعِبٞ وَلَهۡوٞۚ وَإِن تُؤۡمِنُواْ وَتَتَّقُواْ يُؤۡتِكُمۡ أُجُورَكُمۡ وَلَا يَسۡـَٔلۡكُمۡ أَمۡوَٰلَكُمۡ ﴿٣٦﴾ إِن يَسۡـَٔلۡكُمُوهَا فَيُحۡفِكُمۡ تَبۡخَلُواْ وَيُخۡرِجۡ أَضۡغَٰنَكُمۡ ﴿٣٧﴾ هَـٰٓأَنتُمۡ هَـٰٓؤُلَآءِ تُدۡعَوۡنَ لِتُنفِقُواْ فِي سَبِيلِ ٱللَّهِ فَمِنكُم مَّن يَبۡخَلُۖ وَمَن يَبۡخَلۡ فَإِنَّمَا يَبۡخَلُ عَن نَّفۡسِهِۦۚ وَٱللَّهُ ٱلۡغَنِيُّ وَأَنتُمُ ٱلۡفُقَرَآءُۚ وَإِن تَتَوَلَّوۡاْ يَسۡتَبۡدِلۡ قَوۡمًا غَيۡرَكُمۡ ثُمَّ لَا يَكُونُوٓاْ أَمۡثَٰلَكُم ﴿٣٨﴾", "w": [["ولا تُبطلوا أعمالكم", "بالرياء والشرك والمعاصي."], ["فلن يغفر الله لهم", "لأنهم ماتوا على الكفر، والكفر محبط للعمل."], ["فلا تهنوا وتدعوا إلى السلم", "لا تضعفوا وتدعوا إلى الصلح مع الكفار."], ["وأنتم الأعلون", "الغالبون القاهرون."], ["ولن يَتِرَكم أعمالكم", "لن ينقصكم أجر أعمالكم وثوابها."], ["إنما الحياة الدنيا لعب ولهو", "الاشتغال بالدنيا والتفرّغ لها ما هو إلا لهو ولعب لعدم عائده."], ["ولا يسألكم أموالكم", "لا يكلّفكم بإنفاق أموالكم كلها، بل بالزكاة فقط."], ["فيُحفِكم تبخلوا", "بالمبالغة في طلب المال منكم تبخلوا."], ["ويُخرج أضغانكم", "أحقادكم وبغضكم لدين الإسلام."], ["فإنما يبخل عن نفسه", "عائد ذلك على نفسه، فهو الذي يُحرم الثواب."], ["وإن تتولّوا يستبدل قوماً غيركم", "عن طاعة الله ورسوله يأتِ بآخرين غيركم."], ["ثم لا يكونوا أمثالكم", "بل يكونوا أطوع منكم لله ورسوله."]], "m": "لما ذكر الكفار ومشاقّتهم لرسوله نادى المؤمنين: يا أيها الذين آمنوا بالله رباً وبالإسلام ديناً وبمحمد رسولاً، أطيعوا الله وأطيعوا الرسول فيما يأمرانكم به وينهيانكم عنه، ولا تبطلوا أعمالكم بالشرك والرياء والمعاصي فتُحرموا ثوابها. إن الذين كفروا وصدّوا عن الإسلام ثم ماتوا كفاراً قبل أن يتوبوا لن يغفر الله لهم. فلا تضعفوا عن قتال أعدائكم وتدعوهم إلى الصلح والمهادنة وأنتم أقوياء قادرون غالبون، والله معكم، ولن ينقصكم أجر أعمالكم بل يجزيكم ويزيدكم من فضله. إنما الحياة الدنيا إن أقبل عليها العبد ناسياً الآخرة لعب ولهو، لا يظفر منها بطائل، كلعب الصبيان يلهون بجد ثم يعودون إلى والديهم يطلبون الطعام. وإن تؤمنوا الإيمان الصحيح وتتقوا الشرك والمعاصي يؤتكم أجوركم، ولا يسألكم أموالكم كلها، إن يسألكموها فيُلحّ عليكم تبخلوا، إذ هذا معروف من طباع البشر، وقد يترك أحدهم الإسلام لذلك، ويُخرج أحقادكم وكراهيتكم للدين. ها أنتم هؤلاء تُدعون لتنفقوا بعض أموالكم في الزكاة والجهاد، فمنكم من يبخل، ومن يبخل فإنما يحرم نفسه أجر النفقة، والله الغني عنكم وأنتم الفقراء إليه، لا يحضّكم على النفقة لحاجته إليها ولكن لحاجتكم أنتم، إذ بها تزكو نفوسكم وتقوم أموركم وتنتصرون على عدوكم. وإن ترجعوا عن الإسلام يستبدل قوماً غيركم أطوع لله منكم، وحاشاهم أن يتولّوا وما تولّوا، وإنما هذا من باب حثّهم على معالي الأمور، نظراً لمكانتهم من هذه الأمة، فهم أشرفها وأكملها وأطوعها لله وأحبها له ولرسوله.", "h": ["وجوب طاعة الله وطاعة رسوله.", "وجوب إتمام العمل الصالح من صلاة وغيرها بالشروع فيه.", "بطلان العمل الصالح بالرياء، أو بإفساده عند أدائه، أو بالردة عن الإسلام.", "حرمة الركون إلى مصالحة الأعداء مع القدرة على قتالهم والتمكن من دفع شرهم.", "التنفير من الإقبال على الدنيا والإعراض عن الآخرة.", "حرمة البخل مع الجِدة والسعة."], "k": "«ولا تُبطلوا أعمالكم»… العمل يُبنى ويُهدم؛ فما الذي قد يهدم عملي اليوم بعد أن بنيته؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (379, 48, 1, 10, 'سورة الفتح ١ – ١٠', 'الفتح: إنا فتحنا لك فتحاً مبيناً', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 379) = $j$[{"lbl": "الآيات ١ – ٧", "q": "إِنَّا فَتَحۡنَا لَكَ فَتۡحٗا مُّبِينٗا ﴿١﴾ لِّيَغۡفِرَ لَكَ ٱللَّهُ مَا تَقَدَّمَ مِن ذَنۢبِكَ وَمَا تَأَخَّرَ وَيُتِمَّ نِعۡمَتَهُۥ عَلَيۡكَ وَيَهۡدِيَكَ صِرَٰطٗا مُّسۡتَقِيمٗا ﴿٢﴾ وَيَنصُرَكَ ٱللَّهُ نَصۡرًا عَزِيزًا ﴿٣﴾ هُوَ ٱلَّذِيٓ أَنزَلَ ٱلسَّكِينَةَ فِي قُلُوبِ ٱلۡمُؤۡمِنِينَ لِيَزۡدَادُوٓاْ إِيمَٰنٗا مَّعَ إِيمَٰنِهِمۡۗ وَلِلَّهِ جُنُودُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا ﴿٤﴾ لِّيُدۡخِلَ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا وَيُكَفِّرَ عَنۡهُمۡ سَيِّـَٔاتِهِمۡۚ وَكَانَ ذَٰلِكَ عِندَ ٱللَّهِ فَوۡزًا عَظِيمٗا ﴿٥﴾ وَيُعَذِّبَ ٱلۡمُنَٰفِقِينَ وَٱلۡمُنَٰفِقَٰتِ وَٱلۡمُشۡرِكِينَ وَٱلۡمُشۡرِكَٰتِ ٱلظَّآنِّينَ بِٱللَّهِ ظَنَّ ٱلسَّوۡءِۚ عَلَيۡهِمۡ دَآئِرَةُ ٱلسَّوۡءِۖ وَغَضِبَ ٱللَّهُ عَلَيۡهِمۡ وَلَعَنَهُمۡ وَأَعَدَّ لَهُمۡ جَهَنَّمَۖ وَسَآءَتۡ مَصِيرٗا ﴿٦﴾ وَلِلَّهِ جُنُودُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا ﴿٧﴾", "w": [["إنا فتحنا لك فتحاً مبيناً", "قضينا لك بفتح مكة وغيرها عنوة بجهادك فتحاً ظاهراً بيّناً."], ["ليغفر لك الله", "بسبب شكرك له وجهادك في سبيله."], ["ما تقدّم من ذنبك وما تأخّر", "ما تقدّم الفتح وما تأخّر عنه."], ["ويتمّ نعمته عليك", "بنصرك على أعدائك وإظهار دينك ورفع ذكرك."], ["ويهديك صراطاً مستقيماً", "يرشدك طريقاً من الدين لا اعوجاج فيه يفضي بك إلى رضوانه."], ["وينصرك الله نصراً عزيزاً", "على أعدائك ومن ناوأك نصراً لا يغلبه غالب ولا يدفعه دافع."], ["أنزل السكينة في قلوب المؤمنين", "الطمأنينة بعد ما أصابهم من الاضطراب والقلق من جرّاء الصلح."], ["وكان الله عليماً حكيماً", "عليماً بخلقه حكيماً في تدبيره لأوليائه."], ["ليُدخل المؤمنين والمؤمنات", "قضى بالفتح ليشكروه ويجاهدوا في سبيله ليدخلهم الجنة."], ["وكان ذلك عند الله فوزاً عظيماً", "ذلك الإدخال وتكفير السيئات فوز عظيم."], ["ويعذّب المنافقين والمنافقات", "والمشركين والمشركات، يعذّبهم بالهم والحزن لما يرون من نصرة الإسلام وعزة أهله."], ["الظانّين بالله ظنّ السوء", "أن الله لا ينصر رسوله والمؤمنين."], ["عليهم دائرة السوء", "بالذل والعذاب والهوان."], ["وكان الله عزيزاً حكيماً", "غالباً لا يُغلب، حكيماً في الانتقام من أعدائه."]], "m": "فاتحة سورة الفتح التي قال فيها رسول الله ﷺ: «لقد أُنزلت عليّ سورة لهي أحب إليّ مما طلعت عليه الشمس»، وذلك بعد صلح الحديبية سنة ست من الهجرة وهو عائد مع أصحابه إلى المدينة، وقد خالطهم حزن وكآبة إذ صُدّوا عن المسجد الحرام فعادوا ولم يؤدّوا العمرة، وتمّت أحداث جسام تحمّل فيها رسول الله ﷺ ما لا يقدر عليه غيره، فكافأه الله وأصحابه على صبرهم: إنا فتحنا لك فتحاً مبيناً، قضينا لك بفتح مكة وخيبر وغيرهما، وهو أمر واقع لا محالة، وهذا الصلح بداية الفتح، فاحمد ربك واشكره ليغفر لك بذلك وبجهادك وصبرك ما تقدّم من ذنبك وما تأخّر، ويتمّ نعمته عليك بنصرك على أعدائك، ويهديك إلى طريق لا اعوجاج فيه هو الإسلام، وينصرك نصراً ذا عزّ لا ذلّ معه؛ أربع عطايا فرح بها رسول الله ﷺ. هو الذي أنزل الطمأنينة على قلوب أصحابك، وكانوا ألفاً وأربعمائة، بعد اضطراب شديد أصاب نفوسهم، دلّ عليه قول عمر رضي الله عنه للرسول ﷺ: ألست نبي الله حقاً؟ قال: «بلى»، قال: ألسنا على الحق وعدونا على الباطل؟ قال: «بلى»، قال: فلِمَ نُعطى الدنيّة في ديننا؟ قال: «إني رسول الله ولست أعصيه وهو ناصري»، ثم أتى أبا بكر فقال له مثل ذلك، فقال أبو بكر: إنه رسول الله وليس يعصي ربه وهو ناصره، فاستمسك بغرزه، فوالله إنه لعلى الحق. ليزدادوا إيماناً بشرائع الإسلام كلما نزل حكم آمنوا به وعملوا به. ولله جنود السماوات والأرض، كل ذي قوة من الكائنات يسخّره كما شاء، وكان الله عليماً حكيماً. فتح على رسوله والمؤمنين ليشكروا فيدخل المؤمنين والمؤمنات جنات تجري من تحتها الأنهار خالدين فيها ويكفّر عنهم سيئاتهم، وكان ذلك عند الله فوزاً عظيماً، وليكون ذلك غمّاً وحزناً يعذّب الله به المنافقين والمشركين الظانّين أن الله لا ينصر رسوله ولا يُظهر دينه، عليهم دائرة السوء، وغضب الله عليهم ولعنهم وأعدّ لهم جهنم وساءت مصيراً.", "h": ["الذنب الذي غُفر لرسول الله ﷺ من المعلوم بالضرورة أنه ليس من الكبائر في شيء.", "إنعام الله على العبد يوجب الشكر، والشكر يوجب المغفرة وزيادة الإنعام.", "بيان مكافأة الله لرسوله والمؤمنين على صبرهم وجهادهم.", "بيان أن الكافرين يحزنون ويُغمّون لنصر المؤمنين وعزّهم، فيكون ذلك عذاباً لهم في الدنيا."], "k": "«هو الذي أنزل السكينة في قلوب المؤمنين»… حين لا أفهم حكمة ما يجري، هل أطلب السكينة منه؟"}, {"lbl": "الآيات ٨ – ١٠", "q": "إِنَّآ أَرۡسَلۡنَٰكَ شَٰهِدٗا وَمُبَشِّرٗا وَنَذِيرٗا ﴿٨﴾ لِّتُؤۡمِنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَتُعَزِّرُوهُ وَتُوَقِّرُوهُۚ وَتُسَبِّحُوهُ بُكۡرَةٗ وَأَصِيلًا ﴿٩﴾ إِنَّ ٱلَّذِينَ يُبَايِعُونَكَ إِنَّمَا يُبَايِعُونَ ٱللَّهَ يَدُ ٱللَّهِ فَوۡقَ أَيۡدِيهِمۡۚ فَمَن نَّكَثَ فَإِنَّمَا يَنكُثُ عَلَىٰ نَفۡسِهِۦۖ وَمَنۡ أَوۡفَىٰ بِمَا عَٰهَدَ عَلَيۡهُ ٱللَّهَ فَسَيُؤۡتِيهِ أَجۡرًا عَظِيمٗا ﴿١٠﴾", "w": [["إنا أرسلناك شاهداً ومبشّراً ونذيراً", "شاهداً على أمتك أمة الدعوة يوم القيامة، ومبشّراً من آمن منهم وعمل صالحاً بالجنة، ونذيراً من كفر أو عصى وفسق بالنار."], ["لتؤمنوا بالله ورسوله", "هذا علة للإرسال."], ["وتعزّروه وتوقّروه", "تنصروه وتعظّموه، وهذا لله وللرسول."], ["وتسبّحوه بكرة وأصيلاً", "تسبّحوا الله تعالى بالصلاة والذكر صباحاً وعشية."], ["إن الذين يبايعونك", "بيعة الرضوان بالحديبية."], ["إنما يبايعون الله", "لأن طاعة الرسول طاعة لله تعالى."], ["يد الله فوق أيديهم", "لأنهم كانوا يبايعون الله، إذ هو الذي يجاهدون من أجله ويتلقّون الجزاء من عنده."], ["فمن نكث", "نقض عهده فلم يقاتل مع الرسول والمؤمنين."], ["فإنما ينكث على نفسه", "وبال نقضه عائد عليه."], ["فسيؤتيه أجراً عظيماً", "الجنة، إذ هي الأجر العظيم الذي لا أعظم منه إلا رضوان الله."]], "m": "ما زال السياق في بيان ما أنعم الله به على رسوله: إنا أرسلناك شاهداً لله بالوحدانية والكمال المطلق، وشاهداً على هذه الأمة التي أُرسلت إليها عربها وعجمها، ومبشّراً أهل الإيمان والتقوى بالجنة، ونذيراً أهل الكفر والمعاصي من عذاب الله يوم القيامة، لتؤمنوا بالله ورسوله وتنصروه وتعظّموه، وهذه الثلاثة واجبة لله ولرسوله، وأما التسبيح والتقديس فهو لله وحده، ويكون بكلمة سبحان الله وبالصلاة والذكر والدعاء، تسبّحوه صباحاً وعشية. إن الذين يبايعونك على قتال أهل مكة وألا يفرّوا عند اللقاء إنما يبايعون الله، إذ هو الذي أمرهم بالجهاد وواعدهم الأجر، فالعقد وإن كانت صورته مع رسول الله فإنه في الحقيقة مع الله، ولذا قال: يد الله فوق أيديهم. فمن نقض عهده فلم يقاتل فإنما ينكث على نفسه، ومن وفى بما عاهد عليه الله من نصرة الرسول والقتال تحت رايته حتى النصر فسيؤتيه الله أجراً عظيماً هو الجنة دار السلام.", "h": ["تقرير نبوة محمد ﷺ، والإعلان عن شرفه وعلوّ مقامه.", "وجوب الإيمان بالله ورسوله، ووجوب نصرة الرسول وتعظيمه ﷺ.", "وجوب تسبيح الله، وهو تنزيهه عن كل ما لا يليق بجلاله وكماله، مع الصلاة ليلاً ونهاراً.", "وجوب الوفاء بالعهد، وحرمة نقض العهد ونكثه."], "k": "«يد الله فوق أيديهم»… كل عهد مع الله حاضر بين يديه؛ فأي عهد عاهدته ولم أوفِ به؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 379;
insert into public.tdb_cards(topic, i, body) select 379, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٧", "q": "إِنَّا فَتَحۡنَا لَكَ فَتۡحٗا مُّبِينٗا ﴿١﴾ لِّيَغۡفِرَ لَكَ ٱللَّهُ مَا تَقَدَّمَ مِن ذَنۢبِكَ وَمَا تَأَخَّرَ وَيُتِمَّ نِعۡمَتَهُۥ عَلَيۡكَ وَيَهۡدِيَكَ صِرَٰطٗا مُّسۡتَقِيمٗا ﴿٢﴾ وَيَنصُرَكَ ٱللَّهُ نَصۡرًا عَزِيزًا ﴿٣﴾ هُوَ ٱلَّذِيٓ أَنزَلَ ٱلسَّكِينَةَ فِي قُلُوبِ ٱلۡمُؤۡمِنِينَ لِيَزۡدَادُوٓاْ إِيمَٰنٗا مَّعَ إِيمَٰنِهِمۡۗ وَلِلَّهِ جُنُودُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا ﴿٤﴾ لِّيُدۡخِلَ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَا وَيُكَفِّرَ عَنۡهُمۡ سَيِّـَٔاتِهِمۡۚ وَكَانَ ذَٰلِكَ عِندَ ٱللَّهِ فَوۡزًا عَظِيمٗا ﴿٥﴾ وَيُعَذِّبَ ٱلۡمُنَٰفِقِينَ وَٱلۡمُنَٰفِقَٰتِ وَٱلۡمُشۡرِكِينَ وَٱلۡمُشۡرِكَٰتِ ٱلظَّآنِّينَ بِٱللَّهِ ظَنَّ ٱلسَّوۡءِۚ عَلَيۡهِمۡ دَآئِرَةُ ٱلسَّوۡءِۖ وَغَضِبَ ٱللَّهُ عَلَيۡهِمۡ وَلَعَنَهُمۡ وَأَعَدَّ لَهُمۡ جَهَنَّمَۖ وَسَآءَتۡ مَصِيرٗا ﴿٦﴾ وَلِلَّهِ جُنُودُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا ﴿٧﴾", "w": [["إنا فتحنا لك فتحاً مبيناً", "قضينا لك بفتح مكة وغيرها عنوة بجهادك فتحاً ظاهراً بيّناً."], ["ليغفر لك الله", "بسبب شكرك له وجهادك في سبيله."], ["ما تقدّم من ذنبك وما تأخّر", "ما تقدّم الفتح وما تأخّر عنه."], ["ويتمّ نعمته عليك", "بنصرك على أعدائك وإظهار دينك ورفع ذكرك."], ["ويهديك صراطاً مستقيماً", "يرشدك طريقاً من الدين لا اعوجاج فيه يفضي بك إلى رضوانه."], ["وينصرك الله نصراً عزيزاً", "على أعدائك ومن ناوأك نصراً لا يغلبه غالب ولا يدفعه دافع."], ["أنزل السكينة في قلوب المؤمنين", "الطمأنينة بعد ما أصابهم من الاضطراب والقلق من جرّاء الصلح."], ["وكان الله عليماً حكيماً", "عليماً بخلقه حكيماً في تدبيره لأوليائه."], ["ليُدخل المؤمنين والمؤمنات", "قضى بالفتح ليشكروه ويجاهدوا في سبيله ليدخلهم الجنة."], ["وكان ذلك عند الله فوزاً عظيماً", "ذلك الإدخال وتكفير السيئات فوز عظيم."], ["ويعذّب المنافقين والمنافقات", "والمشركين والمشركات، يعذّبهم بالهم والحزن لما يرون من نصرة الإسلام وعزة أهله."], ["الظانّين بالله ظنّ السوء", "أن الله لا ينصر رسوله والمؤمنين."], ["عليهم دائرة السوء", "بالذل والعذاب والهوان."], ["وكان الله عزيزاً حكيماً", "غالباً لا يُغلب، حكيماً في الانتقام من أعدائه."]], "m": "فاتحة سورة الفتح التي قال فيها رسول الله ﷺ: «لقد أُنزلت عليّ سورة لهي أحب إليّ مما طلعت عليه الشمس»، وذلك بعد صلح الحديبية سنة ست من الهجرة وهو عائد مع أصحابه إلى المدينة، وقد خالطهم حزن وكآبة إذ صُدّوا عن المسجد الحرام فعادوا ولم يؤدّوا العمرة، وتمّت أحداث جسام تحمّل فيها رسول الله ﷺ ما لا يقدر عليه غيره، فكافأه الله وأصحابه على صبرهم: إنا فتحنا لك فتحاً مبيناً، قضينا لك بفتح مكة وخيبر وغيرهما، وهو أمر واقع لا محالة، وهذا الصلح بداية الفتح، فاحمد ربك واشكره ليغفر لك بذلك وبجهادك وصبرك ما تقدّم من ذنبك وما تأخّر، ويتمّ نعمته عليك بنصرك على أعدائك، ويهديك إلى طريق لا اعوجاج فيه هو الإسلام، وينصرك نصراً ذا عزّ لا ذلّ معه؛ أربع عطايا فرح بها رسول الله ﷺ. هو الذي أنزل الطمأنينة على قلوب أصحابك، وكانوا ألفاً وأربعمائة، بعد اضطراب شديد أصاب نفوسهم، دلّ عليه قول عمر رضي الله عنه للرسول ﷺ: ألست نبي الله حقاً؟ قال: «بلى»، قال: ألسنا على الحق وعدونا على الباطل؟ قال: «بلى»، قال: فلِمَ نُعطى الدنيّة في ديننا؟ قال: «إني رسول الله ولست أعصيه وهو ناصري»، ثم أتى أبا بكر فقال له مثل ذلك، فقال أبو بكر: إنه رسول الله وليس يعصي ربه وهو ناصره، فاستمسك بغرزه، فوالله إنه لعلى الحق. ليزدادوا إيماناً بشرائع الإسلام كلما نزل حكم آمنوا به وعملوا به. ولله جنود السماوات والأرض، كل ذي قوة من الكائنات يسخّره كما شاء، وكان الله عليماً حكيماً. فتح على رسوله والمؤمنين ليشكروا فيدخل المؤمنين والمؤمنات جنات تجري من تحتها الأنهار خالدين فيها ويكفّر عنهم سيئاتهم، وكان ذلك عند الله فوزاً عظيماً، وليكون ذلك غمّاً وحزناً يعذّب الله به المنافقين والمشركين الظانّين أن الله لا ينصر رسوله ولا يُظهر دينه، عليهم دائرة السوء، وغضب الله عليهم ولعنهم وأعدّ لهم جهنم وساءت مصيراً.", "h": ["الذنب الذي غُفر لرسول الله ﷺ من المعلوم بالضرورة أنه ليس من الكبائر في شيء.", "إنعام الله على العبد يوجب الشكر، والشكر يوجب المغفرة وزيادة الإنعام.", "بيان مكافأة الله لرسوله والمؤمنين على صبرهم وجهادهم.", "بيان أن الكافرين يحزنون ويُغمّون لنصر المؤمنين وعزّهم، فيكون ذلك عذاباً لهم في الدنيا."], "k": "«هو الذي أنزل السكينة في قلوب المؤمنين»… حين لا أفهم حكمة ما يجري، هل أطلب السكينة منه؟"}, {"lbl": "الآيات ٨ – ١٠", "q": "إِنَّآ أَرۡسَلۡنَٰكَ شَٰهِدٗا وَمُبَشِّرٗا وَنَذِيرٗا ﴿٨﴾ لِّتُؤۡمِنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَتُعَزِّرُوهُ وَتُوَقِّرُوهُۚ وَتُسَبِّحُوهُ بُكۡرَةٗ وَأَصِيلًا ﴿٩﴾ إِنَّ ٱلَّذِينَ يُبَايِعُونَكَ إِنَّمَا يُبَايِعُونَ ٱللَّهَ يَدُ ٱللَّهِ فَوۡقَ أَيۡدِيهِمۡۚ فَمَن نَّكَثَ فَإِنَّمَا يَنكُثُ عَلَىٰ نَفۡسِهِۦۖ وَمَنۡ أَوۡفَىٰ بِمَا عَٰهَدَ عَلَيۡهُ ٱللَّهَ فَسَيُؤۡتِيهِ أَجۡرًا عَظِيمٗا ﴿١٠﴾", "w": [["إنا أرسلناك شاهداً ومبشّراً ونذيراً", "شاهداً على أمتك أمة الدعوة يوم القيامة، ومبشّراً من آمن منهم وعمل صالحاً بالجنة، ونذيراً من كفر أو عصى وفسق بالنار."], ["لتؤمنوا بالله ورسوله", "هذا علة للإرسال."], ["وتعزّروه وتوقّروه", "تنصروه وتعظّموه، وهذا لله وللرسول."], ["وتسبّحوه بكرة وأصيلاً", "تسبّحوا الله تعالى بالصلاة والذكر صباحاً وعشية."], ["إن الذين يبايعونك", "بيعة الرضوان بالحديبية."], ["إنما يبايعون الله", "لأن طاعة الرسول طاعة لله تعالى."], ["يد الله فوق أيديهم", "لأنهم كانوا يبايعون الله، إذ هو الذي يجاهدون من أجله ويتلقّون الجزاء من عنده."], ["فمن نكث", "نقض عهده فلم يقاتل مع الرسول والمؤمنين."], ["فإنما ينكث على نفسه", "وبال نقضه عائد عليه."], ["فسيؤتيه أجراً عظيماً", "الجنة، إذ هي الأجر العظيم الذي لا أعظم منه إلا رضوان الله."]], "m": "ما زال السياق في بيان ما أنعم الله به على رسوله: إنا أرسلناك شاهداً لله بالوحدانية والكمال المطلق، وشاهداً على هذه الأمة التي أُرسلت إليها عربها وعجمها، ومبشّراً أهل الإيمان والتقوى بالجنة، ونذيراً أهل الكفر والمعاصي من عذاب الله يوم القيامة، لتؤمنوا بالله ورسوله وتنصروه وتعظّموه، وهذه الثلاثة واجبة لله ولرسوله، وأما التسبيح والتقديس فهو لله وحده، ويكون بكلمة سبحان الله وبالصلاة والذكر والدعاء، تسبّحوه صباحاً وعشية. إن الذين يبايعونك على قتال أهل مكة وألا يفرّوا عند اللقاء إنما يبايعون الله، إذ هو الذي أمرهم بالجهاد وواعدهم الأجر، فالعقد وإن كانت صورته مع رسول الله فإنه في الحقيقة مع الله، ولذا قال: يد الله فوق أيديهم. فمن نقض عهده فلم يقاتل فإنما ينكث على نفسه، ومن وفى بما عاهد عليه الله من نصرة الرسول والقتال تحت رايته حتى النصر فسيؤتيه الله أجراً عظيماً هو الجنة دار السلام.", "h": ["تقرير نبوة محمد ﷺ، والإعلان عن شرفه وعلوّ مقامه.", "وجوب الإيمان بالله ورسوله، ووجوب نصرة الرسول وتعظيمه ﷺ.", "وجوب تسبيح الله، وهو تنزيهه عن كل ما لا يليق بجلاله وكماله، مع الصلاة ليلاً ونهاراً.", "وجوب الوفاء بالعهد، وحرمة نقض العهد ونكثه."], "k": "«يد الله فوق أيديهم»… كل عهد مع الله حاضر بين يديه؛ فأي عهد عاهدته ولم أوفِ به؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (380, 48, 11, 17, 'سورة الفتح ١١ – ١٧', 'الفتح: سيقول لك المخلّفون من الأعراب', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 380) = $j$[{"lbl": "الآيات ١١ – ١٤", "q": "سَيَقُولُ لَكَ ٱلۡمُخَلَّفُونَ مِنَ ٱلۡأَعۡرَابِ شَغَلَتۡنَآ أَمۡوَٰلُنَا وَأَهۡلُونَا فَٱسۡتَغۡفِرۡ لَنَاۚ يَقُولُونَ بِأَلۡسِنَتِهِم مَّا لَيۡسَ فِي قُلُوبِهِمۡۚ قُلۡ فَمَن يَمۡلِكُ لَكُم مِّنَ ٱللَّهِ شَيۡـًٔا إِنۡ أَرَادَ بِكُمۡ ضَرًّا أَوۡ أَرَادَ بِكُمۡ نَفۡعَۢاۚ بَلۡ كَانَ ٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرَۢا ﴿١١﴾ بَلۡ ظَنَنتُمۡ أَن لَّن يَنقَلِبَ ٱلرَّسُولُ وَٱلۡمُؤۡمِنُونَ إِلَىٰٓ أَهۡلِيهِمۡ أَبَدٗا وَزُيِّنَ ذَٰلِكَ فِي قُلُوبِكُمۡ وَظَنَنتُمۡ ظَنَّ ٱلسَّوۡءِ وَكُنتُمۡ قَوۡمَۢا بُورٗا ﴿١٢﴾ وَمَن لَّمۡ يُؤۡمِنۢ بِٱللَّهِ وَرَسُولِهِۦ فَإِنَّآ أَعۡتَدۡنَا لِلۡكَٰفِرِينَ سَعِيرٗا ﴿١٣﴾ وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ يَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۚ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا ﴿١٤﴾", "w": [["المخلّفون من الأعراب", "الذين حول المدينة وقد خلّفهم الله عن صحبتك لما طلبتهم ليخرجوا معك إلى مكة عام الحديبية، وهم غفار ومزينة وجهينة وأشجع."], ["شغلتنا أموالنا وأهلونا", "عن الخروج معك."], ["فاستغفر لنا", "اطلب لنا من الله المغفرة على ترك الخروج معك."], ["يقولون بألسنتهم ما ليس في قلوبهم", "كل ما قالوه من ألسنتهم وليس في قلوبهم منه شيء."], ["فمن يملك لكم من الله شيئاً", "لا أحد، لأن الاستفهام هنا للنفي."], ["بل ظننتم أن لن ينقلب الرسول والمؤمنون", "حسبتم أن قريشاً تقتل الرسول والمؤمنين فلا يرجع منهم أحد إلى المدينة."], ["وظننتم ظنّ السوء", "هذا الظن الذي زيّنه الشيطان في قلوبهم."], ["وكنتم قوماً بوراً", "هالكين عند الله بهذا الظن السيئ، الواحد بائر."], ["فإنا أعتدنا للكافرين سعيراً", "ناراً شديدة الاستعار والالتهاب."], ["يغفر لمن يشاء ويعذّب من يشاء", "يغفر لمن تاب وطلب المغفرة بنفسه، ويعذّب من ظن السوء وقال غير ما يعتقد وأصرّ على ذلك."], ["وكان الله غفوراً رحيماً", "كان وما زال متصفاً بالمغفرة والرحمة، فمن تاب غفر الله له."]], "m": "ما زال السياق في طلب هداية المنافقين في الحضر والبادية بتأنيبهم وذكر معايبهم إرادة إصلاحهم: سيقول لك المخلّفون من الأعراب، غفار ومزينة وجهينة وأشجع، وكانوا أهل بادية حول المدينة استنفرهم رسول الله ﷺ ليخرجوا معه إلى مكة للعمرة تحسّباً لقتال قريش، فأصابهم الخوف والجبن، وزيّن لهم الشيطان أن الرسول والمؤمنين لن يعودوا إلى المدينة، فخلّفهم الله وحرمهم صحبة نبيه وبيعة الرضوان؛ سيقولون معتذرين: شغلتنا أموالنا وأهلونا فاستغفر لنا، يقولون بألسنتهم ما ليس في قلوبهم فهم كاذبون. قل لهم: إن عصيتم الله ورسوله وتركتم الخروج جبناً فمن يملك لكم من الله شيئاً إن أراد بكم ضراً أو أراد بكم نفعاً؟ لا أحد، فكنتم مخطئين في تخلّفكم وظنكم معاً، بل كان الله بما تعملون خبيراً وسيجزيكم به. بل ظننتم أن قريشاً تستأصلهم فلن ينقلبوا إلى أهليهم أبداً، وزيّن ذلك الشيطان في قلوبكم، وظننتم ظن السوء، وكنتم بذلك قوماً هلكى لا خير فيكم. ومن لم يؤمن بالله ورسوله فإنا هيّأنا للكافرين ناراً مستعرة؛ إخبار أريد به تخويفهم لعلهم يرجعون. ولله ملك السماوات والأرض، بيده كل شيء، يغفر لمن يشاء ويعذّب من يشاء، فاللائق بهم التوبة لا الإصرار على النفاق، وقد تاب أكثرهم وصاروا من خيرة الناس، وكان الله غفوراً رحيماً.", "h": ["إخبار القرآن بالغيب وصدقه في ذلك دالّ على أنه كلام الله أوحاه إلى رسوله ﷺ.", "لا يملك النفع ولا الضر على الحقيقة إلا الله، ولذا وجب ألا يُطمع إلا فيه ولا يُرهب إلا منه.", "حرمة ظن السوء في الله عز وجل، ووجوب حسن الظن به تعالى.", "الكفر موجب لعذاب النار، ومن تاب تاب الله عليه، ومن طلب المغفرة في صدق غُفر له.", "ذمّ التخلّف عن المسابقة في الخيرات والمنافسة في الصالحات."], "k": "«شغلتنا أموالنا وأهلونا»… ما العذر الذي أقوله بلساني وأعلم في قلبي أنه ليس الحقيقة؟"}, {"lbl": "الآية ١٥", "q": "سَيَقُولُ ٱلۡمُخَلَّفُونَ إِذَا ٱنطَلَقۡتُمۡ إِلَىٰ مَغَانِمَ لِتَأۡخُذُوهَا ذَرُونَا نَتَّبِعۡكُمۡۖ يُرِيدُونَ أَن يُبَدِّلُواْ كَلَٰمَ ٱللَّهِۚ قُل لَّن تَتَّبِعُونَا كَذَٰلِكُمۡ قَالَ ٱللَّهُ مِن قَبۡلُۖ فَسَيَقُولُونَ بَلۡ تَحۡسُدُونَنَاۚ بَلۡ كَانُواْ لَا يَفۡقَهُونَ إِلَّا قَلِيلٗا ﴿١٥﴾", "w": [["المخلّفون", "المذكورون قبل هذه، وهم غفار وجهينة ومزينة وأشجع."], ["إذا انطلقتم إلى مغانم لتأخذوها", "مغانم خيبر، إذ وعدهم الله بها عند رجوعهم من الحديبية."], ["ذرونا نتّبعكم", "دعونا نخرج معكم لنصيب من الغنائم."], ["يريدون أن يبدّلوا كلام الله", "بطلبهم الخروج يريدون أن يغيّروا وعد الله لأهل الحديبية خاصة بغنائم خيبر."], ["كذلكم قال الله من قبل", "قاله تعالى لنا قبل عودتنا إلى المدينة."], ["فسيقولون بل تحسدوننا", "زعموا أن المنع ليس أمراً من الله وإنما هو من الرسول والمؤمنين حسداً لهم، وهذا دالّ على نفاقهم."], ["بل كانوا لا يفقهون إلا قليلاً", "لا يفهمون فهم الحاذق الماهر إلا قليلاً، وفي أمور الدنيا لا غير."]], "m": "ما زال السياق في طلب هداية المنافقين بكشف عوارهم ودعوتهم إلى التوبة: سيقول المخلّفون الذين تخلّفوا عن الحديبية إذا انطلقتم إلى مغانم لتأخذوها: دعونا نتبعكم؛ وذلك أن الله بعد صلح الحديبية وما نال أهلها من آلام نفسية أكرمهم بنعم كثيرة، منها أنه واعدهم بغنائم خيبر، وكانت أموالاً عظيمة، فلما تهيّؤوا للخروج إليها جاء هؤلاء يطالبون بالسير معهم لأجل الغنيمة لا غير. يريدون أن يبدّلوا وعد الله لأهل الحديبية خاصة، ولذا أمر رسوله أن يقول لهم: لن تتبعونا، كذلكم قال الله من قبل، فقد أخبرنا تعالى بحالكم ومقالكم قبل أن تقولوه. فسيقولون: ما منعتمونا إلا حسداً لنا أن ننال من الغنائم، لم يأمركم الله بمنعنا، وقد قالوه. بل كانوا لا يفقهون إلا قليلاً؛ وصمهم بالجهل وجعله علة تخبّطهم وضلالهم، فليسوا على مستوى الرجل الحاذق البصير الذي يحسن القول والعمل.", "h": ["وعد الله رسوله والمؤمنين بغنائم خيبر وهم في طريقهم من الحديبية إلى المدينة، وإنجازه لهم، دالّ على وجود الله وعلمه وقدرته وحكمته ورحمته، وكلها موجبة للإيمان والتوحيد وحب الله والرغبة إليه والرهبة منه.", "بيان حيرة الكافر واضطراب نفسه وتخبّط قوله وعمله.", "ذمّ الجهل وتقبيحه، إنه بئس الوصف يوصف به المرء، ولذا لا يرضاه حتى الجاهل لنفسه، فلو قلت لجاهل: يا جاهل لا تفعل كذا، لغضب عليك."], "k": "«ذرونا نتّبعكم»… هل أحضر حيث الغنيمة وأغيب حيث التضحية؟"}, {"lbl": "الآيتان ١٦ – ١٧", "q": "قُل لِّلۡمُخَلَّفِينَ مِنَ ٱلۡأَعۡرَابِ سَتُدۡعَوۡنَ إِلَىٰ قَوۡمٍ أُوْلِي بَأۡسٖ شَدِيدٖ تُقَٰتِلُونَهُمۡ أَوۡ يُسۡلِمُونَۖ فَإِن تُطِيعُواْ يُؤۡتِكُمُ ٱللَّهُ أَجۡرًا حَسَنٗاۖ وَإِن تَتَوَلَّوۡاْ كَمَا تَوَلَّيۡتُم مِّن قَبۡلُ يُعَذِّبۡكُمۡ عَذَابًا أَلِيمٗا ﴿١٦﴾ لَّيۡسَ عَلَى ٱلۡأَعۡمَىٰ حَرَجٞ وَلَا عَلَى ٱلۡأَعۡرَجِ حَرَجٞ وَلَا عَلَى ٱلۡمَرِيضِ حَرَجٞۗ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدۡخِلۡهُ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ وَمَن يَتَوَلَّ يُعَذِّبۡهُ عَذَابًا أَلِيمٗا ﴿١٧﴾", "w": [["قل للمخلّفين من الأعراب", "الذين تخلّفوا عن الحديبية وطالبوا بالخروج إلى خيبر، قل لهم اختباراً."], ["ستُدعون إلى قوم أولي بأس شديد", "ستُدعون يوماً إلى قتال قوم ذوي بأس وشدة في الحرب."], ["تقاتلونهم أو يُسلمون", "تقاتلونهم، أو هم يُسلمون فلا حاجة إلى قتالهم."], ["فإن تطيعوا", "أمر الداعي لكم إلى قتال القوم أصحاب البأس الشديد."], ["يؤتكم الله أجراً حسناً", "عودة اعتباركم مؤمنين صالحين في الدنيا، والجنة في الآخرة."], ["وإن تتولّوا", "تعرضوا عن الجهاد كما تولّيتم من قبل."], ["يعذّبكم عذاباً أليماً", "في الدنيا بالقتل والإذلال، وفي الآخرة بعذاب النار."], ["حرج", "إثم."], ["ومن يتولّ", "يعرض عن طاعة الله ورسوله."]], "m": "ما زال السياق في طلب هداية المنافقين من الأعراب: قل للمخلّفين، الذين أصبح وصف التخلّف شعاراً لهم وفي ذلك من الذم ما فيه، مختبراً إياهم: ستُدعون يوماً إلى قتال قوم أولي بأس شديد في الحروب، تقاتلونهم أو يسلمون فلا تقاتلوهم، وذلك بأن يرضوا بدفع الجزية، وهؤلاء لا يكونون إلا نصارى أو مجوساً، فهم إما فارس وإما الروم، وقد اختُلف في تحديدهم. فإن تطيعوا الداعي للجهاد فتخرجوا يؤتكم الله أجراً حسناً: غنائم في الدنيا وحسن الصيت والجنة فوق ذلك، وإن تعرضوا كما أعرضتم من قبل حين لم تخرجوا مع رسول الله إلى مكة خوفاً من قريش يعذّبكم عذاباً أليماً في الدنيا والآخرة. ولما نزلت هذه الآية خاف أصحاب الأعذار وبكوا، فأنزل الله: ليس على الأعمى حرج إذا لم يخرج للجهاد، ولا على الأعرج الذي لا يقدر على المشي والكرّ والفرّ، ولا على المريض بالأمراض المزمنة التي لا يقدر صاحبها على القتال. ومن يطع الله ورسوله في أوامرهما ونواهيهما يدخله جنات تجري من تحتها الأنهار، وعد صادق من رب كريم، ومن يتولّ يعذّبه عذاباً أليماً، وعيد شديد، ألا فليتقِ الله امرؤ فإن الله شديد العقاب.", "h": ["مشروعية الاختبار والامتحان لمعرفة القدرات والمؤهلات.", "بيان أن غزو الإسلام ينتهي إلى أحد أمرين: إسلام الأمة المغزوّة، أو دخولها في الذمة بإعطائها الجزية والرضا بالحكم الإسلامي وسياسته.", "دفع الإثم والحرج في التخلّف عن الجهاد لعذر العمى أو العرج أو المرض.", "بيان وعد الله ووعيده لمن أطاعه ولمن عصاه: الوعد بالجنة، والوعيد بالنار."], "k": "«ليس على الأعمى حرج»… ربي لا يكلّف فوق الطاقة؛ فهل أؤدي ما في طاقتي فعلاً؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 380;
insert into public.tdb_cards(topic, i, body) select 380, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١١ – ١٤", "q": "سَيَقُولُ لَكَ ٱلۡمُخَلَّفُونَ مِنَ ٱلۡأَعۡرَابِ شَغَلَتۡنَآ أَمۡوَٰلُنَا وَأَهۡلُونَا فَٱسۡتَغۡفِرۡ لَنَاۚ يَقُولُونَ بِأَلۡسِنَتِهِم مَّا لَيۡسَ فِي قُلُوبِهِمۡۚ قُلۡ فَمَن يَمۡلِكُ لَكُم مِّنَ ٱللَّهِ شَيۡـًٔا إِنۡ أَرَادَ بِكُمۡ ضَرًّا أَوۡ أَرَادَ بِكُمۡ نَفۡعَۢاۚ بَلۡ كَانَ ٱللَّهُ بِمَا تَعۡمَلُونَ خَبِيرَۢا ﴿١١﴾ بَلۡ ظَنَنتُمۡ أَن لَّن يَنقَلِبَ ٱلرَّسُولُ وَٱلۡمُؤۡمِنُونَ إِلَىٰٓ أَهۡلِيهِمۡ أَبَدٗا وَزُيِّنَ ذَٰلِكَ فِي قُلُوبِكُمۡ وَظَنَنتُمۡ ظَنَّ ٱلسَّوۡءِ وَكُنتُمۡ قَوۡمَۢا بُورٗا ﴿١٢﴾ وَمَن لَّمۡ يُؤۡمِنۢ بِٱللَّهِ وَرَسُولِهِۦ فَإِنَّآ أَعۡتَدۡنَا لِلۡكَٰفِرِينَ سَعِيرٗا ﴿١٣﴾ وَلِلَّهِ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ يَغۡفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُۚ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا ﴿١٤﴾", "w": [["المخلّفون من الأعراب", "الذين حول المدينة وقد خلّفهم الله عن صحبتك لما طلبتهم ليخرجوا معك إلى مكة عام الحديبية، وهم غفار ومزينة وجهينة وأشجع."], ["شغلتنا أموالنا وأهلونا", "عن الخروج معك."], ["فاستغفر لنا", "اطلب لنا من الله المغفرة على ترك الخروج معك."], ["يقولون بألسنتهم ما ليس في قلوبهم", "كل ما قالوه من ألسنتهم وليس في قلوبهم منه شيء."], ["فمن يملك لكم من الله شيئاً", "لا أحد، لأن الاستفهام هنا للنفي."], ["بل ظننتم أن لن ينقلب الرسول والمؤمنون", "حسبتم أن قريشاً تقتل الرسول والمؤمنين فلا يرجع منهم أحد إلى المدينة."], ["وظننتم ظنّ السوء", "هذا الظن الذي زيّنه الشيطان في قلوبهم."], ["وكنتم قوماً بوراً", "هالكين عند الله بهذا الظن السيئ، الواحد بائر."], ["فإنا أعتدنا للكافرين سعيراً", "ناراً شديدة الاستعار والالتهاب."], ["يغفر لمن يشاء ويعذّب من يشاء", "يغفر لمن تاب وطلب المغفرة بنفسه، ويعذّب من ظن السوء وقال غير ما يعتقد وأصرّ على ذلك."], ["وكان الله غفوراً رحيماً", "كان وما زال متصفاً بالمغفرة والرحمة، فمن تاب غفر الله له."]], "m": "ما زال السياق في طلب هداية المنافقين في الحضر والبادية بتأنيبهم وذكر معايبهم إرادة إصلاحهم: سيقول لك المخلّفون من الأعراب، غفار ومزينة وجهينة وأشجع، وكانوا أهل بادية حول المدينة استنفرهم رسول الله ﷺ ليخرجوا معه إلى مكة للعمرة تحسّباً لقتال قريش، فأصابهم الخوف والجبن، وزيّن لهم الشيطان أن الرسول والمؤمنين لن يعودوا إلى المدينة، فخلّفهم الله وحرمهم صحبة نبيه وبيعة الرضوان؛ سيقولون معتذرين: شغلتنا أموالنا وأهلونا فاستغفر لنا، يقولون بألسنتهم ما ليس في قلوبهم فهم كاذبون. قل لهم: إن عصيتم الله ورسوله وتركتم الخروج جبناً فمن يملك لكم من الله شيئاً إن أراد بكم ضراً أو أراد بكم نفعاً؟ لا أحد، فكنتم مخطئين في تخلّفكم وظنكم معاً، بل كان الله بما تعملون خبيراً وسيجزيكم به. بل ظننتم أن قريشاً تستأصلهم فلن ينقلبوا إلى أهليهم أبداً، وزيّن ذلك الشيطان في قلوبكم، وظننتم ظن السوء، وكنتم بذلك قوماً هلكى لا خير فيكم. ومن لم يؤمن بالله ورسوله فإنا هيّأنا للكافرين ناراً مستعرة؛ إخبار أريد به تخويفهم لعلهم يرجعون. ولله ملك السماوات والأرض، بيده كل شيء، يغفر لمن يشاء ويعذّب من يشاء، فاللائق بهم التوبة لا الإصرار على النفاق، وقد تاب أكثرهم وصاروا من خيرة الناس، وكان الله غفوراً رحيماً.", "h": ["إخبار القرآن بالغيب وصدقه في ذلك دالّ على أنه كلام الله أوحاه إلى رسوله ﷺ.", "لا يملك النفع ولا الضر على الحقيقة إلا الله، ولذا وجب ألا يُطمع إلا فيه ولا يُرهب إلا منه.", "حرمة ظن السوء في الله عز وجل، ووجوب حسن الظن به تعالى.", "الكفر موجب لعذاب النار، ومن تاب تاب الله عليه، ومن طلب المغفرة في صدق غُفر له.", "ذمّ التخلّف عن المسابقة في الخيرات والمنافسة في الصالحات."], "k": "«شغلتنا أموالنا وأهلونا»… ما العذر الذي أقوله بلساني وأعلم في قلبي أنه ليس الحقيقة؟"}, {"lbl": "الآية ١٥", "q": "سَيَقُولُ ٱلۡمُخَلَّفُونَ إِذَا ٱنطَلَقۡتُمۡ إِلَىٰ مَغَانِمَ لِتَأۡخُذُوهَا ذَرُونَا نَتَّبِعۡكُمۡۖ يُرِيدُونَ أَن يُبَدِّلُواْ كَلَٰمَ ٱللَّهِۚ قُل لَّن تَتَّبِعُونَا كَذَٰلِكُمۡ قَالَ ٱللَّهُ مِن قَبۡلُۖ فَسَيَقُولُونَ بَلۡ تَحۡسُدُونَنَاۚ بَلۡ كَانُواْ لَا يَفۡقَهُونَ إِلَّا قَلِيلٗا ﴿١٥﴾", "w": [["المخلّفون", "المذكورون قبل هذه، وهم غفار وجهينة ومزينة وأشجع."], ["إذا انطلقتم إلى مغانم لتأخذوها", "مغانم خيبر، إذ وعدهم الله بها عند رجوعهم من الحديبية."], ["ذرونا نتّبعكم", "دعونا نخرج معكم لنصيب من الغنائم."], ["يريدون أن يبدّلوا كلام الله", "بطلبهم الخروج يريدون أن يغيّروا وعد الله لأهل الحديبية خاصة بغنائم خيبر."], ["كذلكم قال الله من قبل", "قاله تعالى لنا قبل عودتنا إلى المدينة."], ["فسيقولون بل تحسدوننا", "زعموا أن المنع ليس أمراً من الله وإنما هو من الرسول والمؤمنين حسداً لهم، وهذا دالّ على نفاقهم."], ["بل كانوا لا يفقهون إلا قليلاً", "لا يفهمون فهم الحاذق الماهر إلا قليلاً، وفي أمور الدنيا لا غير."]], "m": "ما زال السياق في طلب هداية المنافقين بكشف عوارهم ودعوتهم إلى التوبة: سيقول المخلّفون الذين تخلّفوا عن الحديبية إذا انطلقتم إلى مغانم لتأخذوها: دعونا نتبعكم؛ وذلك أن الله بعد صلح الحديبية وما نال أهلها من آلام نفسية أكرمهم بنعم كثيرة، منها أنه واعدهم بغنائم خيبر، وكانت أموالاً عظيمة، فلما تهيّؤوا للخروج إليها جاء هؤلاء يطالبون بالسير معهم لأجل الغنيمة لا غير. يريدون أن يبدّلوا وعد الله لأهل الحديبية خاصة، ولذا أمر رسوله أن يقول لهم: لن تتبعونا، كذلكم قال الله من قبل، فقد أخبرنا تعالى بحالكم ومقالكم قبل أن تقولوه. فسيقولون: ما منعتمونا إلا حسداً لنا أن ننال من الغنائم، لم يأمركم الله بمنعنا، وقد قالوه. بل كانوا لا يفقهون إلا قليلاً؛ وصمهم بالجهل وجعله علة تخبّطهم وضلالهم، فليسوا على مستوى الرجل الحاذق البصير الذي يحسن القول والعمل.", "h": ["وعد الله رسوله والمؤمنين بغنائم خيبر وهم في طريقهم من الحديبية إلى المدينة، وإنجازه لهم، دالّ على وجود الله وعلمه وقدرته وحكمته ورحمته، وكلها موجبة للإيمان والتوحيد وحب الله والرغبة إليه والرهبة منه.", "بيان حيرة الكافر واضطراب نفسه وتخبّط قوله وعمله.", "ذمّ الجهل وتقبيحه، إنه بئس الوصف يوصف به المرء، ولذا لا يرضاه حتى الجاهل لنفسه، فلو قلت لجاهل: يا جاهل لا تفعل كذا، لغضب عليك."], "k": "«ذرونا نتّبعكم»… هل أحضر حيث الغنيمة وأغيب حيث التضحية؟"}, {"lbl": "الآيتان ١٦ – ١٧", "q": "قُل لِّلۡمُخَلَّفِينَ مِنَ ٱلۡأَعۡرَابِ سَتُدۡعَوۡنَ إِلَىٰ قَوۡمٍ أُوْلِي بَأۡسٖ شَدِيدٖ تُقَٰتِلُونَهُمۡ أَوۡ يُسۡلِمُونَۖ فَإِن تُطِيعُواْ يُؤۡتِكُمُ ٱللَّهُ أَجۡرًا حَسَنٗاۖ وَإِن تَتَوَلَّوۡاْ كَمَا تَوَلَّيۡتُم مِّن قَبۡلُ يُعَذِّبۡكُمۡ عَذَابًا أَلِيمٗا ﴿١٦﴾ لَّيۡسَ عَلَى ٱلۡأَعۡمَىٰ حَرَجٞ وَلَا عَلَى ٱلۡأَعۡرَجِ حَرَجٞ وَلَا عَلَى ٱلۡمَرِيضِ حَرَجٞۗ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدۡخِلۡهُ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ وَمَن يَتَوَلَّ يُعَذِّبۡهُ عَذَابًا أَلِيمٗا ﴿١٧﴾", "w": [["قل للمخلّفين من الأعراب", "الذين تخلّفوا عن الحديبية وطالبوا بالخروج إلى خيبر، قل لهم اختباراً."], ["ستُدعون إلى قوم أولي بأس شديد", "ستُدعون يوماً إلى قتال قوم ذوي بأس وشدة في الحرب."], ["تقاتلونهم أو يُسلمون", "تقاتلونهم، أو هم يُسلمون فلا حاجة إلى قتالهم."], ["فإن تطيعوا", "أمر الداعي لكم إلى قتال القوم أصحاب البأس الشديد."], ["يؤتكم الله أجراً حسناً", "عودة اعتباركم مؤمنين صالحين في الدنيا، والجنة في الآخرة."], ["وإن تتولّوا", "تعرضوا عن الجهاد كما تولّيتم من قبل."], ["يعذّبكم عذاباً أليماً", "في الدنيا بالقتل والإذلال، وفي الآخرة بعذاب النار."], ["حرج", "إثم."], ["ومن يتولّ", "يعرض عن طاعة الله ورسوله."]], "m": "ما زال السياق في طلب هداية المنافقين من الأعراب: قل للمخلّفين، الذين أصبح وصف التخلّف شعاراً لهم وفي ذلك من الذم ما فيه، مختبراً إياهم: ستُدعون يوماً إلى قتال قوم أولي بأس شديد في الحروب، تقاتلونهم أو يسلمون فلا تقاتلوهم، وذلك بأن يرضوا بدفع الجزية، وهؤلاء لا يكونون إلا نصارى أو مجوساً، فهم إما فارس وإما الروم، وقد اختُلف في تحديدهم. فإن تطيعوا الداعي للجهاد فتخرجوا يؤتكم الله أجراً حسناً: غنائم في الدنيا وحسن الصيت والجنة فوق ذلك، وإن تعرضوا كما أعرضتم من قبل حين لم تخرجوا مع رسول الله إلى مكة خوفاً من قريش يعذّبكم عذاباً أليماً في الدنيا والآخرة. ولما نزلت هذه الآية خاف أصحاب الأعذار وبكوا، فأنزل الله: ليس على الأعمى حرج إذا لم يخرج للجهاد، ولا على الأعرج الذي لا يقدر على المشي والكرّ والفرّ، ولا على المريض بالأمراض المزمنة التي لا يقدر صاحبها على القتال. ومن يطع الله ورسوله في أوامرهما ونواهيهما يدخله جنات تجري من تحتها الأنهار، وعد صادق من رب كريم، ومن يتولّ يعذّبه عذاباً أليماً، وعيد شديد، ألا فليتقِ الله امرؤ فإن الله شديد العقاب.", "h": ["مشروعية الاختبار والامتحان لمعرفة القدرات والمؤهلات.", "بيان أن غزو الإسلام ينتهي إلى أحد أمرين: إسلام الأمة المغزوّة، أو دخولها في الذمة بإعطائها الجزية والرضا بالحكم الإسلامي وسياسته.", "دفع الإثم والحرج في التخلّف عن الجهاد لعذر العمى أو العرج أو المرض.", "بيان وعد الله ووعيده لمن أطاعه ولمن عصاه: الوعد بالجنة، والوعيد بالنار."], "k": "«ليس على الأعمى حرج»… ربي لا يكلّف فوق الطاقة؛ فهل أؤدي ما في طاقتي فعلاً؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (381, 48, 18, 24, 'سورة الفتح ١٨ – ٢٤', 'الفتح: لقد رضي الله عن المؤمنين إذ يبايعونك تحت الشجرة', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 381) = $j$[{"lbl": "الآيتان ١٨ – ١٩", "q": "۞لَّقَدۡ رَضِيَ ٱللَّهُ عَنِ ٱلۡمُؤۡمِنِينَ إِذۡ يُبَايِعُونَكَ تَحۡتَ ٱلشَّجَرَةِ فَعَلِمَ مَا فِي قُلُوبِهِمۡ فَأَنزَلَ ٱلسَّكِينَةَ عَلَيۡهِمۡ وَأَثَٰبَهُمۡ فَتۡحٗا قَرِيبٗا ﴿١٨﴾ وَمَغَانِمَ كَثِيرَةٗ يَأۡخُذُونَهَاۗ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمٗا ﴿١٩﴾", "w": [["لقد رضي الله عن المؤمنين", "الراسخين في الإيمان الأقوياء فيه، وهم أهل بيعة الرضوان من أصحاب رسول الله ﷺ."], ["إذ يبايعونك", "بالحديبية أيها الرسول."], ["تحت الشجرة", "سَمُرة، وهم ألف وأربعمائة بايعوا على أن يقاتلوا قريشاً ولا يفرّوا."], ["فعلم ما في قلوبهم فأنزل السكينة عليهم", "علم ما في قلوبهم من الصدق والوفاء، فأنزل الطمأنينة عليهم والثبات على ما هم عليه."], ["وأثابهم فتحاً قريباً", "فتح خيبر بعد انصرافهم من الحديبية، غزوها في آخر المحرم من سنة سبع."], ["ومغانم كثيرة يأخذونها", "من خيبر."], ["وكان الله عزيزاً حكيماً", "كان وما زال غالباً حكيماً في تصريف شؤون عباده."]], "m": "هذا إخبار منه تعالى برضاه عن المؤمنين الكاملين في إيمانهم، وهم ألف وأربعمائة بايعوا الرسول ﷺ تحت شجرة سَمُرة، إلا الجدّ بن قيس الأنصاري فإنه لم يبايع، إذ كان لاصقاً بإبط ناقته مختبئاً عن أعين الأصحاب، وكان منافقاً ومات على ذلك. وسبب هذه البيعة أن النبي ﷺ بعث خِراش بن أمية الخزاعي إلى قريش بمكة على جمل له ليبلّغ أشرافهم ما جاء له، فعقروا الجمل وأرادوا قتله فمنعته الأحابيش، فخلّوا سبيله. فدعا رسول الله ﷺ عمر ليبعثه، فقال: يا رسول الله إني أخاف قريشاً على نفسي وليس بمكة من بني عديّ أحد يمنعني، ولكني أدلّك على رجل هو أعزّ بها مني: عثمان بن عفان، فبعث عثمان إلى أبي سفيان وأشراف قريش يخبرهم أنه لم يأتِ لحرب وإنما جاء زائراً لهذا البيت معظّماً لحرمته، فأجاره أبان بن سعيد حتى بلّغ الرسالة، فقالوا له: إن شئت أن تطوف بالبيت فطف، قال: ما كنت لأفعل حتى يطوف به رسول الله ﷺ، فاحتبسته قريش، فبلغ المسلمين أن عثمان قُتل، فقال ﷺ: «لا نبرح حتى نناجز القوم»، ودعا الناس إلى البيعة فكانت بيعة الرضوان تحت الشجرة. فعلم الله ما في قلوبهم من الصدق والوفاء فأنزل الطمأنينة والثبات عليهم، وجزاهم فتحاً قريباً: صلح الحديبية وفتح خيبر، ومغانم كثيرة يأخذونها هي غنائم خيبر، وكان الله عزيزاً حكيماً.", "h": ["بيان فضل أهل بيعة الرضوان، وكرامة الله لهم برضاه عنهم.", "ذكاء عمر وقوة فراسته، إذ أمر بقطع الشجرة خشية أن تُعبد، وكم عُبدت من أشجار في أمة الإسلام في غيبة العلماء وأهل القرآن.", "مكافأة الله تعالى للصادقين الصابرين المجاهدين من عباده المؤمنين بخير الدنيا والآخرة."], "k": "«فعلم ما في قلوبهم»… رضي عنهم بما في قلوبهم قبل أفعالهم؛ فماذا يعلم من قلبي؟"}, {"lbl": "الآيات ٢٠ – ٢٤", "q": "وَعَدَكُمُ ٱللَّهُ مَغَانِمَ كَثِيرَةٗ تَأۡخُذُونَهَا فَعَجَّلَ لَكُمۡ هَٰذِهِۦ وَكَفَّ أَيۡدِيَ ٱلنَّاسِ عَنكُمۡ وَلِتَكُونَ ءَايَةٗ لِّلۡمُؤۡمِنِينَ وَيَهۡدِيَكُمۡ صِرَٰطٗا مُّسۡتَقِيمٗا ﴿٢٠﴾ وَأُخۡرَىٰ لَمۡ تَقۡدِرُواْ عَلَيۡهَا قَدۡ أَحَاطَ ٱللَّهُ بِهَاۚ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٗا ﴿٢١﴾ وَلَوۡ قَٰتَلَكُمُ ٱلَّذِينَ كَفَرُواْ لَوَلَّوُاْ ٱلۡأَدۡبَٰرَ ثُمَّ لَا يَجِدُونَ وَلِيّٗا وَلَا نَصِيرٗا ﴿٢٢﴾ سُنَّةَ ٱللَّهِ ٱلَّتِي قَدۡ خَلَتۡ مِن قَبۡلُۖ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبۡدِيلٗا ﴿٢٣﴾ وَهُوَ ٱلَّذِي كَفَّ أَيۡدِيَهُمۡ عَنكُمۡ وَأَيۡدِيَكُمۡ عَنۡهُم بِبَطۡنِ مَكَّةَ مِنۢ بَعۡدِ أَنۡ أَظۡفَرَكُمۡ عَلَيۡهِمۡۚ وَكَانَ ٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرًا ﴿٢٤﴾", "w": [["وعدكم الله مغانم كثيرة تأخذونها", "من الفتوحات الإسلامية التي وصلت الأندلس غرباً."], ["فعجّل لكم هذه", "غنيمة خيبر."], ["وكفّ أيدي الناس عنكم", "أيدي اليهود حيث همّوا بالغارة على بيوت الصحابة وفيها أزواجهم وأولادهم وأموالهم فصرفهم الله عنهم."], ["ولتكون آية للمؤمنين", "تلك الصرفة آية يستدلون بها على كلاءة الله وحمايته لهم في حضورهم ومغيبهم."], ["ويهديكم صراطاً مستقيماً", "طريقاً لا اعوجاج فيه في التوكل على الله والتفويض إليه في الحضور والغيبة."], ["وأخرى لم تقدروا عليها", "ومغانم أخرى لم تقدروا عليها، وهي غنائم فارس والروم."], ["قد أحاط الله بها", "فهي محفوظة لكم إلى حين تغزون فارس والروم."], ["ولو قاتلكم الذين كفروا", "المشركون في الحديبية."], ["لولّوا الأدبار", "لانهزموا أمامكم وأعطوكم أدبارهم."], ["سنة الله التي قد خلت من قبل", "هزيمة الكافرين ونصر المؤمنين الصابرين سنة ماضية في الأمم."], ["وهو الذي كفّ أيديهم عنكم", "حيث جاء ثمانون من المشركين يريدون رسول الله والمؤمنين بسوء."], ["وأيديكم عنهم ببطن مكة", "فأخذهم أصحاب رسول الله أسرى وأتوا بهم إليه."], ["من بعد أن أظفركم عليهم", "وذلك بالحديبية التي هي بطن مكة."]], "m": "ما زال السياق في ذكر إنعام الله على المؤمنين المبايعين: وعدكم الله مغانم كثيرة تأخذونها، فعجّل لكم غنيمة خيبر، وكفّ أيدي الناس عنكم؛ وذلك أن يهود المدينة تمالؤوا مع يهود خيبر وبعض العرب على أن يُغيروا على دور الأنصار والمهاجرين بالمدينة ليقتلوا من بها وينهبوا ما فيها، فكفّ الله أيديهم كرامة للمؤمنين، ولتكون تلك الصرفة آية تهديهم إلى زيادة التوكل على الله، ويسدّدكم طريقاً واضحاً: أن تثقوا في أموركم كلها بربكم فيكفيكم ما يهمّكم في مغيبكم وحضوركم. وغنائم أخرى لم تقدروا عليها، غنائم الروم وفارس، قد أحاط الله بها فلم يفلت منها شيء حتى تأخذوها، وكان الله على كل شيء قديراً، ومن مظاهر قدرته أن يغنمكم وأنتم أقل عدداً وعُدداً غنائم أكبر دولتين في ذلك الوقت. ولو قاتلكم أهل مكة وأنتم ببطنها لانهزموا أمامكم ثم لا يجدون ولياً ولا نصيراً، سنة الله في الأمم السابقة أن ينصر أولياءه على أعدائه، ولن تجد لسنة الله تبديلاً. وهو الذي كفّ أيديهم عنكم وأيديكم عنهم ببطن مكة؛ إذ بعثت قريش ثمانين شاباً إلى معسكر رسول الله في الحديبية لعلهم يصيبون غرة منه ومن أصحابه، فأوقعهم الله أسرى في أيدي المسلمين، فمنّ عليهم الرسول ﷺ بالعفو، فكان ذلك سبب صلح الحديبية، وكان الله بما تعملون بصيراً.", "h": ["صدق وعد الله لأصحاب رسوله في الغنائم التي وعدهم بها، فتحققت كلماته بعد وفاة رسول الله ﷺ، وهي غنائم فارس والروم.", "كرامة الله للمؤمنين إذ حمى ظهورهم من خلفهم مرتين: الأولى ما همّ به اليهود من غارة على عائلات وأُسر الصحابة بالمدينة النبوية، والثانية ما همّ به رجال من المشركين للفتك بالمؤمنين ليلاً بالحديبية، إذ مكّن الله منهم رسوله والمؤمنين، ثم عفا عنهم رسول الله وأطلق سراحهم، فكان ذلك مساعداً قوياً على تحقيق صلح الحديبية.", "بيان سنة الله في أنه ما تقاتل أولياء الله مع أعدائه في معركة إلا نصر الله أولياءه على أعدائه."], "k": "«وكفّ أيدي الناس عنكم»… كم شرّ صُرف عني وأنا غائب لا أدري؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 381;
insert into public.tdb_cards(topic, i, body) select 381, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ١٨ – ١٩", "q": "۞لَّقَدۡ رَضِيَ ٱللَّهُ عَنِ ٱلۡمُؤۡمِنِينَ إِذۡ يُبَايِعُونَكَ تَحۡتَ ٱلشَّجَرَةِ فَعَلِمَ مَا فِي قُلُوبِهِمۡ فَأَنزَلَ ٱلسَّكِينَةَ عَلَيۡهِمۡ وَأَثَٰبَهُمۡ فَتۡحٗا قَرِيبٗا ﴿١٨﴾ وَمَغَانِمَ كَثِيرَةٗ يَأۡخُذُونَهَاۗ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمٗا ﴿١٩﴾", "w": [["لقد رضي الله عن المؤمنين", "الراسخين في الإيمان الأقوياء فيه، وهم أهل بيعة الرضوان من أصحاب رسول الله ﷺ."], ["إذ يبايعونك", "بالحديبية أيها الرسول."], ["تحت الشجرة", "سَمُرة، وهم ألف وأربعمائة بايعوا على أن يقاتلوا قريشاً ولا يفرّوا."], ["فعلم ما في قلوبهم فأنزل السكينة عليهم", "علم ما في قلوبهم من الصدق والوفاء، فأنزل الطمأنينة عليهم والثبات على ما هم عليه."], ["وأثابهم فتحاً قريباً", "فتح خيبر بعد انصرافهم من الحديبية، غزوها في آخر المحرم من سنة سبع."], ["ومغانم كثيرة يأخذونها", "من خيبر."], ["وكان الله عزيزاً حكيماً", "كان وما زال غالباً حكيماً في تصريف شؤون عباده."]], "m": "هذا إخبار منه تعالى برضاه عن المؤمنين الكاملين في إيمانهم، وهم ألف وأربعمائة بايعوا الرسول ﷺ تحت شجرة سَمُرة، إلا الجدّ بن قيس الأنصاري فإنه لم يبايع، إذ كان لاصقاً بإبط ناقته مختبئاً عن أعين الأصحاب، وكان منافقاً ومات على ذلك. وسبب هذه البيعة أن النبي ﷺ بعث خِراش بن أمية الخزاعي إلى قريش بمكة على جمل له ليبلّغ أشرافهم ما جاء له، فعقروا الجمل وأرادوا قتله فمنعته الأحابيش، فخلّوا سبيله. فدعا رسول الله ﷺ عمر ليبعثه، فقال: يا رسول الله إني أخاف قريشاً على نفسي وليس بمكة من بني عديّ أحد يمنعني، ولكني أدلّك على رجل هو أعزّ بها مني: عثمان بن عفان، فبعث عثمان إلى أبي سفيان وأشراف قريش يخبرهم أنه لم يأتِ لحرب وإنما جاء زائراً لهذا البيت معظّماً لحرمته، فأجاره أبان بن سعيد حتى بلّغ الرسالة، فقالوا له: إن شئت أن تطوف بالبيت فطف، قال: ما كنت لأفعل حتى يطوف به رسول الله ﷺ، فاحتبسته قريش، فبلغ المسلمين أن عثمان قُتل، فقال ﷺ: «لا نبرح حتى نناجز القوم»، ودعا الناس إلى البيعة فكانت بيعة الرضوان تحت الشجرة. فعلم الله ما في قلوبهم من الصدق والوفاء فأنزل الطمأنينة والثبات عليهم، وجزاهم فتحاً قريباً: صلح الحديبية وفتح خيبر، ومغانم كثيرة يأخذونها هي غنائم خيبر، وكان الله عزيزاً حكيماً.", "h": ["بيان فضل أهل بيعة الرضوان، وكرامة الله لهم برضاه عنهم.", "ذكاء عمر وقوة فراسته، إذ أمر بقطع الشجرة خشية أن تُعبد، وكم عُبدت من أشجار في أمة الإسلام في غيبة العلماء وأهل القرآن.", "مكافأة الله تعالى للصادقين الصابرين المجاهدين من عباده المؤمنين بخير الدنيا والآخرة."], "k": "«فعلم ما في قلوبهم»… رضي عنهم بما في قلوبهم قبل أفعالهم؛ فماذا يعلم من قلبي؟"}, {"lbl": "الآيات ٢٠ – ٢٤", "q": "وَعَدَكُمُ ٱللَّهُ مَغَانِمَ كَثِيرَةٗ تَأۡخُذُونَهَا فَعَجَّلَ لَكُمۡ هَٰذِهِۦ وَكَفَّ أَيۡدِيَ ٱلنَّاسِ عَنكُمۡ وَلِتَكُونَ ءَايَةٗ لِّلۡمُؤۡمِنِينَ وَيَهۡدِيَكُمۡ صِرَٰطٗا مُّسۡتَقِيمٗا ﴿٢٠﴾ وَأُخۡرَىٰ لَمۡ تَقۡدِرُواْ عَلَيۡهَا قَدۡ أَحَاطَ ٱللَّهُ بِهَاۚ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٗا ﴿٢١﴾ وَلَوۡ قَٰتَلَكُمُ ٱلَّذِينَ كَفَرُواْ لَوَلَّوُاْ ٱلۡأَدۡبَٰرَ ثُمَّ لَا يَجِدُونَ وَلِيّٗا وَلَا نَصِيرٗا ﴿٢٢﴾ سُنَّةَ ٱللَّهِ ٱلَّتِي قَدۡ خَلَتۡ مِن قَبۡلُۖ وَلَن تَجِدَ لِسُنَّةِ ٱللَّهِ تَبۡدِيلٗا ﴿٢٣﴾ وَهُوَ ٱلَّذِي كَفَّ أَيۡدِيَهُمۡ عَنكُمۡ وَأَيۡدِيَكُمۡ عَنۡهُم بِبَطۡنِ مَكَّةَ مِنۢ بَعۡدِ أَنۡ أَظۡفَرَكُمۡ عَلَيۡهِمۡۚ وَكَانَ ٱللَّهُ بِمَا تَعۡمَلُونَ بَصِيرًا ﴿٢٤﴾", "w": [["وعدكم الله مغانم كثيرة تأخذونها", "من الفتوحات الإسلامية التي وصلت الأندلس غرباً."], ["فعجّل لكم هذه", "غنيمة خيبر."], ["وكفّ أيدي الناس عنكم", "أيدي اليهود حيث همّوا بالغارة على بيوت الصحابة وفيها أزواجهم وأولادهم وأموالهم فصرفهم الله عنهم."], ["ولتكون آية للمؤمنين", "تلك الصرفة آية يستدلون بها على كلاءة الله وحمايته لهم في حضورهم ومغيبهم."], ["ويهديكم صراطاً مستقيماً", "طريقاً لا اعوجاج فيه في التوكل على الله والتفويض إليه في الحضور والغيبة."], ["وأخرى لم تقدروا عليها", "ومغانم أخرى لم تقدروا عليها، وهي غنائم فارس والروم."], ["قد أحاط الله بها", "فهي محفوظة لكم إلى حين تغزون فارس والروم."], ["ولو قاتلكم الذين كفروا", "المشركون في الحديبية."], ["لولّوا الأدبار", "لانهزموا أمامكم وأعطوكم أدبارهم."], ["سنة الله التي قد خلت من قبل", "هزيمة الكافرين ونصر المؤمنين الصابرين سنة ماضية في الأمم."], ["وهو الذي كفّ أيديهم عنكم", "حيث جاء ثمانون من المشركين يريدون رسول الله والمؤمنين بسوء."], ["وأيديكم عنهم ببطن مكة", "فأخذهم أصحاب رسول الله أسرى وأتوا بهم إليه."], ["من بعد أن أظفركم عليهم", "وذلك بالحديبية التي هي بطن مكة."]], "m": "ما زال السياق في ذكر إنعام الله على المؤمنين المبايعين: وعدكم الله مغانم كثيرة تأخذونها، فعجّل لكم غنيمة خيبر، وكفّ أيدي الناس عنكم؛ وذلك أن يهود المدينة تمالؤوا مع يهود خيبر وبعض العرب على أن يُغيروا على دور الأنصار والمهاجرين بالمدينة ليقتلوا من بها وينهبوا ما فيها، فكفّ الله أيديهم كرامة للمؤمنين، ولتكون تلك الصرفة آية تهديهم إلى زيادة التوكل على الله، ويسدّدكم طريقاً واضحاً: أن تثقوا في أموركم كلها بربكم فيكفيكم ما يهمّكم في مغيبكم وحضوركم. وغنائم أخرى لم تقدروا عليها، غنائم الروم وفارس، قد أحاط الله بها فلم يفلت منها شيء حتى تأخذوها، وكان الله على كل شيء قديراً، ومن مظاهر قدرته أن يغنمكم وأنتم أقل عدداً وعُدداً غنائم أكبر دولتين في ذلك الوقت. ولو قاتلكم أهل مكة وأنتم ببطنها لانهزموا أمامكم ثم لا يجدون ولياً ولا نصيراً، سنة الله في الأمم السابقة أن ينصر أولياءه على أعدائه، ولن تجد لسنة الله تبديلاً. وهو الذي كفّ أيديهم عنكم وأيديكم عنهم ببطن مكة؛ إذ بعثت قريش ثمانين شاباً إلى معسكر رسول الله في الحديبية لعلهم يصيبون غرة منه ومن أصحابه، فأوقعهم الله أسرى في أيدي المسلمين، فمنّ عليهم الرسول ﷺ بالعفو، فكان ذلك سبب صلح الحديبية، وكان الله بما تعملون بصيراً.", "h": ["صدق وعد الله لأصحاب رسوله في الغنائم التي وعدهم بها، فتحققت كلماته بعد وفاة رسول الله ﷺ، وهي غنائم فارس والروم.", "كرامة الله للمؤمنين إذ حمى ظهورهم من خلفهم مرتين: الأولى ما همّ به اليهود من غارة على عائلات وأُسر الصحابة بالمدينة النبوية، والثانية ما همّ به رجال من المشركين للفتك بالمؤمنين ليلاً بالحديبية، إذ مكّن الله منهم رسوله والمؤمنين، ثم عفا عنهم رسول الله وأطلق سراحهم، فكان ذلك مساعداً قوياً على تحقيق صلح الحديبية.", "بيان سنة الله في أنه ما تقاتل أولياء الله مع أعدائه في معركة إلا نصر الله أولياءه على أعدائه."], "k": "«وكفّ أيدي الناس عنكم»… كم شرّ صُرف عني وأنا غائب لا أدري؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (382, 48, 25, 29, 'سورة الفتح ٢٥ – ٢٩', 'الفتح: محمد رسول الله والذين معه', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 382) = $j$[{"lbl": "الآيتان ٢٥ – ٢٦", "q": "هُمُ ٱلَّذِينَ كَفَرُواْ وَصَدُّوكُمۡ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ وَٱلۡهَدۡيَ مَعۡكُوفًا أَن يَبۡلُغَ مَحِلَّهُۥۚ وَلَوۡلَا رِجَالٞ مُّؤۡمِنُونَ وَنِسَآءٞ مُّؤۡمِنَٰتٞ لَّمۡ تَعۡلَمُوهُمۡ أَن تَطَـُٔوهُمۡ فَتُصِيبَكُم مِّنۡهُم مَّعَرَّةُۢ بِغَيۡرِ عِلۡمٖۖ لِّيُدۡخِلَ ٱللَّهُ فِي رَحۡمَتِهِۦ مَن يَشَآءُۚ لَوۡ تَزَيَّلُواْ لَعَذَّبۡنَا ٱلَّذِينَ كَفَرُواْ مِنۡهُمۡ عَذَابًا أَلِيمًا ﴿٢٥﴾ إِذۡ جَعَلَ ٱلَّذِينَ كَفَرُواْ فِي قُلُوبِهِمُ ٱلۡحَمِيَّةَ حَمِيَّةَ ٱلۡجَٰهِلِيَّةِ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلۡمُؤۡمِنِينَ وَأَلۡزَمَهُمۡ كَلِمَةَ ٱلتَّقۡوَىٰ وَكَانُوٓاْ أَحَقَّ بِهَا وَأَهۡلَهَاۚ وَكَانَ ٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٗا ﴿٢٦﴾", "w": [["هم الذين كفروا وصدّوكم عن المسجد الحرام", "كفروا بالله ورسوله ومنعوكم من الوصول إلى المسجد الحرام."], ["والهدي معكوفاً أن يبلغ محلّه", "ومنعوا الهدي محبوساً أن يبلغ محلّه من الحرم."], ["ولولا رجال مؤمنون ونساء مؤمنات", "موجودون في مكة."], ["لم تعلموهم", "لم تعرفوهم مؤمنين ومؤمنات."], ["أن تطؤوهم", "قتلاً لهم عند قتالكم المشركين بمكة."], ["فتصيبكم منهم معرّة بغير علم", "إثم وديات قتل الخطأ وعتق أو صيام، لأذن لكم في الفتح."], ["ليُدخل الله في رحمته من يشاء", "لم يؤذن لكم في دخول مكة فاتحين ليدخل الله في الإسلام من يشاء."], ["لو تزيّلوا لعذّبنا الذين كفروا منهم", "لو تميّزوا فكان المؤمنون على حدة والكافرون على حدة لأذنّا لكم وعذّبنا الذين كفروا بأيديكم."], ["الحمية حمية الجاهلية", "الأنفة المانعة من قبول الحق، ولذا منعوا الرسول وأصحابه من دخول مكة."], ["فأنزل الله سكينته على رسوله وعلى المؤمنين", "همّ الصحابة أن يخالفوا أمر رسول الله بالصلح فأنزل الله سكينته عليهم فرضوا فتمّ الصلح."], ["وألزمهم كلمة التقوى", "ألزمهم كلمة لا إله إلا الله، إذ هي الواقية من الشرك."], ["وكانوا أحق بها وأهلها", "أجدر بكلمة التوحيد وأهلاً للتقوى."]], "m": "ما زال السياق في صلح الحديبية: هم الذين كفروا بالله ورسوله وصدّوكم عن المسجد الحرام أن تدخلوه وأنتم محرمون، وصدّوا الهدي محبوساً يُنتظر به دخول مكة لينحر. ولولا رجال مؤمنون ونساء مؤمنات بمكة لم تعرفوهم لأنهم كانوا يخفون إسلامهم، كراهة أن تقتلوهم أثناء قتالكم المشركين فتلحقكم التبعة وما يلزم من قتل المسلم خطأً من الكفارة والدية، لأذن لكم في دخول مكة فاتحين. لم يأذن لكم في القتال ورضي لكم بالصلح ليُدخل في رحمته من يشاء: فالمؤمنون نالتهم رحمته إذ لم يُؤذوا، والمشركون قد يكون تأخّر الفتح سبباً في إسلام من شاء الله منهم، لا سيما حين رأوا رحمة الإسلام تتجلى في ترك القتال رحمة بالمؤمنين. لو تميّز المؤمنون عن المشركين في مكان خاص بهم لأذنّا لكم في دخول مكة وعذّبنا الكافرين بأيديكم، إذ جعل الذين كفروا في قلوبهم الأنفة والتعاظم المانع من قبول الحق، وهي من صفات الجاهلية، فقالوا: كيف ندعهم يدخلون بلادنا وقد قتلوا أبناءنا؟ واللات والعزى ما دخلوها علينا أبداً. ولما همّ المؤمنون بعدم قبول الصلح لما فيه من التنازل الكبير أنزل الله سكينته عليهم، وهي الطمأنينة والوقار والحلم، فرضوا بالمصالحة، وكان فيها خير كثير حتى قيل: إنها فتح، أو فاتحة فتوحات لا حدّ لها. وأكرم المؤمنين بإلزامهم كلمة لا إله إلا الله، كلمة التقوى الواقية من الشرك والعذاب، وجعلهم أحق بها وأهلها، وكان الله بكل شيء عليماً، ومن ذلك علمه بأهلية أصحاب رسول الله للإيمان والتقوى.", "h": ["بيان حكم المحصر، وهو من مُنع من دخول المسجد الحرام وهو محرم بحج أو بعمرة، فإنه يتحلّل بذبح هدي ويعود إلى بلاده، ويذبح الهدي حيث أُحصر.", "الأخذ بالحيطة في معاملة المسلمين حتى لا يُؤذى مؤمن أو مؤمنة بغير علم.", "بيان أن كلمة التقوى هي لا إله إلا الله.", "الإشارة إلى ما أصاب المسلمين من ألم نفسي من جرّاء الشروط القاسية التي اشترطها ممثل قريش في وثيقة الصلح."], "k": "«إذ جعل الذين كفروا في قلوبهم الحمية حمية الجاهلية»… هل في أنفتي شيء من الجاهلية يمنعني من قبول حق؟"}, {"lbl": "الآيتان ٢٧ – ٢٨", "q": "لَّقَدۡ صَدَقَ ٱللَّهُ رَسُولَهُ ٱلرُّءۡيَا بِٱلۡحَقِّۖ لَتَدۡخُلُنَّ ٱلۡمَسۡجِدَ ٱلۡحَرَامَ إِن شَآءَ ٱللَّهُ ءَامِنِينَ مُحَلِّقِينَ رُءُوسَكُمۡ وَمُقَصِّرِينَ لَا تَخَافُونَۖ فَعَلِمَ مَا لَمۡ تَعۡلَمُواْ فَجَعَلَ مِن دُونِ ذَٰلِكَ فَتۡحٗا قَرِيبًا ﴿٢٧﴾ هُوَ ٱلَّذِيٓ أَرۡسَلَ رَسُولَهُۥ بِٱلۡهُدَىٰ وَدِينِ ٱلۡحَقِّ لِيُظۡهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦۚ وَكَفَىٰ بِٱللَّهِ شَهِيدٗا ﴿٢٨﴾", "w": [["لقد صدق الله رسوله الرؤيا بالحق", "جعل رؤيا رسوله التي رآها في النوم عام الحديبية حقاً."], ["لتدخلُنّ المسجد الحرام إن شاء الله", "هذا مضمون الرؤيا."], ["محلّقين رؤوسكم ومقصّرين", "حالقين جميع شعوركم أو مقصّرينها."], ["لا تخافون", "أبداً، حال الإحرام وبعده."], ["فعلم ما لم تعلموا", "في الصلح الذي تمّ، من المعرّة التي كانت تلحق المسلمين بقتال إخوانهم المؤمنين وهم لا يعلمون."], ["فجعل من دون ذلك فتحاً قريباً", "هو فتح خيبر، وتحققت الرؤيا في العام القابل."], ["هو الذي أرسل رسوله بالهدى", "فلذا لا يُخلفه رؤياه بل يصدقها."], ["ليُظهره على الدين كله", "ليُعليه على سائر الأديان بنسخ الحق فيها وإبطال الباطل، أو بتسليط المسلمين على أهلها فيحكمونهم."], ["وكفى بالله شهيداً", "على أنك مرسل بالهدى ودين الحق."]], "m": "ما زال السياق في صلح الحديبية: لقد صدق الله رسوله محمداً ﷺ الرؤيا التي رآها وأخبر بها أصحابه عند خروجهم من المدينة إلى مكة فسرّوا بها، ولما تم الصلح بعد جهاد سياسي وعسكري مرير وأمرهم الرسول أن ينحروا ويحلقوا اندهشوا، وقال بعضهم: أين الرؤيا التي رأيت؟ ونزلت سورة الفتح عند منصرفهم وفيها: لتدخلُنّ المسجد الحرام إن شاء الله آمنين محلّقين رؤوسكم ومقصّرين لا تخافون. فلما جاء العام القابل في نفس الأيام من ذي القعدة خرج رسول الله والمسلمون محرمين يلبّون، وأخلت لهم قريش المسجد الحرام، فطافوا وسعوا وتحلّلوا، فمنهم المحلّق ومنهم المقصّر. فعلم ما لم تعلموا فأثبت الصلح، لأنه لو كان قتال لهلك المؤمنون والمؤمنات بمكة بالحرب ولحقت المسلمين معرّة كبرى بقتل إخوانهم، وجعل من دون ذلك فتحاً قريباً: الصلح فتح، وفتح خيبر فتح، وفتح مكة فتح. هو الذي أرسل رسوله محمداً بالهدى ودين الحق، فكيف لا يصدقه رؤياه كما ظن البعض؟ ليظهره على الدين كله بنسخ الحق الذي فيه وإبطال الباطل الذي ألصق به، أو بتسليط المسلمين على حكم أهل تلك الأديان، وقد حصل من هذا شيء كبير، وكفى بالله شهيداً.", "h": ["تقرير أن رؤيا الأنبياء حق.", "تعبير الرؤيا قد يتأخر سنة أو أكثر.", "مشروعية الحلق والتقصير للتحلّل من الحج أو العمرة، وأن الحلق أفضل لتقدّمه.", "مشروعية قول «إن شاء الله» في كل قول أو عمل يُراد به المستقبل."], "k": "«فعلم ما لم تعلموا»… كم صلح أو تأخير كرهته كان فيه خير لم أعلمه؟"}, {"lbl": "الآية ٢٩", "q": "مُّحَمَّدٞ رَّسُولُ ٱللَّهِۚ وَٱلَّذِينَ مَعَهُۥٓ أَشِدَّآءُ عَلَى ٱلۡكُفَّارِ رُحَمَآءُ بَيۡنَهُمۡۖ تَرَىٰهُمۡ رُكَّعٗا سُجَّدٗا يَبۡتَغُونَ فَضۡلٗا مِّنَ ٱللَّهِ وَرِضۡوَٰنٗاۖ سِيمَاهُمۡ فِي وُجُوهِهِم مِّنۡ أَثَرِ ٱلسُّجُودِۚ ذَٰلِكَ مَثَلُهُمۡ فِي ٱلتَّوۡرَىٰةِۚ وَمَثَلُهُمۡ فِي ٱلۡإِنجِيلِ كَزَرۡعٍ أَخۡرَجَ شَطۡـَٔهُۥ فَـَٔازَرَهُۥ فَٱسۡتَغۡلَظَ فَٱسۡتَوَىٰ عَلَىٰ سُوقِهِۦ يُعۡجِبُ ٱلزُّرَّاعَ لِيَغِيظَ بِهِمُ ٱلۡكُفَّارَۗ وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ مِنۡهُم مَّغۡفِرَةٗ وَأَجۡرًا عَظِيمَۢا ﴿٢٩﴾", "w": [["محمد رسول الله والذين معه", "أصحابه رضوان الله عليهم."], ["أشداء على الكفار", "غلاظ لا يرحمونهم."], ["رحماء بينهم", "متعاطفون متوادّون كالوالد مع الولد."], ["تراهم ركعاً سجداً", "تبصرهم راكعين ساجدين."], ["يبتغون فضلاً من الله ورضواناً", "يطلبون بالركوع والسجود ثواباً من ربهم هو الجنة، ورضواناً هو رضاه عز وجل."], ["سيماهم في وجوههم", "نور وبياض يُعرفون به يوم القيامة أنهم سجدوا في الدنيا."], ["مثلهم في التوراة", "صفتهم في التوراة كتاب موسى ﵇."], ["أخرج شطأه", "فراخه."], ["فآزره", "قوّاه وأعانه."], ["فاستغلظ فاستوى", "غلظ واستوى، أي قوي."], ["على سوقه", "جمع ساق، أي على أصوله."], ["يُعجب الزرّاع", "زارعيه لحسنه."], ["ليغيظ بهم الكفار", "قوّاهم وكثّرهم ليغيظ بهم الكفار."]], "m": "لما أخبر تعالى أنه أرسل رسوله بالهدى ودين الحق ليظهره على الدين كله أخبر عنه بما يؤكد تلك الشهادة: محمد رسول الله، والذين معه من أصحابه أشداء على الكفار، غلاظ عليهم لأمرين: أنهم كفروا بالله وعادوه والله يبغضهم لذلك، وأن الغلظة قد تكون سبباً في هدايتهم إذ يرون خلافها مع المسلمين فيُسلمون فيُرحمون. رحماء فيما بينهم يتعاطفون، يصافح أحدهم أخاه المسلم ويعانقه ويلاطفه ويعينه ويُظهر له الود. تراهم راكعين ساجدين في صلواتهم، يطلبون بصلاتهم بعد إيمانهم وتحابّهم فضلاً من ربهم ورضواناً، الجنة ورضا الله، وهذا أسمى ما يطلبه المؤمن. علامات إيمانهم وصفائهم في وجوههم من أثر السجود، إذ يُبعثون يوم القيامة غرّاً محجّلين من آثار الوضوء، وفي الدنيا عليهم سيما التقوى والصلاح والتواضع واللين والرحمة. ذلك المذكور صفتهم في التوراة، وصفتهم في الإنجيل كزرع أخرج فراخه فقوّاه فغلظ فقام على أصوله يعجب الزرّاع بحسنه، قوّاهم وكثّرهم ليغيظ بهم الكفار، ولذا ورد عن مالك بن أنس رحمه الله أن من يغيظه أصحاب رسول الله فهو كافر. وعد الله الذين آمنوا وعملوا الصالحات منهم مغفرة لذنوبهم وأجراً عظيماً هو الجنة؛ وهذا وعد خاص بأصحاب رسول الله، وهناك وعد عام لسائر المؤمنين والمؤمنات في آيات أخرى كآية المائدة.", "h": ["تقرير نبوة رسول الله ﷺ وتأكيد رسالته.", "بيان ما كان عليه رسول الله وأصحابه من الشدة والغلظة على الكفار والعطف والرحمة على أهل الإيمان، وهذا مما يجب الائتساء بهم فيه والاقتداء.", "بيان فضل الصلاة ذات الركوع والسجود والطمأنينة والخشوع.", "صفة أصحاب رسول الله في كل من التوراة والإنجيل ترفع من درجتهم.", "بيان أن أصحاب رسول الله ﷺ بدؤوا قليلين ثم أخذوا يكثرون حتى كثروا.", "بُغض أصحاب رسول الله ﷺ يتنافى مع الإيمان منافاة كاملة، لا سيما خيارهم وكبارهم كالخلفاء الراشدين الأربعة والمبشّرين بالجنة العشرة وأصحاب بيعة الرضوان وأهل بدر قبلهم، ولذا روي عن مالك رحمه الله تعالى أن من يغيظه أصحاب رسول الله ﷺ فهو كافر."], "k": "«رحماء بينهم»… هل يجد إخوتي عندي رحمة؟ وهل يُرى في وجهي أثر سجودي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 382;
insert into public.tdb_cards(topic, i, body) select 382, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيتان ٢٥ – ٢٦", "q": "هُمُ ٱلَّذِينَ كَفَرُواْ وَصَدُّوكُمۡ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ وَٱلۡهَدۡيَ مَعۡكُوفًا أَن يَبۡلُغَ مَحِلَّهُۥۚ وَلَوۡلَا رِجَالٞ مُّؤۡمِنُونَ وَنِسَآءٞ مُّؤۡمِنَٰتٞ لَّمۡ تَعۡلَمُوهُمۡ أَن تَطَـُٔوهُمۡ فَتُصِيبَكُم مِّنۡهُم مَّعَرَّةُۢ بِغَيۡرِ عِلۡمٖۖ لِّيُدۡخِلَ ٱللَّهُ فِي رَحۡمَتِهِۦ مَن يَشَآءُۚ لَوۡ تَزَيَّلُواْ لَعَذَّبۡنَا ٱلَّذِينَ كَفَرُواْ مِنۡهُمۡ عَذَابًا أَلِيمًا ﴿٢٥﴾ إِذۡ جَعَلَ ٱلَّذِينَ كَفَرُواْ فِي قُلُوبِهِمُ ٱلۡحَمِيَّةَ حَمِيَّةَ ٱلۡجَٰهِلِيَّةِ فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَىٰ رَسُولِهِۦ وَعَلَى ٱلۡمُؤۡمِنِينَ وَأَلۡزَمَهُمۡ كَلِمَةَ ٱلتَّقۡوَىٰ وَكَانُوٓاْ أَحَقَّ بِهَا وَأَهۡلَهَاۚ وَكَانَ ٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٗا ﴿٢٦﴾", "w": [["هم الذين كفروا وصدّوكم عن المسجد الحرام", "كفروا بالله ورسوله ومنعوكم من الوصول إلى المسجد الحرام."], ["والهدي معكوفاً أن يبلغ محلّه", "ومنعوا الهدي محبوساً أن يبلغ محلّه من الحرم."], ["ولولا رجال مؤمنون ونساء مؤمنات", "موجودون في مكة."], ["لم تعلموهم", "لم تعرفوهم مؤمنين ومؤمنات."], ["أن تطؤوهم", "قتلاً لهم عند قتالكم المشركين بمكة."], ["فتصيبكم منهم معرّة بغير علم", "إثم وديات قتل الخطأ وعتق أو صيام، لأذن لكم في الفتح."], ["ليُدخل الله في رحمته من يشاء", "لم يؤذن لكم في دخول مكة فاتحين ليدخل الله في الإسلام من يشاء."], ["لو تزيّلوا لعذّبنا الذين كفروا منهم", "لو تميّزوا فكان المؤمنون على حدة والكافرون على حدة لأذنّا لكم وعذّبنا الذين كفروا بأيديكم."], ["الحمية حمية الجاهلية", "الأنفة المانعة من قبول الحق، ولذا منعوا الرسول وأصحابه من دخول مكة."], ["فأنزل الله سكينته على رسوله وعلى المؤمنين", "همّ الصحابة أن يخالفوا أمر رسول الله بالصلح فأنزل الله سكينته عليهم فرضوا فتمّ الصلح."], ["وألزمهم كلمة التقوى", "ألزمهم كلمة لا إله إلا الله، إذ هي الواقية من الشرك."], ["وكانوا أحق بها وأهلها", "أجدر بكلمة التوحيد وأهلاً للتقوى."]], "m": "ما زال السياق في صلح الحديبية: هم الذين كفروا بالله ورسوله وصدّوكم عن المسجد الحرام أن تدخلوه وأنتم محرمون، وصدّوا الهدي محبوساً يُنتظر به دخول مكة لينحر. ولولا رجال مؤمنون ونساء مؤمنات بمكة لم تعرفوهم لأنهم كانوا يخفون إسلامهم، كراهة أن تقتلوهم أثناء قتالكم المشركين فتلحقكم التبعة وما يلزم من قتل المسلم خطأً من الكفارة والدية، لأذن لكم في دخول مكة فاتحين. لم يأذن لكم في القتال ورضي لكم بالصلح ليُدخل في رحمته من يشاء: فالمؤمنون نالتهم رحمته إذ لم يُؤذوا، والمشركون قد يكون تأخّر الفتح سبباً في إسلام من شاء الله منهم، لا سيما حين رأوا رحمة الإسلام تتجلى في ترك القتال رحمة بالمؤمنين. لو تميّز المؤمنون عن المشركين في مكان خاص بهم لأذنّا لكم في دخول مكة وعذّبنا الكافرين بأيديكم، إذ جعل الذين كفروا في قلوبهم الأنفة والتعاظم المانع من قبول الحق، وهي من صفات الجاهلية، فقالوا: كيف ندعهم يدخلون بلادنا وقد قتلوا أبناءنا؟ واللات والعزى ما دخلوها علينا أبداً. ولما همّ المؤمنون بعدم قبول الصلح لما فيه من التنازل الكبير أنزل الله سكينته عليهم، وهي الطمأنينة والوقار والحلم، فرضوا بالمصالحة، وكان فيها خير كثير حتى قيل: إنها فتح، أو فاتحة فتوحات لا حدّ لها. وأكرم المؤمنين بإلزامهم كلمة لا إله إلا الله، كلمة التقوى الواقية من الشرك والعذاب، وجعلهم أحق بها وأهلها، وكان الله بكل شيء عليماً، ومن ذلك علمه بأهلية أصحاب رسول الله للإيمان والتقوى.", "h": ["بيان حكم المحصر، وهو من مُنع من دخول المسجد الحرام وهو محرم بحج أو بعمرة، فإنه يتحلّل بذبح هدي ويعود إلى بلاده، ويذبح الهدي حيث أُحصر.", "الأخذ بالحيطة في معاملة المسلمين حتى لا يُؤذى مؤمن أو مؤمنة بغير علم.", "بيان أن كلمة التقوى هي لا إله إلا الله.", "الإشارة إلى ما أصاب المسلمين من ألم نفسي من جرّاء الشروط القاسية التي اشترطها ممثل قريش في وثيقة الصلح."], "k": "«إذ جعل الذين كفروا في قلوبهم الحمية حمية الجاهلية»… هل في أنفتي شيء من الجاهلية يمنعني من قبول حق؟"}, {"lbl": "الآيتان ٢٧ – ٢٨", "q": "لَّقَدۡ صَدَقَ ٱللَّهُ رَسُولَهُ ٱلرُّءۡيَا بِٱلۡحَقِّۖ لَتَدۡخُلُنَّ ٱلۡمَسۡجِدَ ٱلۡحَرَامَ إِن شَآءَ ٱللَّهُ ءَامِنِينَ مُحَلِّقِينَ رُءُوسَكُمۡ وَمُقَصِّرِينَ لَا تَخَافُونَۖ فَعَلِمَ مَا لَمۡ تَعۡلَمُواْ فَجَعَلَ مِن دُونِ ذَٰلِكَ فَتۡحٗا قَرِيبًا ﴿٢٧﴾ هُوَ ٱلَّذِيٓ أَرۡسَلَ رَسُولَهُۥ بِٱلۡهُدَىٰ وَدِينِ ٱلۡحَقِّ لِيُظۡهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦۚ وَكَفَىٰ بِٱللَّهِ شَهِيدٗا ﴿٢٨﴾", "w": [["لقد صدق الله رسوله الرؤيا بالحق", "جعل رؤيا رسوله التي رآها في النوم عام الحديبية حقاً."], ["لتدخلُنّ المسجد الحرام إن شاء الله", "هذا مضمون الرؤيا."], ["محلّقين رؤوسكم ومقصّرين", "حالقين جميع شعوركم أو مقصّرينها."], ["لا تخافون", "أبداً، حال الإحرام وبعده."], ["فعلم ما لم تعلموا", "في الصلح الذي تمّ، من المعرّة التي كانت تلحق المسلمين بقتال إخوانهم المؤمنين وهم لا يعلمون."], ["فجعل من دون ذلك فتحاً قريباً", "هو فتح خيبر، وتحققت الرؤيا في العام القابل."], ["هو الذي أرسل رسوله بالهدى", "فلذا لا يُخلفه رؤياه بل يصدقها."], ["ليُظهره على الدين كله", "ليُعليه على سائر الأديان بنسخ الحق فيها وإبطال الباطل، أو بتسليط المسلمين على أهلها فيحكمونهم."], ["وكفى بالله شهيداً", "على أنك مرسل بالهدى ودين الحق."]], "m": "ما زال السياق في صلح الحديبية: لقد صدق الله رسوله محمداً ﷺ الرؤيا التي رآها وأخبر بها أصحابه عند خروجهم من المدينة إلى مكة فسرّوا بها، ولما تم الصلح بعد جهاد سياسي وعسكري مرير وأمرهم الرسول أن ينحروا ويحلقوا اندهشوا، وقال بعضهم: أين الرؤيا التي رأيت؟ ونزلت سورة الفتح عند منصرفهم وفيها: لتدخلُنّ المسجد الحرام إن شاء الله آمنين محلّقين رؤوسكم ومقصّرين لا تخافون. فلما جاء العام القابل في نفس الأيام من ذي القعدة خرج رسول الله والمسلمون محرمين يلبّون، وأخلت لهم قريش المسجد الحرام، فطافوا وسعوا وتحلّلوا، فمنهم المحلّق ومنهم المقصّر. فعلم ما لم تعلموا فأثبت الصلح، لأنه لو كان قتال لهلك المؤمنون والمؤمنات بمكة بالحرب ولحقت المسلمين معرّة كبرى بقتل إخوانهم، وجعل من دون ذلك فتحاً قريباً: الصلح فتح، وفتح خيبر فتح، وفتح مكة فتح. هو الذي أرسل رسوله محمداً بالهدى ودين الحق، فكيف لا يصدقه رؤياه كما ظن البعض؟ ليظهره على الدين كله بنسخ الحق الذي فيه وإبطال الباطل الذي ألصق به، أو بتسليط المسلمين على حكم أهل تلك الأديان، وقد حصل من هذا شيء كبير، وكفى بالله شهيداً.", "h": ["تقرير أن رؤيا الأنبياء حق.", "تعبير الرؤيا قد يتأخر سنة أو أكثر.", "مشروعية الحلق والتقصير للتحلّل من الحج أو العمرة، وأن الحلق أفضل لتقدّمه.", "مشروعية قول «إن شاء الله» في كل قول أو عمل يُراد به المستقبل."], "k": "«فعلم ما لم تعلموا»… كم صلح أو تأخير كرهته كان فيه خير لم أعلمه؟"}, {"lbl": "الآية ٢٩", "q": "مُّحَمَّدٞ رَّسُولُ ٱللَّهِۚ وَٱلَّذِينَ مَعَهُۥٓ أَشِدَّآءُ عَلَى ٱلۡكُفَّارِ رُحَمَآءُ بَيۡنَهُمۡۖ تَرَىٰهُمۡ رُكَّعٗا سُجَّدٗا يَبۡتَغُونَ فَضۡلٗا مِّنَ ٱللَّهِ وَرِضۡوَٰنٗاۖ سِيمَاهُمۡ فِي وُجُوهِهِم مِّنۡ أَثَرِ ٱلسُّجُودِۚ ذَٰلِكَ مَثَلُهُمۡ فِي ٱلتَّوۡرَىٰةِۚ وَمَثَلُهُمۡ فِي ٱلۡإِنجِيلِ كَزَرۡعٍ أَخۡرَجَ شَطۡـَٔهُۥ فَـَٔازَرَهُۥ فَٱسۡتَغۡلَظَ فَٱسۡتَوَىٰ عَلَىٰ سُوقِهِۦ يُعۡجِبُ ٱلزُّرَّاعَ لِيَغِيظَ بِهِمُ ٱلۡكُفَّارَۗ وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ مِنۡهُم مَّغۡفِرَةٗ وَأَجۡرًا عَظِيمَۢا ﴿٢٩﴾", "w": [["محمد رسول الله والذين معه", "أصحابه رضوان الله عليهم."], ["أشداء على الكفار", "غلاظ لا يرحمونهم."], ["رحماء بينهم", "متعاطفون متوادّون كالوالد مع الولد."], ["تراهم ركعاً سجداً", "تبصرهم راكعين ساجدين."], ["يبتغون فضلاً من الله ورضواناً", "يطلبون بالركوع والسجود ثواباً من ربهم هو الجنة، ورضواناً هو رضاه عز وجل."], ["سيماهم في وجوههم", "نور وبياض يُعرفون به يوم القيامة أنهم سجدوا في الدنيا."], ["مثلهم في التوراة", "صفتهم في التوراة كتاب موسى ﵇."], ["أخرج شطأه", "فراخه."], ["فآزره", "قوّاه وأعانه."], ["فاستغلظ فاستوى", "غلظ واستوى، أي قوي."], ["على سوقه", "جمع ساق، أي على أصوله."], ["يُعجب الزرّاع", "زارعيه لحسنه."], ["ليغيظ بهم الكفار", "قوّاهم وكثّرهم ليغيظ بهم الكفار."]], "m": "لما أخبر تعالى أنه أرسل رسوله بالهدى ودين الحق ليظهره على الدين كله أخبر عنه بما يؤكد تلك الشهادة: محمد رسول الله، والذين معه من أصحابه أشداء على الكفار، غلاظ عليهم لأمرين: أنهم كفروا بالله وعادوه والله يبغضهم لذلك، وأن الغلظة قد تكون سبباً في هدايتهم إذ يرون خلافها مع المسلمين فيُسلمون فيُرحمون. رحماء فيما بينهم يتعاطفون، يصافح أحدهم أخاه المسلم ويعانقه ويلاطفه ويعينه ويُظهر له الود. تراهم راكعين ساجدين في صلواتهم، يطلبون بصلاتهم بعد إيمانهم وتحابّهم فضلاً من ربهم ورضواناً، الجنة ورضا الله، وهذا أسمى ما يطلبه المؤمن. علامات إيمانهم وصفائهم في وجوههم من أثر السجود، إذ يُبعثون يوم القيامة غرّاً محجّلين من آثار الوضوء، وفي الدنيا عليهم سيما التقوى والصلاح والتواضع واللين والرحمة. ذلك المذكور صفتهم في التوراة، وصفتهم في الإنجيل كزرع أخرج فراخه فقوّاه فغلظ فقام على أصوله يعجب الزرّاع بحسنه، قوّاهم وكثّرهم ليغيظ بهم الكفار، ولذا ورد عن مالك بن أنس رحمه الله أن من يغيظه أصحاب رسول الله فهو كافر. وعد الله الذين آمنوا وعملوا الصالحات منهم مغفرة لذنوبهم وأجراً عظيماً هو الجنة؛ وهذا وعد خاص بأصحاب رسول الله، وهناك وعد عام لسائر المؤمنين والمؤمنات في آيات أخرى كآية المائدة.", "h": ["تقرير نبوة رسول الله ﷺ وتأكيد رسالته.", "بيان ما كان عليه رسول الله وأصحابه من الشدة والغلظة على الكفار والعطف والرحمة على أهل الإيمان، وهذا مما يجب الائتساء بهم فيه والاقتداء.", "بيان فضل الصلاة ذات الركوع والسجود والطمأنينة والخشوع.", "صفة أصحاب رسول الله في كل من التوراة والإنجيل ترفع من درجتهم.", "بيان أن أصحاب رسول الله ﷺ بدؤوا قليلين ثم أخذوا يكثرون حتى كثروا.", "بُغض أصحاب رسول الله ﷺ يتنافى مع الإيمان منافاة كاملة، لا سيما خيارهم وكبارهم كالخلفاء الراشدين الأربعة والمبشّرين بالجنة العشرة وأصحاب بيعة الرضوان وأهل بدر قبلهم، ولذا روي عن مالك رحمه الله تعالى أن من يغيظه أصحاب رسول الله ﷺ فهو كافر."], "k": "«رحماء بينهم»… هل يجد إخوتي عندي رحمة؟ وهل يُرى في وجهي أثر سجودي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (383, 49, 1, 8, 'سورة الحجرات ١ – ٨', 'الحجرات: لا تقدّموا بين يدي الله ورسوله', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 383) = $j$[{"lbl": "الآيات ١ – ٣", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُقَدِّمُواْ بَيۡنَ يَدَيِ ٱللَّهِ وَرَسُولِهِۦۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ ﴿١﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَرۡفَعُوٓاْ أَصۡوَٰتَكُمۡ فَوۡقَ صَوۡتِ ٱلنَّبِيِّ وَلَا تَجۡهَرُواْ لَهُۥ بِٱلۡقَوۡلِ كَجَهۡرِ بَعۡضِكُمۡ لِبَعۡضٍ أَن تَحۡبَطَ أَعۡمَٰلُكُمۡ وَأَنتُمۡ لَا تَشۡعُرُونَ ﴿٢﴾ إِنَّ ٱلَّذِينَ يَغُضُّونَ أَصۡوَٰتَهُمۡ عِندَ رَسُولِ ٱللَّهِ أُوْلَـٰٓئِكَ ٱلَّذِينَ ٱمۡتَحَنَ ٱللَّهُ قُلُوبَهُمۡ لِلتَّقۡوَىٰۚ لَهُم مَّغۡفِرَةٞ وَأَجۡرٌ عَظِيمٌ ﴿٣﴾", "w": [["لا تقدّموا", "لا تتقدّموا بقول ولا فعل."], ["بين يدي الله ورسوله", "كمن ذبح يوم العيد قبل أن يذبح رسول الله ﷺ، وكإرادة أحد الشيخين تأمير رجل على قوم قبل استشارة الرسول ﷺ."], ["واتقوا الله إن الله سميع عليم", "خافوا الله، إنه سميع لأقوالكم عليم بأعمالكم."], ["لا ترفعوا أصواتكم فوق صوت النبي", "إذا نطقتم فوق صوت النبي إذا نطق."], ["ولا تجهروا له بالقول كجهر بعضكم لبعض", "إذا ناجيتموه فلا تجهروا كما تجهرون فيما بينكم، إجلالاً له ﷺ وتوقيراً."], ["أن تحبط أعمالكم", "كراهة أن تبطل أعمالكم فلا تُثابوا عليها."], ["وأنتم لا تشعرون", "بحبوطها، إذ قد يصحب ذلك استخفاف بالنبي ﷺ وعدم مبالاة فهو الكفر."], ["يغضّون أصواتهم عند رسول الله", "يخفضونها حتى لكأنهم يسارّونه، ومنهم أبو بكر رضي الله عنه."], ["امتحن الله قلوبهم للتقوى", "شرحها ووسّعها لتتحمّل تقوى الله."], ["لهم مغفرة وأجر عظيم", "مغفرة لذنوبهم، وأجر عظيم هو الجنة."]], "m": "المناسبة بين هذه السورة والتي قبلها تتجلّى إذا رجعنا إلى موقف عمر رضي الله عنه وهو يريد ألا يتم الصلح، وإلى موقف الصحابة من عدم التحلّل ونحر هداياهم والرسول يأمرهم حتى تقدّمهم ﷺ فنحر ثم نحروا؛ فتلك المواقف فيها معنى تقديم الرأي بين يدي الله ورسوله. فلما انتهت تلك الحال أنزل الله: يا أيها الذين آمنوا بالله رباً وبالإسلام ديناً وبمحمد رسولاً، لا تقدّموا بين يدي الله ورسوله قولاً ولا عملاً ولا رأياً، أي لا تقولوا ولا تعملوا إلا تبعاً لما قال الله ورسوله وشرعاه، واتقوا الله، فإن التقدم بالشيء قبل أن يشرعه الله ورسوله فيه معنى أنكم أعلم وأحكم من الله ورسوله، وهذه زلة كبرى. فواجب المسلم ألا يقول ولا يعمل ولا يقضي ولا يفتي برأيه إلا إذا علم قول الله ورسوله، فإذا لم يجد اجتهد فقال أو عمل بما يراه أقرب إلى رضا الله، فإذا لاح له بعد ذلك نص من كتاب أو سنة عدل عن رأيه إليه. ثم طالبهم بالتأدب مع رسول الله ﷺ: لا ترفعوا أصواتكم فوق صوته إذا تحدّثتم معه، بل يكون صوت أحدكم أخفض من صوت الرسول، وقد كان أبو بكر إذا كلّم رسول الله يسارّه الكلام مسارّة، ولا تجهروا له بالقول إذا ناجيتموه كجهر بعضكم لبعض، خشية أن تحبط أعمالكم كما تحبط بالشرك وأنتم لا تشعرون، إذ رفع الصوت على الرسول ونداؤه بأعلى الصوت إذا صاحبه استخفاف أو إهانة صار كفراً محبطاً للعمل قطعاً. ثم أثنى على الذين يخفضون أصواتهم في حضرته كأبي بكر وعمر رضي الله عنهما، أولئك الذين وسّع الله قلوبهم وشرحها لتتحمّل التقوى، والرسول ﷺ يقول: «التقوى ها هنا» ويشير إلى صدره ثلاثاً، لهم مغفرة لذنوبهم وأجر عظيم هو الجنة.", "h": ["لا يجوز للمسلم أن يقدّم رأيه أو اجتهاده على الكتاب والسنة، فلا رأي ولا اجتهاد إلا عند عدم وجود نص من كتاب أو سنة، وعليه إذا اجتهد أن يكون ما اجتهد فيه أقرب إلى مراد الله ورسوله، أي ألصق بالشرع، وإن ظهر له بعد الاجتهاد نص من كتاب أو سنة عاد إلى الكتاب والسنة وترك رأيه أو اجتهاده فوراً وبلا تردد.", "بما أن الله تعالى قد قبض إليه نبيه، ولم يبق بيننا رسول الله نتكلم معه أو نناجيه فنخفض أصواتنا عند ذلك، فإن علينا إذا ذُكر رسول الله بيننا أو ذُكر حديثه أن نتأدب عند ذلك، فلا نضحك ولا نرفع الصوت ولا نُظهر أي استخفاف أو عدم مبالاة، وإلا يُخشى علينا أن تحبط أعمالنا.", "على الذين يغشون مسجد رسول الله ﷺ ألا يرفعوا أصواتهم فيه إلا لضرورة درس أو خطبة أو أذان أو إقامة."], "k": "«لا تقدّموا بين يدي الله ورسوله»… في أي مسألة أقدّم رأيي قبل أن أعرف حكم الله فيها؟"}, {"lbl": "الآيات ٤ – ٨", "q": "إِنَّ ٱلَّذِينَ يُنَادُونَكَ مِن وَرَآءِ ٱلۡحُجُرَٰتِ أَكۡثَرُهُمۡ لَا يَعۡقِلُونَ ﴿٤﴾ وَلَوۡ أَنَّهُمۡ صَبَرُواْ حَتَّىٰ تَخۡرُجَ إِلَيۡهِمۡ لَكَانَ خَيۡرٗا لَّهُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ﴿٥﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن جَآءَكُمۡ فَاسِقُۢ بِنَبَإٖ فَتَبَيَّنُوٓاْ أَن تُصِيبُواْ قَوۡمَۢا بِجَهَٰلَةٖ فَتُصۡبِحُواْ عَلَىٰ مَا فَعَلۡتُمۡ نَٰدِمِينَ ﴿٦﴾ وَٱعۡلَمُوٓاْ أَنَّ فِيكُمۡ رَسُولَ ٱللَّهِۚ لَوۡ يُطِيعُكُمۡ فِي كَثِيرٖ مِّنَ ٱلۡأَمۡرِ لَعَنِتُّمۡ وَلَٰكِنَّ ٱللَّهَ حَبَّبَ إِلَيۡكُمُ ٱلۡإِيمَٰنَ وَزَيَّنَهُۥ فِي قُلُوبِكُمۡ وَكَرَّهَ إِلَيۡكُمُ ٱلۡكُفۡرَ وَٱلۡفُسُوقَ وَٱلۡعِصۡيَانَۚ أُوْلَـٰٓئِكَ هُمُ ٱلرَّـٰشِدُونَ ﴿٧﴾ فَضۡلٗا مِّنَ ٱللَّهِ وَنِعۡمَةٗۚ وَٱللَّهُ عَلِيمٌ حَكِيمٞ ﴿٨﴾", "w": [["إن الذين ينادونك من وراء الحجرات", "حجرات نسائه، والذين نادوه وفد من أعراب بني تميم منهم الزبرقان بن بدر والأقرع بن حابس وعيينة بن حصن."], ["أكثرهم لا يعقلون", "فيما فعلوه بمحلّك الرفيع ومقامك الشريف."], ["ولو أنهم صبروا حتى تخرج إليهم", "لو انتظروك حتى تخرج بعد قيامك من قيلولتك."], ["لكان خيراً لهم", "من ذلك النداء بأعلى أصواتهم من كل أبواب الحجرات."], ["والله غفور رحيم", "غفور لمن تاب منهم رحيم بهم."], ["فاسق بنبأ", "ذو فسق، وهو المرتكب لكبيرة، والنبأ الخبر."], ["فتبيّنوا", "تثبّتوا قبل أن تقولوا أو تفعلوا أو تحكموا."], ["أن تصيبوا قوماً بجهالة", "خشية إصابة قوم بجهالة منكم."], ["فتصبحوا على ما فعلتم نادمين", "فتصيروا على فعلكم الخاطئ نادمين."], ["واعلموا أن فيكم رسول الله", "فاحذروا أن تكذبوا أو تقولوا الباطل فإن الوحي ينزل فتُفضحون."], ["لو يطيعكم في كثير من الأمر لعنتّم", "لوقعتم في المشقة الشديدة والإثم أحياناً."], ["وكرّه إليكم الكفر والفسوق والعصيان", "بغّض إلى قلوبكم الكفر، والفسوق كالكذب، والعصيان بترك واجب أو فعل محرم."], ["أولئك هم الراشدون", "السالكون سبيل الرشاد."], ["فضلاً من الله ونعمة", "أفضل بذلك عليهم فضلاً وأنعم إنعاماً."], ["والله عليم حكيم", "عليم بخلقه وما يعملون، حكيم في تدبيره لعباده."]], "m": "ما زال السياق في تأديب المؤمنين إزاء نبيهم ﷺ: عاب تعالى أقواماً معهم جفاء وغلظة، وفد من أعراب بني تميم جاؤوا والرسول قائل وقت القيلولة، فوقفوا على أبواب الحجرات، وكانت إلى المسجد، ينادون بأعلى أصواتهم: يا محمد، اخرج إلينا فإن مدحنا زين وذمّنا شين، فنزلت تأديباً لهم: إن الذين ينادونك من وراء الحجرات أكثرهم لا يعقلون مقام الرسول الشريف، ولو أنهم صبروا حتى تخرج إليهم بعد قيامك من قيلولتك لكان خيراً لهم، والله غفور لمن تاب منهم رحيم بهم إذ لم يعجّل لهم العقوبة وأدّبهم ولم يعنّف. وآية: إن جاءكم فاسق بنبأ فتبيّنوا، وإن كان لها سبب نزول، وهو أن النبي ﷺ بعث الوليد بن عقبة إلى بني المصطلق ليأتي بزكاتهم، وكان بينهم وبين أسرته عداء في الجاهلية، فهاب أن يدخل عليهم، فرجع وذكر أنهم منعوه الزكاة وهمّوا بقتله، فهمّ رسول الله بغزوهم، حتى أتى وفد منهم يخبرونه أنهم على العهد وأن الوليد رجع من الطريق، وبعث خالد بن الوليد فوجدهم يؤذّنون ويصلّون، فإنها عامة وقاعدة أساسية: على الفرد والجماعة والدولة ألا يقبلوا الأخبار ولا يعملوا بمقتضاها إلا بعد التثبّت، كراهية أن يصيبوا أحداً بسوء بغير موجب، صوناً لكرامة الأفراد وحماية لأرواحهم وأموالهم. واعلموا أن فيكم رسول الله حياً ينزل عليه الوحي، فالتزموا الصدق وإلا فضحكم الوحي كما فضح الوليد، ولو كان يطيعكم في كل ما ترونه وتقترحونه لوقعتم في مشاق وآثام، ولكن الله حبّب إليكم الإيمان وزيّنه في قلوبكم وكرّه إليكم الكفر والفسوق والعصيان، فوقاكم كثيراً من أن تكذبوا على رسولكم أو تفرضوا آراءكم، أولئك أصحاب رسول الله هم الراشدون، فضلاً من الله ونعمة، فهم أفضل هذه الأمة على الإطلاق، ولا مطمع لأحد بعدهم أن يفوقهم في الفضل والكمال، فرضي الله عنهم أجمعين.", "h": ["بيان سموّ المقام المحمدي وشرف منزلته ﷺ.", "وجوب التثبّت في الأخبار ذات الشأن التي قد يترتب عليها أذى أو ضرر بمن قيلت فيه، وحرمة التسرّع المفضي بالأخذ بالظنّة فيندم الفاعل بعد ذلك في الدنيا والآخرة.", "من أكبر النعم على المؤمن تحبيب الله تعالى الإيمان إليه وتزيينه في قلبه، وتكريه الكفر والفسوق والعصيان إليه، وبذلك أصبح المؤمن أرشد الخلق بعد أصحاب رسول الله ﷺ."], "k": "«إن جاءكم فاسق بنبأ فتبيّنوا»… كم رسالة أنقلها قبل أن أتثبّت منها؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 383;
insert into public.tdb_cards(topic, i, body) select 383, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٣", "q": "يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تُقَدِّمُواْ بَيۡنَ يَدَيِ ٱللَّهِ وَرَسُولِهِۦۖ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ سَمِيعٌ عَلِيمٞ ﴿١﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَرۡفَعُوٓاْ أَصۡوَٰتَكُمۡ فَوۡقَ صَوۡتِ ٱلنَّبِيِّ وَلَا تَجۡهَرُواْ لَهُۥ بِٱلۡقَوۡلِ كَجَهۡرِ بَعۡضِكُمۡ لِبَعۡضٍ أَن تَحۡبَطَ أَعۡمَٰلُكُمۡ وَأَنتُمۡ لَا تَشۡعُرُونَ ﴿٢﴾ إِنَّ ٱلَّذِينَ يَغُضُّونَ أَصۡوَٰتَهُمۡ عِندَ رَسُولِ ٱللَّهِ أُوْلَـٰٓئِكَ ٱلَّذِينَ ٱمۡتَحَنَ ٱللَّهُ قُلُوبَهُمۡ لِلتَّقۡوَىٰۚ لَهُم مَّغۡفِرَةٞ وَأَجۡرٌ عَظِيمٌ ﴿٣﴾", "w": [["لا تقدّموا", "لا تتقدّموا بقول ولا فعل."], ["بين يدي الله ورسوله", "كمن ذبح يوم العيد قبل أن يذبح رسول الله ﷺ، وكإرادة أحد الشيخين تأمير رجل على قوم قبل استشارة الرسول ﷺ."], ["واتقوا الله إن الله سميع عليم", "خافوا الله، إنه سميع لأقوالكم عليم بأعمالكم."], ["لا ترفعوا أصواتكم فوق صوت النبي", "إذا نطقتم فوق صوت النبي إذا نطق."], ["ولا تجهروا له بالقول كجهر بعضكم لبعض", "إذا ناجيتموه فلا تجهروا كما تجهرون فيما بينكم، إجلالاً له ﷺ وتوقيراً."], ["أن تحبط أعمالكم", "كراهة أن تبطل أعمالكم فلا تُثابوا عليها."], ["وأنتم لا تشعرون", "بحبوطها، إذ قد يصحب ذلك استخفاف بالنبي ﷺ وعدم مبالاة فهو الكفر."], ["يغضّون أصواتهم عند رسول الله", "يخفضونها حتى لكأنهم يسارّونه، ومنهم أبو بكر رضي الله عنه."], ["امتحن الله قلوبهم للتقوى", "شرحها ووسّعها لتتحمّل تقوى الله."], ["لهم مغفرة وأجر عظيم", "مغفرة لذنوبهم، وأجر عظيم هو الجنة."]], "m": "المناسبة بين هذه السورة والتي قبلها تتجلّى إذا رجعنا إلى موقف عمر رضي الله عنه وهو يريد ألا يتم الصلح، وإلى موقف الصحابة من عدم التحلّل ونحر هداياهم والرسول يأمرهم حتى تقدّمهم ﷺ فنحر ثم نحروا؛ فتلك المواقف فيها معنى تقديم الرأي بين يدي الله ورسوله. فلما انتهت تلك الحال أنزل الله: يا أيها الذين آمنوا بالله رباً وبالإسلام ديناً وبمحمد رسولاً، لا تقدّموا بين يدي الله ورسوله قولاً ولا عملاً ولا رأياً، أي لا تقولوا ولا تعملوا إلا تبعاً لما قال الله ورسوله وشرعاه، واتقوا الله، فإن التقدم بالشيء قبل أن يشرعه الله ورسوله فيه معنى أنكم أعلم وأحكم من الله ورسوله، وهذه زلة كبرى. فواجب المسلم ألا يقول ولا يعمل ولا يقضي ولا يفتي برأيه إلا إذا علم قول الله ورسوله، فإذا لم يجد اجتهد فقال أو عمل بما يراه أقرب إلى رضا الله، فإذا لاح له بعد ذلك نص من كتاب أو سنة عدل عن رأيه إليه. ثم طالبهم بالتأدب مع رسول الله ﷺ: لا ترفعوا أصواتكم فوق صوته إذا تحدّثتم معه، بل يكون صوت أحدكم أخفض من صوت الرسول، وقد كان أبو بكر إذا كلّم رسول الله يسارّه الكلام مسارّة، ولا تجهروا له بالقول إذا ناجيتموه كجهر بعضكم لبعض، خشية أن تحبط أعمالكم كما تحبط بالشرك وأنتم لا تشعرون، إذ رفع الصوت على الرسول ونداؤه بأعلى الصوت إذا صاحبه استخفاف أو إهانة صار كفراً محبطاً للعمل قطعاً. ثم أثنى على الذين يخفضون أصواتهم في حضرته كأبي بكر وعمر رضي الله عنهما، أولئك الذين وسّع الله قلوبهم وشرحها لتتحمّل التقوى، والرسول ﷺ يقول: «التقوى ها هنا» ويشير إلى صدره ثلاثاً، لهم مغفرة لذنوبهم وأجر عظيم هو الجنة.", "h": ["لا يجوز للمسلم أن يقدّم رأيه أو اجتهاده على الكتاب والسنة، فلا رأي ولا اجتهاد إلا عند عدم وجود نص من كتاب أو سنة، وعليه إذا اجتهد أن يكون ما اجتهد فيه أقرب إلى مراد الله ورسوله، أي ألصق بالشرع، وإن ظهر له بعد الاجتهاد نص من كتاب أو سنة عاد إلى الكتاب والسنة وترك رأيه أو اجتهاده فوراً وبلا تردد.", "بما أن الله تعالى قد قبض إليه نبيه، ولم يبق بيننا رسول الله نتكلم معه أو نناجيه فنخفض أصواتنا عند ذلك، فإن علينا إذا ذُكر رسول الله بيننا أو ذُكر حديثه أن نتأدب عند ذلك، فلا نضحك ولا نرفع الصوت ولا نُظهر أي استخفاف أو عدم مبالاة، وإلا يُخشى علينا أن تحبط أعمالنا.", "على الذين يغشون مسجد رسول الله ﷺ ألا يرفعوا أصواتهم فيه إلا لضرورة درس أو خطبة أو أذان أو إقامة."], "k": "«لا تقدّموا بين يدي الله ورسوله»… في أي مسألة أقدّم رأيي قبل أن أعرف حكم الله فيها؟"}, {"lbl": "الآيات ٤ – ٨", "q": "إِنَّ ٱلَّذِينَ يُنَادُونَكَ مِن وَرَآءِ ٱلۡحُجُرَٰتِ أَكۡثَرُهُمۡ لَا يَعۡقِلُونَ ﴿٤﴾ وَلَوۡ أَنَّهُمۡ صَبَرُواْ حَتَّىٰ تَخۡرُجَ إِلَيۡهِمۡ لَكَانَ خَيۡرٗا لَّهُمۡۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ ﴿٥﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِن جَآءَكُمۡ فَاسِقُۢ بِنَبَإٖ فَتَبَيَّنُوٓاْ أَن تُصِيبُواْ قَوۡمَۢا بِجَهَٰلَةٖ فَتُصۡبِحُواْ عَلَىٰ مَا فَعَلۡتُمۡ نَٰدِمِينَ ﴿٦﴾ وَٱعۡلَمُوٓاْ أَنَّ فِيكُمۡ رَسُولَ ٱللَّهِۚ لَوۡ يُطِيعُكُمۡ فِي كَثِيرٖ مِّنَ ٱلۡأَمۡرِ لَعَنِتُّمۡ وَلَٰكِنَّ ٱللَّهَ حَبَّبَ إِلَيۡكُمُ ٱلۡإِيمَٰنَ وَزَيَّنَهُۥ فِي قُلُوبِكُمۡ وَكَرَّهَ إِلَيۡكُمُ ٱلۡكُفۡرَ وَٱلۡفُسُوقَ وَٱلۡعِصۡيَانَۚ أُوْلَـٰٓئِكَ هُمُ ٱلرَّـٰشِدُونَ ﴿٧﴾ فَضۡلٗا مِّنَ ٱللَّهِ وَنِعۡمَةٗۚ وَٱللَّهُ عَلِيمٌ حَكِيمٞ ﴿٨﴾", "w": [["إن الذين ينادونك من وراء الحجرات", "حجرات نسائه، والذين نادوه وفد من أعراب بني تميم منهم الزبرقان بن بدر والأقرع بن حابس وعيينة بن حصن."], ["أكثرهم لا يعقلون", "فيما فعلوه بمحلّك الرفيع ومقامك الشريف."], ["ولو أنهم صبروا حتى تخرج إليهم", "لو انتظروك حتى تخرج بعد قيامك من قيلولتك."], ["لكان خيراً لهم", "من ذلك النداء بأعلى أصواتهم من كل أبواب الحجرات."], ["والله غفور رحيم", "غفور لمن تاب منهم رحيم بهم."], ["فاسق بنبأ", "ذو فسق، وهو المرتكب لكبيرة، والنبأ الخبر."], ["فتبيّنوا", "تثبّتوا قبل أن تقولوا أو تفعلوا أو تحكموا."], ["أن تصيبوا قوماً بجهالة", "خشية إصابة قوم بجهالة منكم."], ["فتصبحوا على ما فعلتم نادمين", "فتصيروا على فعلكم الخاطئ نادمين."], ["واعلموا أن فيكم رسول الله", "فاحذروا أن تكذبوا أو تقولوا الباطل فإن الوحي ينزل فتُفضحون."], ["لو يطيعكم في كثير من الأمر لعنتّم", "لوقعتم في المشقة الشديدة والإثم أحياناً."], ["وكرّه إليكم الكفر والفسوق والعصيان", "بغّض إلى قلوبكم الكفر، والفسوق كالكذب، والعصيان بترك واجب أو فعل محرم."], ["أولئك هم الراشدون", "السالكون سبيل الرشاد."], ["فضلاً من الله ونعمة", "أفضل بذلك عليهم فضلاً وأنعم إنعاماً."], ["والله عليم حكيم", "عليم بخلقه وما يعملون، حكيم في تدبيره لعباده."]], "m": "ما زال السياق في تأديب المؤمنين إزاء نبيهم ﷺ: عاب تعالى أقواماً معهم جفاء وغلظة، وفد من أعراب بني تميم جاؤوا والرسول قائل وقت القيلولة، فوقفوا على أبواب الحجرات، وكانت إلى المسجد، ينادون بأعلى أصواتهم: يا محمد، اخرج إلينا فإن مدحنا زين وذمّنا شين، فنزلت تأديباً لهم: إن الذين ينادونك من وراء الحجرات أكثرهم لا يعقلون مقام الرسول الشريف، ولو أنهم صبروا حتى تخرج إليهم بعد قيامك من قيلولتك لكان خيراً لهم، والله غفور لمن تاب منهم رحيم بهم إذ لم يعجّل لهم العقوبة وأدّبهم ولم يعنّف. وآية: إن جاءكم فاسق بنبأ فتبيّنوا، وإن كان لها سبب نزول، وهو أن النبي ﷺ بعث الوليد بن عقبة إلى بني المصطلق ليأتي بزكاتهم، وكان بينهم وبين أسرته عداء في الجاهلية، فهاب أن يدخل عليهم، فرجع وذكر أنهم منعوه الزكاة وهمّوا بقتله، فهمّ رسول الله بغزوهم، حتى أتى وفد منهم يخبرونه أنهم على العهد وأن الوليد رجع من الطريق، وبعث خالد بن الوليد فوجدهم يؤذّنون ويصلّون، فإنها عامة وقاعدة أساسية: على الفرد والجماعة والدولة ألا يقبلوا الأخبار ولا يعملوا بمقتضاها إلا بعد التثبّت، كراهية أن يصيبوا أحداً بسوء بغير موجب، صوناً لكرامة الأفراد وحماية لأرواحهم وأموالهم. واعلموا أن فيكم رسول الله حياً ينزل عليه الوحي، فالتزموا الصدق وإلا فضحكم الوحي كما فضح الوليد، ولو كان يطيعكم في كل ما ترونه وتقترحونه لوقعتم في مشاق وآثام، ولكن الله حبّب إليكم الإيمان وزيّنه في قلوبكم وكرّه إليكم الكفر والفسوق والعصيان، فوقاكم كثيراً من أن تكذبوا على رسولكم أو تفرضوا آراءكم، أولئك أصحاب رسول الله هم الراشدون، فضلاً من الله ونعمة، فهم أفضل هذه الأمة على الإطلاق، ولا مطمع لأحد بعدهم أن يفوقهم في الفضل والكمال، فرضي الله عنهم أجمعين.", "h": ["بيان سموّ المقام المحمدي وشرف منزلته ﷺ.", "وجوب التثبّت في الأخبار ذات الشأن التي قد يترتب عليها أذى أو ضرر بمن قيلت فيه، وحرمة التسرّع المفضي بالأخذ بالظنّة فيندم الفاعل بعد ذلك في الدنيا والآخرة.", "من أكبر النعم على المؤمن تحبيب الله تعالى الإيمان إليه وتزيينه في قلبه، وتكريه الكفر والفسوق والعصيان إليه، وبذلك أصبح المؤمن أرشد الخلق بعد أصحاب رسول الله ﷺ."], "k": "«إن جاءكم فاسق بنبأ فتبيّنوا»… كم رسالة أنقلها قبل أن أتثبّت منها؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (384, 49, 9, 18, 'سورة الحجرات ٩ – ١٨', 'الحجرات: إنما المؤمنون إخوة', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 384) = $j$[{"lbl": "الآيات ٩ – ١٣", "q": "وَإِن طَآئِفَتَانِ مِنَ ٱلۡمُؤۡمِنِينَ ٱقۡتَتَلُواْ فَأَصۡلِحُواْ بَيۡنَهُمَاۖ فَإِنۢ بَغَتۡ إِحۡدَىٰهُمَا عَلَى ٱلۡأُخۡرَىٰ فَقَٰتِلُواْ ٱلَّتِي تَبۡغِي حَتَّىٰ تَفِيٓءَ إِلَىٰٓ أَمۡرِ ٱللَّهِۚ فَإِن فَآءَتۡ فَأَصۡلِحُواْ بَيۡنَهُمَا بِٱلۡعَدۡلِ وَأَقۡسِطُوٓاْۖ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُقۡسِطِينَ ﴿٩﴾ إِنَّمَا ٱلۡمُؤۡمِنُونَ إِخۡوَةٞ فَأَصۡلِحُواْ بَيۡنَ أَخَوَيۡكُمۡۚ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُرۡحَمُونَ ﴿١٠﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا يَسۡخَرۡ قَوۡمٞ مِّن قَوۡمٍ عَسَىٰٓ أَن يَكُونُواْ خَيۡرٗا مِّنۡهُمۡ وَلَا نِسَآءٞ مِّن نِّسَآءٍ عَسَىٰٓ أَن يَكُنَّ خَيۡرٗا مِّنۡهُنَّۖ وَلَا تَلۡمِزُوٓاْ أَنفُسَكُمۡ وَلَا تَنَابَزُواْ بِٱلۡأَلۡقَٰبِۖ بِئۡسَ ٱلِٱسۡمُ ٱلۡفُسُوقُ بَعۡدَ ٱلۡإِيمَٰنِۚ وَمَن لَّمۡ يَتُبۡ فَأُوْلَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ ﴿١١﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱجۡتَنِبُواْ كَثِيرٗا مِّنَ ٱلظَّنِّ إِنَّ بَعۡضَ ٱلظَّنِّ إِثۡمٞۖ وَلَا تَجَسَّسُواْ وَلَا يَغۡتَب بَّعۡضُكُم بَعۡضًاۚ أَيُحِبُّ أَحَدُكُمۡ أَن يَأۡكُلَ لَحۡمَ أَخِيهِ مَيۡتٗا فَكَرِهۡتُمُوهُۚ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ تَوَّابٞ رَّحِيمٞ ﴿١٢﴾ يَـٰٓأَيُّهَا ٱلنَّاسُ إِنَّا خَلَقۡنَٰكُم مِّن ذَكَرٖ وَأُنثَىٰ وَجَعَلۡنَٰكُمۡ شُعُوبٗا وَقَبَآئِلَ لِتَعَارَفُوٓاْۚ إِنَّ أَكۡرَمَكُمۡ عِندَ ٱللَّهِ أَتۡقَىٰكُمۡۚ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرٞ ﴿١٣﴾", "w": [["وإن طائفتان من المؤمنين", "جماعتان من المسلمين، قلّ أفرادهما أو كثروا."], ["اقتتلوا فأصلحوا بينهما", "همّوا بالاقتتال أو باشروه فعلاً، فأصلحوا ما فسد بينهما."], ["فإن بغت إحداهما على الأخرى", "تعدّت بعد المصالحة بأن رفضت ذلك ولم ترضَ بحكم الله."], ["فقاتلوا التي تبغي حتى تفيء إلى أمر الله", "قاتلوا مجتمعين الطائفة التي بغت حتى ترجع إلى الحق."], ["فإن فاءت فأصلحوا بينهما بالعدل", "رجعت إلى الحق بعد مقاتلتها فأصلحوا بينهما بالحق."], ["وأقسطوا إن الله يحب المقسطين", "اعدلوا في حكمكم، إن الله يحب أهل العدل."], ["إنما المؤمنون إخوة", "في الدين الإسلامي."], ["فأصلحوا بين أخويكم", "إذا تنازعا شيئاً وتخاصما فيه."], ["لا يسخر قوم من قوم", "لا يزدرِ قوم منكم قوماً آخرين ويحتقرونهم."], ["عسى أن يكونوا خيراً منهم", "عند الله، والعبرة بما عند الله لا بما عند الناس."], ["ولا تلمزوا أنفسكم", "لا يعب بعضكم بعضاً، فإنكم كفرد واحد."], ["ولا تنابزوا بالألقاب", "لا يدعُ بعضكم بعضاً بلقب يكرهه نحو: يا فاسق، يا جاهل."], ["بئس الاسم الفسوق بعد الإيمان", "قبُح اسم الفسوق يكون للمرء بعد إيمانه وإسلامه."], ["اجتنبوا كثيراً من الظن", "التهم التي ليس لها ما يوجبها من الأسباب والقرائن."], ["إن بعض الظن إثم", "كظن السوء بأهل الخير من المؤمنين."], ["ولا تجسّسوا", "لا تتبّعوا عورات المسلمين وما بهم بالبحث عنها."], ["أيحب أحدكم أن يأكل لحم أخيه ميتاً فكرهتموه", "لا يحسن به ذلك، فكما كرهتم أكل لحمه ميتاً فاكرهوه حياً وهو الغيبة."], ["وجعلناكم شعوباً وقبائل", "جمع شعب، والقبيلة دون الشعب."], ["لتعارفوا", "ليعرف بعضكم بعضاً فتعارفوا، لا للتفاخر بعلوّ الأنساب."], ["إن أكرمكم عند الله أتقاكم", "أشدكم تقوى لله بفعل أوامره وترك نواهيه هو أكرم عند الله."]], "m": "ما زال السياق في تأديب المسلمين وتربيتهم: يرشد الله المسلمين إلى علاج النزاع المسلح الذي قد يحدث في المجتمع الإسلامي بحكم الضعف الإنساني: وإن طائفتان من المؤمنين اقتتلوا، ولو كانا اثنين فقط، فأصلحوا بينهما بالقضاء على أسباب الخلاف وترضية الطرفين بما هو حق، وليس هذا بصعب مع وجود قلوب مؤمنة، فإن اعتدت إحداهما بعد الصلح فرفضت حكم الله فقاتلوها مجتمعين حتى ترجع إلى الحق، فإن أذعنت فأصلحوا بينهما بالعدل، وأقسطوا دائماً إن الله يحب المقسطين. إنما المؤمنون إخوة، يقرّر الأخوّة الإسلامية ويقصر المؤمنين عليها، فوجب رأب كل صدع بينهم وعدم التساهل في ذلك، واتقوا الله فلا تتوانوا حتى تُسفك الدماء المؤمنة، لعلكم ترحمون فلا تتشتّت أمتكم إلى طوائف متعادية؛ ولما لم يتقِ المسلمون الله في الإصلاح الفوري حصل من الفساد ما الله به عليم في الغرب الإسلامي والشرق. ومن عوامل النزاع سخرية المؤمن بأخيه واحتقاره لضعف حاله ورثاثة ثيابه، فحرّمها الله منبّهاً إلى أن المحتقَر قد يكون خيراً عند الله، والرجال والنساء في هذا سواء. وحرّم اللمز، أي أن يعيب بعضكم بعضاً، فإنكم كشخص واحد، والتنابز بالألقاب المكروهة، فلا يحل لمؤمن أن يقول لأخيه: يا فاسق أو يا كافر، بئس الاسم الفسوق بعد الإيمان، ومن لم يتب فأولئك هم الظالمون. ثم ناداهم بعنوان الإيمان الذي به أصبحوا أحياء: اجتنبوا كثيراً من الظن، وهو كل ظن ليس له ما يوجبه من القرائن، إن بعض الظن إثم كظن السوء بأهل الصلاح فقد يترتب عليه قول باطل أو فعل سوء، ولا تتبّعوا عورات المسلمين، ولا يذكر أحدكم أخاه في غيبته بما يكره، وفي الصحيح أن الغيبة: «ذكرك أخاك بما يكره»، فإن لم يكن فيه ما تقول فقد بهتّه، أيحب أحدكم أن يأكل لحم أخيه ميتاً؟ لا قطعاً، فاكرهوا أكل لحمه حياً بالغيبة، والعرض أعزّ من الجسم، واتقوا الله إن الله توّاب رحيم. وآخر نداءات السورة أعمّ: يا أيها الناس إنا خلقناكم من ذكر وأنثى، آدم وحواء، وجعلناكم شعوباً وقبائل لحكمة التعارف المقتضي للتعاون، فلا تتفرّقوا للتفاخر بالأنساب، فلا قيمة للحسب ولا للنسب إذا كان المرء هابطاً في خلقه فاسداً في سلوكه، إن أكرمكم عند الله أتقاكم، إن الله عليم خبير بما يكمّلكم ويسعدكم، فليُسلَّم له التشريع.", "h": ["وجوب مبادرة المسلمين إلى إصلاح ذات البين بينهم كلما حصل فساد أو خلل فيها.", "وجوب تعاون المسلمين على تأديب أية جماعة تبغي وتعتدي حتى تفيء إلى الحق.", "وجوب الحكم بالعدل في أية قضية من قضايا المسلمين وغيرهم.", "تقرير الأخوّة الإسلامية، ووجوب تحقيقها بالقول والعمل.", "حرمة السخرية واللمز والتنابز بين المسلمين.", "وجوب اجتناب كل ظن لا قرينة ولا حال قوية تدعو إليه.", "حرمة التجسس، أي تتبّع عورات المسلمين وكشفها وإطلاع الناس عليها.", "حرمة الغيبة والنميمة، والنميمة هي نقل الحديث على وجه الإفساد، ويجوز ذكر الشخص وهو غائب في مواطن هي: التظلّم بأن يذكر المسلم من ظلمه لإزالة ظلمه، والاستعانة على تغيير المنكر بذكر صاحبه، والاستفتاء نحو قول المستفتي: ظلمني فلان بكذا فهل يجوز له ذلك، وتحذير المسلمين من الشر بذكر فاعله قصد أن يحذروه، والمجاهر بالفسق لا غيبة له، والتعريف بلقب لا يُعرف الرجل إلا به.", "حرمة التفاخر بالأنساب، ووجوب التعارف للتعاون.", "لا شرف ولا كرم إلا بشرف التقوى وكرامتها: «إن أكرمكم عند الله أتقاكم»، وفي الحديث: «لا فضل لعربي على عجمي ولا لأبيض على أسود إلا بالتقوى» رواه الطبراني."], "k": "«أيحب أحدكم أن يأكل لحم أخيه ميتاً»… في آخر مجلس جلسته، هل أكلت لحم أحد؟"}, {"lbl": "الآيات ١٤ – ١٨", "q": "۞قَالَتِ ٱلۡأَعۡرَابُ ءَامَنَّاۖ قُل لَّمۡ تُؤۡمِنُواْ وَلَٰكِن قُولُوٓاْ أَسۡلَمۡنَا وَلَمَّا يَدۡخُلِ ٱلۡإِيمَٰنُ فِي قُلُوبِكُمۡۖ وَإِن تُطِيعُواْ ٱللَّهَ وَرَسُولَهُۥ لَا يَلِتۡكُم مِّنۡ أَعۡمَٰلِكُمۡ شَيۡـًٔاۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ ﴿١٤﴾ إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرَسُولِهِۦ ثُمَّ لَمۡ يَرۡتَابُواْ وَجَٰهَدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ فِي سَبِيلِ ٱللَّهِۚ أُوْلَـٰٓئِكَ هُمُ ٱلصَّـٰدِقُونَ ﴿١٥﴾ قُلۡ أَتُعَلِّمُونَ ٱللَّهَ بِدِينِكُمۡ وَٱللَّهُ يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ ﴿١٦﴾ يَمُنُّونَ عَلَيۡكَ أَنۡ أَسۡلَمُواْۖ قُل لَّا تَمُنُّواْ عَلَيَّ إِسۡلَٰمَكُمۖ بَلِ ٱللَّهُ يَمُنُّ عَلَيۡكُمۡ أَنۡ هَدَىٰكُمۡ لِلۡإِيمَٰنِ إِن كُنتُمۡ صَٰدِقِينَ ﴿١٧﴾ إِنَّ ٱللَّهَ يَعۡلَمُ غَيۡبَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَٱللَّهُ بَصِيرُۢ بِمَا تَعۡمَلُونَ ﴿١٨﴾", "w": [["قالت الأعراب آمنّا", "نفر من بني أسد قدموا على الرسول وقالوا له: آمنا، وهم غير مؤمنين."], ["قل لم تؤمنوا ولكن قولوا أسلمنا", "قل لهم إنكم ما آمنتم بعد، ولكن قولوا: استسلمنا."], ["ولما يدخل الإيمان في قلوبكم", "لم يدخل بعد، ولكنه يتوقّع له."], ["وإن تطيعوا الله ورسوله", "في الإيمان والقيام بالفرائض واجتناب المحارم."], ["لا يلِتكم من أعمالكم شيئاً", "لا ينقصكم من ثواب أعمالكم شيئاً."], ["إنما المؤمنون", "حقاً وصدقاً لا ادّعاءً ونطقاً."], ["ثم لم يرتابوا", "لم يشكّوا فيما آمنوا به."], ["وجاهدوا بأموالهم وأنفسهم في سبيل الله", "جاهدوا مع رسول الله أعداء الله الكافرين بأموالهم وأنفسهم."], ["أولئك هم الصادقون", "في إيمانهم، لا الذين قالوا آمنا بألسنتهم واستسلموا ظاهراً."], ["قل أتعلّمون الله بدينكم", "أتُشعرون الله بدينكم؟"], ["يمنّون عليك أن أسلموا", "كونهم أسلموا بدون قتال وغيرهم أسلم بعد قتال."], ["قل لا تمنّوا عليّ إسلامكم", "لا حق لكم في ذلك، بل المنّة لله الذي هداكم للإيمان إن كنتم صادقين."], ["إن الله يعلم غيب السماوات والأرض", "لا يخفى عليه أمر من صدق في إيمانه ومن كذب، ومن أسلم رغبة ومن أسلم رهبة."]], "m": "جماعة من أعراب بني أسد وفدوا على رسول الله ﷺ بالمدينة بأولادهم ونسائهم في سنة مجدبة، فأظهروا الإسلام ولم يكونوا مؤمنين في نفوسهم، وكانوا يقولون: أتتك العرب بأنفسها على ظهور رواحلها، ونحن جئناك بالأطفال والعيال ولم نقاتلك كما قاتلك بنو فلان، يمنّون على رسول الله وهم يريدون الصدقة، فأنزل الله تربية لهم: قالت الأعراب: آمنا، صدّقنا بتوحيد الله وبنبوتك، قل: لم تؤمنوا بعد، ولكن الصواب أن تقولوا: أسلمنا، أي انقدنا للإسلام الظاهري، ولما يدخل الإيمان في قلوبكم بعد، وسيدخل إن شاء الله، وإن تطيعوا الله ورسوله لا ينقصكم من أجور أعمالكم شيئاً، إن الله غفور للتائبين رحيم، فتوبوا إليه واصدقوه. ثم عرّفهم بالإيمان الصحيح دعوة لهم: إنما المؤمنون حقاً الذين آمنوا بالله رباً وإلهاً وبرسوله نبياً مطاعاً، ثم لم يشكّوا أبداً، وجاهدوا أنفسهم فألزموها النهوض بالتكاليف في المنشط والمكره، وجاهدوا بأموالهم وأنفسهم أعداء الإسلام لا لغرض دنيوي وإنما لرضا الله وإعلاء كلمته، أولئك هم الصادقون في دعوى الإيمان. قل لهم: أتعلّمون الله بإيمانكم وطاعتكم، والله يعلم ما في السماوات وما في الأرض؟ إن هذا مظهر من مظاهر جهلكم بالله. يمنّون عليك إسلامهم، قل: لا تمنّوا عليّ إسلامكم، بل الله يمنّ عليكم أن هداكم للإيمان إن كنتم صادقين. إن الله يعلم كل ما غاب في السماوات والأرض، والله بصير بما تعملون، فتأدّبوا مع الله وأحسنوا الظن فيه تنجوا من هلاك لازم لمن أساء الظن بالله وأساء الأدب مع رسوله.", "h": ["بيان طبيعة أهل البادية، وهي الغلظة والجفاء والبعد عن الكياسة والأدب.", "بيان الفرق بين الإيمان والإسلام إذا اجتمعا: فالإيمان من أعمال القلوب، والإسلام من أعمال الجوارح، وإذا افترقا فالإيمان هو الإسلام والإسلام هو الإيمان؛ والحقيقة أنه لا يوجد إيمان صحيح بدون إسلام صحيح، ولا إسلام صحيح بدون إيمان صحيح، ولكن يوجد إسلام صوري بدون إيمان، وتوجد دعوى إيمان كاذبة.", "بيان المؤمنين حقاً، وهم الذين آمنوا بالله ورسوله ثم لم يرتابوا وجاهدوا بأموالهم وأنفسهم.", "بيان حكم المنّ، وأنه مذموم من الإنسان، محمود من الرحمن عز وجل، وحقيقة المنّ عدّ النعمة وذكرها للمنعَم عليه وتعدادها المرة بعد المرة.", "بيان إحاطة علم الله بسائر المخلوقات، وأنه لا يخفى عليه من أعمال العباد شيء."], "k": "«بل الله يمنّ عليكم أن هداكم للإيمان»… هل أشعر أن عبادتي فضل لي، أم أراها منّة مني؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 384;
insert into public.tdb_cards(topic, i, body) select 384, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٩ – ١٣", "q": "وَإِن طَآئِفَتَانِ مِنَ ٱلۡمُؤۡمِنِينَ ٱقۡتَتَلُواْ فَأَصۡلِحُواْ بَيۡنَهُمَاۖ فَإِنۢ بَغَتۡ إِحۡدَىٰهُمَا عَلَى ٱلۡأُخۡرَىٰ فَقَٰتِلُواْ ٱلَّتِي تَبۡغِي حَتَّىٰ تَفِيٓءَ إِلَىٰٓ أَمۡرِ ٱللَّهِۚ فَإِن فَآءَتۡ فَأَصۡلِحُواْ بَيۡنَهُمَا بِٱلۡعَدۡلِ وَأَقۡسِطُوٓاْۖ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُقۡسِطِينَ ﴿٩﴾ إِنَّمَا ٱلۡمُؤۡمِنُونَ إِخۡوَةٞ فَأَصۡلِحُواْ بَيۡنَ أَخَوَيۡكُمۡۚ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُرۡحَمُونَ ﴿١٠﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا يَسۡخَرۡ قَوۡمٞ مِّن قَوۡمٍ عَسَىٰٓ أَن يَكُونُواْ خَيۡرٗا مِّنۡهُمۡ وَلَا نِسَآءٞ مِّن نِّسَآءٍ عَسَىٰٓ أَن يَكُنَّ خَيۡرٗا مِّنۡهُنَّۖ وَلَا تَلۡمِزُوٓاْ أَنفُسَكُمۡ وَلَا تَنَابَزُواْ بِٱلۡأَلۡقَٰبِۖ بِئۡسَ ٱلِٱسۡمُ ٱلۡفُسُوقُ بَعۡدَ ٱلۡإِيمَٰنِۚ وَمَن لَّمۡ يَتُبۡ فَأُوْلَـٰٓئِكَ هُمُ ٱلظَّـٰلِمُونَ ﴿١١﴾ يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱجۡتَنِبُواْ كَثِيرٗا مِّنَ ٱلظَّنِّ إِنَّ بَعۡضَ ٱلظَّنِّ إِثۡمٞۖ وَلَا تَجَسَّسُواْ وَلَا يَغۡتَب بَّعۡضُكُم بَعۡضًاۚ أَيُحِبُّ أَحَدُكُمۡ أَن يَأۡكُلَ لَحۡمَ أَخِيهِ مَيۡتٗا فَكَرِهۡتُمُوهُۚ وَٱتَّقُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ تَوَّابٞ رَّحِيمٞ ﴿١٢﴾ يَـٰٓأَيُّهَا ٱلنَّاسُ إِنَّا خَلَقۡنَٰكُم مِّن ذَكَرٖ وَأُنثَىٰ وَجَعَلۡنَٰكُمۡ شُعُوبٗا وَقَبَآئِلَ لِتَعَارَفُوٓاْۚ إِنَّ أَكۡرَمَكُمۡ عِندَ ٱللَّهِ أَتۡقَىٰكُمۡۚ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرٞ ﴿١٣﴾", "w": [["وإن طائفتان من المؤمنين", "جماعتان من المسلمين، قلّ أفرادهما أو كثروا."], ["اقتتلوا فأصلحوا بينهما", "همّوا بالاقتتال أو باشروه فعلاً، فأصلحوا ما فسد بينهما."], ["فإن بغت إحداهما على الأخرى", "تعدّت بعد المصالحة بأن رفضت ذلك ولم ترضَ بحكم الله."], ["فقاتلوا التي تبغي حتى تفيء إلى أمر الله", "قاتلوا مجتمعين الطائفة التي بغت حتى ترجع إلى الحق."], ["فإن فاءت فأصلحوا بينهما بالعدل", "رجعت إلى الحق بعد مقاتلتها فأصلحوا بينهما بالحق."], ["وأقسطوا إن الله يحب المقسطين", "اعدلوا في حكمكم، إن الله يحب أهل العدل."], ["إنما المؤمنون إخوة", "في الدين الإسلامي."], ["فأصلحوا بين أخويكم", "إذا تنازعا شيئاً وتخاصما فيه."], ["لا يسخر قوم من قوم", "لا يزدرِ قوم منكم قوماً آخرين ويحتقرونهم."], ["عسى أن يكونوا خيراً منهم", "عند الله، والعبرة بما عند الله لا بما عند الناس."], ["ولا تلمزوا أنفسكم", "لا يعب بعضكم بعضاً، فإنكم كفرد واحد."], ["ولا تنابزوا بالألقاب", "لا يدعُ بعضكم بعضاً بلقب يكرهه نحو: يا فاسق، يا جاهل."], ["بئس الاسم الفسوق بعد الإيمان", "قبُح اسم الفسوق يكون للمرء بعد إيمانه وإسلامه."], ["اجتنبوا كثيراً من الظن", "التهم التي ليس لها ما يوجبها من الأسباب والقرائن."], ["إن بعض الظن إثم", "كظن السوء بأهل الخير من المؤمنين."], ["ولا تجسّسوا", "لا تتبّعوا عورات المسلمين وما بهم بالبحث عنها."], ["أيحب أحدكم أن يأكل لحم أخيه ميتاً فكرهتموه", "لا يحسن به ذلك، فكما كرهتم أكل لحمه ميتاً فاكرهوه حياً وهو الغيبة."], ["وجعلناكم شعوباً وقبائل", "جمع شعب، والقبيلة دون الشعب."], ["لتعارفوا", "ليعرف بعضكم بعضاً فتعارفوا، لا للتفاخر بعلوّ الأنساب."], ["إن أكرمكم عند الله أتقاكم", "أشدكم تقوى لله بفعل أوامره وترك نواهيه هو أكرم عند الله."]], "m": "ما زال السياق في تأديب المسلمين وتربيتهم: يرشد الله المسلمين إلى علاج النزاع المسلح الذي قد يحدث في المجتمع الإسلامي بحكم الضعف الإنساني: وإن طائفتان من المؤمنين اقتتلوا، ولو كانا اثنين فقط، فأصلحوا بينهما بالقضاء على أسباب الخلاف وترضية الطرفين بما هو حق، وليس هذا بصعب مع وجود قلوب مؤمنة، فإن اعتدت إحداهما بعد الصلح فرفضت حكم الله فقاتلوها مجتمعين حتى ترجع إلى الحق، فإن أذعنت فأصلحوا بينهما بالعدل، وأقسطوا دائماً إن الله يحب المقسطين. إنما المؤمنون إخوة، يقرّر الأخوّة الإسلامية ويقصر المؤمنين عليها، فوجب رأب كل صدع بينهم وعدم التساهل في ذلك، واتقوا الله فلا تتوانوا حتى تُسفك الدماء المؤمنة، لعلكم ترحمون فلا تتشتّت أمتكم إلى طوائف متعادية؛ ولما لم يتقِ المسلمون الله في الإصلاح الفوري حصل من الفساد ما الله به عليم في الغرب الإسلامي والشرق. ومن عوامل النزاع سخرية المؤمن بأخيه واحتقاره لضعف حاله ورثاثة ثيابه، فحرّمها الله منبّهاً إلى أن المحتقَر قد يكون خيراً عند الله، والرجال والنساء في هذا سواء. وحرّم اللمز، أي أن يعيب بعضكم بعضاً، فإنكم كشخص واحد، والتنابز بالألقاب المكروهة، فلا يحل لمؤمن أن يقول لأخيه: يا فاسق أو يا كافر، بئس الاسم الفسوق بعد الإيمان، ومن لم يتب فأولئك هم الظالمون. ثم ناداهم بعنوان الإيمان الذي به أصبحوا أحياء: اجتنبوا كثيراً من الظن، وهو كل ظن ليس له ما يوجبه من القرائن، إن بعض الظن إثم كظن السوء بأهل الصلاح فقد يترتب عليه قول باطل أو فعل سوء، ولا تتبّعوا عورات المسلمين، ولا يذكر أحدكم أخاه في غيبته بما يكره، وفي الصحيح أن الغيبة: «ذكرك أخاك بما يكره»، فإن لم يكن فيه ما تقول فقد بهتّه، أيحب أحدكم أن يأكل لحم أخيه ميتاً؟ لا قطعاً، فاكرهوا أكل لحمه حياً بالغيبة، والعرض أعزّ من الجسم، واتقوا الله إن الله توّاب رحيم. وآخر نداءات السورة أعمّ: يا أيها الناس إنا خلقناكم من ذكر وأنثى، آدم وحواء، وجعلناكم شعوباً وقبائل لحكمة التعارف المقتضي للتعاون، فلا تتفرّقوا للتفاخر بالأنساب، فلا قيمة للحسب ولا للنسب إذا كان المرء هابطاً في خلقه فاسداً في سلوكه، إن أكرمكم عند الله أتقاكم، إن الله عليم خبير بما يكمّلكم ويسعدكم، فليُسلَّم له التشريع.", "h": ["وجوب مبادرة المسلمين إلى إصلاح ذات البين بينهم كلما حصل فساد أو خلل فيها.", "وجوب تعاون المسلمين على تأديب أية جماعة تبغي وتعتدي حتى تفيء إلى الحق.", "وجوب الحكم بالعدل في أية قضية من قضايا المسلمين وغيرهم.", "تقرير الأخوّة الإسلامية، ووجوب تحقيقها بالقول والعمل.", "حرمة السخرية واللمز والتنابز بين المسلمين.", "وجوب اجتناب كل ظن لا قرينة ولا حال قوية تدعو إليه.", "حرمة التجسس، أي تتبّع عورات المسلمين وكشفها وإطلاع الناس عليها.", "حرمة الغيبة والنميمة، والنميمة هي نقل الحديث على وجه الإفساد، ويجوز ذكر الشخص وهو غائب في مواطن هي: التظلّم بأن يذكر المسلم من ظلمه لإزالة ظلمه، والاستعانة على تغيير المنكر بذكر صاحبه، والاستفتاء نحو قول المستفتي: ظلمني فلان بكذا فهل يجوز له ذلك، وتحذير المسلمين من الشر بذكر فاعله قصد أن يحذروه، والمجاهر بالفسق لا غيبة له، والتعريف بلقب لا يُعرف الرجل إلا به.", "حرمة التفاخر بالأنساب، ووجوب التعارف للتعاون.", "لا شرف ولا كرم إلا بشرف التقوى وكرامتها: «إن أكرمكم عند الله أتقاكم»، وفي الحديث: «لا فضل لعربي على عجمي ولا لأبيض على أسود إلا بالتقوى» رواه الطبراني."], "k": "«أيحب أحدكم أن يأكل لحم أخيه ميتاً»… في آخر مجلس جلسته، هل أكلت لحم أحد؟"}, {"lbl": "الآيات ١٤ – ١٨", "q": "۞قَالَتِ ٱلۡأَعۡرَابُ ءَامَنَّاۖ قُل لَّمۡ تُؤۡمِنُواْ وَلَٰكِن قُولُوٓاْ أَسۡلَمۡنَا وَلَمَّا يَدۡخُلِ ٱلۡإِيمَٰنُ فِي قُلُوبِكُمۡۖ وَإِن تُطِيعُواْ ٱللَّهَ وَرَسُولَهُۥ لَا يَلِتۡكُم مِّنۡ أَعۡمَٰلِكُمۡ شَيۡـًٔاۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٌ ﴿١٤﴾ إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرَسُولِهِۦ ثُمَّ لَمۡ يَرۡتَابُواْ وَجَٰهَدُواْ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ فِي سَبِيلِ ٱللَّهِۚ أُوْلَـٰٓئِكَ هُمُ ٱلصَّـٰدِقُونَ ﴿١٥﴾ قُلۡ أَتُعَلِّمُونَ ٱللَّهَ بِدِينِكُمۡ وَٱللَّهُ يَعۡلَمُ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٞ ﴿١٦﴾ يَمُنُّونَ عَلَيۡكَ أَنۡ أَسۡلَمُواْۖ قُل لَّا تَمُنُّواْ عَلَيَّ إِسۡلَٰمَكُمۖ بَلِ ٱللَّهُ يَمُنُّ عَلَيۡكُمۡ أَنۡ هَدَىٰكُمۡ لِلۡإِيمَٰنِ إِن كُنتُمۡ صَٰدِقِينَ ﴿١٧﴾ إِنَّ ٱللَّهَ يَعۡلَمُ غَيۡبَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَٱللَّهُ بَصِيرُۢ بِمَا تَعۡمَلُونَ ﴿١٨﴾", "w": [["قالت الأعراب آمنّا", "نفر من بني أسد قدموا على الرسول وقالوا له: آمنا، وهم غير مؤمنين."], ["قل لم تؤمنوا ولكن قولوا أسلمنا", "قل لهم إنكم ما آمنتم بعد، ولكن قولوا: استسلمنا."], ["ولما يدخل الإيمان في قلوبكم", "لم يدخل بعد، ولكنه يتوقّع له."], ["وإن تطيعوا الله ورسوله", "في الإيمان والقيام بالفرائض واجتناب المحارم."], ["لا يلِتكم من أعمالكم شيئاً", "لا ينقصكم من ثواب أعمالكم شيئاً."], ["إنما المؤمنون", "حقاً وصدقاً لا ادّعاءً ونطقاً."], ["ثم لم يرتابوا", "لم يشكّوا فيما آمنوا به."], ["وجاهدوا بأموالهم وأنفسهم في سبيل الله", "جاهدوا مع رسول الله أعداء الله الكافرين بأموالهم وأنفسهم."], ["أولئك هم الصادقون", "في إيمانهم، لا الذين قالوا آمنا بألسنتهم واستسلموا ظاهراً."], ["قل أتعلّمون الله بدينكم", "أتُشعرون الله بدينكم؟"], ["يمنّون عليك أن أسلموا", "كونهم أسلموا بدون قتال وغيرهم أسلم بعد قتال."], ["قل لا تمنّوا عليّ إسلامكم", "لا حق لكم في ذلك، بل المنّة لله الذي هداكم للإيمان إن كنتم صادقين."], ["إن الله يعلم غيب السماوات والأرض", "لا يخفى عليه أمر من صدق في إيمانه ومن كذب، ومن أسلم رغبة ومن أسلم رهبة."]], "m": "جماعة من أعراب بني أسد وفدوا على رسول الله ﷺ بالمدينة بأولادهم ونسائهم في سنة مجدبة، فأظهروا الإسلام ولم يكونوا مؤمنين في نفوسهم، وكانوا يقولون: أتتك العرب بأنفسها على ظهور رواحلها، ونحن جئناك بالأطفال والعيال ولم نقاتلك كما قاتلك بنو فلان، يمنّون على رسول الله وهم يريدون الصدقة، فأنزل الله تربية لهم: قالت الأعراب: آمنا، صدّقنا بتوحيد الله وبنبوتك، قل: لم تؤمنوا بعد، ولكن الصواب أن تقولوا: أسلمنا، أي انقدنا للإسلام الظاهري، ولما يدخل الإيمان في قلوبكم بعد، وسيدخل إن شاء الله، وإن تطيعوا الله ورسوله لا ينقصكم من أجور أعمالكم شيئاً، إن الله غفور للتائبين رحيم، فتوبوا إليه واصدقوه. ثم عرّفهم بالإيمان الصحيح دعوة لهم: إنما المؤمنون حقاً الذين آمنوا بالله رباً وإلهاً وبرسوله نبياً مطاعاً، ثم لم يشكّوا أبداً، وجاهدوا أنفسهم فألزموها النهوض بالتكاليف في المنشط والمكره، وجاهدوا بأموالهم وأنفسهم أعداء الإسلام لا لغرض دنيوي وإنما لرضا الله وإعلاء كلمته، أولئك هم الصادقون في دعوى الإيمان. قل لهم: أتعلّمون الله بإيمانكم وطاعتكم، والله يعلم ما في السماوات وما في الأرض؟ إن هذا مظهر من مظاهر جهلكم بالله. يمنّون عليك إسلامهم، قل: لا تمنّوا عليّ إسلامكم، بل الله يمنّ عليكم أن هداكم للإيمان إن كنتم صادقين. إن الله يعلم كل ما غاب في السماوات والأرض، والله بصير بما تعملون، فتأدّبوا مع الله وأحسنوا الظن فيه تنجوا من هلاك لازم لمن أساء الظن بالله وأساء الأدب مع رسوله.", "h": ["بيان طبيعة أهل البادية، وهي الغلظة والجفاء والبعد عن الكياسة والأدب.", "بيان الفرق بين الإيمان والإسلام إذا اجتمعا: فالإيمان من أعمال القلوب، والإسلام من أعمال الجوارح، وإذا افترقا فالإيمان هو الإسلام والإسلام هو الإيمان؛ والحقيقة أنه لا يوجد إيمان صحيح بدون إسلام صحيح، ولا إسلام صحيح بدون إيمان صحيح، ولكن يوجد إسلام صوري بدون إيمان، وتوجد دعوى إيمان كاذبة.", "بيان المؤمنين حقاً، وهم الذين آمنوا بالله ورسوله ثم لم يرتابوا وجاهدوا بأموالهم وأنفسهم.", "بيان حكم المنّ، وأنه مذموم من الإنسان، محمود من الرحمن عز وجل، وحقيقة المنّ عدّ النعمة وذكرها للمنعَم عليه وتعدادها المرة بعد المرة.", "بيان إحاطة علم الله بسائر المخلوقات، وأنه لا يخفى عليه من أعمال العباد شيء."], "k": "«بل الله يمنّ عليكم أن هداكم للإيمان»… هل أشعر أن عبادتي فضل لي، أم أراها منّة مني؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (385, 50, 1, 15, 'سورة ق ١ – ١٥', 'ق: أفعيينا بالخلق الأول', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 385) = $j$[{"lbl": "الآيات ١ – ٥", "q": "قٓۚ وَٱلۡقُرۡءَانِ ٱلۡمَجِيدِ ﴿١﴾ بَلۡ عَجِبُوٓاْ أَن جَآءَهُم مُّنذِرٞ مِّنۡهُمۡ فَقَالَ ٱلۡكَٰفِرُونَ هَٰذَا شَيۡءٌ عَجِيبٌ ﴿٢﴾ أَءِذَا مِتۡنَا وَكُنَّا تُرَابٗاۖ ذَٰلِكَ رَجۡعُۢ بَعِيدٞ ﴿٣﴾ قَدۡ عَلِمۡنَا مَا تَنقُصُ ٱلۡأَرۡضُ مِنۡهُمۡۖ وَعِندَنَا كِتَٰبٌ حَفِيظُۢ ﴿٤﴾ بَلۡ كَذَّبُواْ بِٱلۡحَقِّ لَمَّا جَآءَهُمۡ فَهُمۡ فِيٓ أَمۡرٖ مَّرِيجٍ ﴿٥﴾", "w": [["ق", "أحد الحروف المقطعة، يُكتب «ق» ويُقرأ «قاف»."], ["والقرآن المجيد", "الكريم، وجواب القسم محذوف تقديره: لقد أرسلنا محمداً مبلّغاً."], ["بل عجبوا أن جاءهم منذر منهم", "لم يُنكروا أصل الإرسال، وإنما أنكروا كون المرسل بشراً مثلهم ينذرهم عذاب الله يوم القيامة."], ["فقال الكافرون هذا شيء عجيب", "قال المكذبون بالبعث: البعث بعد الموت والبلى أمر عجيب."], ["أإذا متنا وكنا تراباً", "أإذا متنا وصرنا رفاتاً وعظاماً نخرة نرجع أحياء؟"], ["ذلك رجع بعيد", "بعيد الإمكان في غاية البعد."], ["قد علمنا ما تنقص الأرض منهم", "أحاط علمنا بما تنقص الأرض من أجساد الموتى وما تأكل من لحومهم وعظامهم."], ["وعندنا كتاب حفيظ", "كتاب المقادير الذي كُتب فيه كل شيء، ومن بين ذلك أعداد الموتى وأسماؤهم وصورهم ويوم إعادتهم."], ["بل كذّبوا بالحق لما جاءهم", "كذّبوا بما هو أقبح من تكذيبهم بالبعث، وهو تكذيبهم بالنبوة المحمدية وبالقرآن."], ["فهم في أمر مريج", "مختلط عليهم، قالوا مرة سحر، ومرة شعر، ومرة كهانة، وأخرى أساطير."]], "m": "ق: الله أعلم بمراده به، إذ هو من الحروف المقطعة الأحادية نحو ص ون. والقرآن المجيد الكريم لما فيه من الخير والبركة، إذ قراءة الحرف منه بعشر حسنات، قسم جوابه محذوف تقديره: إن محمداً لرسول أمين. بل عجبوا أن جاءهم منذر منهم، لم ينكروا أصل الإرسال وإنما أنكروا كون المرسل بشراً مثلهم ينذرهم عذاب يوم القيامة وهم لا يؤمنون بالبعث، فقالوا: هذا أمر يدعو إلى التعجب، من مات وصار تراباً لا يُعقل أن يحيا مرة أخرى فيُسأل ويُحاسب، أإذا متنا وكنا تراباً؟ ذلك رجوع بعيد التحقيق. قال تعالى مبرهناً على إبطال دعواهم: قد علمنا ما تنقص الأرض منهم بعد الموت من لحم وعظم، وعندنا كتاب حفيظ قد حوى كل شيء مادةً وكميةً وكيفية، بمقتضاه يعود الخلق كما بدأ لا ينقص منه شيء. بل هناك ما هو أشنع من إنكارهم وأقبح عقلاً، وهو تكذيبهم بالقرآن ومن أُنزل عليه وهو الحق من الله، فلذا هم في أمر مختلط: قالوا في الرسول ساحر وشاعر ومفترٍ كذّاب، وقالوا في القرآن أساطير الأولين، فهم لا يدرون ما يقولون ولا يثبتون عليه.", "h": ["بيان شرف القرآن ومجده وكرمه.", "تقرير البعث والوحي الإلهي.", "البرهنة الصحيحة الواضحة على صحة البعث والجزاء وإمكانهما.", "تقرير عقيدة القضاء والقدر بتقرير كتاب المقادير."], "k": "«قد علمنا ما تنقص الأرض منهم»… لا يضيع عنده ذرة من جسدي؛ أفيضيع عنده عملي؟"}, {"lbl": "الآيات ٦ – ١١", "q": "أَفَلَمۡ يَنظُرُوٓاْ إِلَى ٱلسَّمَآءِ فَوۡقَهُمۡ كَيۡفَ بَنَيۡنَٰهَا وَزَيَّنَّـٰهَا وَمَا لَهَا مِن فُرُوجٖ ﴿٦﴾ وَٱلۡأَرۡضَ مَدَدۡنَٰهَا وَأَلۡقَيۡنَا فِيهَا رَوَٰسِيَ وَأَنۢبَتۡنَا فِيهَا مِن كُلِّ زَوۡجِۭ بَهِيجٖ ﴿٧﴾ تَبۡصِرَةٗ وَذِكۡرَىٰ لِكُلِّ عَبۡدٖ مُّنِيبٖ ﴿٨﴾ وَنَزَّلۡنَا مِنَ ٱلسَّمَآءِ مَآءٗ مُّبَٰرَكٗا فَأَنۢبَتۡنَا بِهِۦ جَنَّـٰتٖ وَحَبَّ ٱلۡحَصِيدِ ﴿٩﴾ وَٱلنَّخۡلَ بَاسِقَٰتٖ لَّهَا طَلۡعٞ نَّضِيدٞ ﴿١٠﴾ رِّزۡقٗا لِّلۡعِبَادِۖ وَأَحۡيَيۡنَا بِهِۦ بَلۡدَةٗ مَّيۡتٗاۚ كَذَٰلِكَ ٱلۡخُرُوجُ ﴿١١﴾", "w": [["أفلم ينظروا إلى السماء فوقهم", "أعموا فلم ينظروا بعيونهم معتبرين بعقولهم إلى السماء فوقهم فيعلموا أن استبعادهم للبعث غير صحيح؟"], ["كيف بنيناها وزيّنّاها", "بنيناها بلا عمد، وزيّنّاها بالكواكب."], ["وما لها من فروج", "ليس لها من شقوق تعيبها."], ["والأرض مددناها", "بسطناها."], ["وألقينا فيها رواسي", "جبالاً ثوابت مثبتة للأرض كي لا تميد بأهلها."], ["من كل زوج بهيج", "من كل صنف من أنواع النبات حسن."], ["تبصرة وذكرى لكل عبد منيب", "جعلنا ذلك تبصرة وذكرى لكل عبد راجع إلى طاعتنا."], ["ماءً مباركاً", "ماء المطر كثير البركة."], ["فأنبتنا به جنات وحبّ الحصيد", "بساتين، والحب المحصود من بُرّ وشعير وغيرهما."], ["والنخل باسقات", "النخيل الطوال العاليات."], ["لها طلع نضيد", "منضّد متراكب بعضه فوق بعض."], ["رزقاً للعباد", "قوتاً لهم، مؤمنهم وكافرهم."], ["وأحيينا به بلدة ميتاً", "أحيينا بذلك الماء بلدة لا نبات فيها من الجدب."], ["كذلك الخروج", "كما أخرجنا النبات من الأرض الميتة بالماء نخرجكم أحياء من قبوركم يوم القيامة بماء ننزله من السماء."]], "m": "ما زال السياق في تقرير عقيدة البعث، وهي العقيدة التي يُبنى عليها كل إصلاح يُراد للإنسان بعد الإيمان بالله: أعَمِي المنكرون للبعث فلم ينظروا بعيونهم وعقولهم إلى السماء الواسعة الرفيعة فوقهم، رُفعت بلا عمد، وزيّنها خالقها بكواكب منيرة، ولم يُرَ فيها تصدّع ولا شقوق على طول الحياة؟ أليس القادر على خلق السماء ابتداءً وعلى الإماتة قادراً على إحياء من خلق وأمات؟ وما لهم لا ينظرون إلى الأرض بسطها وألقى فيها الجبال لتثبيتها حتى لا تميد بهم، وأنبت فيها من كل صنف من النبات بهيّ المنظر، تبصرة وذكرى لكل عبد منيب؟ وأنزل من السماء ماءً مباركاً لما يكثر به من الخيرات والبركات، فأنبت به بساتين من أشجار ونخيل وأعناب، وحب الحصيد من قمح وشعير وذرة، والنخل العاليات لها طلعها المتراكب ليتحوّل إلى رطب يأكله الإنسان، قوتاً للعباد مؤمنين وكافرين، إلا أن المؤمن إذا أكل شكر والكافر إذا أكل كفر، وأحيا به بلدة ميتة لا عشب فيها فأصبحت تهتزّ رابية؛ كذلك يكون خروجكم من قبوركم أيها المنكرون للبعث: ينزل الله من السماء ماءً فتنبتون وتخرجون كما يخرج الزرع من الأرض، فبأي عقل تنكرون البعث؟ إنها لا تعمى الأبصار ولكن تعمى القلوب التي في الصدور.", "h": ["تقرير عقيدة البعث بمظاهر القدرة الإلهية في الكون.", "مشروعية النظر والاعتبار فيما يحيط بالإنسان من مظاهر الكون والحياة للعبرة، طلباً لزيادة الإيمان والوصول به إلى مستوى اليقين.", "فضل العبد المنيب وفضيلة الإنابة إلى الله تعالى، والمنيب هو الذي يرجع إلى ربه في كل ما يهمه، والإنابة التوبة إلى الله والرجوع إلى طاعته بعد معصيته."], "k": "«تبصرة وذكرى لكل عبد منيب»… النخلة والمطر يذكّرانني به؛ فهل أنظر إليهما بعين المنيب؟"}, {"lbl": "الآيات ١٢ – ١٥", "q": "كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحٖ وَأَصۡحَٰبُ ٱلرَّسِّ وَثَمُودُ ﴿١٢﴾ وَعَادٞ وَفِرۡعَوۡنُ وَإِخۡوَٰنُ لُوطٖ ﴿١٣﴾ وَأَصۡحَٰبُ ٱلۡأَيۡكَةِ وَقَوۡمُ تُبَّعٖۚ كُلّٞ كَذَّبَ ٱلرُّسُلَ فَحَقَّ وَعِيدِ ﴿١٤﴾ أَفَعَيِينَا بِٱلۡخَلۡقِ ٱلۡأَوَّلِۚ بَلۡ هُمۡ فِي لَبۡسٖ مِّنۡ خَلۡقٖ جَدِيدٖ ﴿١٥﴾", "w": [["كذّبت قبلهم قوم نوح", "كذّبت قبل قومك يا رسولنا بالبعث والتوحيد والنبوة قوم نوح."], ["وأصحاب الرسّ وثمود", "أصحاب الرسّ، وهي بئر كانوا مقيمين حولها يعبدون الأصنام، وثمود أصحاب الحِجر قوم صالح."], ["وعاد وفرعون", "وكذّبت عاد قوم هود، وكذّب فرعون موسى ﵇."], ["وإخوان لوط وأصحاب الأيكة", "وكذّب قوم لوط أخاهم لوطاً، وكذّب أصحاب الأيكة شعيباً."], ["وقوم تُبّع", "قوم تُبّع الحِميري اليمني."], ["كلٌّ كذّب الرسل", "كل من ذُكر قد كذّب الرسل، فلست وحدك المكذَّب."], ["فحقّ وعيد", "وجب وعيدي لهم بنزول العذاب فنزل فهلكوا."], ["أفعيينا بالخلق الأول", "أعجزنا بخلق الناس أولاً؟ لا، فكيف نعجز عن إعادتهم كما كانوا؟"], ["بل هم في لبس من خلق جديد", "غير منكرين لقدرة الله على الخلق الأول، بل هم في خلط وشك من خلق جديد لمخالفته العادة."]], "m": "ما زال السياق في تقرير عقيدة البعث وإثبات النبوة: كذّبت قبل قريش قوم نوح، وهي أول أمة كذّبت، وعاش نوح فيها ألف سنة إلا خمسين عاماً يدعوها فلم يؤمن منهم أكثر من نيّف وثمانين نسمة، وأصحاب الرسّ أخذوا نبيهم فرسّوه في بئر فقتلوه فأهلكهم الله في تلك البئر، وثمود قوم صالح، وعاد قوم هود، وفرعون، وقوم لوط، وأصحاب الأيكة، أي الشجر الملتفّ، إذ كانوا يعبدون أشجارها، وقوم تُبّع الحِميري. كل تلك الأمم كذّبوا الرسل ولم يؤمنوا بما جاؤوهم به من التوحيد والشرع، فوجب لذلك عذابهم الذي توعّدتهم به على ألسنة رسلي فأهلكناهم أجمعين، وقومك يا محمد موعودون بالعذاب أيضاً إن لم يبادروا بالإيمان. أفعيينا بالخلق الأول؟ لا، لم يعجز الله عن خلق ما خلق من الملائكة والإنس والجن، فكيف يعجز بالإعادة وهي أهون من البدء؟ بل هم غير منكرين لقدرتنا على الخلق الأول، ولكنهم في خلط وشك من خلق جديد لمخالفته العادة، إذ يرون الناس يموتون ولا يحيون.", "h": ["تعزية الرسول ﷺ وتسليته بإعلامه بأن قومه ليسوا أول من كذّب الرسل.", "تهديد المصرّين على التكذيب من كفار قريش بالعذاب، إذ ليسوا بأفضل من غيرهم وقد أُهلكوا لما كذّبوا.", "تقرير البعث والجزاء، وإثبات عقيدتهما بالأدلة العقلية كبدء الخلق.", "ضعف إدراك المنكرين للبعث لظلمة نفوسهم بالشرك والمعاصي."], "k": "«أفعيينا بالخلق الأول»… الذي بدأني لن يعجزه أن يعيدني؛ فهل أستعد لذلك اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 385;
insert into public.tdb_cards(topic, i, body) select 385, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٥", "q": "قٓۚ وَٱلۡقُرۡءَانِ ٱلۡمَجِيدِ ﴿١﴾ بَلۡ عَجِبُوٓاْ أَن جَآءَهُم مُّنذِرٞ مِّنۡهُمۡ فَقَالَ ٱلۡكَٰفِرُونَ هَٰذَا شَيۡءٌ عَجِيبٌ ﴿٢﴾ أَءِذَا مِتۡنَا وَكُنَّا تُرَابٗاۖ ذَٰلِكَ رَجۡعُۢ بَعِيدٞ ﴿٣﴾ قَدۡ عَلِمۡنَا مَا تَنقُصُ ٱلۡأَرۡضُ مِنۡهُمۡۖ وَعِندَنَا كِتَٰبٌ حَفِيظُۢ ﴿٤﴾ بَلۡ كَذَّبُواْ بِٱلۡحَقِّ لَمَّا جَآءَهُمۡ فَهُمۡ فِيٓ أَمۡرٖ مَّرِيجٍ ﴿٥﴾", "w": [["ق", "أحد الحروف المقطعة، يُكتب «ق» ويُقرأ «قاف»."], ["والقرآن المجيد", "الكريم، وجواب القسم محذوف تقديره: لقد أرسلنا محمداً مبلّغاً."], ["بل عجبوا أن جاءهم منذر منهم", "لم يُنكروا أصل الإرسال، وإنما أنكروا كون المرسل بشراً مثلهم ينذرهم عذاب الله يوم القيامة."], ["فقال الكافرون هذا شيء عجيب", "قال المكذبون بالبعث: البعث بعد الموت والبلى أمر عجيب."], ["أإذا متنا وكنا تراباً", "أإذا متنا وصرنا رفاتاً وعظاماً نخرة نرجع أحياء؟"], ["ذلك رجع بعيد", "بعيد الإمكان في غاية البعد."], ["قد علمنا ما تنقص الأرض منهم", "أحاط علمنا بما تنقص الأرض من أجساد الموتى وما تأكل من لحومهم وعظامهم."], ["وعندنا كتاب حفيظ", "كتاب المقادير الذي كُتب فيه كل شيء، ومن بين ذلك أعداد الموتى وأسماؤهم وصورهم ويوم إعادتهم."], ["بل كذّبوا بالحق لما جاءهم", "كذّبوا بما هو أقبح من تكذيبهم بالبعث، وهو تكذيبهم بالنبوة المحمدية وبالقرآن."], ["فهم في أمر مريج", "مختلط عليهم، قالوا مرة سحر، ومرة شعر، ومرة كهانة، وأخرى أساطير."]], "m": "ق: الله أعلم بمراده به، إذ هو من الحروف المقطعة الأحادية نحو ص ون. والقرآن المجيد الكريم لما فيه من الخير والبركة، إذ قراءة الحرف منه بعشر حسنات، قسم جوابه محذوف تقديره: إن محمداً لرسول أمين. بل عجبوا أن جاءهم منذر منهم، لم ينكروا أصل الإرسال وإنما أنكروا كون المرسل بشراً مثلهم ينذرهم عذاب يوم القيامة وهم لا يؤمنون بالبعث، فقالوا: هذا أمر يدعو إلى التعجب، من مات وصار تراباً لا يُعقل أن يحيا مرة أخرى فيُسأل ويُحاسب، أإذا متنا وكنا تراباً؟ ذلك رجوع بعيد التحقيق. قال تعالى مبرهناً على إبطال دعواهم: قد علمنا ما تنقص الأرض منهم بعد الموت من لحم وعظم، وعندنا كتاب حفيظ قد حوى كل شيء مادةً وكميةً وكيفية، بمقتضاه يعود الخلق كما بدأ لا ينقص منه شيء. بل هناك ما هو أشنع من إنكارهم وأقبح عقلاً، وهو تكذيبهم بالقرآن ومن أُنزل عليه وهو الحق من الله، فلذا هم في أمر مختلط: قالوا في الرسول ساحر وشاعر ومفترٍ كذّاب، وقالوا في القرآن أساطير الأولين، فهم لا يدرون ما يقولون ولا يثبتون عليه.", "h": ["بيان شرف القرآن ومجده وكرمه.", "تقرير البعث والوحي الإلهي.", "البرهنة الصحيحة الواضحة على صحة البعث والجزاء وإمكانهما.", "تقرير عقيدة القضاء والقدر بتقرير كتاب المقادير."], "k": "«قد علمنا ما تنقص الأرض منهم»… لا يضيع عنده ذرة من جسدي؛ أفيضيع عنده عملي؟"}, {"lbl": "الآيات ٦ – ١١", "q": "أَفَلَمۡ يَنظُرُوٓاْ إِلَى ٱلسَّمَآءِ فَوۡقَهُمۡ كَيۡفَ بَنَيۡنَٰهَا وَزَيَّنَّـٰهَا وَمَا لَهَا مِن فُرُوجٖ ﴿٦﴾ وَٱلۡأَرۡضَ مَدَدۡنَٰهَا وَأَلۡقَيۡنَا فِيهَا رَوَٰسِيَ وَأَنۢبَتۡنَا فِيهَا مِن كُلِّ زَوۡجِۭ بَهِيجٖ ﴿٧﴾ تَبۡصِرَةٗ وَذِكۡرَىٰ لِكُلِّ عَبۡدٖ مُّنِيبٖ ﴿٨﴾ وَنَزَّلۡنَا مِنَ ٱلسَّمَآءِ مَآءٗ مُّبَٰرَكٗا فَأَنۢبَتۡنَا بِهِۦ جَنَّـٰتٖ وَحَبَّ ٱلۡحَصِيدِ ﴿٩﴾ وَٱلنَّخۡلَ بَاسِقَٰتٖ لَّهَا طَلۡعٞ نَّضِيدٞ ﴿١٠﴾ رِّزۡقٗا لِّلۡعِبَادِۖ وَأَحۡيَيۡنَا بِهِۦ بَلۡدَةٗ مَّيۡتٗاۚ كَذَٰلِكَ ٱلۡخُرُوجُ ﴿١١﴾", "w": [["أفلم ينظروا إلى السماء فوقهم", "أعموا فلم ينظروا بعيونهم معتبرين بعقولهم إلى السماء فوقهم فيعلموا أن استبعادهم للبعث غير صحيح؟"], ["كيف بنيناها وزيّنّاها", "بنيناها بلا عمد، وزيّنّاها بالكواكب."], ["وما لها من فروج", "ليس لها من شقوق تعيبها."], ["والأرض مددناها", "بسطناها."], ["وألقينا فيها رواسي", "جبالاً ثوابت مثبتة للأرض كي لا تميد بأهلها."], ["من كل زوج بهيج", "من كل صنف من أنواع النبات حسن."], ["تبصرة وذكرى لكل عبد منيب", "جعلنا ذلك تبصرة وذكرى لكل عبد راجع إلى طاعتنا."], ["ماءً مباركاً", "ماء المطر كثير البركة."], ["فأنبتنا به جنات وحبّ الحصيد", "بساتين، والحب المحصود من بُرّ وشعير وغيرهما."], ["والنخل باسقات", "النخيل الطوال العاليات."], ["لها طلع نضيد", "منضّد متراكب بعضه فوق بعض."], ["رزقاً للعباد", "قوتاً لهم، مؤمنهم وكافرهم."], ["وأحيينا به بلدة ميتاً", "أحيينا بذلك الماء بلدة لا نبات فيها من الجدب."], ["كذلك الخروج", "كما أخرجنا النبات من الأرض الميتة بالماء نخرجكم أحياء من قبوركم يوم القيامة بماء ننزله من السماء."]], "m": "ما زال السياق في تقرير عقيدة البعث، وهي العقيدة التي يُبنى عليها كل إصلاح يُراد للإنسان بعد الإيمان بالله: أعَمِي المنكرون للبعث فلم ينظروا بعيونهم وعقولهم إلى السماء الواسعة الرفيعة فوقهم، رُفعت بلا عمد، وزيّنها خالقها بكواكب منيرة، ولم يُرَ فيها تصدّع ولا شقوق على طول الحياة؟ أليس القادر على خلق السماء ابتداءً وعلى الإماتة قادراً على إحياء من خلق وأمات؟ وما لهم لا ينظرون إلى الأرض بسطها وألقى فيها الجبال لتثبيتها حتى لا تميد بهم، وأنبت فيها من كل صنف من النبات بهيّ المنظر، تبصرة وذكرى لكل عبد منيب؟ وأنزل من السماء ماءً مباركاً لما يكثر به من الخيرات والبركات، فأنبت به بساتين من أشجار ونخيل وأعناب، وحب الحصيد من قمح وشعير وذرة، والنخل العاليات لها طلعها المتراكب ليتحوّل إلى رطب يأكله الإنسان، قوتاً للعباد مؤمنين وكافرين، إلا أن المؤمن إذا أكل شكر والكافر إذا أكل كفر، وأحيا به بلدة ميتة لا عشب فيها فأصبحت تهتزّ رابية؛ كذلك يكون خروجكم من قبوركم أيها المنكرون للبعث: ينزل الله من السماء ماءً فتنبتون وتخرجون كما يخرج الزرع من الأرض، فبأي عقل تنكرون البعث؟ إنها لا تعمى الأبصار ولكن تعمى القلوب التي في الصدور.", "h": ["تقرير عقيدة البعث بمظاهر القدرة الإلهية في الكون.", "مشروعية النظر والاعتبار فيما يحيط بالإنسان من مظاهر الكون والحياة للعبرة، طلباً لزيادة الإيمان والوصول به إلى مستوى اليقين.", "فضل العبد المنيب وفضيلة الإنابة إلى الله تعالى، والمنيب هو الذي يرجع إلى ربه في كل ما يهمه، والإنابة التوبة إلى الله والرجوع إلى طاعته بعد معصيته."], "k": "«تبصرة وذكرى لكل عبد منيب»… النخلة والمطر يذكّرانني به؛ فهل أنظر إليهما بعين المنيب؟"}, {"lbl": "الآيات ١٢ – ١٥", "q": "كَذَّبَتۡ قَبۡلَهُمۡ قَوۡمُ نُوحٖ وَأَصۡحَٰبُ ٱلرَّسِّ وَثَمُودُ ﴿١٢﴾ وَعَادٞ وَفِرۡعَوۡنُ وَإِخۡوَٰنُ لُوطٖ ﴿١٣﴾ وَأَصۡحَٰبُ ٱلۡأَيۡكَةِ وَقَوۡمُ تُبَّعٖۚ كُلّٞ كَذَّبَ ٱلرُّسُلَ فَحَقَّ وَعِيدِ ﴿١٤﴾ أَفَعَيِينَا بِٱلۡخَلۡقِ ٱلۡأَوَّلِۚ بَلۡ هُمۡ فِي لَبۡسٖ مِّنۡ خَلۡقٖ جَدِيدٖ ﴿١٥﴾", "w": [["كذّبت قبلهم قوم نوح", "كذّبت قبل قومك يا رسولنا بالبعث والتوحيد والنبوة قوم نوح."], ["وأصحاب الرسّ وثمود", "أصحاب الرسّ، وهي بئر كانوا مقيمين حولها يعبدون الأصنام، وثمود أصحاب الحِجر قوم صالح."], ["وعاد وفرعون", "وكذّبت عاد قوم هود، وكذّب فرعون موسى ﵇."], ["وإخوان لوط وأصحاب الأيكة", "وكذّب قوم لوط أخاهم لوطاً، وكذّب أصحاب الأيكة شعيباً."], ["وقوم تُبّع", "قوم تُبّع الحِميري اليمني."], ["كلٌّ كذّب الرسل", "كل من ذُكر قد كذّب الرسل، فلست وحدك المكذَّب."], ["فحقّ وعيد", "وجب وعيدي لهم بنزول العذاب فنزل فهلكوا."], ["أفعيينا بالخلق الأول", "أعجزنا بخلق الناس أولاً؟ لا، فكيف نعجز عن إعادتهم كما كانوا؟"], ["بل هم في لبس من خلق جديد", "غير منكرين لقدرة الله على الخلق الأول، بل هم في خلط وشك من خلق جديد لمخالفته العادة."]], "m": "ما زال السياق في تقرير عقيدة البعث وإثبات النبوة: كذّبت قبل قريش قوم نوح، وهي أول أمة كذّبت، وعاش نوح فيها ألف سنة إلا خمسين عاماً يدعوها فلم يؤمن منهم أكثر من نيّف وثمانين نسمة، وأصحاب الرسّ أخذوا نبيهم فرسّوه في بئر فقتلوه فأهلكهم الله في تلك البئر، وثمود قوم صالح، وعاد قوم هود، وفرعون، وقوم لوط، وأصحاب الأيكة، أي الشجر الملتفّ، إذ كانوا يعبدون أشجارها، وقوم تُبّع الحِميري. كل تلك الأمم كذّبوا الرسل ولم يؤمنوا بما جاؤوهم به من التوحيد والشرع، فوجب لذلك عذابهم الذي توعّدتهم به على ألسنة رسلي فأهلكناهم أجمعين، وقومك يا محمد موعودون بالعذاب أيضاً إن لم يبادروا بالإيمان. أفعيينا بالخلق الأول؟ لا، لم يعجز الله عن خلق ما خلق من الملائكة والإنس والجن، فكيف يعجز بالإعادة وهي أهون من البدء؟ بل هم غير منكرين لقدرتنا على الخلق الأول، ولكنهم في خلط وشك من خلق جديد لمخالفته العادة، إذ يرون الناس يموتون ولا يحيون.", "h": ["تعزية الرسول ﷺ وتسليته بإعلامه بأن قومه ليسوا أول من كذّب الرسل.", "تهديد المصرّين على التكذيب من كفار قريش بالعذاب، إذ ليسوا بأفضل من غيرهم وقد أُهلكوا لما كذّبوا.", "تقرير البعث والجزاء، وإثبات عقيدتهما بالأدلة العقلية كبدء الخلق.", "ضعف إدراك المنكرين للبعث لظلمة نفوسهم بالشرك والمعاصي."], "k": "«أفعيينا بالخلق الأول»… الذي بدأني لن يعجزه أن يعيدني؛ فهل أستعد لذلك اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (386, 50, 16, 45, 'سورة ق ١٦ – ٤٥', 'ق: ونحن أقرب إليه من حبل الوريد', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 386) = $j$[{"lbl": "الآيات ١٦ – ٢٢", "q": "وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ وَنَعۡلَمُ مَا تُوَسۡوِسُ بِهِۦ نَفۡسُهُۥۖ وَنَحۡنُ أَقۡرَبُ إِلَيۡهِ مِنۡ حَبۡلِ ٱلۡوَرِيدِ ﴿١٦﴾ إِذۡ يَتَلَقَّى ٱلۡمُتَلَقِّيَانِ عَنِ ٱلۡيَمِينِ وَعَنِ ٱلشِّمَالِ قَعِيدٞ ﴿١٧﴾ مَّا يَلۡفِظُ مِن قَوۡلٍ إِلَّا لَدَيۡهِ رَقِيبٌ عَتِيدٞ ﴿١٨﴾ وَجَآءَتۡ سَكۡرَةُ ٱلۡمَوۡتِ بِٱلۡحَقِّۖ ذَٰلِكَ مَا كُنتَ مِنۡهُ تَحِيدُ ﴿١٩﴾ وَنُفِخَ فِي ٱلصُّورِۚ ذَٰلِكَ يَوۡمُ ٱلۡوَعِيدِ ﴿٢٠﴾ وَجَآءَتۡ كُلُّ نَفۡسٖ مَّعَهَا سَآئِقٞ وَشَهِيدٞ ﴿٢١﴾ لَّقَدۡ كُنتَ فِي غَفۡلَةٖ مِّنۡ هَٰذَا فَكَشَفۡنَا عَنكَ غِطَآءَكَ فَبَصَرُكَ ٱلۡيَوۡمَ حَدِيدٞ ﴿٢٢﴾", "w": [["ولقد خلقنا الإنسان", "خلقناه بقدرتنا وعلمنا لحكمة اقتضت خلقه، فلم نخلقه عبثاً."], ["ونعلم ما توسوس به نفسه", "نعلم ما تحدّث به نفسه من خواطر."], ["ونحن أقرب إليه من حبل الوريد", "نحن بقدرتنا على الأخذ منه والعطاء، وعلمنا بما يُسرّ ويُظهر، أقرب إليه من حبل الوريد الذي في عنقه."], ["إذ يتلقّى المتلقّيان", "حين يتلقّى الملكان الموكّلان به عمله فيكتبانه."], ["عن اليمين وعن الشمال قعيد", "أحدهما عن يمينه قاعد، والثاني عن شماله قاعد."], ["ما يلفظ من قول", "ما يقول من قول."], ["إلا لديه رقيب عتيد", "إلا عنده ملك رقيب حافظ، عتيد حاضر معدّ للكتابة."], ["وجاءت سكرة الموت بالحق", "غمرة الموت وشدّته بالحق من أمر الآخرة حتى يراه المنكر عياناً."], ["ذلك ما كنت منه تحيد", "ذلك الموت الذي كنت تهرب منه وتفزع."], ["ونُفخ في الصور", "نفخ إسرافيل في الصور، وهو القرن."], ["معها سائق وشهيد", "معها ملك يسوقها إلى المحشر، وملك يشهد عليها."], ["لقد كنت في غفلة من هذا", "من هذا العذاب النازل بك الآن."], ["فكشفنا عنك غطاءك", "أزلنا عنك غفلتك بما تشاهده اليوم."], ["فبصرك اليوم حديد", "حادّ تدرك به ما كنت تنكره في الدنيا من البعث والجزاء."]], "m": "ما زال السياق في تقرير عقيدة البعث والجزاء: ولقد خلقنا الإنسان بقدرتنا وعلمنا لحكمة اقتضت خلقه، ولم نخلقه عبثاً، ونحن نعلم ما تتحدث به نفسه من إرادات وخواطر، ونحن أقرب إليه من حبل الوريد؛ فلو أردنا أن نأخذ منه أو نعطيه أو نسمع منه أو نعلم به لكنا على ذلك قادرين، وذلك في الوقت الذي يتلقّى فيه الملكان سائر أقواله وأعماله يثبتانها ويحفظانها، أحدهما عن يمينه قاعد يكتب الحسنات، والثاني عن شماله قاعد يكتب السيئات. ما يقول الإنسان من قول إلا عنده ملك رقيب حافظ حاضر لا يفارقه مدى الحياة، إلا أنهما يتناوبان: ملكان بالنهار وملكان بالليل، ويجتمعون في صلاتي الصبح والعصر. وإن طال العمر فلا بد من الموت، وها هي ذي قد جاءت سكرة الموت أي غمرته وشدته بالحق من أمر الآخرة، حتى يراه المنكر للبعث عياناً، ويقال له: هذا الموت الذي كنت منه تهرب وتفزع. ونفخ إسرافيل في الصور نفخة البعث بعد نفخة الفناء، ذلك يوم الوعيد بالعذاب للكافرين، وجاءت كل نفس معها ملك يسوقها إلى المحشر وملك شاهد يشهد عليها، ويقال للكافر: لقد كنت في الدنيا في غفلة عن الآخرة وما فيها بشهواتك ولذّاتك وغرورك بالحياة الدنيا، فأزلنا عنك غفلتك بما تشاهده اليوم عياناً من ألوان العذاب، فبصرك اليوم حادّ تدرك به ما كنت تكفر به في الدنيا.", "h": ["بيان قدرة الله وعلمه، وأنه أقرب إلى الإنسان من حبل وريده، ألا فليتّقِ الله امرؤ.", "تقرير عقيدة أن لكل إنسان مكلّف ملكين يكتبان حسناته وسيئاته.", "بيان أن للموت سكرات قطعاً.", "ساعة الاحتضار يؤمن كل إنسان بالدار الآخرة، إذ يرى ما كان ينكره بعينه.", "تقرير عقيدة البعث والجزاء بعرض بعض أحوال الآخرة وأهوالها."], "k": "«ما يلفظ من قول إلا لديه رقيب عتيد»… كل كلمة أقولها اليوم مكتوبة؛ فهل أرضى أن أقرأها غداً؟"}, {"lbl": "الآيات ٢٣ – ٣٠", "q": "وَقَالَ قَرِينُهُۥ هَٰذَا مَا لَدَيَّ عَتِيدٌ ﴿٢٣﴾ أَلۡقِيَا فِي جَهَنَّمَ كُلَّ كَفَّارٍ عَنِيدٖ ﴿٢٤﴾ مَّنَّاعٖ لِّلۡخَيۡرِ مُعۡتَدٖ مُّرِيبٍ ﴿٢٥﴾ ٱلَّذِي جَعَلَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَأَلۡقِيَاهُ فِي ٱلۡعَذَابِ ٱلشَّدِيدِ ﴿٢٦﴾ ۞قَالَ قَرِينُهُۥ رَبَّنَا مَآ أَطۡغَيۡتُهُۥ وَلَٰكِن كَانَ فِي ضَلَٰلِۭ بَعِيدٖ ﴿٢٧﴾ قَالَ لَا تَخۡتَصِمُواْ لَدَيَّ وَقَدۡ قَدَّمۡتُ إِلَيۡكُم بِٱلۡوَعِيدِ ﴿٢٨﴾ مَا يُبَدَّلُ ٱلۡقَوۡلُ لَدَيَّ وَمَآ أَنَا۠ بِظَلَّـٰمٖ لِّلۡعَبِيدِ ﴿٢٩﴾ يَوۡمَ نَقُولُ لِجَهَنَّمَ هَلِ ٱمۡتَلَأۡتِ وَتَقُولُ هَلۡ مِن مَّزِيدٖ ﴿٣٠﴾", "w": [["وقال قرينه", "قال الملك الموكّل به."], ["هذا ما لديّ عتيد", "هذا عمله حاضر لديّ."], ["كل كفّار عنيد", "كثير الكفر والجحود لتوحيد الله ولقائه ورسوله، معاند كثير العناد."], ["منّاع للخير معتدٍ مريب", "منّاع للحقوق والواجبات من المال وغيره، معتدٍ على الناس، شاكّ في الدين."], ["الذي جعل مع الله إلهاً آخر", "أشرك بالله فجعل معه آلهة أخرى يعبدها."], ["ربنا ما أطغيته", "يقول قرينه من الشياطين: يا ربنا ما حملته على الطغيان."], ["ولكن كان في ضلال بعيد", "ولكن الرجل كان في ضلال بعيد عن كل هدى."], ["وقد قدّمت إليكم بالوعيد", "قدّمت إليكم وعيدي بالعذاب في كتبي وعلى ألسنة رسلي."], ["ما يُبدّل القول لديّ", "ما يُغيّر القول عندي، وهو قوله: لأملأنّ جهنم منكم أجمعين."], ["يوم نقول لجهنم هل امتلأت", "وما الله بظلّام للعبيد يوم يقول لجهنم: هل امتلأت؟"], ["وتقول هل من مزيد", "لم أمتلئ، هل من زيادة؟ فيضع الجبار عليها قدمه فتقول: قط قط."]], "m": "ما زال السياق في تقرير عقيدة البعث والجزاء بذكر مشاهد القيامة: قال قرين ذلك الكافر الذي جيء به إلى ساحة فصل القضاء، وهو الملك الموكّل بحفظ أعماله وكتابتها: هذا ما لديّ من أعماله حاضر. وهنا يقال للسائق والشهيد: ألقيا في جهنم كل كفّار عنيد منّاع للخير معتدٍ مريب؛ فهذه خمس صفات اجتمعت في شخص واحد فأوبقته: كفّار كثير الجحود لأركان الإيمان، وعنيد تارك لكل ما وجب عليه معاند في الحق، ومنّاع للخير لا يبذل معروفاً قط، ومعتدٍ على حدود الشرع وعلى الناس في أعراضهم وأموالهم وأبدانهم، ومريب شاكّ لا يصدّق بشيء من أمور الدين. والسادسة أسوأ تلك الصفات: اتخاذه إلهاً آخر يعبده دون الله، فألقياه في العذاب الشديد. ولما اعتذر المشرك بأن قرينه من الشياطين أطغاه، ردّ عليه القرين: ربنا ما أطغيته ولكن كان في ضلال بعيد. فقال الرب تعالى: لا تختصموا لديّ وقد قدّمت إليكم بالوعيد في كتبي وعلى ألسن رسلي أن من كفر بي وأشرك وعصى رسلي فله نار جهنم خالداً فيها. ما يُبدّل القول لديّ، إذ سبق قوله لإبليس: لأملأنّ جهنم منك وممن تبعك منهم أجمعين، وما أنا بظلّام للعبيد، والظلم أن يعذّب مطيعاً أو يدخل الجنة كافراً. اذكر يا نبينا لقومك يوم نقول لجهنم هل امتلأت بعدما يدخلها كل كافر وكافرة من الإنس والجن، فتقول طالبةً الزيادة: هل من مزيد؟ ولما لم يبق أحد يستحق النار يضع الجبار فيها قدمه فينزوي بعضها إلى بعض وتقول: قط قط، والحديث معناه في الصحيحين.", "h": ["تقرير عقيدة البعث والجزاء.", "التحذير من الصفات الست التي جاءت في الآيات.", "بيان خصومة أهل النار من إنسان وشيطان.", "نفي الظلم عن الله تعالى، فلا يظلم الله أحداً من خلقه.", "إثبات صفة القدم للرب تعالى كما يليق بذاته التي لا تشبه الذوات، سبحانه وتعالى عن صفات المحدثين من خلقه."], "k": "«منّاع للخير»… صفة من صفات أهل النار؛ فهل في يدي خير أمنعه وأنا أقدر عليه؟"}, {"lbl": "الآيات ٣١ – ٣٥", "q": "وَأُزۡلِفَتِ ٱلۡجَنَّةُ لِلۡمُتَّقِينَ غَيۡرَ بَعِيدٍ ﴿٣١﴾ هَٰذَا مَا تُوعَدُونَ لِكُلِّ أَوَّابٍ حَفِيظٖ ﴿٣٢﴾ مَّنۡ خَشِيَ ٱلرَّحۡمَٰنَ بِٱلۡغَيۡبِ وَجَآءَ بِقَلۡبٖ مُّنِيبٍ ﴿٣٣﴾ ٱدۡخُلُوهَا بِسَلَٰمٖۖ ذَٰلِكَ يَوۡمُ ٱلۡخُلُودِ ﴿٣٤﴾ لَهُم مَّا يَشَآءُونَ فِيهَا وَلَدَيۡنَا مَزِيدٞ ﴿٣٥﴾", "w": [["وأُزلفت الجنة للمتقين", "قُرّبت الجنة للمتقين الذين اتقوا الشرك والمعاصي."], ["غير بعيد", "مكاناً غير بعيد منهم بحيث يرونها."], ["لكل أوّاب حفيظ", "لكل رجّاع إلى طاعة الله، كلما ترك طاعة عاد إليها، حافظ لحدود الله."], ["من خشي الرحمن بالغيب", "خاف الله تعالى وهو لم يره فلم يعصه، وإن عصاه تاب إليه."], ["وجاء بقلب منيب", "مقبل على طاعته تعالى."], ["ادخلوها بسلام", "يقال للمتقين: ادخلوا الجنة مُسلَّماً عليكم، سالمين من كل مخوف."], ["ولدينا مزيد", "مزيد من الإنعام والتكريم في الجنة، وهو النظر إلى وجه الله الكريم."]], "m": "ما زال السياق في تقرير البعث والجزاء: بعد ما ذكر ما لأهل النار من عذاب قال تعالى: وأُدنيت الجنة وقُرّبت للمتقين في مكان غير بعيد، وهم الذين اتقوا الله بترك الشرك والمعاصي، فلا تركوا فريضة ولا غشوا كبيرة. ويقال لهم: هذا ما توعدون من النعيم المقيم لكل أوّاب رجّاع إلى طاعة الله، حفيظ لحدود الله، حفيظ أيضاً لذنوبه لا ينساها، كلما ذكرها استغفر الله منها؛ وهو من خاف الرحمن بالغيب وهو لا يراه فلم يعصه بترك واجب ولا بفعل حرام، وجاء بقلب منيب إلى ربه مقبل على طاعته بذكره فلا ينساه، ويطيعه فلا يعصيه. ويقال للمتقين: ادخلوا الجنة مُسلَّماً عليكم سالمين من كل مخوف كالموت والمرض والألم والحزن، ذلك يوم الخلود، فأهل الجنة خالدون فيها وأهل النار خالدون فيها. لهم فيها ما يشاؤون مما تشتهيه أنفسهم وتلذّه أعينهم، ولدينا مزيد من النعيم، وهو النظر إلى وجهه الكريم.", "h": ["فضل التقوى وكرامة المتقين على رب العالمين.", "فضل الأوّاب الحفيظ، وهو الذي كلما ذكر ذنبه استغفر ربه.", "بيان أكبر نعيم في الجنة، وهو رضا الله والنظر إلى وجهه الكريم."], "k": "«من خشي الرحمن بالغيب»… الخشية الحقيقية حين لا يراني أحد؛ فكيف أنا في خلوتي؟"}, {"lbl": "الآيات ٣٦ – ٤٥", "q": "وَكَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّن قَرۡنٍ هُمۡ أَشَدُّ مِنۡهُم بَطۡشٗا فَنَقَّبُواْ فِي ٱلۡبِلَٰدِ هَلۡ مِن مَّحِيصٍ ﴿٣٦﴾ إِنَّ فِي ذَٰلِكَ لَذِكۡرَىٰ لِمَن كَانَ لَهُۥ قَلۡبٌ أَوۡ أَلۡقَى ٱلسَّمۡعَ وَهُوَ شَهِيدٞ ﴿٣٧﴾ وَلَقَدۡ خَلَقۡنَا ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا فِي سِتَّةِ أَيَّامٖ وَمَا مَسَّنَا مِن لُّغُوبٖ ﴿٣٨﴾ فَٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ قَبۡلَ طُلُوعِ ٱلشَّمۡسِ وَقَبۡلَ ٱلۡغُرُوبِ ﴿٣٩﴾ وَمِنَ ٱلَّيۡلِ فَسَبِّحۡهُ وَأَدۡبَٰرَ ٱلسُّجُودِ ﴿٤٠﴾ وَٱسۡتَمِعۡ يَوۡمَ يُنَادِ ٱلۡمُنَادِ مِن مَّكَانٖ قَرِيبٖ ﴿٤١﴾ يَوۡمَ يَسۡمَعُونَ ٱلصَّيۡحَةَ بِٱلۡحَقِّۚ ذَٰلِكَ يَوۡمُ ٱلۡخُرُوجِ ﴿٤٢﴾ إِنَّا نَحۡنُ نُحۡيِۦ وَنُمِيتُ وَإِلَيۡنَا ٱلۡمَصِيرُ ﴿٤٣﴾ يَوۡمَ تَشَقَّقُ ٱلۡأَرۡضُ عَنۡهُمۡ سِرَاعٗاۚ ذَٰلِكَ حَشۡرٌ عَلَيۡنَا يَسِيرٞ ﴿٤٤﴾ نَّحۡنُ أَعۡلَمُ بِمَا يَقُولُونَۖ وَمَآ أَنتَ عَلَيۡهِم بِجَبَّارٖۖ فَذَكِّرۡ بِٱلۡقُرۡءَانِ مَن يَخَافُ وَعِيدِ ﴿٤٥﴾", "w": [["وكم أهلكنا قبلهم من قرن", "كثيراً من أهل القرون قبل كفار قريش أهلكناهم."], ["هم أشد منهم بطشاً", "أهل تلك القرون أشد قوة وأعظم أخذاً من كفار قريش، ومع هذا أهلكناهم."], ["فنقّبوا في البلاد هل من محيص", "بحثوا وفتّشوا في البلاد علّهم يجدون مهرباً من الهلاك فلم يجدوا."], ["إن في ذلك لذكرى", "إن في المذكور من إهلاك الأمم القوية موعظة."], ["لمن كان له قلب أو ألقى السمع", "الموعظة تحصل لمن له قلب حي، وألقى سمعه يستمع."], ["وهو شهيد", "حاضر القلب والحواس أثناء استماعه."], ["وما مسّنا من لغوب", "وما أصابنا من تعب."], ["فاصبر على ما يقولون", "فاصبر يا رسولنا على ما يقوله اليهود وغيرهم من التشبيه لله والتكذيب بصفاته."], ["وسبّح بحمد ربك قبل طلوع الشمس", "صلّ حامداً لربك قبل طلوع الشمس، وهي صلاة الصبح."], ["وقبل الغروب", "صلّ صلاة الظهر والعصر."], ["ومن الليل فسبّحه", "صلّ صلاتي المغرب والعشاء."], ["وأدبار السجود", "بعد أداء الفرائض سبّح بألفاظ الذكر والتسبيح."], ["يوم ينادِ المنادِ من مكان قريب", "يوم ينادي إسرافيل من مكان قريب من السماء، وهو صخرة بيت المقدس."], ["يوم يسمعون الصيحة بالحق", "نفخة إسرافيل الثانية، وهي نفخة البعث."], ["ذلك يوم الخروج", "أي من القبور."], ["يوم تشقّق الأرض عنهم سراعاً", "يخرجون من قبورهم مسرعين بعد تشقّقها عنهم."], ["ذلك حشر علينا يسير", "حشر الناس وجمعهم في موقف الحساب سهل علينا."], ["وما أنت عليهم بجبّار", "لست بحيث تجبرهم على الإيمان والتقوى."], ["فذكّر بالقرآن من يخاف وعيد", "عِظ بالقرآن مرغّباً مرهّباً، فاقرأه على المؤمنين، فهم الذين يخافون وعيد الله ويطمعون في وعده."]], "m": "بعد ذلك العرض العظيم لأحوال القيامة وأهوالها على كفار قريش المكذبين بالتوحيد والنبوة والبعث، أخبر تعالى رسوله أن إهلاكهم يسير، فكم أهلك قبلهم من قرن هم أشد منهم قوة وأخذاً، ولما جاءهم العذاب فرّوا يبحثون في البلاد عن ملجأ يلجؤون إليه فلم يجدوا. إن في ذلك لموعظة يتعظ بها عبد له قلب حي، وألقى سمعه يستمع وهو حاضر بكل مشاعره. ولقد خلقنا السماوات والأرض وما بينهما في ستة أيام، وما مسّنا من تعب؛ ردّ الله بهذا على اليهود الذين قالوا: أتمّ الله خلق السماوات والأرض يوم الجمعة واستراح يوم السبت، إذ التعب يلحق العامل من المباشرة، والله يخلق بكلمة التكوين، فلا معنى لأن يصيبه تعب. فاصبر يا رسولنا على ما يقوله اليهود وغيرهم من الكفر والباطل، واستعن على الصبر بالصلاة والتسبيح: قبل طلوع الشمس صلاة الصبح، وقبل الغروب صلاة الظهر والعصر، ومن الليل صلاة المغرب والعشاء، فشمل الإرشاد الصلوات الخمس، ولنعم العون على الصبر الصلاة، ولذا كان ﷺ إذا حزبه أمر فزع إلى الصلاة. وأدبار السجود: بعد الصلوات سبّح ربك بحمده، نحو: سبحان الله والحمد لله والله أكبر. واستمع أيها المخاطب يوم ينادي إسرافيل من صخرة بيت المقدس، وهي مكان قريب من السماء: أيتها العظام البالية والأوصال المتقطعة واللحوم المتمزقة والشعور المتفرقة، إن الله يأمركنّ أن تجتمعن لفصل القضاء. يوم يسمعون نفخة البعث بالحق، ذلك يوم الخروج من القبور، يوم تشقّق الأرض عنهم فيخرجون مسرعين، ذلك حشر علينا سهل لا صعوبة فيه. نحن أعلم بما يقولون، وفيه تسلية للرسول ﷺ وتهديد لكفار قريش، وما أنت عليهم بذي قوة تجبرهم بها على الإيمان، فمهمتك التذكير لا الإجبار، فذكّر بالقرآن من يخاف وعيد، وهم المؤمنون الصادقون.", "h": ["مشروعية تخويف العصاة والمكذبين بالعذاب، وقربه وعدم بعده.", "للانتفاع بالمواعظ شروط: أن يكون السامع ذا قلب حي واعٍ، وأن يُلقي بسمعه كاملاً، وأن يكون حاضر الحواس شهيدها.", "وجوب الصبر، والاستعانة على تحقيقه بالصلاة.", "مشروعية الذكر والدعاء بعد الصلاة فرادى لا جماعات.", "تقرير البعث وتفصيل مبادئه.", "المواعظ ينتفع بها أهل القلوب الحية."], "k": "«لمن كان له قلب أو ألقى السمع وهو شهيد»… أسمع القرآن كثيراً؛ فهل أسمعه بقلب حاضر؟"}]$j$::jsonb then 0 else 1 end;
