insert into public.tdb_cards(topic, i, body) select 386, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١٦ – ٢٢", "q": "وَلَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ وَنَعۡلَمُ مَا تُوَسۡوِسُ بِهِۦ نَفۡسُهُۥۖ وَنَحۡنُ أَقۡرَبُ إِلَيۡهِ مِنۡ حَبۡلِ ٱلۡوَرِيدِ ﴿١٦﴾ إِذۡ يَتَلَقَّى ٱلۡمُتَلَقِّيَانِ عَنِ ٱلۡيَمِينِ وَعَنِ ٱلشِّمَالِ قَعِيدٞ ﴿١٧﴾ مَّا يَلۡفِظُ مِن قَوۡلٍ إِلَّا لَدَيۡهِ رَقِيبٌ عَتِيدٞ ﴿١٨﴾ وَجَآءَتۡ سَكۡرَةُ ٱلۡمَوۡتِ بِٱلۡحَقِّۖ ذَٰلِكَ مَا كُنتَ مِنۡهُ تَحِيدُ ﴿١٩﴾ وَنُفِخَ فِي ٱلصُّورِۚ ذَٰلِكَ يَوۡمُ ٱلۡوَعِيدِ ﴿٢٠﴾ وَجَآءَتۡ كُلُّ نَفۡسٖ مَّعَهَا سَآئِقٞ وَشَهِيدٞ ﴿٢١﴾ لَّقَدۡ كُنتَ فِي غَفۡلَةٖ مِّنۡ هَٰذَا فَكَشَفۡنَا عَنكَ غِطَآءَكَ فَبَصَرُكَ ٱلۡيَوۡمَ حَدِيدٞ ﴿٢٢﴾", "w": [["ولقد خلقنا الإنسان", "خلقناه بقدرتنا وعلمنا لحكمة اقتضت خلقه، فلم نخلقه عبثاً."], ["ونعلم ما توسوس به نفسه", "نعلم ما تحدّث به نفسه من خواطر."], ["ونحن أقرب إليه من حبل الوريد", "نحن بقدرتنا على الأخذ منه والعطاء، وعلمنا بما يُسرّ ويُظهر، أقرب إليه من حبل الوريد الذي في عنقه."], ["إذ يتلقّى المتلقّيان", "حين يتلقّى الملكان الموكّلان به عمله فيكتبانه."], ["عن اليمين وعن الشمال قعيد", "أحدهما عن يمينه قاعد، والثاني عن شماله قاعد."], ["ما يلفظ من قول", "ما يقول من قول."], ["إلا لديه رقيب عتيد", "إلا عنده ملك رقيب حافظ، عتيد حاضر معدّ للكتابة."], ["وجاءت سكرة الموت بالحق", "غمرة الموت وشدّته بالحق من أمر الآخرة حتى يراه المنكر عياناً."], ["ذلك ما كنت منه تحيد", "ذلك الموت الذي كنت تهرب منه وتفزع."], ["ونُفخ في الصور", "نفخ إسرافيل في الصور، وهو القرن."], ["معها سائق وشهيد", "معها ملك يسوقها إلى المحشر، وملك يشهد عليها."], ["لقد كنت في غفلة من هذا", "من هذا العذاب النازل بك الآن."], ["فكشفنا عنك غطاءك", "أزلنا عنك غفلتك بما تشاهده اليوم."], ["فبصرك اليوم حديد", "حادّ تدرك به ما كنت تنكره في الدنيا من البعث والجزاء."]], "m": "ما زال السياق في تقرير عقيدة البعث والجزاء: ولقد خلقنا الإنسان بقدرتنا وعلمنا لحكمة اقتضت خلقه، ولم نخلقه عبثاً، ونحن نعلم ما تتحدث به نفسه من إرادات وخواطر، ونحن أقرب إليه من حبل الوريد؛ فلو أردنا أن نأخذ منه أو نعطيه أو نسمع منه أو نعلم به لكنا على ذلك قادرين، وذلك في الوقت الذي يتلقّى فيه الملكان سائر أقواله وأعماله يثبتانها ويحفظانها، أحدهما عن يمينه قاعد يكتب الحسنات، والثاني عن شماله قاعد يكتب السيئات. ما يقول الإنسان من قول إلا عنده ملك رقيب حافظ حاضر لا يفارقه مدى الحياة، إلا أنهما يتناوبان: ملكان بالنهار وملكان بالليل، ويجتمعون في صلاتي الصبح والعصر. وإن طال العمر فلا بد من الموت، وها هي ذي قد جاءت سكرة الموت أي غمرته وشدته بالحق من أمر الآخرة، حتى يراه المنكر للبعث عياناً، ويقال له: هذا الموت الذي كنت منه تهرب وتفزع. ونفخ إسرافيل في الصور نفخة البعث بعد نفخة الفناء، ذلك يوم الوعيد بالعذاب للكافرين، وجاءت كل نفس معها ملك يسوقها إلى المحشر وملك شاهد يشهد عليها، ويقال للكافر: لقد كنت في الدنيا في غفلة عن الآخرة وما فيها بشهواتك ولذّاتك وغرورك بالحياة الدنيا، فأزلنا عنك غفلتك بما تشاهده اليوم عياناً من ألوان العذاب، فبصرك اليوم حادّ تدرك به ما كنت تكفر به في الدنيا.", "h": ["بيان قدرة الله وعلمه، وأنه أقرب إلى الإنسان من حبل وريده، ألا فليتّقِ الله امرؤ.", "تقرير عقيدة أن لكل إنسان مكلّف ملكين يكتبان حسناته وسيئاته.", "بيان أن للموت سكرات قطعاً.", "ساعة الاحتضار يؤمن كل إنسان بالدار الآخرة، إذ يرى ما كان ينكره بعينه.", "تقرير عقيدة البعث والجزاء بعرض بعض أحوال الآخرة وأهوالها."], "k": "«ما يلفظ من قول إلا لديه رقيب عتيد»… كل كلمة أقولها اليوم مكتوبة؛ فهل أرضى أن أقرأها غداً؟"}, {"lbl": "الآيات ٢٣ – ٣٠", "q": "وَقَالَ قَرِينُهُۥ هَٰذَا مَا لَدَيَّ عَتِيدٌ ﴿٢٣﴾ أَلۡقِيَا فِي جَهَنَّمَ كُلَّ كَفَّارٍ عَنِيدٖ ﴿٢٤﴾ مَّنَّاعٖ لِّلۡخَيۡرِ مُعۡتَدٖ مُّرِيبٍ ﴿٢٥﴾ ٱلَّذِي جَعَلَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَأَلۡقِيَاهُ فِي ٱلۡعَذَابِ ٱلشَّدِيدِ ﴿٢٦﴾ ۞قَالَ قَرِينُهُۥ رَبَّنَا مَآ أَطۡغَيۡتُهُۥ وَلَٰكِن كَانَ فِي ضَلَٰلِۭ بَعِيدٖ ﴿٢٧﴾ قَالَ لَا تَخۡتَصِمُواْ لَدَيَّ وَقَدۡ قَدَّمۡتُ إِلَيۡكُم بِٱلۡوَعِيدِ ﴿٢٨﴾ مَا يُبَدَّلُ ٱلۡقَوۡلُ لَدَيَّ وَمَآ أَنَا۠ بِظَلَّـٰمٖ لِّلۡعَبِيدِ ﴿٢٩﴾ يَوۡمَ نَقُولُ لِجَهَنَّمَ هَلِ ٱمۡتَلَأۡتِ وَتَقُولُ هَلۡ مِن مَّزِيدٖ ﴿٣٠﴾", "w": [["وقال قرينه", "قال الملك الموكّل به."], ["هذا ما لديّ عتيد", "هذا عمله حاضر لديّ."], ["كل كفّار عنيد", "كثير الكفر والجحود لتوحيد الله ولقائه ورسوله، معاند كثير العناد."], ["منّاع للخير معتدٍ مريب", "منّاع للحقوق والواجبات من المال وغيره، معتدٍ على الناس، شاكّ في الدين."], ["الذي جعل مع الله إلهاً آخر", "أشرك بالله فجعل معه آلهة أخرى يعبدها."], ["ربنا ما أطغيته", "يقول قرينه من الشياطين: يا ربنا ما حملته على الطغيان."], ["ولكن كان في ضلال بعيد", "ولكن الرجل كان في ضلال بعيد عن كل هدى."], ["وقد قدّمت إليكم بالوعيد", "قدّمت إليكم وعيدي بالعذاب في كتبي وعلى ألسنة رسلي."], ["ما يُبدّل القول لديّ", "ما يُغيّر القول عندي، وهو قوله: لأملأنّ جهنم منكم أجمعين."], ["يوم نقول لجهنم هل امتلأت", "وما الله بظلّام للعبيد يوم يقول لجهنم: هل امتلأت؟"], ["وتقول هل من مزيد", "لم أمتلئ، هل من زيادة؟ فيضع الجبار عليها قدمه فتقول: قط قط."]], "m": "ما زال السياق في تقرير عقيدة البعث والجزاء بذكر مشاهد القيامة: قال قرين ذلك الكافر الذي جيء به إلى ساحة فصل القضاء، وهو الملك الموكّل بحفظ أعماله وكتابتها: هذا ما لديّ من أعماله حاضر. وهنا يقال للسائق والشهيد: ألقيا في جهنم كل كفّار عنيد منّاع للخير معتدٍ مريب؛ فهذه خمس صفات اجتمعت في شخص واحد فأوبقته: كفّار كثير الجحود لأركان الإيمان، وعنيد تارك لكل ما وجب عليه معاند في الحق، ومنّاع للخير لا يبذل معروفاً قط، ومعتدٍ على حدود الشرع وعلى الناس في أعراضهم وأموالهم وأبدانهم، ومريب شاكّ لا يصدّق بشيء من أمور الدين. والسادسة أسوأ تلك الصفات: اتخاذه إلهاً آخر يعبده دون الله، فألقياه في العذاب الشديد. ولما اعتذر المشرك بأن قرينه من الشياطين أطغاه، ردّ عليه القرين: ربنا ما أطغيته ولكن كان في ضلال بعيد. فقال الرب تعالى: لا تختصموا لديّ وقد قدّمت إليكم بالوعيد في كتبي وعلى ألسن رسلي أن من كفر بي وأشرك وعصى رسلي فله نار جهنم خالداً فيها. ما يُبدّل القول لديّ، إذ سبق قوله لإبليس: لأملأنّ جهنم منك وممن تبعك منهم أجمعين، وما أنا بظلّام للعبيد، والظلم أن يعذّب مطيعاً أو يدخل الجنة كافراً. اذكر يا نبينا لقومك يوم نقول لجهنم هل امتلأت بعدما يدخلها كل كافر وكافرة من الإنس والجن، فتقول طالبةً الزيادة: هل من مزيد؟ ولما لم يبق أحد يستحق النار يضع الجبار فيها قدمه فينزوي بعضها إلى بعض وتقول: قط قط، والحديث معناه في الصحيحين.", "h": ["تقرير عقيدة البعث والجزاء.", "التحذير من الصفات الست التي جاءت في الآيات.", "بيان خصومة أهل النار من إنسان وشيطان.", "نفي الظلم عن الله تعالى، فلا يظلم الله أحداً من خلقه.", "إثبات صفة القدم للرب تعالى كما يليق بذاته التي لا تشبه الذوات، سبحانه وتعالى عن صفات المحدثين من خلقه."], "k": "«منّاع للخير»… صفة من صفات أهل النار؛ فهل في يدي خير أمنعه وأنا أقدر عليه؟"}, {"lbl": "الآيات ٣١ – ٣٥", "q": "وَأُزۡلِفَتِ ٱلۡجَنَّةُ لِلۡمُتَّقِينَ غَيۡرَ بَعِيدٍ ﴿٣١﴾ هَٰذَا مَا تُوعَدُونَ لِكُلِّ أَوَّابٍ حَفِيظٖ ﴿٣٢﴾ مَّنۡ خَشِيَ ٱلرَّحۡمَٰنَ بِٱلۡغَيۡبِ وَجَآءَ بِقَلۡبٖ مُّنِيبٍ ﴿٣٣﴾ ٱدۡخُلُوهَا بِسَلَٰمٖۖ ذَٰلِكَ يَوۡمُ ٱلۡخُلُودِ ﴿٣٤﴾ لَهُم مَّا يَشَآءُونَ فِيهَا وَلَدَيۡنَا مَزِيدٞ ﴿٣٥﴾", "w": [["وأُزلفت الجنة للمتقين", "قُرّبت الجنة للمتقين الذين اتقوا الشرك والمعاصي."], ["غير بعيد", "مكاناً غير بعيد منهم بحيث يرونها."], ["لكل أوّاب حفيظ", "لكل رجّاع إلى طاعة الله، كلما ترك طاعة عاد إليها، حافظ لحدود الله."], ["من خشي الرحمن بالغيب", "خاف الله تعالى وهو لم يره فلم يعصه، وإن عصاه تاب إليه."], ["وجاء بقلب منيب", "مقبل على طاعته تعالى."], ["ادخلوها بسلام", "يقال للمتقين: ادخلوا الجنة مُسلَّماً عليكم، سالمين من كل مخوف."], ["ولدينا مزيد", "مزيد من الإنعام والتكريم في الجنة، وهو النظر إلى وجه الله الكريم."]], "m": "ما زال السياق في تقرير البعث والجزاء: بعد ما ذكر ما لأهل النار من عذاب قال تعالى: وأُدنيت الجنة وقُرّبت للمتقين في مكان غير بعيد، وهم الذين اتقوا الله بترك الشرك والمعاصي، فلا تركوا فريضة ولا غشوا كبيرة. ويقال لهم: هذا ما توعدون من النعيم المقيم لكل أوّاب رجّاع إلى طاعة الله، حفيظ لحدود الله، حفيظ أيضاً لذنوبه لا ينساها، كلما ذكرها استغفر الله منها؛ وهو من خاف الرحمن بالغيب وهو لا يراه فلم يعصه بترك واجب ولا بفعل حرام، وجاء بقلب منيب إلى ربه مقبل على طاعته بذكره فلا ينساه، ويطيعه فلا يعصيه. ويقال للمتقين: ادخلوا الجنة مُسلَّماً عليكم سالمين من كل مخوف كالموت والمرض والألم والحزن، ذلك يوم الخلود، فأهل الجنة خالدون فيها وأهل النار خالدون فيها. لهم فيها ما يشاؤون مما تشتهيه أنفسهم وتلذّه أعينهم، ولدينا مزيد من النعيم، وهو النظر إلى وجهه الكريم.", "h": ["فضل التقوى وكرامة المتقين على رب العالمين.", "فضل الأوّاب الحفيظ، وهو الذي كلما ذكر ذنبه استغفر ربه.", "بيان أكبر نعيم في الجنة، وهو رضا الله والنظر إلى وجهه الكريم."], "k": "«من خشي الرحمن بالغيب»… الخشية الحقيقية حين لا يراني أحد؛ فكيف أنا في خلوتي؟"}, {"lbl": "الآيات ٣٦ – ٤٥", "q": "وَكَمۡ أَهۡلَكۡنَا قَبۡلَهُم مِّن قَرۡنٍ هُمۡ أَشَدُّ مِنۡهُم بَطۡشٗا فَنَقَّبُواْ فِي ٱلۡبِلَٰدِ هَلۡ مِن مَّحِيصٍ ﴿٣٦﴾ إِنَّ فِي ذَٰلِكَ لَذِكۡرَىٰ لِمَن كَانَ لَهُۥ قَلۡبٌ أَوۡ أَلۡقَى ٱلسَّمۡعَ وَهُوَ شَهِيدٞ ﴿٣٧﴾ وَلَقَدۡ خَلَقۡنَا ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ وَمَا بَيۡنَهُمَا فِي سِتَّةِ أَيَّامٖ وَمَا مَسَّنَا مِن لُّغُوبٖ ﴿٣٨﴾ فَٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَسَبِّحۡ بِحَمۡدِ رَبِّكَ قَبۡلَ طُلُوعِ ٱلشَّمۡسِ وَقَبۡلَ ٱلۡغُرُوبِ ﴿٣٩﴾ وَمِنَ ٱلَّيۡلِ فَسَبِّحۡهُ وَأَدۡبَٰرَ ٱلسُّجُودِ ﴿٤٠﴾ وَٱسۡتَمِعۡ يَوۡمَ يُنَادِ ٱلۡمُنَادِ مِن مَّكَانٖ قَرِيبٖ ﴿٤١﴾ يَوۡمَ يَسۡمَعُونَ ٱلصَّيۡحَةَ بِٱلۡحَقِّۚ ذَٰلِكَ يَوۡمُ ٱلۡخُرُوجِ ﴿٤٢﴾ إِنَّا نَحۡنُ نُحۡيِۦ وَنُمِيتُ وَإِلَيۡنَا ٱلۡمَصِيرُ ﴿٤٣﴾ يَوۡمَ تَشَقَّقُ ٱلۡأَرۡضُ عَنۡهُمۡ سِرَاعٗاۚ ذَٰلِكَ حَشۡرٌ عَلَيۡنَا يَسِيرٞ ﴿٤٤﴾ نَّحۡنُ أَعۡلَمُ بِمَا يَقُولُونَۖ وَمَآ أَنتَ عَلَيۡهِم بِجَبَّارٖۖ فَذَكِّرۡ بِٱلۡقُرۡءَانِ مَن يَخَافُ وَعِيدِ ﴿٤٥﴾", "w": [["وكم أهلكنا قبلهم من قرن", "كثيراً من أهل القرون قبل كفار قريش أهلكناهم."], ["هم أشد منهم بطشاً", "أهل تلك القرون أشد قوة وأعظم أخذاً من كفار قريش، ومع هذا أهلكناهم."], ["فنقّبوا في البلاد هل من محيص", "بحثوا وفتّشوا في البلاد علّهم يجدون مهرباً من الهلاك فلم يجدوا."], ["إن في ذلك لذكرى", "إن في المذكور من إهلاك الأمم القوية موعظة."], ["لمن كان له قلب أو ألقى السمع", "الموعظة تحصل لمن له قلب حي، وألقى سمعه يستمع."], ["وهو شهيد", "حاضر القلب والحواس أثناء استماعه."], ["وما مسّنا من لغوب", "وما أصابنا من تعب."], ["فاصبر على ما يقولون", "فاصبر يا رسولنا على ما يقوله اليهود وغيرهم من التشبيه لله والتكذيب بصفاته."], ["وسبّح بحمد ربك قبل طلوع الشمس", "صلّ حامداً لربك قبل طلوع الشمس، وهي صلاة الصبح."], ["وقبل الغروب", "صلّ صلاة الظهر والعصر."], ["ومن الليل فسبّحه", "صلّ صلاتي المغرب والعشاء."], ["وأدبار السجود", "بعد أداء الفرائض سبّح بألفاظ الذكر والتسبيح."], ["يوم ينادِ المنادِ من مكان قريب", "يوم ينادي إسرافيل من مكان قريب من السماء، وهو صخرة بيت المقدس."], ["يوم يسمعون الصيحة بالحق", "نفخة إسرافيل الثانية، وهي نفخة البعث."], ["ذلك يوم الخروج", "أي من القبور."], ["يوم تشقّق الأرض عنهم سراعاً", "يخرجون من قبورهم مسرعين بعد تشقّقها عنهم."], ["ذلك حشر علينا يسير", "حشر الناس وجمعهم في موقف الحساب سهل علينا."], ["وما أنت عليهم بجبّار", "لست بحيث تجبرهم على الإيمان والتقوى."], ["فذكّر بالقرآن من يخاف وعيد", "عِظ بالقرآن مرغّباً مرهّباً، فاقرأه على المؤمنين، فهم الذين يخافون وعيد الله ويطمعون في وعده."]], "m": "بعد ذلك العرض العظيم لأحوال القيامة وأهوالها على كفار قريش المكذبين بالتوحيد والنبوة والبعث، أخبر تعالى رسوله أن إهلاكهم يسير، فكم أهلك قبلهم من قرن هم أشد منهم قوة وأخذاً، ولما جاءهم العذاب فرّوا يبحثون في البلاد عن ملجأ يلجؤون إليه فلم يجدوا. إن في ذلك لموعظة يتعظ بها عبد له قلب حي، وألقى سمعه يستمع وهو حاضر بكل مشاعره. ولقد خلقنا السماوات والأرض وما بينهما في ستة أيام، وما مسّنا من تعب؛ ردّ الله بهذا على اليهود الذين قالوا: أتمّ الله خلق السماوات والأرض يوم الجمعة واستراح يوم السبت، إذ التعب يلحق العامل من المباشرة، والله يخلق بكلمة التكوين، فلا معنى لأن يصيبه تعب. فاصبر يا رسولنا على ما يقوله اليهود وغيرهم من الكفر والباطل، واستعن على الصبر بالصلاة والتسبيح: قبل طلوع الشمس صلاة الصبح، وقبل الغروب صلاة الظهر والعصر، ومن الليل صلاة المغرب والعشاء، فشمل الإرشاد الصلوات الخمس، ولنعم العون على الصبر الصلاة، ولذا كان ﷺ إذا حزبه أمر فزع إلى الصلاة. وأدبار السجود: بعد الصلوات سبّح ربك بحمده، نحو: سبحان الله والحمد لله والله أكبر. واستمع أيها المخاطب يوم ينادي إسرافيل من صخرة بيت المقدس، وهي مكان قريب من السماء: أيتها العظام البالية والأوصال المتقطعة واللحوم المتمزقة والشعور المتفرقة، إن الله يأمركنّ أن تجتمعن لفصل القضاء. يوم يسمعون نفخة البعث بالحق، ذلك يوم الخروج من القبور، يوم تشقّق الأرض عنهم فيخرجون مسرعين، ذلك حشر علينا سهل لا صعوبة فيه. نحن أعلم بما يقولون، وفيه تسلية للرسول ﷺ وتهديد لكفار قريش، وما أنت عليهم بذي قوة تجبرهم بها على الإيمان، فمهمتك التذكير لا الإجبار، فذكّر بالقرآن من يخاف وعيد، وهم المؤمنون الصادقون.", "h": ["مشروعية تخويف العصاة والمكذبين بالعذاب، وقربه وعدم بعده.", "للانتفاع بالمواعظ شروط: أن يكون السامع ذا قلب حي واعٍ، وأن يُلقي بسمعه كاملاً، وأن يكون حاضر الحواس شهيدها.", "وجوب الصبر، والاستعانة على تحقيقه بالصلاة.", "مشروعية الذكر والدعاء بعد الصلاة فرادى لا جماعات.", "تقرير البعث وتفصيل مبادئه.", "المواعظ ينتفع بها أهل القلوب الحية."], "k": "«لمن كان له قلب أو ألقى السمع وهو شهيد»… أسمع القرآن كثيراً؛ فهل أسمعه بقلب حاضر؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (387, 51, 1, 30, 'سورة الذاريات ١ – ٣٠', 'الذاريات: وفي أنفسكم أفلا تبصرون', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 387) = $j$[{"lbl": "الآيات ١ – ١٤", "q": "وَٱلذَّـٰرِيَٰتِ ذَرۡوٗا ﴿١﴾ فَٱلۡحَٰمِلَٰتِ وِقۡرٗا ﴿٢﴾ فَٱلۡجَٰرِيَٰتِ يُسۡرٗا ﴿٣﴾ فَٱلۡمُقَسِّمَٰتِ أَمۡرًا ﴿٤﴾ إِنَّمَا تُوعَدُونَ لَصَادِقٞ ﴿٥﴾ وَإِنَّ ٱلدِّينَ لَوَٰقِعٞ ﴿٦﴾ وَٱلسَّمَآءِ ذَاتِ ٱلۡحُبُكِ ﴿٧﴾ إِنَّكُمۡ لَفِي قَوۡلٖ مُّخۡتَلِفٖ ﴿٨﴾ يُؤۡفَكُ عَنۡهُ مَنۡ أُفِكَ ﴿٩﴾ قُتِلَ ٱلۡخَرَّـٰصُونَ ﴿١٠﴾ ٱلَّذِينَ هُمۡ فِي غَمۡرَةٖ سَاهُونَ ﴿١١﴾ يَسۡـَٔلُونَ أَيَّانَ يَوۡمُ ٱلدِّينِ ﴿١٢﴾ يَوۡمَ هُمۡ عَلَى ٱلنَّارِ يُفۡتَنُونَ ﴿١٣﴾ ذُوقُواْ فِتۡنَتَكُمۡ هَٰذَا ٱلَّذِي كُنتُم بِهِۦ تَسۡتَعۡجِلُونَ ﴿١٤﴾", "w": [["والذاريات ذرواً", "الرياح تذرو التراب وغيره ذرواً."], ["فالحاملات وِقراً", "السحب تحمل الماء."], ["فالجاريات يُسراً", "السفن تجري على سطح الماء بسهولة."], ["فالمقسّمات أمراً", "الملائكة تقسم بأمر ربها الأرزاق والأمطار وغيرها بين العباد."], ["إنما توعدون لصادق", "إن ما وعدكم به ربكم لصادق، سواء كان خيراً أو شراً."], ["وإن الدين لواقع", "وإن الجزاء بعد الحساب لواقع لا محالة."], ["والسماء ذات الحُبُك", "ذات الطرق كالطرق التي تكون على الرمل."], ["إنكم لفي قول مختلف", "يا أهل مكة، إنكم في شأن القرآن والنبي ﷺ لفي قول مختلف: فمنكم من يقول سحر، ومنكم من يقول شعر أو كهانة."], ["يُؤفك عنه من أُفك", "يُصرف عن النبي والقرآن من صُرف."], ["قُتل الخرّاصون", "لُعن الكذابون الذين يقولون بالخرص والكذب."], ["الذين هم في غمرة ساهون", "في غمرة جهل تغمرهم، غافلون عن أمر الآخرة."], ["يسألون أيّان يوم الدين", "يسألون النبي ﷺ سؤال استهزاء: متى يوم القيامة؟"], ["يوم هم على النار يُفتنون", "يُعذّبون فيها."]], "m": "هذا شروع في قسم ضخم أقسم الله تعالى به: والذاريات ذرواً، أي الرياح تذرو التراب وغيره من الأشياء الخفيفة، فالحاملات وقراً أي السحب تحمل الماء، فالجاريات يسراً أي السفن، فالمقسّمات أمراً أي الملائكة تقسم الأرزاق والأمطار وغيرها بأمر ربها. وجواب القسم: إنما توعدون أيها الناس من البعث والجزاء بالنعيم المقيم أو بعذاب الجحيم لصادق، وإن الجزاء العادل لكائن لا محالة. والسماء ذات الحبك قسم آخر، أي ذات الطرق كالتي على الرمل، وجوابه: إنكم لفي قول مختلف؛ فمنكم من يقول محمد ساحر، ومنكم من يقول كاذب أو كاهن، ومنكم من يقول في القرآن سحر وشعر وكهانة. يُصرف عن القرآن ومن نزل عليه من صُرف بقضاء الله وقدره. لُعن الكذابون الذين يقولون بالخرص والكذب والظن، الذين هم في غمرة جهل تغمرهم، غافلون عن أمر الآخرة وما لهم فيه من عذاب. يسألون متى قيام الساعة وهم في هذا مستهزئون ساخرون، وجوابهم: يوم هم على النار يُعذّبون، ويقال لهم: ذوقوا عذابكم هذا الذي كنتم تطالبون رسولنا بتعجيله لكم استخفافاً وتكذيباً.", "h": ["تقرير عقيدة البعث والجزاء، حيث أقسم تعالى على ذلك.", "تقرير عقيدة القضاء والقدر في قوله: «يؤفك عنه من أفك».", "بيان لعن الخرّاصين الذين يقولون بالخرص والكذب، ويسألون استهزاءً وسخرية لا طلباً للعلم والمعرفة للعمل."], "k": "«الذين هم في غمرة ساهون»… الغفلة تغمر الإنسان وهو لا يشعر؛ فهل أنا منتبه أم ساهٍ؟"}, {"lbl": "الآيات ١٥ – ٢٣", "q": "إِنَّ ٱلۡمُتَّقِينَ فِي جَنَّـٰتٖ وَعُيُونٍ ﴿١٥﴾ ءَاخِذِينَ مَآ ءَاتَىٰهُمۡ رَبُّهُمۡۚ إِنَّهُمۡ كَانُواْ قَبۡلَ ذَٰلِكَ مُحۡسِنِينَ ﴿١٦﴾ كَانُواْ قَلِيلٗا مِّنَ ٱلَّيۡلِ مَا يَهۡجَعُونَ ﴿١٧﴾ وَبِٱلۡأَسۡحَارِ هُمۡ يَسۡتَغۡفِرُونَ ﴿١٨﴾ وَفِيٓ أَمۡوَٰلِهِمۡ حَقّٞ لِّلسَّآئِلِ وَٱلۡمَحۡرُومِ ﴿١٩﴾ وَفِي ٱلۡأَرۡضِ ءَايَٰتٞ لِّلۡمُوقِنِينَ ﴿٢٠﴾ وَفِيٓ أَنفُسِكُمۡۚ أَفَلَا تُبۡصِرُونَ ﴿٢١﴾ وَفِي ٱلسَّمَآءِ رِزۡقُكُمۡ وَمَا تُوعَدُونَ ﴿٢٢﴾ فَوَرَبِّ ٱلسَّمَآءِ وَٱلۡأَرۡضِ إِنَّهُۥ لَحَقّٞ مِّثۡلَ مَآ أَنَّكُمۡ تَنطِقُونَ ﴿٢٣﴾", "w": [["إن المتقين في جنات وعيون", "إن الذين اتقوا ربهم في بساتين، وعيون تجري خلالها."], ["آخذين ما آتاهم ربهم", "آخذين ما أعطاهم ربهم من الثواب."], ["إنهم كانوا قبل ذلك محسنين", "كانوا قبل دخولهم الجنة محسنين في الدنيا في عبادة ربهم وإلى عباده."], ["كانوا قليلاً من الليل ما يهجعون", "كانوا في الدنيا يحيون الليل ولا ينامون فيه إلا قليلاً."], ["وبالأسحار هم يستغفرون", "وفي وقت السحر، وهو السدس الأخير من الليل، يستغفرون يقولون: ربنا اغفر لنا."], ["وفي أموالهم حق للسائل والمحروم", "للذي يسأل، والمحروم الذي لا يسأل لتعفّفه، وهذا حق أوجبوه على أنفسهم زيادة على الزكاة الواجبة."], ["وفي الأرض آيات للموقنين", "من الجبال والأنهار والأشجار والبحار والإنسان والحيوان دلالات على قدرة الله، مقتضية للبعث وموجبة للتوحيد."], ["وفي أنفسكم أفلا تبصرون", "آيات من الخلق والتركيب والسمع والبصر والتعقّل والتحرك، أفلا تبصرون ذلك فتستدلون به على وجود الله وعلمه؟"], ["وفي السماء رزقكم وما توعدون", "من الأمطار التي بها الزرع وسائر الأقوات، وما توعدون من ثواب وعقاب، كل ذلك عند الله في السماء مكتوب في اللوح المحفوظ."], ["فوربّ السماء والأرض إنه لحق", "ما توعدون لحق ثابت."], ["مثل ما أنكم تنطقون", "إن البعث لحق مثل نطقكم؛ فهل يشك أحد في نطقه إذا نطق؟ فكذلك ما توعدون."]], "m": "ما زال السياق في تقرير عقيدة البعث والجزاء التي كذّب بها المشركون في مكة: إن الذين اتقوا ربهم فلم يشركوا به ولم يعصوه بترك الواجبات ولا بفعل المحرمات، هؤلاء يوم القيامة في بساتين وعيون تجري فيها، آخذين ما أعطاهم ربهم من ثواب ونعيم مقيم في دار السلام. ثم ذكر تعالى مقتضيات هذا العطاء العظيم: إنهم كانوا قبل دخولهم الجنة محسنين في الدنيا، أحسنوا نياتهم وأعمالهم فأخلصوها لربهم وأتوا بها وفق ما شرعه بلا زيادة ولا نقصان، كما أحسنوا إلى عباده ولم يسيئوا إليهم بقول ولا عمل. وثانيها: أنهم كانوا لا ينامون من الليل إلا قليلاً، إذ أكثر الليل يقضونه في الصلاة، وفي السدس الأخير من الليل يستغفرون: ربنا اغفر لنا ذنوبنا وقنا عذاب النار. وثالثها: أنهم أوجبوا على أنفسهم في أموالهم، زيادة على الزكاة المفروضة، حقاً يبذلونه للسائل والمحروم الذي لا يسأل لحيائه وعفّته. وفيما خُلق في الأرض من جبال وأنهار وزروع وضروع وثمار وإنسان وحيوان دلائل على قدرة الله وعلمه وحكمته ورحمته، موجبة لتوحيده ومقررة لقدرته على البعث والجزاء؛ وكونها للموقنين لأنهم ذوو بصائر، كلما نظروا إلى آية ازداد إيمانهم حتى بلغوا اليقين. وفي أنفسكم أيها الناس دلائل في خلق الإنسان وأطواره من نطفة إلى علقة إلى مضغة إلى طفل إلى شاب فكهل، وفي إدراكه وسمعه وبصره ونطقه، وقوله: أفلا تبصرون توبيخ لأهل الغفلة والإعراض عن التفكر. وفي السماء رزقكم، يريد تدبير الأمر والأمطار التي هي سبب الثمار والحبوب، وما توعدون من خير وشر، إذ الأمر لله وكتاب المقادير في السماء. ثم أقسم تعالى بنفسه أن البعث والجزاء حق ثابت كائن لا محالة؛ فكما لا نشك في نطقنا إذا نطقنا، فكذلك البعث واقع لا محالة.", "h": ["بيان ما للمتقين من نعيم مقيم في الدار الآخرة.", "بيان صفات المتقين من التهجد بالليل والاستغفار في آخره والإنفاق في سبيل الله.", "بيان أن في الأرض كما في الأنفس آيات، أي دلائل وعلامات على قدرة الله على البعث.", "بيان أن في السماء رزق العباد، فلا يُطلب إلا من الله تعالى، وأن ما يُوعَدونه من خير وشر أمره في السماء ومنها ينزل بأمره، فليكن طلبنا الخير من الله دائماً، وتعوّذنا من الشر بالله وحده."], "k": "«وبالأسحار هم يستغفرون»… يقومون الليل ثم يستغفرون كأنهم مقصّرون؛ فكيف بي؟"}, {"lbl": "الآيات ٢٤ – ٣٠", "q": "هَلۡ أَتَىٰكَ حَدِيثُ ضَيۡفِ إِبۡرَٰهِيمَ ٱلۡمُكۡرَمِينَ ﴿٢٤﴾ إِذۡ دَخَلُواْ عَلَيۡهِ فَقَالُواْ سَلَٰمٗاۖ قَالَ سَلَٰمٞ قَوۡمٞ مُّنكَرُونَ ﴿٢٥﴾ فَرَاغَ إِلَىٰٓ أَهۡلِهِۦ فَجَآءَ بِعِجۡلٖ سَمِينٖ ﴿٢٦﴾ فَقَرَّبَهُۥٓ إِلَيۡهِمۡ قَالَ أَلَا تَأۡكُلُونَ ﴿٢٧﴾ فَأَوۡجَسَ مِنۡهُمۡ خِيفَةٗۖ قَالُواْ لَا تَخَفۡۖ وَبَشَّرُوهُ بِغُلَٰمٍ عَلِيمٖ ﴿٢٨﴾ فَأَقۡبَلَتِ ٱمۡرَأَتُهُۥ فِي صَرَّةٖ فَصَكَّتۡ وَجۡهَهَا وَقَالَتۡ عَجُوزٌ عَقِيمٞ ﴿٢٩﴾ قَالُواْ كَذَٰلِكِ قَالَ رَبُّكِۖ إِنَّهُۥ هُوَ ٱلۡحَكِيمُ ٱلۡعَلِيمُ ﴿٣٠﴾", "w": [["هل أتاك حديث", "قد أتاك يا نبينا حديث، أي كلام."], ["ضيف إبراهيم المكرمين", "جبريل وميكائيل وإسرافيل، أكرمهم إبراهيم الخليل."], ["قال سلام قوم منكرون", "عليكم سلام، أنتم قوم منكرون، أي غير معروفين."], ["فراغ إلى أهله فجاء بعجل سمين", "عدل ومال إلى أهله فجاء بعجل سمين حنيذ."], ["فقال ألا تأكلون", "أمسكوا عن الأكل فقال لهم: ألا تأكلون؟"], ["فأوجس منهم خيفة", "أضمر في نفسه خوفاً منهم."], ["بغلام عليم", "بولد يكون ذا علم كبير غزير."], ["فأقبلت امرأته في صرّة", "في صيحة."], ["فصكّت وجهها", "لطمت وجهها، أي ضربت بأصابعها جبينها متعجبة."], ["وقالت عجوز عقيم", "كبيرة السن، وعقيم لم يولد لها قط."], ["قالوا كذلك قال ربك", "قالت الملائكة لها: كالذي قلنا لكِ قال ربك."], ["إنه هو الحكيم العليم", "الحكيم في تدبيره وتصريف شؤون عباده، العليم بما يصلح للعبد وما لا يصلح، فليفوّض الأمر إليه."]], "m": "هذا الحديث يشتمل على موجز قصة ذُكرت في سورتي هود والحجر، والمقصود منه تقرير نبوة محمد ﷺ، إذ مثل هذا القصص لا يتم لأمّي لا يقرأ ولا يكتب إلا من طريق الوحي، كما يحمل في نهايته التهديد بالوعيد لمشركي قريش المصرين على الكفر والتكذيب، إذ يجيب الملائكة إبراهيم بأنهم أُرسلوا إلى قوم مجرمين لإهلاكهم من أجل إجرامهم. قد أتاك يا نبينا حديث ضيف إبراهيم الخليل، وهم ملائكة في صورة رجال، إذ دخلوا عليه في منزله فسلّموا عليه فردّ السلام ثم قال: أنتم قوم غرباء لستم من أهل هذا البلد، فلذا سارع في إكرامهم، فمال إلى أهله فعمد إلى عجل سمين من أبقاره فشواه بعد ذبحه وقرّبه إليهم، فأمسكوا عن تناوله فعرض عليهم الأكل بقوله: ألا تأكلون؟ ولما لم يأكلوا شعر بالخوف في نفسه منهم، لأن العادة البشرية أن المرء إذا أراد بأخيه سوءاً لا يأكل طعامه، وهذا حكم غالبي وليس عاماً. قالوا: لا تخف، وأعلموه أنهم مرسلون من ربه إلى قوم لوط لإهلاكهم، وبشّروه بغلام يولد له، وهو إسحاق. فأقبلت امرأته في صيحة لما سمعت البشرى، فلطمت وجهها بأصابع يدها متعجبة وقالت: عجوز عقيم كيف ألد؟ إذ كان عمرها تجاوز التسعين وعمر إبراهيم تجاوز المئة، وكانت عقيماً لا تلد قط. فأجابها الملائكة: هكذا قال ربك فاقبلي البشرى واحمديه واشكريه، إنه هو الحكيم في تصرفاته في شؤون عباده، العليم بما يصلح لهم وما لا يصلح، فليفوَّض الأمر إليه ولا يُعترض عليه.", "h": ["تقرير النبوة المحمدية.", "فضيلة إبراهيم ﵇ أبي الأنبياء وإمام الموحدين.", "وجوب إكرام الضيف.", "الخوف الفطري عند وجود أسبابه لا يقدح في العقيدة ولا يُعدّ شركاً."], "k": "«فراغ إلى أهله فجاء بعجل سمين»… أكرم ضيوفاً لا يعرفهم بأحسن ما عنده؛ فكيف أستقبل ضيفي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 387;
insert into public.tdb_cards(topic, i, body) select 387, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ١٤", "q": "وَٱلذَّـٰرِيَٰتِ ذَرۡوٗا ﴿١﴾ فَٱلۡحَٰمِلَٰتِ وِقۡرٗا ﴿٢﴾ فَٱلۡجَٰرِيَٰتِ يُسۡرٗا ﴿٣﴾ فَٱلۡمُقَسِّمَٰتِ أَمۡرًا ﴿٤﴾ إِنَّمَا تُوعَدُونَ لَصَادِقٞ ﴿٥﴾ وَإِنَّ ٱلدِّينَ لَوَٰقِعٞ ﴿٦﴾ وَٱلسَّمَآءِ ذَاتِ ٱلۡحُبُكِ ﴿٧﴾ إِنَّكُمۡ لَفِي قَوۡلٖ مُّخۡتَلِفٖ ﴿٨﴾ يُؤۡفَكُ عَنۡهُ مَنۡ أُفِكَ ﴿٩﴾ قُتِلَ ٱلۡخَرَّـٰصُونَ ﴿١٠﴾ ٱلَّذِينَ هُمۡ فِي غَمۡرَةٖ سَاهُونَ ﴿١١﴾ يَسۡـَٔلُونَ أَيَّانَ يَوۡمُ ٱلدِّينِ ﴿١٢﴾ يَوۡمَ هُمۡ عَلَى ٱلنَّارِ يُفۡتَنُونَ ﴿١٣﴾ ذُوقُواْ فِتۡنَتَكُمۡ هَٰذَا ٱلَّذِي كُنتُم بِهِۦ تَسۡتَعۡجِلُونَ ﴿١٤﴾", "w": [["والذاريات ذرواً", "الرياح تذرو التراب وغيره ذرواً."], ["فالحاملات وِقراً", "السحب تحمل الماء."], ["فالجاريات يُسراً", "السفن تجري على سطح الماء بسهولة."], ["فالمقسّمات أمراً", "الملائكة تقسم بأمر ربها الأرزاق والأمطار وغيرها بين العباد."], ["إنما توعدون لصادق", "إن ما وعدكم به ربكم لصادق، سواء كان خيراً أو شراً."], ["وإن الدين لواقع", "وإن الجزاء بعد الحساب لواقع لا محالة."], ["والسماء ذات الحُبُك", "ذات الطرق كالطرق التي تكون على الرمل."], ["إنكم لفي قول مختلف", "يا أهل مكة، إنكم في شأن القرآن والنبي ﷺ لفي قول مختلف: فمنكم من يقول سحر، ومنكم من يقول شعر أو كهانة."], ["يُؤفك عنه من أُفك", "يُصرف عن النبي والقرآن من صُرف."], ["قُتل الخرّاصون", "لُعن الكذابون الذين يقولون بالخرص والكذب."], ["الذين هم في غمرة ساهون", "في غمرة جهل تغمرهم، غافلون عن أمر الآخرة."], ["يسألون أيّان يوم الدين", "يسألون النبي ﷺ سؤال استهزاء: متى يوم القيامة؟"], ["يوم هم على النار يُفتنون", "يُعذّبون فيها."]], "m": "هذا شروع في قسم ضخم أقسم الله تعالى به: والذاريات ذرواً، أي الرياح تذرو التراب وغيره من الأشياء الخفيفة، فالحاملات وقراً أي السحب تحمل الماء، فالجاريات يسراً أي السفن، فالمقسّمات أمراً أي الملائكة تقسم الأرزاق والأمطار وغيرها بأمر ربها. وجواب القسم: إنما توعدون أيها الناس من البعث والجزاء بالنعيم المقيم أو بعذاب الجحيم لصادق، وإن الجزاء العادل لكائن لا محالة. والسماء ذات الحبك قسم آخر، أي ذات الطرق كالتي على الرمل، وجوابه: إنكم لفي قول مختلف؛ فمنكم من يقول محمد ساحر، ومنكم من يقول كاذب أو كاهن، ومنكم من يقول في القرآن سحر وشعر وكهانة. يُصرف عن القرآن ومن نزل عليه من صُرف بقضاء الله وقدره. لُعن الكذابون الذين يقولون بالخرص والكذب والظن، الذين هم في غمرة جهل تغمرهم، غافلون عن أمر الآخرة وما لهم فيه من عذاب. يسألون متى قيام الساعة وهم في هذا مستهزئون ساخرون، وجوابهم: يوم هم على النار يُعذّبون، ويقال لهم: ذوقوا عذابكم هذا الذي كنتم تطالبون رسولنا بتعجيله لكم استخفافاً وتكذيباً.", "h": ["تقرير عقيدة البعث والجزاء، حيث أقسم تعالى على ذلك.", "تقرير عقيدة القضاء والقدر في قوله: «يؤفك عنه من أفك».", "بيان لعن الخرّاصين الذين يقولون بالخرص والكذب، ويسألون استهزاءً وسخرية لا طلباً للعلم والمعرفة للعمل."], "k": "«الذين هم في غمرة ساهون»… الغفلة تغمر الإنسان وهو لا يشعر؛ فهل أنا منتبه أم ساهٍ؟"}, {"lbl": "الآيات ١٥ – ٢٣", "q": "إِنَّ ٱلۡمُتَّقِينَ فِي جَنَّـٰتٖ وَعُيُونٍ ﴿١٥﴾ ءَاخِذِينَ مَآ ءَاتَىٰهُمۡ رَبُّهُمۡۚ إِنَّهُمۡ كَانُواْ قَبۡلَ ذَٰلِكَ مُحۡسِنِينَ ﴿١٦﴾ كَانُواْ قَلِيلٗا مِّنَ ٱلَّيۡلِ مَا يَهۡجَعُونَ ﴿١٧﴾ وَبِٱلۡأَسۡحَارِ هُمۡ يَسۡتَغۡفِرُونَ ﴿١٨﴾ وَفِيٓ أَمۡوَٰلِهِمۡ حَقّٞ لِّلسَّآئِلِ وَٱلۡمَحۡرُومِ ﴿١٩﴾ وَفِي ٱلۡأَرۡضِ ءَايَٰتٞ لِّلۡمُوقِنِينَ ﴿٢٠﴾ وَفِيٓ أَنفُسِكُمۡۚ أَفَلَا تُبۡصِرُونَ ﴿٢١﴾ وَفِي ٱلسَّمَآءِ رِزۡقُكُمۡ وَمَا تُوعَدُونَ ﴿٢٢﴾ فَوَرَبِّ ٱلسَّمَآءِ وَٱلۡأَرۡضِ إِنَّهُۥ لَحَقّٞ مِّثۡلَ مَآ أَنَّكُمۡ تَنطِقُونَ ﴿٢٣﴾", "w": [["إن المتقين في جنات وعيون", "إن الذين اتقوا ربهم في بساتين، وعيون تجري خلالها."], ["آخذين ما آتاهم ربهم", "آخذين ما أعطاهم ربهم من الثواب."], ["إنهم كانوا قبل ذلك محسنين", "كانوا قبل دخولهم الجنة محسنين في الدنيا في عبادة ربهم وإلى عباده."], ["كانوا قليلاً من الليل ما يهجعون", "كانوا في الدنيا يحيون الليل ولا ينامون فيه إلا قليلاً."], ["وبالأسحار هم يستغفرون", "وفي وقت السحر، وهو السدس الأخير من الليل، يستغفرون يقولون: ربنا اغفر لنا."], ["وفي أموالهم حق للسائل والمحروم", "للذي يسأل، والمحروم الذي لا يسأل لتعفّفه، وهذا حق أوجبوه على أنفسهم زيادة على الزكاة الواجبة."], ["وفي الأرض آيات للموقنين", "من الجبال والأنهار والأشجار والبحار والإنسان والحيوان دلالات على قدرة الله، مقتضية للبعث وموجبة للتوحيد."], ["وفي أنفسكم أفلا تبصرون", "آيات من الخلق والتركيب والسمع والبصر والتعقّل والتحرك، أفلا تبصرون ذلك فتستدلون به على وجود الله وعلمه؟"], ["وفي السماء رزقكم وما توعدون", "من الأمطار التي بها الزرع وسائر الأقوات، وما توعدون من ثواب وعقاب، كل ذلك عند الله في السماء مكتوب في اللوح المحفوظ."], ["فوربّ السماء والأرض إنه لحق", "ما توعدون لحق ثابت."], ["مثل ما أنكم تنطقون", "إن البعث لحق مثل نطقكم؛ فهل يشك أحد في نطقه إذا نطق؟ فكذلك ما توعدون."]], "m": "ما زال السياق في تقرير عقيدة البعث والجزاء التي كذّب بها المشركون في مكة: إن الذين اتقوا ربهم فلم يشركوا به ولم يعصوه بترك الواجبات ولا بفعل المحرمات، هؤلاء يوم القيامة في بساتين وعيون تجري فيها، آخذين ما أعطاهم ربهم من ثواب ونعيم مقيم في دار السلام. ثم ذكر تعالى مقتضيات هذا العطاء العظيم: إنهم كانوا قبل دخولهم الجنة محسنين في الدنيا، أحسنوا نياتهم وأعمالهم فأخلصوها لربهم وأتوا بها وفق ما شرعه بلا زيادة ولا نقصان، كما أحسنوا إلى عباده ولم يسيئوا إليهم بقول ولا عمل. وثانيها: أنهم كانوا لا ينامون من الليل إلا قليلاً، إذ أكثر الليل يقضونه في الصلاة، وفي السدس الأخير من الليل يستغفرون: ربنا اغفر لنا ذنوبنا وقنا عذاب النار. وثالثها: أنهم أوجبوا على أنفسهم في أموالهم، زيادة على الزكاة المفروضة، حقاً يبذلونه للسائل والمحروم الذي لا يسأل لحيائه وعفّته. وفيما خُلق في الأرض من جبال وأنهار وزروع وضروع وثمار وإنسان وحيوان دلائل على قدرة الله وعلمه وحكمته ورحمته، موجبة لتوحيده ومقررة لقدرته على البعث والجزاء؛ وكونها للموقنين لأنهم ذوو بصائر، كلما نظروا إلى آية ازداد إيمانهم حتى بلغوا اليقين. وفي أنفسكم أيها الناس دلائل في خلق الإنسان وأطواره من نطفة إلى علقة إلى مضغة إلى طفل إلى شاب فكهل، وفي إدراكه وسمعه وبصره ونطقه، وقوله: أفلا تبصرون توبيخ لأهل الغفلة والإعراض عن التفكر. وفي السماء رزقكم، يريد تدبير الأمر والأمطار التي هي سبب الثمار والحبوب، وما توعدون من خير وشر، إذ الأمر لله وكتاب المقادير في السماء. ثم أقسم تعالى بنفسه أن البعث والجزاء حق ثابت كائن لا محالة؛ فكما لا نشك في نطقنا إذا نطقنا، فكذلك البعث واقع لا محالة.", "h": ["بيان ما للمتقين من نعيم مقيم في الدار الآخرة.", "بيان صفات المتقين من التهجد بالليل والاستغفار في آخره والإنفاق في سبيل الله.", "بيان أن في الأرض كما في الأنفس آيات، أي دلائل وعلامات على قدرة الله على البعث.", "بيان أن في السماء رزق العباد، فلا يُطلب إلا من الله تعالى، وأن ما يُوعَدونه من خير وشر أمره في السماء ومنها ينزل بأمره، فليكن طلبنا الخير من الله دائماً، وتعوّذنا من الشر بالله وحده."], "k": "«وبالأسحار هم يستغفرون»… يقومون الليل ثم يستغفرون كأنهم مقصّرون؛ فكيف بي؟"}, {"lbl": "الآيات ٢٤ – ٣٠", "q": "هَلۡ أَتَىٰكَ حَدِيثُ ضَيۡفِ إِبۡرَٰهِيمَ ٱلۡمُكۡرَمِينَ ﴿٢٤﴾ إِذۡ دَخَلُواْ عَلَيۡهِ فَقَالُواْ سَلَٰمٗاۖ قَالَ سَلَٰمٞ قَوۡمٞ مُّنكَرُونَ ﴿٢٥﴾ فَرَاغَ إِلَىٰٓ أَهۡلِهِۦ فَجَآءَ بِعِجۡلٖ سَمِينٖ ﴿٢٦﴾ فَقَرَّبَهُۥٓ إِلَيۡهِمۡ قَالَ أَلَا تَأۡكُلُونَ ﴿٢٧﴾ فَأَوۡجَسَ مِنۡهُمۡ خِيفَةٗۖ قَالُواْ لَا تَخَفۡۖ وَبَشَّرُوهُ بِغُلَٰمٍ عَلِيمٖ ﴿٢٨﴾ فَأَقۡبَلَتِ ٱمۡرَأَتُهُۥ فِي صَرَّةٖ فَصَكَّتۡ وَجۡهَهَا وَقَالَتۡ عَجُوزٌ عَقِيمٞ ﴿٢٩﴾ قَالُواْ كَذَٰلِكِ قَالَ رَبُّكِۖ إِنَّهُۥ هُوَ ٱلۡحَكِيمُ ٱلۡعَلِيمُ ﴿٣٠﴾", "w": [["هل أتاك حديث", "قد أتاك يا نبينا حديث، أي كلام."], ["ضيف إبراهيم المكرمين", "جبريل وميكائيل وإسرافيل، أكرمهم إبراهيم الخليل."], ["قال سلام قوم منكرون", "عليكم سلام، أنتم قوم منكرون، أي غير معروفين."], ["فراغ إلى أهله فجاء بعجل سمين", "عدل ومال إلى أهله فجاء بعجل سمين حنيذ."], ["فقال ألا تأكلون", "أمسكوا عن الأكل فقال لهم: ألا تأكلون؟"], ["فأوجس منهم خيفة", "أضمر في نفسه خوفاً منهم."], ["بغلام عليم", "بولد يكون ذا علم كبير غزير."], ["فأقبلت امرأته في صرّة", "في صيحة."], ["فصكّت وجهها", "لطمت وجهها، أي ضربت بأصابعها جبينها متعجبة."], ["وقالت عجوز عقيم", "كبيرة السن، وعقيم لم يولد لها قط."], ["قالوا كذلك قال ربك", "قالت الملائكة لها: كالذي قلنا لكِ قال ربك."], ["إنه هو الحكيم العليم", "الحكيم في تدبيره وتصريف شؤون عباده، العليم بما يصلح للعبد وما لا يصلح، فليفوّض الأمر إليه."]], "m": "هذا الحديث يشتمل على موجز قصة ذُكرت في سورتي هود والحجر، والمقصود منه تقرير نبوة محمد ﷺ، إذ مثل هذا القصص لا يتم لأمّي لا يقرأ ولا يكتب إلا من طريق الوحي، كما يحمل في نهايته التهديد بالوعيد لمشركي قريش المصرين على الكفر والتكذيب، إذ يجيب الملائكة إبراهيم بأنهم أُرسلوا إلى قوم مجرمين لإهلاكهم من أجل إجرامهم. قد أتاك يا نبينا حديث ضيف إبراهيم الخليل، وهم ملائكة في صورة رجال، إذ دخلوا عليه في منزله فسلّموا عليه فردّ السلام ثم قال: أنتم قوم غرباء لستم من أهل هذا البلد، فلذا سارع في إكرامهم، فمال إلى أهله فعمد إلى عجل سمين من أبقاره فشواه بعد ذبحه وقرّبه إليهم، فأمسكوا عن تناوله فعرض عليهم الأكل بقوله: ألا تأكلون؟ ولما لم يأكلوا شعر بالخوف في نفسه منهم، لأن العادة البشرية أن المرء إذا أراد بأخيه سوءاً لا يأكل طعامه، وهذا حكم غالبي وليس عاماً. قالوا: لا تخف، وأعلموه أنهم مرسلون من ربه إلى قوم لوط لإهلاكهم، وبشّروه بغلام يولد له، وهو إسحاق. فأقبلت امرأته في صيحة لما سمعت البشرى، فلطمت وجهها بأصابع يدها متعجبة وقالت: عجوز عقيم كيف ألد؟ إذ كان عمرها تجاوز التسعين وعمر إبراهيم تجاوز المئة، وكانت عقيماً لا تلد قط. فأجابها الملائكة: هكذا قال ربك فاقبلي البشرى واحمديه واشكريه، إنه هو الحكيم في تصرفاته في شؤون عباده، العليم بما يصلح لهم وما لا يصلح، فليفوَّض الأمر إليه ولا يُعترض عليه.", "h": ["تقرير النبوة المحمدية.", "فضيلة إبراهيم ﵇ أبي الأنبياء وإمام الموحدين.", "وجوب إكرام الضيف.", "الخوف الفطري عند وجود أسبابه لا يقدح في العقيدة ولا يُعدّ شركاً."], "k": "«فراغ إلى أهله فجاء بعجل سمين»… أكرم ضيوفاً لا يعرفهم بأحسن ما عنده؛ فكيف أستقبل ضيفي؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;